TURATH_CHUNK(19,[{"num":3800,"demo":false,"sanad":"","matn":["عَنْ هِشَامِ بْنِ عَامِرٍ، قَالَ: شُكِيَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْجِرَاحَاتُ يَوْمَ أُحُدٍ فَقَالَ: احْفِرُوا وَأَوْسِعُوا وَأَحْسِنُوا وَادْفِنُوا الاِثْنَيْنِ وَالثَّلاَثَةَ فِي قَبْرٍ وَاحِدٍ، وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا.","قال: فمات أبي فقُدم بين يدي رجلين.","وفي رواية: قُتِلَ أَبِي يَوْمَ أُحُدٍ فَقَالَ النَّبِيُّ صلى الله عليه وسلم: احْفِرُوا وَأَوْسِعُوا وَأَحْسِنُوا وَادْفِنُوا الِاثْنَيْنِ وَالثَّلَاثَةَ فِي الْقَبْرِ، وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا ،، فَكَانَ أَبِي ثَالِثَ ثَلَاثَةٍ، وَكَانَ أَكْثَرَهُمْ قُرْآنًا فَقُدِّمَ."],"takhrij":"صحيح: رواه الترمذي (1713)، وابن ماجه (1560) كلاهما عن أزهر ابن مروان، قال: حدثنا عبد الوارث بن سعيد، قال: حدثنا أيوب، عن حُميد ابن هلال، عن أبي الدهماء، عن هشام بن عامر فذكره، واللفظ للترمذي. ولفظ ابن ماجه مختصراً.","grade":"صحيح","chapter_ar":"باب ما جاء في إعماق القبر وتوسيعه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Tirmidhī (1713), Ibn Mājah (1560), and the second narration is with al-Nasā’ī (2018).","chapter_en":"What is reported about making the grave deep and spacious","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":8,"content":{"translation":{"en":["Hishām ibn ʿĀmir said: The many wounds on the day of Uḥud were mentioned to the Messenger of Allah ﷺ, so he said: “Dig, make the graves wider, do it well, and bury two or three in one grave, and place the one who knew more Qur’an first.” He said: Then my father died, and he was placed ahead of two men.","In another narration: My father was killed on the day of Uḥud, and the Prophet ﷺ said: “Dig, make the graves wider, do it well, and bury two or three in one grave, and place the one who knew more Qur’an first.” So my father was the third of three, and he knew the most Qur’an among them, so he was placed first."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1713)، وابن ماجه (1560)، والرواية الثانية عند النسائي (2018)."},{"num":3801,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، مِنَ الأَنْصَارِ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَنَازَةٍ، فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى الْقَبْرِ يُوصِي الْحَافِرَ: أَوْسِعْ مِنْ قِبَلِ رِجْلَيْهِ، أَوْسِعْ مِنْ قِبَلِ رَأْسِهِ.","وفي رواية: لرُبَّ عَذْقٍ له في الجنة ."],"takhrij":"حسن: رواه أبو داود (3332) عن محمد بن العلاء، أخبرنا ابن إدريس، أخبرنا عاصم بن كليب، عن أبيه، عن رجل من الأنصار في حديث طويل سيأتي في موضعه.","grade":"حسن","chapter_ar":"باب ما جاء في إعماق القبر وتوسيعه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3332), Aḥmad (22509, 23465).","chapter_en":"What is reported about making the grave deep and spacious","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":8,"content":{"translation":{"en":["A man from the Anṣār said: We went out with the Messenger of Allah ﷺ in a funeral, and I saw the Messenger of Allah ﷺ standing over the grave instructing the digger: “Widen it from the direction of his feet, widen it from the direction of his head.” And in another narration: “How many date-palm clusters he has in Paradise!”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3332)، والإمام أحمد (22509، 23465)."},{"num":3802,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ،  أَنَّ سَعْدَ بْنَ أَبِي وَقَّاصٍ قَالَ: فِي مَرَضِهِ الَّذِي هَلَكَ فِيهِ: الْحَدُوا لِي لَحْدًا، وَانْصِبُوا عَلَيَّ اللَّبِنَ نَصْبًا، كَمَا صُنِعَ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في الجنائز (966) عن يحيى بن يحيى، نا عبدالله بن جعفر المِسْوَرِي، عن إسماعيل بن محمد بن سعد، عن عامر بن سعد بن أبي وقاص فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في اللحد ونصب اللبن على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (966).","chapter_en":"What is reported about the burial niche and setting bricks over the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":9,"content":{"translation":{"en":["ʿĀmir ibn Saʿd ibn Abī Waqqāṣ reported that Saʿd ibn Abī Waqqāṣ said during the illness in which he died: “Make a burial niche for me, and set the bricks over me in place, just as was done for the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"rep":[9377,9963],"tks":"صحيح: رواه مسلم (966)."},{"num":3803,"demo":false,"sanad":"","matn":["عن علي بن أَبِي طَالِبٍ غَسَّلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَهَبْتُ لِأَنْظُرَ مَا يَكُونُ مِنَ الْمَيِّتِ، فَلَمْ أَرَ شَيْئًا، وَكَانَ طَيِّبًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَيًّا وَمَيِّتًا، وَوَلِي دَفْنَهُ وَإِجْنَانَهُ دُونَ النَّاسِ أَرْبَعَةٌ: عَلِيٌّ، وَالْعَبَّاسُ، وَالْفَضْلُ، وَصَالِحٌ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلُحِدَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَحْدٌ أَوْ نُصِبَ عَلَيْهِ اللَّبِنُ نَصْبًا."],"takhrij":"صحيح: رواه الحاكم (1339) وعنه البيهقي (6626) من طريق مسدد، ثنا عبدالواحد بن زياد، ثنا معمر، عن الزهري، عن سعيد بن المسيب، قال: قال علي بن أبي طالب فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في اللحد ونصب اللبن على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Ḥākim (1339), al-Bayhaqī (3/388).","chapter_en":"What is reported about the burial niche and setting bricks over the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":9,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib said: I washed the Prophet ﷺ, and I went to see what is usually seen from the dead, but I saw nothing. He was pure and fragrant in life and in death. The ones who took charge of burying him and placing him in the grave, apart from the rest of the people, were four: ʿAlī, al-ʿAbbās, al-Faḍl, and Ṣāliḥ, the freedman of the Messenger of Allah ﷺ. A burial niche was made for the Messenger of Allah ﷺ, and bricks were set over him."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9378],"tks":"صحيح: رواه الحاكم (1339)، والبيهقي (6626)."},{"num":3804,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: لَمَّا تُوُفِّيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ بِالْمَدِينَةِ رَجُلٌ يَلْحَدُ، وَآخَرُ يَضْرَحُ. فَقَالُوا: نَسْتَخِيرُ رَبَّنَا وَنَبْعَثُ إِلَيْهِمَا، فَأَيُّهُمَا سَبَقَ تَرَكْنَاهُ. فَأُرْسِلَ إِلَيْهِمَا، فَسَبَقَ صَاحِبُ اللَّحْدِ. فَلَحَدُوا لِلنَّبِيِّ ـ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه ابن ماجه (1557) قال: حدثنا محمود بن غيلان، قال: حدثنا هاشم بن القاسم، قال: حدثنا مبارك بن فَضالة، قال: حدثني حُميد الطويل، عن أنس فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في اللحد ونصب اللبن على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (1557), Aḥmad (12415).","chapter_en":"What is reported about the burial niche and setting bricks over the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Mālik said: When the Prophet ﷺ passed away, there was in Madinah one man who made burial niches and another who made straight graves. So they said: “We will seek our Lord’s guidance and send for both of them, and whichever of them arrives first, we will leave it to him.” So both were sent for, and the one who made the burial niche arrived first, so they made a burial niche for the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9376],"tks":"حسن: رواه ابن ماجه (1557)، وأحمد (12415)."},{"num":3805,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ بِالْمَدِينَةِ حَفَّارَان، أَحَدُهُمَا يَلْحَدُ، وَالْاخَرُ يَشُقُّ فَانْتَظِرُوا أَنْ يَجِئَ أَحَدُهُمَا فَجَاءَ الَّذِي يَلْحَدُ، فَلَحَدَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه ابن سعد (666) عن يزيد بن هارون وهشام أبي الوليد الطيالسي، قال يزيد: قال أخبرنا، وقال هشام: أخبرنا حماد بن سلمة، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في اللحد ونصب اللبن على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Saʿd (2/295).","chapter_en":"What is reported about the burial niche and setting bricks over the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":9,"content":{"translation":{"en":["ʿĀ’ishah said: There were two grave diggers in Madinah. One used to make burial niches and the other used to make straight graves. They waited to see which of them would come, and the one who made the burial niche came, so he made the burial niche for the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9379],"tks":"صحيح: رواه ابن سعد (666)."},{"num":3806,"demo":false,"sanad":"","matn":["عَنْ عبد الله بن عباس قَالَ: دَخَلَ قَبْرَ رَسُولِ اللهِ صلى الله عليه وسلم الْعَبَّاسُ وَعَلِيٌّ وَالْفَضْلُ، وَشَقَّ لَحْدَهُ رَجُلٌ مِنَ الْأَنْصَارِ، وَهُوَ الَّذِي يَشُقُّ لُحُودَ قُبُورِ الشُّهَدَاءِ."],"takhrij":"صحيح: رواه ابن الجارود في المنتقى (547) عن محمد بن عبد الملك ابن زنجويه، قال: ثنا أبو بدر شجاع بن الوليد، قال: ثنى زياد بن خيثمة، قال: أني إسماعيلُ السدي، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في اللحد ونصب اللبن على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn al-Jārūd in al-Muntaqā (547).","chapter_en":"What is reported about the burial niche and setting bricks over the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: Al-ʿAbbās, ʿAlī, and al-Faḍl entered the grave of the Messenger of Allah ﷺ, and a man from the Anṣār made the burial niche for him. He was the same man who used to prepare the burial niches of the martyrs’ graves."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن الجارود في المنتقى (547)."},{"num":3807,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْمَعُ بَيْنَ الرَّجُلَيْنِ مِنْ قَتْلَى أُحُدٍ فِي ثَوْبٍ وَاحِدٍ، ثُمَّ يَقُولُ: أَيُّهُمْ أَكْثَرُ أَخْذًا لِلْقُرْآنِ. فَإِذَا أُشِيرَ لَهُ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ، وَقَالَ: أَنَا شَهِيدٌ عَلَى هَؤُلاَءِ. وَأَمَرَ بِدَفْنِهِمْ بِدِمَائِهِمْ، وَلَمْ يُصَلِّ عَلَيْهِمْ وَلَمْ يُغَسِّلْهُمْ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1347) عن ابن مقاتل، أخبرنا","grade":"صحيح","chapter_ar":"باب دفن الجماعة في قبر واحد ويقدم من هو أكثر قرآناً","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1347).","chapter_en":"Burying a group in one grave, and giving precedence to the one who knew more of the Qur’an","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":10,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Messenger of Allah ﷺ used to place two men from the martyrs of Uḥud in one cloth, then say: “Which of them had taken more of the Qur’an?” When one of them was pointed out to him, he placed that one first in the burial niche and said: “I am a witness for these.” He ordered that they be buried in their blood, and he did not pray over them and did not wash them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1347)."},{"num":3808,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَعَنَ المُختَفِيَ والمُختَفيَةَ.","وزاد في رواية: يَعْنِي نَبَّاشَ الْقُبُورِ."],"takhrij":"صحيح: رواه البيهقي في الكبرى (١٧٣٢٦) من طريق يحيى بن صالح الوحاظي وأبي قتيبة سَلْم بن قتيبة كلاهما عن مالك، عن أبي الرجال محمد بن عبدالرحمن، عن أمّه عمرة بنت عبدالرحمن، عن عائشة فذكرتْه. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في نبّاش القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bayhaqī in al-Kubrā (8/270).","chapter_en":"What is reported concerning one who digs up graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah said: The Messenger of Allah ﷺ cursed the male grave-robber and the female grave-robber. Meaning: the one who digs up graves."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البيهقي في الكبرى (17245)."},{"num":3809,"demo":false,"sanad":"","matn":["عَنْ جابرٍ قَالَ: أَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عبدالله بْنَ أُبيّ بَعْدَ مَا أُدْخل حُفْرتَه، فَأَمَرَ بِهِ فَأُخْرِجَ، فَوَضَعَهُ عَلَى رُكْبَتَيْهِ، ونَفَثَ عَلَيْهِ مِنْ رِيقِهِ، وَأَلْبَسَهُ قَمِيصَهُ، فَاللَّهُ أَعْلَمُ وَكَانَ ( أي عبدالله بن أُبيّ ) كَسَا عبَّاساً قَمِيصًا.","قَالَ سُفْيَانُ: وَقَالَ أَبُو هَارُونَ: وَكَانَ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم قَمِيصَانِ، فَقَالَ لَهُ ابْنُ عبدالله يَا رَسُولَ اللَّهِ! أَلْبِسْ أَبِي قَمِيصَكَ الَّذِي يَلِي جِلْدَكَ. قَالَ سُفْيَانُ: فَيُرَوْنَ أَنَّ النَّبِيَّ صلى الله عليه وسلم أَلْبَسَ عبدالله قَمِيصَهُ مُكَافَأَةً لِمَا صَنَعَ.","قوله: \" قال أبو هارون \" هو الصحيح، وفي نسخة البخاري أبوهريرة، وهو تصحيف."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1350)، ومسلم في صفات المنافقين (2773) كلاهما من حديث سفيان بن عيينة، عن عمرو قال: سمعت جابر بن عبدالله يقول: فذكر الحديث واللفظ للبخاري، ولم يذكر مسلم بعد قوله: فالله أعلم .","grade":"متفق عليه","chapter_ar":"باب جواز إخراج الميت من القبر للضرورة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1350) and Muslim (2773).","chapter_en":"The permissibility of removing a deceased person from the grave when necessary","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: The Messenger of Allah ﷺ came to ʿAbdullāh ibn Ubayy after he had been placed in his grave pit. He ordered that he be taken out, so he was taken out. The Prophet ﷺ placed him upon his knees, blew some of his saliva upon him, and clothed him in his own shirt. Allah knows best. ʿAbdullāh ibn Ubayy had previously given al-ʿAbbās a shirt.","Sufyān said: Abū Hārūn said that the Messenger of Allah ﷺ had two shirts, and the son of ʿAbdullāh said to him: “O Messenger of Allah ﷺ, clothe my father in the shirt of yours that touches your skin.” Sufyān said: They considered that the Prophet ﷺ clothed ʿAbdullāh in his shirt as repayment for what he had done. The wording “Abū Hārūn said” is the correct reading; in one copy of al-Bukhārī it reads “Abū Hurayrah,” which is a scribal error."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1350)، ومسلم (2773)."},{"num":3810,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا حَضَرَ أُحُدٌ دَعَانِي أَبِي مِنَ اللَّيْلِ فَقَالَ: مَا أُرَانِي إِلاَّ مَقْتُولاً فِي أَوَّلِ مَنْ يُقْتَلُ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنِّي لاَ أَتْرُكُ بَعْدِي أَعَزَّ عَلَىَّ مِنْكَ، غَيْرَ نَفْسِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِنَّ عَلَىَّ دَيْنًا فَاقْضِ، وَاسْتَوْصِ بِأَخَوَاتِكَ خَيْرًا. فَأَصْبَحْنَا فَكَانَ أَوَّلَ قَتِيلٍ، وَدُفِنَ مَعَهُ آخَرُ فِي قَبْرٍ، ثُمَّ لَمْ تَطِبْ نَفْسِي أَنْ أَتْرُكَهُ مَعَ الآخَرِ، فَاسْتَخْرَجْتُهُ بَعْدَ سِتَّةِ أَشْهُرٍ، فَإِذَا هُوَ كَيَوْمِ وَضَعْتُهُ هُنَيَّةً، غَيْرَ أُذُنِهِ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1351) عن مسدد، أخبرنا بشر بن المفضَّل، حدثنا حسين المعلم، عن عطاء، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب جواز إخراج الميت من القبر للضرورة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1351).","chapter_en":"The permissibility of removing a deceased person from the grave when necessary","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: When the day of Uḥud approached, my father called me during the night and said: “I think I will be among the first of the Companions of the Prophet ﷺ to be killed, and after the Messenger of Allah ﷺ there is no one more beloved to me whom I leave behind than you. I owe a debt, so repay it, and treat your sisters well.” By the morning, he was the first one killed, and another man was buried with him in one grave. Then I no longer felt at ease leaving him with the other man, so I took him out after six months, and he was as though I had placed him there only a short while earlier, except for his ear."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8839],"tks":"صحيح: رواه البخاري (1351)."},{"num":3811,"demo":false,"sanad":"","matn":["عَنِ الْمُطَّلِبِ، قَالَ: لَمَّا مَاتَ عُثْمَانُ بْنُ مَظْعُونٍ أُخْرِجَ بِجَنَازَتِهِ، فَدُفِنَ، أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً أَنْ يَأْتِيَهُ بِحَجَرٍ، فَلَمْ يَسْتَطِعْ حَمْلَهُ، فَقَامَ إِلَيْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحَسَرَ عَنْ ذِرَاعَيْهِ، - قَالَ كَثِيرٌ: قَالَ الْمُطَّلِبُ: قَالَ الَّذِي يُخْبِرُنِي ذَلِكَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: - كَأَنِّي أَنْظُرُ إِلَى بَيَاضِ ذِرَاعَىْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ حَسَرَ عَنْهُمَا، ثُمَّ حَمَلَهَا فَوَضَعَهَا عِنْدَ رَأْسِهِ وَقَالَ: أَتَعَلَّمُ بِهَا قَبْرَ أَخِي، وَأَدْفِنُ إِلَيْهِ مَنْ مَاتَ مِنْ أَهْلِي."],"takhrij":"حسن: رواه أبو داود (3206) من طريقين عن كثير بن زيد المدني، عن المطلب فذكره. وكثير بن زيد مختلف فيه غير أنه حسن الحديث.","grade":"حسن","chapter_ar":"باب وضع العَلَم على القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3206).","chapter_en":"Placing a marker on the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":13,"content":{"translation":{"en":["Al-Muṭṭalib said: When ʿUthmān ibn Maẓʿūn died, his funeral was taken out and he was buried. Then the Prophet ﷺ ordered a man to bring him a stone, but he was unable to carry it. So the Messenger of Allah ﷺ stood up to it and uncovered his forearms. Kathīr said: Al-Muṭṭalib said: The one who told me this about the Messenger of Allah ﷺ said: It is as if I can still see the whiteness of the forearms of the Messenger of Allah ﷺ when he uncovered them. Then he carried it and placed it at the head of the grave and said: “I will mark the grave of my brother with it, and I will bury near him those of my family who die.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3206)."},{"num":3812,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: حَرَّمَ اللَّهُ مَكَّةَ، فَلَمْ تَحِلَّ لأَحَدٍ قَبْلِي، وَلاَ لأَحَدٍ بَعْدِي، أُحِلَّتْ لِي سَاعَةً مِنْ نَهَارٍ، لاَ يُخْتَلَى خَلاَهَا، وَلاَ يُعْضَدُ شَجَرُهَا، وَلاَ يُنَفَّرُ صَيْدُهَا، وَلاَ تُلْتَقَطُ لُقَطَتُهَا إِلاَّ لِمُعَرِّفٍ. فَقَالَ الْعَبَّاسُ: رَضِيَ اللَّهُ! عَنْهُ إِلاَّ الإِذْخِرَ لِصَاغَتِنَا وَقُبُورِنَا. فَقَالَ: إِلاَّ الإِذْخِرَ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1349) عن محمد بن عبدالله بن حوشب، حدثنا عبد الوهاب، حدثنا خالد، عن عكرمة، عن ابن عباس فذكره. ورواه الشيخان – البخاري (1834)، ومسلم (1353) كلاهما من حديث جرير، عن منصور، عن مجاهد، عن طاوس، عن ابن عباس في سياق أطول وسيأتي في موضعه إن شاء الله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في طرح الإذخر في القبر وبسطه فيه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1349, 1834), Muslim (1353).","chapter_en":"What is reported about putting idhkhir grass in the grave and spreading it there","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Prophet ﷺ said: “Allah made Makkah sacred. It was not made lawful for anyone before me, and it will not be lawful for anyone after me. It was only made lawful for me for part of a day. Its grass is not to be cut, its trees are not to be chopped down, its game is not to be driven away, and its lost property is not to be picked up except by one who will announce it.” Al-ʿAbbās then said: “O Messenger of Allah ﷺ, except for idhkhir, for our metalworkers and for our graves.” So he said: “Except for idhkhir.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1349، 1834)، ومسلم (1353)."},{"num":3813,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  جُعِلَ فِي قَبْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطِيفَةٌ حَمْرَاءُ."],"takhrij":"صحيح: رواه مسلم في الجنائز (967) من طرق عن شعبة، قال: حدثنا أبو حمزة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب في الثوب الذي يُلقى تحت الميت في القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (967).","chapter_en":"The cloth placed beneath the deceased in the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās said: A red velvet-like cloth was placed in the grave of the Prophet ﷺ."]},"buhuth":{"en":["A qaṭīfah is a thick cloth or covering that has a soft pile."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9380],"tks":"صحيح: رواه مسلم (967)."},{"num":3814,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَنَازَةِ رَجُلٍ مِنَ الأَنْصَارِ، فَانْتَهَيْنَا إِلَى الْقَبْرِ وَلَمَّا يُلْحَدْ، فَجَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَلَسْنَا حَوْلَهُ كَأَنَّمَا عَلَى رؤوسنا الطَّيْرُ، وَفِي يَدِهِ عُودٌ يَنْكُتُ بِهِ فِي الأَرْضِ، فَرَفَعَ رَأْسَهُ فَقَالَ: اسْتَعِيذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ مَرَّتَيْنِ أَوْ ثَلاَثًا، وذكر الحديث بِطُولِهِ وسيأتي فِي باب إثبات عَذَابِ الْقَبْرِ."],"takhrij":"صحيح: رواه أبو داود (3212)، والنسائي (2003)، وابن ماجه (1548) كلهم من طريق المنهال بن عمرو، عن زاذان، عن البراء فذكره.","grade":"صحيح","chapter_ar":"باب الجلوس عند القبر أثناء الدفن للتذكير والموعظة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3212), al-Nasā’ī (2003), Ibn Mājah (1548).","chapter_en":"Sitting by the grave during burial for reminder and exhortation","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":16,"content":{"translation":{"en":["Al-Barā’ ibn ʿĀzib said: We went out with the Messenger of Allah ﷺ in the funeral of a man from the Anṣār, and we came to the grave before the burial niche had been made. So the Messenger of Allah ﷺ sat, and we sat around him as if birds were on our heads. In his hand was a stick with which he was scratching the ground. Then he raised his head and said: “Seek refuge in Allah from the punishment of the grave,” two or three times. The hadith continues at length and will appear later in the chapter affirming the punishment of the grave."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3212)، والنسائي (2003)، وابن ماجه (1548)."},{"num":3815,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: إِنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَتَعَذَّرُ فِي مَرَضِهِ: أَيْنَ أَنَا الْيَوْمَ، أَيْنَ أَنَا غَدًا؟ اسْتِبْطَاءً لِيَوْمِ عَائِشَةَ، فَلَمَّا كَانَ يَوْمِي قَبَضَهُ اللَّهُ بَيْنَ سَحْرِي وَنَحْرِي، وَدُفِنَ فِي بَيْتِي."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1389) ومسلم في الفضائل (2443/84) كلاهما من طرق عن هشام، عن عروة، عن عائشة فذكرته، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب في قبر النبي ﷺ وأبي بكر وعمر رضي الله عنهما","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1389), Muslim (2443/84), and this is the wording of al-Bukhārī.","chapter_en":"About the grave of the Prophet ﷺ, Abū Bakr, and ʿUmar","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":17,"content":{"translation":{"en":["ʿĀ’ishah said: During his illness, the Messenger of Allah ﷺ would keep asking: “Where am I today? Where will I be tomorrow?” longing for the day of ʿĀ’ishah. Then when my day came, Allah took his soul while he was between my upper chest and my neck, and he was buried in my house."]}},"tuhfa":{},"full":1,"rep":[9382],"tks":"متفق عليه: رواه البخاري (1389)، ومسلم (2443/84)، واللفظ للبخاري."},{"num":3816,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ: لَعَنَ اللَّهُ الْيَهُودَ وَالنَّصَارَى، اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسْجِدًا.","قَالَتْ: وَلَوْلاَ ذَلِكَ لأَبْرَزُوا قَبْرَهُ غَيْرَ أَنِّي أَخْشَى أَنْ يُتَّخَذَ مَسْجِدًا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1330) ومسلم في المساجد (529) كلاهما من حديث شيبان، عن هلال - هو الوزّان- عن عروة، عن عائشة فذكرتْه.","grade":"متفق عليه","chapter_ar":"باب في قبر النبي ﷺ وأبي بكر وعمر رضي الله عنهما","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1330), Muslim (529).","chapter_en":"About the grave of the Prophet ﷺ, Abū Bakr, and ʿUmar","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":17,"content":{"translation":{"en":["ʿĀ’ishah reported that in the illness in which he died, the Prophet ﷺ said: “May Allah curse the Jews and Christians; they took the graves of their prophets as places of worship.” She said: Were it not for that, his grave would have been made visible, but I fear that it would be taken as a place of worship."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1330)، ومسلم (529)."},{"num":3817,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ مَيْمُونٍ الأَوْدِيِّ، قَالَ: رَأَيْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: يَا عَبْدَ اللَّهِ بْنَ عُمَرَ، اذْهَبْ إِلَى أُمِّ الْمُؤْمِنِينَ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فَقُلْ: يَقْرَأُ عُمَرُ بْنُ الْخَطَّابِ عَلَيْكِ السَّلاَمَ، ثُمَّ سَلْهَا أَنْ أُدْفَنَ مَعَ صَاحِبَىَّ. قَالَتْ: كُنْتُ أُرِيدُهُ لِنَفْسِي، فَلأُوثِرَنَّهُ الْيَوْمَ عَلَى نَفْسِي. فَلَمَّا أَقْبَلَ قَالَ لَهُ: مَا لَدَيْكَ؟ قَالَ: أَذِنَتْ لَكَ يَا أَمِيرَ الْمُؤْمِنِينَ. قَالَ: مَا كَانَ شَىْءٌ أَهَمَّ إِلَىَّ مِنْ ذَلِكَ الْمَضْجَعِ، فَإِذَا قُبِضْتُ فَاحْمِلُونِي، ثُمَّ سَلِّمُوا، ثُمَّ قُلْ: يَسْتَأْذِنُ عُمَرُ بْنُ الْخَطَّابِ. فَإِنْ أَذِنَتْ لِي فَادْفِنُونِي، وَإِلاَّ فَرُدُّونِي إِلَى مَقَابِرِ الْمُسْلِمِينَ، إِنِّي لاَ أَعْلَمُ أَحَدًا أَحَقَّ بِهَذَا الأَمْرِ مِنْ هَؤُلاَءِ النَّفَرِ الَّذِينَ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَنْهُمْ رَاضٍ، فَمَنِ اسْتَخْلَفُوا بَعْدِي فَهُوَ الْخَلِيفَةُ، فَاسْمَعُوا لَهُ وَأَطِيعُوا. فَسَمَّى عُثْمَانَ وَعَلِيًّا وَطَلْحَةَ وَالزُّبَيْرَ وَعَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ وَسَعْدَ بْنَ أَبِي وَقَّاصٍ، وَوَلَجَ عَلَيْهِ شَابٌّ مِنَ الأَنْصَارِ فَقَالَ: أَبْشِرْ يَا أَمِيرَ الْمُؤْمِنِينَ بِبُشْرَى اللَّهِ، كَانَ لَكَ مِنَ الْقَدَمِ فِي الإِسْلاَمِ مَا قَدْ عَلِمْتَ، ثُمَّ اسْتُخْلِفْتَ فَعَدَلْتَ، ثُمَّ الشَّهَادَةُ بَعْدَ هَذَا كُلِّهِ. فَقَالَ: لَيْتَنِي يَا ابْنَ أَخِي وَذَلِكَ كَفَافًا لاَ عَلَىَّ وَلاَ لِي، أُوصِي الْخَلِيفَةَ مِنْ بَعْدِي بِالْمُهَاجِرِينَ الأَوَّلِينَ خَيْرًا، أَنْ يَعْرِفَ لَهُمْ حَقَّهُمْ، وَأَنْ يَحْفَظَ لَهُمْ حُرْمَتَهُمْ، وَأُوصِيهِ بِالأَنْصَارِ خَيْرًا، الَّذِينَ تَبَوَّءُوا الدَّارَ وَالإِيمَانَ أَنْ يُقْبَلَ مِنْ مُحْسِنِهِمْ، وَيُعْفَى عَنْ مُسِيئِهِمْ، وَأُوصِيهِ بِذِمَّةِ اللَّهِ وَذِمَّةِ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُوفَى لَهُمْ بِعَهْدِهِمْ، وَأَنْ يُقَاتَلَ مِنْ وَرَائِهِمْ، وَأَنْ لاَ يُكَلَّفُوا فَوْقَ طَاقَتِهِمْ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1392) عن قتيبة، حدثنا جرير بن عبد الحميد، حدثنا حُصين بن عبدالرحمن، عن عمرو بن ميمون فذكره.","grade":"صحيح","chapter_ar":"باب في قبر النبي ﷺ وأبي بكر وعمر رضي الله عنهما","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1392).","chapter_en":"About the grave of the Prophet ﷺ, Abū Bakr, and ʿUmar","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":17,"content":{"translation":{"en":["ʿAmr ibn Maymūn al-Awdī said: I saw ʿUmar ibn al-Khaṭṭāb, may Allah be pleased with him, say: “O ʿAbdullāh ibn ʿUmar, go to the Mother of the Believers, ʿĀ’ishah, may Allah be pleased with her, and say: ʿUmar ibn al-Khaṭṭāb sends you greetings of peace, then ask her permission that I may be buried with my two companions.” She said: “I had wanted that place for myself, but today I will prefer him over myself.” When he returned, he said to him: “What do you have?” He said: “She has given you permission, O Commander of the Believers.” He said: “Nothing was more important to me than that resting place. When I die, carry me, then give salām, then say: ʿUmar ibn al-Khaṭṭāb asks permission. If she gives me permission, then bury me there. Otherwise, return me to the graveyards of the Muslims. I do not know anyone more deserving of this matter than those men with whom the Messenger of Allah ﷺ died while pleased with them. So whoever they appoint after me is the caliph; listen to him and obey him.” Then he named ʿUthmān, ʿAlī, Ṭalḥah, al-Zubayr, ʿAbd al-Raḥmān ibn ʿAwf, and Saʿd ibn Abī Waqqāṣ. Then a young man from the Anṣār entered and said: “Receive glad tidings, O Commander of the Believers, of good from Allah. You had the early honor in Islam that is well known, then you were made leader and ruled justly, and now martyrdom after all that.” He said: “I wish, my nephew, that it may be neither against me nor for me.” I advise the caliph after me to treat the earliest Emigrants well, to recognize their rights, and to preserve their honor. I also advise him to treat the Anṣār well, those who settled in the home and embraced faith, that he accept from their good-doers and pardon their wrong-doers. And I advise him regarding the protection granted by Allah and the protection granted by His Messenger ﷺ: that their covenant be fulfilled, that fighting be done in defense of them, and that they not be burdened beyond their capacity."]}},"tuhfa":{},"full":1,"rep":[7698],"tks":"صحيح: رواه البخاري (1392)."},{"num":3818,"demo":false,"sanad":"","matn":["قَالَتْ لِعَبْدِ اللَّهِ بْنِ الزُّبَيْرِ: ادْفِنِّي مَعَ صَوَاحِبِي، وَلاَ تَدْفِنِّي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْبَيْتِ، فَإِنِّي أَكْرَهُ أَنْ أُزَكَّى."],"takhrij":"صحيح: رواه البخاري في الاعتصام (7327) عن عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في قبر النبي ﷺ وأبي بكر وعمر رضي الله عنهما","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (7327).","chapter_en":"About the grave of the Prophet ﷺ, Abū Bakr, and ʿUmar","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":17,"content":{"translation":{"en":["ʿĀ’ishah said to ʿAbdullāh ibn al-Zubayr: “Bury me with my female companions, and do not bury me with the Prophet ﷺ in the house, for I dislike that I be praised on account of that.”"]},"buhuth":{"en":["Her phrase “that I be praised” means: that people would speak highly of me because of that and consider it a special distinction and virtue for me."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7327)."},{"num":3819,"demo":false,"sanad":"","matn":["عَنْ سُفْيَانَ التَّمَّارِ، أَنَّهُ حَدَّثَهُ أَنَّهُ، رَأَى قَبْرَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُسَنَّمًا."],"takhrij":"صحيح: رواه البخاري في الجنائز (1390.2) عن محمد بن مقاتل، أخبرنا عبدالله، أخبرنا أبو بكر بن عياش، عن سفيان التمار فذكره.","grade":"صحيح","chapter_ar":"باب في قبر النبي ﷺ وأبي بكر وعمر رضي الله عنهما","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1390).","chapter_en":"About the grave of the Prophet ﷺ, Abū Bakr, and ʿUmar","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":17,"content":{"translation":{"en":["Sufyān al-Tammār reported that he saw the grave of the Prophet ﷺ raised in a rounded shape."]},"buhuth":{"en":["The phrase “raised in a rounded shape” means elevated.","This does not contradict the description “leveled with the red gravel of the courtyard.” Rather, the meaning is that it was slightly raised and covered with the red gravel of the open ground, not built up and not plastered. The graves of his two companions were like that as well."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1390)."},{"num":3820,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُلْحِدَ، لَهُ وَنُصِبَ عَلَيْهِ اللَّبِنُ نَصَبًا، وَرُفِعَ قَبْرُهُ مِنَ الأَرْضِ نَحْوًا مِنْ شِبْرٍ."],"takhrij":"صحيح: رواه ابن حبان (6635)، والبيهقي (6736) كلاهما من طريق أبي كامل الجحدري، حدثنا الفُضيل بن سليمان، حدثنا جعفر بن محمد، عن أبيه، عن جابر بن عبدالله فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في قبر النبي ﷺ وأبي بكر وعمر رضي الله عنهما","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Ḥibbān (6635), al-Bayhaqī (3/410).","chapter_en":"About the grave of the Prophet ﷺ, Abū Bakr, and ʿUmar","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":17,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Prophet ﷺ was buried in a burial niche, bricks were set over him, and his grave was raised above the ground by about a handspan."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (6635)، والبيهقي (6736)."},{"num":3821,"demo":false,"sanad":"","matn":["عَنْ أَوْسِ بْنِ أَوْسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ، فِيهِ خُلِقَ آدَمُ، وَفِيهِ قُبِضَ، وَفِيهِ النَّفْخَةُ، وَفِيهِ الصَّعْقَةُ، فَأَكْثِرُوا عَلَىَّ مِنَ الصَّلاَةِ فِيهِ، فَإِنَّ صَلاَتَكُمْ مَعْرُوضَةٌ عَلَىَّ. قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ! وَكَيْفَ تُعْرَضُ صَلاَتُنَا عَلَيْكَ وَقَدْ أَرِمْتَ؟ يَقُولُونَ: بَلِيتَ. فَقَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ عَلَى الأَرْضِ أَجْسَادَ الأَنْبِيَاءِ."],"takhrij":"صحيح: رواه أبو داود (1047)، والنسائي (1374)، وابن ماجه (1636) كلهم من طريق عبدالرحمن بن يزيد بن جابر، عن أبي الأشعث الصنعاني،عن أوس بن أوس فذكره.","grade":"صحيح","chapter_ar":"باب إن الله حرَّم على الأرض أن تأكل أجساد الأنبياء","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (1047), al-Nasā’ī (1374), Ibn Mājah (1636).","chapter_en":"Allah has forbidden the earth from consuming the bodies of the prophets","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":18,"content":{"translation":{"en":["Aws ibn Aws said: The Messenger of Allah ﷺ said: “Among your best days is Friday. On it Adam was created, on it he died, on it the Trumpet will be blown, and on it the fainting blast will occur. So send many prayers upon me on that day, for your prayers are presented to me.” They said: “O Messenger of Allah ﷺ, how will our prayers be presented to you when you have decayed?” meaning: when you have become dust? He said: “Allah, Mighty and Majestic, has forbidden the earth from consuming the bodies of the prophets.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[685,3238,10750,10873,16132],"tks":"صحيح: رواه أبو داود (1047)، والنسائي (1374)، وابن ماجه (1636)."},{"num":3822,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَرَرْتُ عَلَى مُوسَى لَيْلَةَ أُسْرِيَ بِي عِنْدَ الْكَثِيبِ الْأَحْمَرِ، وَهُوَ قَائِمٌ يُصَلِّي فِي قَبْرِهِ ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2375) من طريق عن حماد بن سلمة، عن ثابت البناني وسليمان التيمي، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب أن الأنبياء أحياء في قبورهم يصلون","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (2375).","chapter_en":"The prophets are alive in their graves and praying","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":19,"content":{"translation":{"en":["Anas ibn Mālik reported that the Messenger of Allah ﷺ said: “On the night I was taken on the Night Journey, I passed by Mūsā near the red sand hill, and he was standing and praying in his grave.”"]}},"tuhfa":{},"full":1,"rep":[683],"tks":"صحيح: رواه مسلم (2375)."},{"num":3823,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْأَنْبِيَاءُ أَحْيَاءٌ فِي قُبُورِهِمْ يُصَلُّونَ."],"takhrij":"حسن: رواه أبو يعلى في مسنده (3425) عن أبي الجهم الأزرق بن علي، ثنا يحيى بن أبي بكير، ثنا المستلم بن سعيد، عن الحجاج، عن ثابت، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب أن الأنبياء أحياء في قبورهم يصلون","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Yaʿlā in his Musnad (3425).","chapter_en":"The prophets are alive in their graves and praying","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":19,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “The prophets are alive in their graves, praying.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى في مسنده (3425)."},{"num":3824,"demo":false,"sanad":"","matn":["عَنْ هَانِئٍ، - مَوْلَى عُثْمَانَ - قَالَ: كَانَ عُثْمَانُ بْنُ عَفَّانَ إِذَا وَقَفَ عَلَى قَبْرٍ يَبْكِي حَتَّى يَبُلَّ لِحْيَتَهُ، فَقِيلَ لَهُ: تَذْكُرُ الْجَنَّةَ وَالنَّارَ وَلاَ تَبْكِي، وَتَبْكِي مِنْ هَذَا؟ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْقَبْرَ أَوَّلُ مَنَازِلِ الآخِرَةِ، فَإِنْ نَجَا مِنْهُ فَمَا بَعْدَهُ أَيْسَرُ مِنْهُ، وَإِنْ لَمْ يَنْجُ مِنْهُ، فَمَا بَعْدَهُ أَشَدُّ مِنْهُ. قَالَ: وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا رَأَيْتُ مَنْظَرًا قَطُّ إِلاَّ وَالْقَبْرُ أَفْظَعُ مِنْهُ."],"takhrij":"حسن: رواه الترمذي (2308)، وابن ماجه (4267) كلاهما من حديث يحيى بن معين، قال: حدثنا هشام بن يوسف، عن عبدالله بن بَحير، عن هانئ مولى عثمان فذكره.","grade":"حسن","chapter_ar":"باب إن القبر أول منازل الآخرة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Tirmidhī (2308), who graded it Ḥasan, and Ibn Mājah (4267).","chapter_en":"The grave is the first stage of the Hereafter","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Hānī’, the freedman of ʿUthmān, said: Whenever ʿUthmān ibn ʿAffān stood at a grave, he would weep until his beard became wet. It was said to him: “You remember Paradise and the Fire and do not weep, yet you weep because of this?” He said: The Messenger of Allah ﷺ said: “The grave is the first stage of the Hereafter. If a person is saved from it, then what comes after it is easier than it. But if he is not saved from it, then what comes after it is harder than it.” He also said: The Messenger of Allah ﷺ said: “I have never seen any sight except that the grave is more terrifying than it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15111],"tks":"حسن: رواه الترمذي (2308) وحسنه، وابن ماجه (4267)."},{"num":3825,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْعَبْدُ إِذَا وُضِعَ فِي قَبْرِهِ، وَتُوُلِّيَ وَذَهَبَ أَصْحَابُهُ حَتَّى إِنَّهُ لَيَسْمَعُ قَرْعَ نِعَالِهِمْ، أَتَاهُ مَلَكَانِ، فَأَقْعَدَاهُ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1338)، ومسلم في صفة الجنة (2870/71) كلاهما من حديث يزيد بن زُريع، حدثنا سعيد بن أبي عروبة، عن قتادة، عن أنس بن مالك فذكره ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب إن الميت يسمع خفق النعال","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1338) and Muslim (2870).","chapter_en":"The deceased hears the sound of sandals","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ said: “When the servant is placed in his grave and his companions turn away and leave, he hears the sound of their sandals. Two angels then come to him and make him sit up. They ask him: ‘What did you used to say about this man, Muḥammad ﷺ?’ He says: ‘I testify that he is the servant of Allah and His Messenger.’ It is then said to him: ‘Look at your place in the Fire; Allah has replaced it for you with a place in Paradise.’” The Prophet ﷺ said: “He will see both of them.” “As for the disbeliever—or the hypocrite—he will say: ‘I do not know. I used to say what the people used to say.’ It will be said: ‘You neither knew nor followed.’ Then he will be struck between his ears with an iron hammer, and he will scream with a cry that will be heard by everything near him except humans and jinn.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1338)، ومسلم (2870)."},{"num":3826,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَنَازَةِ رَجُلٍ مِنَ الأَنْصَارِ، فَانْتَهَيْنَا إِلَى الْقَبْرِ، وَلَمَّا يُلْحَدْ، فَجَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَلَسْنَا حَوْلَهُ كَأَنَّمَا عَلَى رُءُوسِنَا الطَّيْرُ، وَفِي يَدِهِ عُودٌ يَنْكُتُ بِهِ فِي الأَرْضِ، فَرَفَعَ رَأْسَهُ فَقَالَ: اسْتَعِيذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ. مَرَّتَيْنِ أَوْ ثَلاَثًا - زَادَ فِي حَدِيثِ جَرِيرٍ هَا هُنَا - وَقَالَ: وَإِنَّهُ لَيَسْمَعُ خَفْقَ نِعَالِهِمْ إِذَا وَلَّوْا مُدْبِرِينَ حِينَ يُقَالُ لَهُ: يَا هَذَا مَنْ رَبُّكَ؟ وَمَا دِينُكَ؟ وَمَنْ نَبِيُّكَ."],"takhrij":"حسن: رواه أبو داود (4753) عن عثمان بن أبي شيبة، حدثنا جرير، ح وحدثنا هناد بن السري، قال: حدثنا معاوية، وهذا لفظ هناد - عن الأعمش، عن المنهال، عن زاذان، عن البراء بن عازب فذكره في حديث طويل.","grade":"حسن","chapter_ar":"باب إن الميت يسمع خفق النعال","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (4753).","chapter_en":"The deceased hears the sound of sandals","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Al-Barā’ ibn ʿĀzib said: We went out with the Messenger of Allah ﷺ in the funeral of a man from the Anṣār. We came to the grave before the burial niche had been made, so the Messenger of Allah ﷺ sat, and we sat around him as though birds were on our heads. In his hand was a stick with which he scratched the ground. Then he raised his head and said: “Seek refuge in Allah from the punishment of the grave,” two or three times. In the narration of Jarīr there is an addition here: “He hears the sound of their sandals when they turn away and leave, at the time when it is said to him: O this one, who is your Lord? What is your religion? Who is your prophet?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4753)."},{"num":3827,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ الْمَيِّتَ يسمع خَفْقَ نِعَالِهِمْ إِذَا ولَّوا عَنْهُ يَعْنِي مُدْبِرِينَ."],"takhrij":"حسن: رواه البزار كشف الأستار (873) عن محمد بن عبدالله المخرمي، ثنا وكيع بن الجراح، ثنا سفيان – يعني الثوري، عن السُدِّي، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب إن الميت يسمع خفق النعال","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bazzār in Kashf al-Astār (873).","chapter_en":"The deceased hears the sound of sandals","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “The deceased hears the sound of their sandals when they turn away from him,” meaning when they depart."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (873)."},{"num":3828,"demo":false,"sanad":"","matn":["عَنْ أَبِي طَلْحَةَ، أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ يَوْمَ بَدْرٍ بِأَرْبَعَةٍ وَعِشْرِينَ رَجُلاً مِنْ صَنَادِيدِ قُرَيْشٍ فَقُذِفُوا فِي طَوِيٍّ مِنْ أَطْوَاءِ بَدْرٍ خَبِيثٍ مُخْبِثٍ، وَكَانَ إِذَا ظَهَرَ عَلَى قَوْمٍ أَقَامَ بِالْعَرْصَةِ ثَلاَثَ لَيَالٍ، فَلَمَّا كَانَ بِبَدْرٍ الْيَوْمَ الثَّالِثَ، أَمَرَ بِرَاحِلَتِهِ فَشُدَّ عَلَيْهَا رَحْلُهَا، ثُمَّ مَشَى، وَاتَّبَعَهُ أَصْحَابُهُ وَقَالُوا: مَا نُرَى يَنْطَلِقُ إِلاَّ لِبَعْضِ حَاجَتِهِ، حَتَّى قَامَ عَلَى شَفَةِ الرَّكِيِّ، فَجَعَلَ يُنَادِيهِمْ بِأَسْمَائِهِمْ وَأَسْمَاءِ آبَائِهِمْ: يَا فُلاَنُ بْنَ فُلاَنٍ، وَيَا فُلاَنُ بْنَ فُلاَنٍ، أَيَسُرُّكُمْ أَنَّكُمْ أَطَعْتُمُ اللَّهَ وَرَسُولَهُ؟ ﴿فَإِنَّا قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا، فَهَلْ وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حَقًّا﴾. [سورة الأعراف: 44]","قَالَ: فَقَالَ عُمَرُ: يَا رَسُولَ اللَّهِ! مَا تُكَلِّمُ مِنْ أَجْسَادٍ لاَ أَرْوَاحَ لَهَا، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ .."],"takhrij":"متفق عليه: رواه البخاري في المغازي (3976)، ومسلم في الجنة (2875) كلاهما من حديث رَوح بن عُبادة، حدثنا سعيد بن أبي عروبة، عن قتادة، عن أنس ابن مالك، عن أبي طلحة فذكر الحديث واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سماع الموتى","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (3976), Muslim (2875), and this is the wording of al-Bukhārī.","chapter_en":"What is reported about the hearing of the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Abū Ṭalḥah reported that on the day of Badr, the Prophet of Allah ﷺ ordered that twenty-four men from the chiefs of Quraysh be thrown into one of the foul wells of Badr. When he overcame a people, he would stay in the battlefield area for three nights. So when the third day at Badr came, he ordered his riding animal to be saddled, then he walked, and his companions followed him. They said: “We think he is only going out for some need,” until he stood at the edge of the well and began calling them by their names and the names of their fathers: “O so-and-so son of so-and-so, O so-and-so son of so-and-so, would it have pleased you if you had obeyed Allah and His Messenger? We have indeed found what our Lord promised us to be true, so have you found what your Lord promised you to be true?” Then ʿUmar said: “O Messenger of Allah ﷺ, are you speaking to bodies that have no souls?”","So the Messenger of Allah ﷺ said: “By the One in whose hand is the soul of Muhammad, you do not hear what I am saying any better than they do.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3976)، ومسلم (2875)، واللفظ للبخاري."},{"num":3829,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَخْبَرَهُ قَالَ: اطَّلَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَهْلِ الْقَلِيبِ فَقَالَ: وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حَقًّا. فَقِيلَ لَهُ: تَدْعُو أَمْوَاتًا؟ فَقَالَ: مَا أَنْتُمْ بِأَسْمَعَ مِنْهُمْ، وَلَكِنْ لاَ يُجِيبُونَ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1370) عن علي بن عبدالله، حدثنا يعقوب بن إبراهيم، حدثني، أبي، عن صالح، حدثني نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في سماع الموتى","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1370).","chapter_en":"What is reported about the hearing of the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar said: The Prophet ﷺ looked over the people of the well and said: “Have you found what your Lord promised you to be true?” It was said to him: “Are you calling out to the dead?” He said: “You do not hear better than they do, but they cannot answer.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1370)."},{"num":3830,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بن الْخَطَّابِ قَالَ: ثُمَّ أمر النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فطرحوا فِي بِئْرٍ، فَانْطَلَقَ إِلَيْهِمْ فَقَالَ: يَا فُلَانَ بْنَ فُلَانٍ، يَا فُلَانَ بْنَ فُلَانٍ، هَلْ وَجَدْتُمْ مَا وَعَدَكُمُ اللهُ وَرَسُولُهُ حَقًّا؟ فَإِنِّي قَدْ وَجَدْتُ مَا وَعَدَنِي اللهُ حقاً قُلْتُ: يَا رَسُولَ اللَّهِ! كَيْفَ تُكَلِّمُ أَجْسَادًا لَا أَرْوَاحَ فِيهَا؟ قَالَ: مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ، غَيْرَ أَنَّهُمْ لَا يَسْتَطِيعُونَ أَنْ يَرُدُّوا عَلَيَّ شَيْئًا ."],"takhrij":"صحيح: رواه مسلم في الجنة (2873) من طرق عن سليمان بن المغيرة، عن ثابت، عن أنس بن مالك، عن عمر بن الخطاب فذكره في قصة مصارع أهل بدر.","grade":"صحيح","chapter_ar":"باب ما جاء في سماع الموتى","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (2873).","chapter_en":"What is reported about the hearing of the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb said: Then the Prophet ﷺ ordered that they be thrown into a well. Then he went to them and said: “O so-and-so son of so-and-so, O so-and-so son of so-and-so, have you found what Allah and His Messenger promised you to be true? For I have indeed found what Allah promised me to be true.” I said: “O Messenger of Allah ﷺ, how can you speak to bodies that have no souls in them?” He said: “You do not hear what I am saying any better than they do, except that they are unable to respond to me.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2873)."},{"num":3831,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَرَكَ قَتْلَى بَدْرٍ ثَلَاثًا ثُمَّ أَتَاهُمْ فَقَامَ عَلَيْهِمْ فَنَادَاهُمْ فَقَالَ: يَا أَبَا جَهْلِ بْنَ هِشَامٍ، يَا أُمَيَّةَ ابن خَلَفٍ، يَا عُتْبَةَ بْنَ رَبِيعَةَ، يَا شَيْبَةَ بْنَ رَبِيعَةَ، أَلَيْسَ قَدْ وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حقاً؟ فَإِنِّي قَدْ وَجَدْتُ مَا وَعَدَنِي رَبِّي حقاًّ ، فَسَمِعَ عُمَرُ قَوْلَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ: يَا رَسُولَ اللَّهِ! كَيْفَ يَسْمَعُوا، وأنَّى يُجِيبُوا وَقَدْ جيَّفوا؟ قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : وَالَّذِي نَفْسِي بِيَدِهِ مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ، وَلَكِنَّهُمْ لَا يَقْدِرُونَ أَنْ يُجِيبُوا ثُمَّ أَمَرَ بِهِمْ فَسُحِبُوا فَأُلْقُوا فِي قَلِيبِ بدرٍ."],"takhrij":"صحيح: رواه مسلم في الجنة (2874) من طريق حماد بن سلمة، عن ثابت البناني، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في سماع الموتى","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (2874).","chapter_en":"What is reported about the hearing of the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ left the slain of Badr for three days, then came to them and stood over them and called out, saying: “O Abū Jahl ibn Hishām, O Umayyah ibn Khalaf, O ʿUtbah ibn Rabīʿah, O Shaybah ibn Rabīʿah, have you found what your Lord promised you to be true? For I have indeed found what my Lord promised me to be true.” ʿUmar heard the words of the Prophet ﷺ and said: “O Messenger of Allah ﷺ, how can they hear, and how can they answer, when they have already decayed?” The Prophet ﷺ said: “By the One in whose hand is my soul, you do not hear what I am saying any better than they do, but they are not able to answer.” Then he ordered that they be dragged and thrown into the well of Badr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2874)."},{"num":3832,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ بن الزُّبَيْرِ قَالَ: ذُكِرَ عِنْدَ عَائِشَةَ أَنَّ ابْنَ عُمَرَ يَرْفَعُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ الْمَيِّتَ يُعذَّب فِي قَبْرِهِ بِبُكَاءِ أَهْلِهِ عَلَيْهِ فَقَالَتْ: وَهِل، إِنَّمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّهُ لَيُعذَّب بِخَطِيئَتِهِ وذنبه، وَإِنَّ أَهْلَهُ لَيَبْكُونَ عَلَيْهِ الْآنَ وَذَلِكَ مِثْلُ قَوْلِهِ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ عَلَى الْقَلِيبِ يَوْمَ بَدْرٍ، وَفِيهِ قَتْلَى بَدْرٍ مِنَ الْمُشْرِكِينَ فَقَالَ لَهُمْ مَا قَالَ: إِنَّهُمْ يسمعون مَا أَقُولُ وَقَدْ وَهِل، إِنَّمَا قَالَ: إِنَّهُمْ الْآنَ لَيَعْلَمُونَ أَنَّ مَا كُنْتُ أَقُولُ لَهُمْ حَقٌّ ثُمَّ قَرَأَتْ: إِنَّكَ لَا تُسْمِعُ الْمَوْتَى [النمل: 80]، ﴿وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ﴾ [فاطر: 22] يَقُولُ: حِينَ تبؤوا مَقَاعِدَهُمْ مِنَ النَّارِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (3978)، ومسلم في الجنائز (932) كلاهما من طريق أبي أسامة، عن هشام بن عروة، عن أبيه فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء من إنكار عائشة على سماع الموتى","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (3978), Muslim (932).","chapter_en":"What is reported of ʿĀ’ishah’s objection regarding the hearing of the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr said: It was mentioned in the presence of ʿĀ’ishah that Ibn ʿUmar was attributing to the Prophet ﷺ the statement: “The deceased is punished in his grave because of the crying of his family over him.” She said: He was mistaken. Rather, the Messenger of Allah ﷺ said: “He is being punished because of his own sin and wrongdoing, while his family is now crying over him.” And this is like what was said about the statement that the Messenger of Allah ﷺ stood over the well on the day of Badr, in which the slain of Badr from the polytheists had been thrown, and said to them what he said: “They hear what I am saying.” She said: He was mistaken. Rather, he said: “They now know that what I used to say to them was true.” Then she recited: “You cannot make the dead hear” [al-Naml 27:80], and “You cannot make those in the graves hear” [Fāṭir 35:22], meaning: when they had already taken their places in the Fire."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3978)، ومسلم (932)."},{"num":3833,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّهُ قَالَ: وَقَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْقَلِيبِ يَوْمَ بَدْرٍ فَقَالَ: يَا فُلَانُ يَا فُلَانُ، هَلْ وَجَدْتُمْ مَا وَعَدَكُمْ رَبُّكُمْ حَقًّا؟ أَمَا وَاللهِ إِنَّهُمُ الْآنَ لَيَسْمَعُونَ كَلَامِي، قَالَ يَحْيَى: فَقَالَتْ عَائِشَةُ: غَفَرَ اللَّهُ لِأَبِي عَبْدِ الرَّحْمَنِ إِنَّهُ وَهِلَ، إِنَّمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَاللهِ إِنَّهُمْ لَيَعْلَمُونَ الْآنَ أَنَّ الَّذِي كُنْتُ أَقُولُ لَهُمْ حَقًّا، وَإِنَّ اللَّهَ تَعَالَى يَقُولُ: ﴿إِنَّكَ لَا تُسْمِعُ الْمَوْتَى﴾ [النمل: ٨٠] وَ﴿وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ﴾ [فاطر:"],"takhrij":"حسن: رواه الإمام أحمد (4864) عن يزيد، أخبرنا محمد –يعني ابن عمرو، عن يحيى بن عبدالرحمن بن حاطب، أنه حدثهم عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من إنكار عائشة على سماع الموتى","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: narrated by Aḥmad (4864).","chapter_en":"What is reported of ʿĀ’ishah’s objection regarding the hearing of the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ stood over the well on the day of Badr and said: “O so-and-so, O so-and-so, have you found what your Lord promised you to be true? By Allah, they now hear my words.” Yaḥyā said: Then ʿĀ’ishah said: “May Allah forgive Abū ʿAbd al-Raḥmān. He made a mistake. Rather, the Messenger of Allah ﷺ said: ‘By Allah, they now know that what I used to say to them was the truth.’” And Allah the Exalted says: “You cannot make the dead hear” [al-Naml 27:80], and “You cannot make those in the graves hear” [Fāṭir 35:22]."]},"buhuth":{"en":["Fiqh of the hadith:","What ʿĀ’ishah understood as a contradiction between the verse and the hadith was also understood by some of the Companions, because they were surprised by the Prophet’s statement ﷺ: “O so-and-so son of so-and-so, have you found what your Lord promised you to be true?” even though the bodies had already decayed. So the Prophet ﷺ answered that they were hearing at that moment. This hadith shows that something outside the normal pattern occurred in that specific case.","Because of that, it is also established that ʿĀ’ishah later returned to the view of those narrations, since Ibn Isḥāq narrated in al-Maghāzī with a good chain from ʿĀ’ishah something similar to the hadith of Abū Ṭalḥah, containing the words: “You do not hear what I say any better than they do.” Aḥmad narrated it with a hasan chain."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (4864)."},{"num":3834,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ رَضِيَ اللَّهُ عَنْهُمْ قَالَ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ وَجَبَتِ الشَّمْسُ، فَسَمِعَ صَوْتًا فَقَالَ: يَهُودُ تُعَذَّبُ فِي قُبُورِهَا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1375)، ومسلم في صفة الجنة والنار (2869) كلاهما من حديث شعبة، عن عون بن أبي جحيفة، عن أبيه، عن البراء بن عازب، عن أبي أيوب فذكر الحديث. واللفظ للبخاري، ولفظ مسلم قريب منه وفيه: خرج رسوله صلى الله عليه وسلم بعد ما غربت الشمس .","grade":"متفق عليه","chapter_ar":"باب إثبات عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1375), Muslim (2869). This is the wording of al-Bukhārī, and Muslim has a close wording, including: “The Messenger of Allah ﷺ went out after the sun had set.”","chapter_en":"Affirmation of the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["Abū Ayyūb al-Anṣārī said: The Prophet ﷺ went out after the sun had set, then he heard a sound and said: “Jews are being punished in their graves.”"]},"buhuth":{"en":["The phrase “the sun had set” means it had dropped below the horizon."]},"intro":{"ar":["قال اللّٰه تعالى: (سَنُعَذِّبُهُم مَرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ) [سورة التوبة: ١٠١].","قوله:  مرتين  إحداهما في الدنيا، والأخرى في القبر.","وقوله:  إلى عذاب عظيم  عذاب جهنم.","وقال تعالى: (وَحَاقَ بِآلِ فِرْعَوْنَ سُوءُ ٱلْعَذَابِ ۝ ٱلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ ٱلسَّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ ٱلْعَذَابِ) [سورة غافر: ٤٥-٤٦].","قوله:  بآل فرعون  أتباعه وأهل طاعته.","وقوله:  وحاق  أي نزل وحلَّ.","وقوله:  النار يُعرضون عليها غدوًّا وعشيًّا  أي أنهم في القبر يُعرضون على النار صباحًا ومساءً إلى أن تقوم الساعة.","وقوله:  أدخلوا آل فرعون أشد العذاب  وذلك يوم القيامة."],"en":["Allah the Exalted said: “We will punish them twice, then they will be returned to a great punishment.” [al-Tawbah 9:101]","The phrase “twice” means: once in this world, and the second time in the grave.","And the phrase “to a great punishment” means: the punishment of Hell.","And He said: “And there encompassed the people of Pharaoh the worst punishment: the Fire, they are exposed to it morning and evening, and on the Day the Hour is established: Enter the people of Pharaoh into the severest punishment.” [Ghāfir 40:45–46]","The phrase “the people of Pharaoh” means his followers and those who obeyed him.","The phrase “there encompassed” means it descended upon them and settled on them.","The phrase “they are exposed to it morning and evening” means they are shown the Fire in the grave every morning and evening until the Hour begins.","And the phrase “Enter the people of Pharaoh into the severest punishment” refers to the Day of Resurrection."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1375)، ومسلم (2869). واللفظ للبخاري، ولفظ مسلم قريب منه، وفيه: (( خرج رسول الله ﷺ بعد ما غربت الشمس ))."},{"num":3835,"demo":false,"sanad":"","matn":["عن أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ أَنَّهَا قَالَتْ: أَتَيْتُ عَائِشَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حِينَ خَسَفَتِ الشَّمْسُ، فَإِذَا النَّاسُ قِيَامٌ يُصَلُّونَ، وَإِذَا هِيَ قَائِمَةٌ تُصَلِّي، فَقُلْتُ: مَا لِلنَّاسِ؟ فَأَشَارَتْ بِيَدِهَا نَحْوَ السَّمَاءِ، وَقَالَتْ: سُبْحَانَ اللَّهِ. فَقُلْتُ: آيَةٌ؟ فَأَشَارَتْ: أَىْ نَعَمْ. فَقُمْتُ حَتَّى تَجَلاَّنِي الْغَشْىُ، وَجَعَلْتُ أَصُبُّ فَوْقَ رَأْسِي مَاءً، فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: مَا مِنْ شَىْءٍ كُنْتُ لَمْ أَرَهُ إِلاَّ قَدْ رَأَيْتُهُ فِي مَقَامِي هَذَا، حَتَّى الْجَنَّةِ وَالنَّارِ، وَلَقَدْ أُوحِيَ إِلَىَّ أَنَّكُمْ تُفْتَنُونَ فِي الْقُبُورِ مِثْلَ أَوْ قَرِيبًا مِنْ فِتْنَةِ الدَّجَّالِ ـ لاَ أَدْرِي أَىَّ ذَلِكَ قَالَتْ أَسْمَاءُ، ـ يُؤْتَى أَحَدُكُمْ فَيُقَالُ مَا عِلْمُكَ بِهَذَا الرَّجُلِ فَأَمَّا الْمُؤْمِنُ ـ أَوِ الْمُوقِنُ لاَ أَدْرِي أَىَّ ذَلِكَ قَالَتْ أَسْمَاءُ ـ فَيَقُولُ: هُوَ مُحَمَّدٌ رَسُولُ اللَّهِ، جَاءَنَا بِالْبَيِّنَاتِ وَالْهُدَى، فَأَجَبْنَا وَآمَنَّا وَاتَّبَعْنَا، فَيُقَالُ نَمْ صَالِحًا، فَقَدْ عَلِمْنَا إِنْ كُنْتَ لَمُؤْمِنًا، وَأَمَّا الْمُنَافِقُ، ـ أَوِ الْمُرْتَابُ لاَ أَدْرِي أَىَّ ذَلِكَ قَالَتْ أَسْمَاءُ ـ فَيَقُولُ: لاَ أَدْرِي، سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُهُ."],"takhrij":"متفق عليه: رواه مالك في الكسوف (4) عن هشام بن عروة، عن فاطمة بنت المنذر، عن أسماء بنت أبي بكر فذكرته. ورواه البخاري في الوضوء (184) وفي الكسوف (1053) من طريقين عن مالك بإسناده.","grade":"متفق عليه","chapter_ar":"باب إثبات عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (4), al-Bukhārī (86, 184), Muslim (905).","chapter_en":"Affirmation of the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["Asmā’ bint Abī Bakr, may Allah be pleased with them both, said: I came to ʿĀ’ishah, the wife of the Prophet ﷺ, at the time of the solar eclipse, and the people were standing in prayer, and she too was standing praying. I said: “What is happening with the people?” She pointed with her hand toward the sky and said, “Glory be to Allah.” I said: “A sign?” She indicated yes. She said: So I stood until faintness almost overcame me, and I began pouring water over my head. When the Messenger of Allah ﷺ finished, he praised Allah and extolled Him, then said: “There is nothing I had not seen before except that I have now seen it in this place of mine, even Paradise and the Fire. And it has been revealed to me that you will be tested in your graves with a trial like — or close to — the trial of the Dajjāl.” Asmā’ said: I do not know which of the two phrases she said. “One of you will be brought and asked: What knowledge did you have of this man? As for the believer — or the one with certainty —” Asmā’ said: I do not know which one she said, “he will say: Muhammad is the Messenger of Allah ﷺ. He came to us with clear proofs and guidance, so we answered, believed, and followed. Then it will be said to him: Sleep in peace. We knew that you were a person of certainty. But as for the hypocrite — or the doubtful one —” Asmā’ said: I do not know which one she said, “he will say: I do not know. I heard people saying something, so I said it too.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (4)، والبخاري (86، 184)، ومسلم (905)."},{"num":3836,"demo":false,"sanad":"","matn":["عن أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا تَقُولُ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطِيبًا فَذَكَرَ فِتْنَةَ الْقَبْرِ الَّتِي يَفْتَتِنُ فِيهَا الْمَرْءُ، فَلَمَّا ذَكَرَ ذَلِكَ ضَجَّ الْمُسْلِمُونَ ضَجَّةً."],"takhrij":"صحيح: رواه البخاري في الجنائز (1373) عن يحيى بن سليمان، حدثنا ابن وهب، قال: أخبرني يونس، عن ابن شهاب، أخبرني عروة بن الزبير، أنه سمع أسماء بنت أبي بكر تقول: فذكرته.","grade":"صحيح","chapter_ar":"باب إثبات عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1373).","chapter_en":"Affirmation of the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["Asmā’ bint Abī Bakr said: The Messenger of Allah ﷺ stood delivering a sermon and mentioned the trial of the grave in which a person is tested. When he mentioned that, the Muslims cried out loudly."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1373)."},{"num":3837,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللهَ أَنْ يُسْمِعَكُمْ مِنْ عَذَابِ الْقَبْرِ."],"takhrij":"صحيح: رواه مسلم في كتاب الجنة (2868) من طرق عن محمد بن جعفر، حدثنا شعبة، عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب إثبات عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (2868).","chapter_en":"Affirmation of the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ said: “Were it not that you would stop burying one another, I would have asked Allah to let you hear some of the punishment of the grave.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2868)."},{"num":3838,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: دَخَلَتْ عَلَىَّ عَجُوزَانِ مِنْ عُجُزِ يَهُودِ الْمَدِينَةِ فَقَالَتَا لِي: إِنَّ أَهْلَ الْقُبُورِ يُعَذَّبُونَ فِي قُبُورِهِمْ، فَكَذَّبْتُهُمَا، وَلَمْ أُنْعِمْ أَنْ أُصَدِّقَهُمَا، فَخَرَجَتَا، وَدَخَلَ عَلَىَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ لَهُ يَا رَسُولَ اللَّهِ! إِنَّ عَجُوزَيْنِ وَذَكَرْتُ لَهُ، فَقَالَ: صَدَقَتَا، إِنَّهُمْ يُعَذَّبُونَ عَذَابًا تَسْمَعُهُ الْبَهَائِمُ كُلُّهَا. فَمَا رَأَيْتُهُ بَعْدُ فِي صَلاَةٍ إِلاَّ تَعَوَّذَ مِنْ عَذَابِ الْقَبْرِ."],"takhrij":"متفق عليه: رواه البخاري في الدّعوات (6366)، ومسلم في المساجد (586/125) كلاهما من حديث جرير، عن منصور، عن أبي وائل، عن مسروق، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب إثبات عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6366) and Muslim (586).","chapter_en":"Affirmation of the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["ʿĀʾishah reported: Two elderly Jewish women of Madinah entered upon me and said: “The inhabitants of the graves are punished in their graves.” I rejected what they said and was unwilling to believe them. They left, and the Prophet ﷺ entered upon me. I said: “O Messenger of Allah ﷺ, two elderly women…” and I told him what they had said. He replied: “They spoke the truth. They are punished with a punishment that all the animals can hear.” After that, I never saw him perform a prayer except that he sought refuge from the punishment of the grave."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6366)، ومسلم (586)."},{"num":3839,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ:  دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدِي امْرَأَةٌ مِنَ الْيَهُودِ وَهِْيَ تَقُولُ: هَلْ شَعَرْتِ أَنَّكُمْ تُفْتَنُونَ فِي الْقُبُورِ؟ قَالَتْ: فَارْتَاعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ! وَقَالَ: إِنَّمَا تُفْتَنُ يَهُودُ قَالَتْ عَائِشَةُ: فَلَبِثْنَا لَيَالِيَ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ شَعَرْتِ أَنَّهُ أُوحِيَ إِلَيَّ أَنَّكُمْ تُفْتَنُونَ فِي الْقُبُورِ؟ قَالَتْ عَائِشَةُ: فَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدُ يَسْتَعِيذُ مِنْ عَذَابِ الْقَبْرِ."],"takhrij":"صحيح: رواه مسلم في المساجد (584) من طرق عن يونس بن يزيد، عن ابن شهاب، قال: حدثني عروة بن الزبير، أن عائشة قالت فذكرته.","grade":"صحيح","chapter_ar":"باب إثبات عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (584).","chapter_en":"Affirmation of the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah said: The Messenger of Allah ﷺ entered upon me while a Jewish woman was with me, and she was saying: “Do you realize that you are tested in the graves?” ʿĀ’ishah said: The Messenger of Allah ﷺ was alarmed and said: “It is only the Jews who are tested.” She said: Then we remained for some nights, and after that the Messenger of Allah ﷺ said: “Do you realize that it has been revealed to me that you are tested in the graves?” ʿĀ’ishah said: Then afterward I heard the Messenger of Allah ﷺ seeking refuge from the punishment of the grave."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (584)."},{"num":3840,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ يَهُودِيَّةً كَانَتْ تَخْدُمُهَا، فَلَا تَصْنَعُ عَائِشَةُ إِلَيْهَا شَيْئًا مِنَ الْمَعْرُوفِ، إِلَّا قَالَتْ لَهَا الْيَهُودِيَّةُ: وَقَاكِ اللهُ عَذَابَ الْقَبْرِ، قَالَتْ: فَدَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيَّ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، هَلْ لِلْقَبْرِ عَذَابٌ قَبْلَ يَوْمِ الْقِيَامَةِ؟ قَالَ: لَا، وَعَمَّ ذَاكَ؟ قَالَتْ: هَذِهِ الْيَهُودِيَّةُ لَا نَصْنَعُ إِلَيْهَا مِنَ الْمَعْرُوفِ شَيْئًا، إِلَّا قَالَتْ: وَقَاكِ اللهُ عَذَابَ الْقَبْرِ، قَالَ: كَذَبَتْ يَهُودُ، وَهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ أَكْذَبُ، لَا عَذَابَ دُونَ يَوْمِ الْقِيَامَةِ، قَالَتْ: ثُمَّ مَكَثَ بَعْدَ ذَاكَ مَا شَاءَ اللَّهُ أَنْ يَمْكُثَ، فَخَرَجَ ذَاتَ يَوْمٍ نِصْفَ النَّهَارِ مُشْتَمِلًا بِثَوْبِهِ، مُحْمَرَّةً عَيْنَاهُ، وَهُوَ يُنَادِي بِأَعْلَى صَوْتِهِ: أَيُّهَا النَّاسُ، أَظَلَّتْكُمُ الْفِتَنُ كَقِطَعِ اللَّيْلِ الْمُظْلِمِ، أَيُّهَا النَّاسُ، لَوْ تَعْلَمُونَ مَا أَعْلَمُ، بَكَيْتُمْ كَثِيرًا، وَضَحِكْتُمْ قَلِيلًا، أَيُّهَا النَّاسُ، اسْتَعِيذُوا بِاللهِ مِنْ عَذَابِ الْقَبْرِ، فَإِنَّ عَذَابَ الْقَبْرِ حَقٌّ."],"takhrij":"صحيح: رواه الإمام أحمد (24520) عن هاشم، قال: حدثنا إسحاق بن سعيد، قال: حدثنا سعيد، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب إثبات عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Aḥmad (24520).","chapter_en":"Affirmation of the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah reported that a Jewish woman used to serve her, and whenever ʿĀ’ishah did any act of kindness for her, the Jewish woman would say: “May Allah protect you from the punishment of the grave.” She said: Then the Messenger of Allah ﷺ entered upon me, so I said: “O Messenger of Allah ﷺ, is there punishment in the grave before the Day of Resurrection?” He said: “No. Why do you ask that?” She said: “This Jewish woman — whenever we do any kindness for her, she says: ‘May Allah protect you from the punishment of the grave.’” He said: “The Jews lied, and they are the greatest liars against Allah. There is no punishment before the Day of Resurrection.” She said: Then after that he remained for as long as Allah willed. Then one day, around midday, he went out wrapped in his garment, with his eyes reddened, calling out at the top of his voice: “O people, the trials have drawn near like pieces of a dark night. O people, if you knew what I know, you would laugh little and weep much. O people, seek refuge in Allah from the punishment of the grave, for the punishment of the grave is true.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (24520)."},{"num":3841,"demo":false,"sanad":"","matn":["عن زَيْدِ بن ثَابِتٍ قَالَ: بَيْنَمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَائِطٍ لِبَنِي النَّجَّارِ عَلَى بَغْلَةٍ لَهُ، وَنَحْنُ مَعَهُ، إِذْ حَادَتْ بِهِ، فَكَادَتْ تُلْقِيهِ، وَإِذَا أَقْبُرٌ سِتَّةٌ أَوْ خَمْسَةٌ أَوْ أَرْبَعَةٌ. قَالَ: كَذَا كَانَ يَقُولُ الْجُرَيْرِيُّ. فَقَالَ: مَنْ يَعْرِفُ أَصْحَابَ هَذِهِ الْأَقْبُرِ؟ فَقَالَ رَجُلٌ: أَنَا. قَالَ: فَمَتَى مَاتَ هَؤُلَاءِ؟ قَالَ: مَاتُوا فِي الْإِشْرَاكِ. فَقَالَ: إِنَّ هَذِهِ الْأُمَّةَ تُبْتَلَى فِي قُبُورِهَا، فَلَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللهَ أَنْ يُسْمِعَكُمْ مِنْ عَذَابِ الْقَبْرِ الَّذِي أَسْمَعُ مِنْهُ. ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ: تَعَوَّذُوا بِاللهِ مِنْ عَذَابِ النَّارِ. قَالُوا: نَعُوذُ بِاللهِ مِنْ عَذَابِ النَّارِ. فَقَالَ: تَعَوَّذُوا بِاللهِ مِنْ عَذَابِ الْقَبْرِ. قَالُوا: نَعُوذُ بِاللهِ مِنْ عَذَابِ الْقَبْرِ. قَالَ: تَعَوَّذُوا بِاللهِ مِنَ الْفِتَنِ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ. قَالُوا: نَعُوذُ بِاللهِ مِنَ الْفِتَنِ، مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ. قَالَ: تَعَوَّذُوا بِاللهِ مِنْ فِتْنَةِ الدَّجَّالِ. قَالُوا: نَعُوذُ بِاللهِ مِنْ فِتْنَةِ الدَّجَّالِ."],"takhrij":"صحيح: رواه مسلم في كتاب الجنة (2867) من طرق عن سعيد الجُريري، عن أبي نضرة، عن أبي سعيد الخدري، عن زيد بن ثابت.","grade":"صحيح","chapter_ar":"باب أن أهل الجاهلية يُعذَّبون في قبورهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (2867).","chapter_en":"The people of the pre-Islamic age are punished in their graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Zayd ibn Thābit said: While the Prophet ﷺ was in an enclosed garden belonging to Banū al-Najjār on a mule of his, and we were with him, it suddenly shied and nearly threw him off. Then there were graves there, six or five or four — this is how al-Jurayrī narrated it — and he said: “Who knows the occupants of these graves?” A man said: “I do.” He said: “When did these people die?” He said: “They died in polytheism.” He said: “This ummah is tested in its graves. Were it not that you would stop burying one another, I would ask Allah to let you hear some of the punishment of the grave that I hear.” Then he turned his face toward us and said: “Seek refuge in Allah from the punishment of the Fire.” They said: “We seek refuge in Allah from the punishment of the Fire.” He said: “Seek refuge in Allah from the punishment of the grave.” They said: “We seek refuge in Allah from the punishment of the grave.” He said: “Seek refuge in Allah from trials, both outward and inward.” They said: “We seek refuge in Allah from trials, both outward and inward.” He said: “Seek refuge in Allah from the trial of the Dajjāl.” They said: “We seek refuge in Allah from the trial of the Dajjāl.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2867)."},{"num":3842,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ نَخْلًا لِبَنِي النَّجَّارِ، فَسَمِعَ صَوْتًا فَفَزِعَ، فَقَالَ: مَنْ أَصْحَابُ هَذِهِ الْقُبُورِ؟ قَالُوا: يَا نَبِيَّ اللَّهِ: نَاسٌ مَاتُوا فِي الْجَاهِلِيَّةِ، قَالَ: تَعَوَّذُوا بِاللهِ مِنْ عَذَابِ الْقَبْرِ، وَعَذَابِ النَّارِ، وَفِتْنَةِ الدَّجَّالِ قَالُوا: وَمَا ذَاكَ يَا رَسُولَ اللَّهِ؟","قال: إنَّ هذه الأمة تُبْتَلى في قُبُورِها، فإنَّ المؤمن إذا وُضِعَ في قبره، أتاه مَلَكٌ فسَأَلَهُ: ما كنتَ تَعْبُدُ؟ فإنِ اللهُ هدَاهُ قال: كنتُ أعبدالله، فيُقالُ له: ما كنتَ تقولُ في هذا الرجل؟ قال: فيقولُ: هو عبدالله ورسولُه، قال: فما يُسأَلُ عن شيءٍ غيرَها، فيُنْطَلَقُ به إلى بيتٍ كانَ له في النار، فيُقال له: هذا بَيْتُكَ كانَ في النار، ولكِنَّ الله عَصَمَكَ ورَحِمَكَ، فأَبدَلَكَ به بيتاً في الجَنَّةِ، فيقولُ: دَعُوني حتَّى أذهبَ فأُبَشِّرَ أَهلِي، فيُقالُ له: اسْكُنْ .","وَإِنَّ الْكَافِرَ إِذَا وُضِعَ فِي قَبْرِهِ، أَتَاهُ مَلَكٌ فَيَقُولُ لَهُ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ؟ فَيَقُولُ: كُنْتُ أَقُولُ مَا يَقُولُ النَّاسُ، فَيَضْرِبُهُ بِمِطْرَاقٍ مِنْ حَدِيدٍ بَيْنَ أُذُنَيْهِ، فَيَصِيحُ صَيْحَةً فَيَسْمَعُهَا الْخَلْقُ غَيْرَ الثَّقَلَيْنِ .."],"takhrij":"صحيح: رواه أحمد (13447) عن عبد الوهاب، حدثنا سعيد بن أبي عروبة، عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب أن أهل الجاهلية يُعذَّبون في قبورهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Aḥmad (13447). Muslim also narrated it in shorter form (2870/72) without mentioning the story of those who died in the pre-Islamic period.","chapter_en":"The people of the pre-Islamic age are punished in their graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ entered a palm grove belonging to Banū al-Najjār, and he heard a sound and became alarmed. He said: “Who are the occupants of these graves?” They said: “O Prophet of Allah ﷺ, people who died in the time of ignorance.” He said: “Seek refuge in Allah from the punishment of the grave, the punishment of the Fire, and the trial of the Dajjāl.” They said: “What is that, O Messenger of Allah ﷺ?” He said: “This ummah is tested in its graves. When the believer is placed in his grave, an angel comes to him and asks him: What did you worship? If Allah guided him, he says: I used to worship Allah. Then it is said to him: What did you used to say about this man? He says: He is the servant of Allah and His Messenger. He is not asked about anything else after that. Then he is taken to a house that had been for him in the Fire, and it is said to him: This was your house in the Fire, but Allah protected you and had mercy on you, so He replaced it for you with a house in Paradise. Then he says: Let me go so I may give glad tidings to my family. It is said to him: Remain where you are.”","“And when the disbeliever is placed in his grave, an angel comes to him and says: What did you used to say about this man? He says: I used to say what people said. Then he is struck with an iron hammer between his ears, and he lets out a scream that all creation hears except humans and jinn.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (13447). ورواه مسلم (2870/72) مختصرا، ولم يذكر فيه قصة الجاهلية."},{"num":3843,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَ صَوْتًا مِنْ قَبْرٍ فَقَالَ: مَتَى مَاتَ هَذَا. قَالُوا: مَاتَ فِي الْجَاهِلِيَّةِ. فَسُرَّ بِذَلِكَ وَقَالَ: لَوْلاَ أَنْ لاَ تَدَافَنُوا لَدَعَوْتُ اللَّهَ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ."],"takhrij":"صحيح: رواه النسائي (2058) عن سويد بن نصر، قال: حدثنا عبدالله، عن حُميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب أن أهل الجاهلية يُعذَّبون في قبورهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (2058), authenticated by Ibn Ḥibbān (3126).","chapter_en":"The people of the pre-Islamic age are punished in their graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ heard a sound coming from a grave and said: “When did this person die?” They said: “He died in the pre-Islamic period.” So he was relieved by that and said: “Were it not that you would stop burying one another, I would ask Allah to let you hear the punishment of the grave.”"]},"buhuth":{"en":["In Aḥmad’s narration (12007), Anas said: The Prophet ﷺ entered one of the gardens of Madinah belonging to Banū al-Najjār and heard a sound from a grave, so he asked about it and the same account was mentioned. His going out was for relieving himself, as stated in another narration of Imām Aḥmad (12096) with an authentic chain."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2058)، وصححه ابن حبان (3126)."},{"num":3844,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: أَخْبَرَنِي بَعْضُ مَنْ لَا أَتَّهِمُهُ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: بَيْنَمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبِلَالٌ يَمْشِيَانِ بِالْبَقِيعِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا بِلَالُ، هَلْ تَسْمَعُ مَا أَسْمَعُ؟ قَالَ: لَا، وَاللهِ يَا رَسُولَ اللَّهِ، مَا أَسْمَعُهُ، قَالَ: أَلَا تَسْمَعُ أَهْلَ هَذِهِ الْقُبُورِ يُعَذَّبُونَ؟ يَعْنِي قُبُورَ الْجَاهِلِيَّةِ."],"takhrij":"حسن: رواه الإمام أحمد (13719) عن سُريج، حدثنا فُليح، عن هلال ابن علي، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب أن أهل الجاهلية يُعذَّبون في قبورهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: narrated by Imām Aḥmad (13719).","chapter_en":"The people of the pre-Islamic age are punished in their graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik said: Someone among the Companions of the Prophet ﷺ, whom I do not suspect, informed me that while the Messenger of Allah ﷺ and Bilāl were walking in al-Baqīʿ, the Messenger of Allah ﷺ said: “O Bilāl, do you hear what I hear?” He said: “No, by Allah, O Messenger of Allah ﷺ, I do not hear it.” He said: “Do you not hear the people of these graves being punished?” meaning the graves from the pre-Islamic period."]},"buhuth":{"en":["The mention of al-Baqīʿ in this hadith is objectionable, because there were no graves from the pre-Islamic period there."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (13719)."},{"num":3845,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: بَيْنَمَا نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَخْلٍ لَنَا، نَخْلٌ لِأَبِي طَلْحَةَ يَتَبَرَّزُ لِحَاجَتِهِ، قَالَ: وَبِلَالٌ يَمْشِي وَرَاءَهُ، يُكَرِّمُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَمْشِيَ إِلَى جَنْبِهِ، فَمَرَّ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَبْرٍ، فَقَامَ حَتَّى تَمَّ إِلَيْهِ بِلَالٌ، فَقَالَ: وَيْحَكَ يَا بِلَالُ، هَلْ تَسْمَعُ مَا أَسْمَعُ؟ قَالَ: مَا أَسْمَعُ شَيْئًا. قَالَ: صَاحِبُ الْقَبْرِ يُعَذَّبُ. قَالَ: فَسُئِلَ عَنْهُ، فَوُجِدَ يَهُودِيًّا."],"takhrij":"صحيح: رواه الإمام أحمد (12530) عن عبد الصّمد، حدثني أبي، حدثنا عبدالعزيز، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب أن أهل الجاهلية يُعذَّبون في قبورهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: narrated by Imām Aḥmad (12530).","chapter_en":"The people of the pre-Islamic age are punished in their graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Anas said: While the Prophet of Allah ﷺ was in one of our palm groves, one belonging to Abū Ṭalḥah, relieving himself, and Bilāl was walking behind him out of respect for the Prophet of Allah ﷺ so as not to walk beside him, the Prophet of Allah ﷺ passed by a grave and stopped until Bilāl caught up with him. Then he said: “Woe to you, O Bilāl, do you hear what I hear?” He said: “I do not hear anything.” He said: “The occupant of this grave is being punished.” He said: Then inquiry was made about him, and he was found to have been a Jew."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (12530)."},{"num":3846,"demo":false,"sanad":"","matn":["عَنْ أُمِّ مُبَشِّرٍ، قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَنَا فِي حَائِطٍ مِنْ حَوَائِطِ بَنِي النَّجَّارِ، فِيهِ قُبُورٌ، مِنْهُمْ، قَدْ مُوِّتُوا فِي الْجَاهِلِيَّةِ، فَسَمِعَهُمْ وَهُمْ يُعَذَّبُونَ، فَخَرَجَ وَهُوَ يَقُولُ: اسْتَعِيذُوا بِاللهِ مِنْ عَذَابِ الْقَبْرِ. قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، وَإِنَّهُمْ لَيُعَذَّبُونَ فِي قُبُورِهِمْ؟ قَالَ: نَعَمْ، عَذَابًا تَسْمَعُهُ الْبَهَائِمُ."],"takhrij":"صحيح: رواه الإمام أحمد (27044)، والطبراني في الكبير (25/103)، والبيهقي في إثبات عذاب القبر (108) كلهم من طريق أبي معاوية قال: حدثنا الأعمش، عن أبي سفيان، عن جابر، عن أم مبشر فذكرته.","grade":"صحيح","chapter_ar":"باب أن أهل الجاهلية يُعذَّبون في قبورهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Imām Aḥmad (27044), al-Ṭabarānī in al-Kabīr (25/103).","chapter_en":"The people of the pre-Islamic age are punished in their graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Umm Mubashshir said: The Messenger of Allah ﷺ entered upon me while I was in one of the gardens of Banū al-Najjār, in which there were graves of people who had died in the pre-Islamic period. He heard them while they were being punished, then he came out saying: “Seek refuge in Allah from the punishment of the grave.” She said: I asked, “O Messenger of Allah ﷺ, are they really being punished in their graves?” He said: “Yes, with a punishment that the animals hear.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (27044)، والطبراني في الكبير (25/103)."},{"num":3847,"demo":false,"sanad":"","matn":["عن جابر بْنِ عبدالله يَقُولُ: دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا نَخْلًا لِبَنِي النَّجَّارِ، فَسَمِعَ أَصْوَاتَ رِجَالٍ مِنْ بَنِي النَّجَّارِ مَاتُوا فِي الْجَاهِلِيَّةِ، يُعَذَّبُونَ فِي قُبُورِهِمْ، فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَزِعًا، فَأَمَرَ أَصْحَابَهُ أَنْ يَتَعَوَّذُوا مِنْ عَذَابِ الْقَبْرِ."],"takhrij":"حسن: رواه أحمد (14152) عن عبد الرزاق – وهو في مصنفه (6742) قال: أخبرنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب أن أهل الجاهلية يُعذَّبون في قبورهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (14152), and ʿAbd al-Razzāq in his Muṣannaf (6742).","chapter_en":"The people of the pre-Islamic age are punished in their graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: One day the Prophet ﷺ entered a palm grove of Banū al-Najjār and heard the voices of men from Banū al-Najjār who had died in the pre-Islamic period being punished in their graves. The Prophet ﷺ came out alarmed and commanded his companions to seek refuge from the punishment of the grave."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (14152)، وعبد الرزاق في مصنفه (6742)."},{"num":3848,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  مَرَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَبْرَيْنِ، فَقَالَ: أَمَا إِنَّهُمَا لَيُعَذَّبَانِ. وَمَا يُعَذَّبَانِ فِي كَبِيرٍ، أَمَّا أَحَدُهُمَا فَكَانَ يَمْشِي بِالنَّمِيمَةِ، وَأَمَّا الْآخَرُ فَكَانَ لَا يَسْتَتِرُ مِنْ بَوْلِهِ. قَالَ: فَدَعَا بِعَسِيبٍ رَطْبٍ فَشَقَّهُ بِاثْنَيْنِ، ثُمَّ غَرَسَ عَلَى هَذَا وَاحِدًا، وَعَلَى هَذَا وَاحِدًا، ثُمَّ قَالَ: لَعَلَّهُ أَنْ يُخَفَّفَ عَنْهُمَا مَا لَمْ يَيْبَسَا.","وفي رواية: وَكَانَ الْآخَرُ لَا يَسْتَنْزِهُ عَنِ الْبَوْلِ، أَوْ مِنَ الْبَوْلِ .."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (218)، وفي الجنائز bukhari(1361)، ومسلم في الطهارة (292) كلاهما من طريق الأعمش، قال: سمعت مجاهداً يحدِّث عن طاوس، عن ابن عباس... فذكر الحديث. واللفظ لمسلم، وفي لفظ البخاري: ثم أخذ جريدة رطبة... وفيه أيضاً: قالوا: يا رسول الله لم صنعت هذا؟ فقال: لعله أن يخفف عنهما ما لم ييبسا .","grade":"متفق عليه","chapter_ar":"باب ما جاء أن أكثر عذاب القبر من البول والنميمة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (218, 1361), Muslim (292), and this is the wording of Muslim.","chapter_en":"What is reported that most of the punishment of the grave is from urine and tale-bearing","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās said: The Messenger of Allah ﷺ passed by two graves and said: “Indeed, they are both being punished, and they are not being punished for something people would consider major. One of them used to go about spreading gossip, and the other used not to protect himself from his urine.” He then called for a fresh palm stalk, split it into two, planted one piece on this grave and one piece on that grave, then said: “Perhaps it will be lightened for them as long as they do not dry out.” In another narration: “And the other one did not cleanse himself from urine,” or, “from his own urine.”"]},"buhuth":{"ar":["وفي لفظ البخاري: ثم أخذ جريدةً رطبة… وفيه أيضًا: قالوا: يا رسولَ اللّٰه ﷺ، لِمَ صنعتَ هذا؟ فقال:  لعله أن يُخفَّف عنهما ما لم ييبسا ."],"en":["In al-Bukhārī’s wording: Then he took a fresh branch… and in it they said: “O Messenger of Allah ﷺ, why did you do this?” He said: “Perhaps it may lighten it for them as long as they do not dry out.”"]}},"tuhfa":{},"full":1,"rep":[1423,13602],"tks":"متفق عليه: رواه البخاري (218، 1361)، ومسلم (292)، واللفظ لمسلم."},{"num":3849,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: قال رسول الله صلى الله عليه وسلم: إني مررت بقبرين يعذبان، فأحببت بشفاعتي أن يُرَفَّه عنهما ما دام الغصنان رطبين ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (3012) قال: حدثنا هارون بن معروف ومحمد بن عباد، قالا: حدثنا حاتم بن إسماعيل، عن يعقوب بن مجاهد أبي حزرة، عن عبادة بن الوليد بن عبادة بن الصامت، عن جابر بن عبد الله في حديث طويل. وسيأتي كاملا في موضعه.","grade":"صحيح","chapter_ar":"باب ما جاء أن أكثر عذاب القبر من البول والنميمة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (3012).","chapter_en":"What is reported that most of the punishment of the grave is from urine and tale-bearing","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Messenger of Allah ﷺ said: “I passed by two graves whose occupants were being punished, and I wished that through my intercession it might be eased for them as long as the two branches remained fresh.”"]},"buhuth":{"ar":["هذا خاصٌّ بالنبي ﷺ؛ لأنه أولًا أُعلم بعذابهما، ثم سأل الشفاعة لهما، فأُجيبت شفاعتُه بالتخفيف عنهما إلى أن ييبسا."],"en":["This is specific to the Prophet ﷺ, because first he was informed of their punishment, then he asked intercession on their behalf, and his intercession was accepted by lightening their punishment until the branches dried out."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (3012)."},{"num":3850,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ قَالَ: بَيْنَمَا أَنَا أُمَاشِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ آخِذٌ بِيَدِي، وَرَجُلٌ عَنْ يَسَارِهِ، فَإِذَا نَحْنُ بِقَبْرَيْنِ أَمَامَنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ، وَبَلَى، فَأَيُّكُمْ يَأْتِينِي بِجَرِيدَةٍ؟ فَاسْتَبَقْنَا، فَسَبَقْتُهُ، فَأَتَيْتُهُ بِجَرِيدَةٍ، فَكَسَرَهَا نِصْفَيْنِ، ألقي عَلَى ذَا الْقَبْرِ قِطْعَةً، وَعَلَى ذَا الْقَبْرِ قِطْعَةً، وَقَالَ: إِنَّهُ يُهوَّنُ عَلَيْهِمَا مَا كانا رَطْبَتَيْنِ، وَمَا يُعدَّبان إِلَّا فِي الْبَوْلِ وَالْغِيبَةِ ."],"takhrij":"حسن: رواه أحمد (20373) عن أبي سعيد مولى بني هاشم، والبزَّار (3636)، من طريق مسلم بن إبراهيم، كلاهما – أعني أبا سعيد ومسلم بن إبراهيم – عن الأسود بن شيبان، عن بحر بن مرَار، عن عبدالرحمن بن أبي بكرة، عن أبي بكرة.. فذكر الحديث، وهذا إسناد حسن متصل؛ إن بحر بن مرَّار سمع عن جده عبدالرحمن بن أبي بكرة.","grade":"حسن","chapter_ar":"باب ما جاء أن أكثر عذاب القبر من البول والنميمة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan due to supporting narrations: Aḥmad (20373), al-Bazzār (3636).","chapter_en":"What is reported that most of the punishment of the grave is from urine and tale-bearing","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Abū Bakrah said: While I was walking with the Messenger of Allah ﷺ and he was holding my hand, with another man on his left, we came upon two graves in front of us. The Messenger of Allah ﷺ said: “Indeed, they are being punished, and they are not being punished for something considered major — rather, yes. Which of you will bring me a palm branch?” So we hurried to do so, and I beat the other man and brought him a branch. He broke it into two halves and placed one piece on this grave and one piece on that grave, and said: “It will be made lighter for them as long as the two pieces remain fresh, and they are only being punished because of urine and backbiting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20373)، والبزار (3636)."},{"num":3851,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما، أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  قَالَ: إِنَّ عَامَّةَ عَذَابِ الْقَبْرِ مِنَ الْبَوْلِ فَتَنَزَّهُوا مِنَ الْبَوْلِ."],"takhrij":"حسن: رواه البزار كشف الأستار (243)، والطبراني في الكبير (11120)، والحاكم (1/183-184) كلهم من طريق إسرائيل، عن أبي يحيى، عن مجاهد، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن أكثر عذاب القبر من البول والنميمة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bazzār in Kashf al-Astār (243), and al-Ṭabarānī in al-Kabīr (11/84).","chapter_en":"What is reported that most of the punishment of the grave is from urine and tale-bearing","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: The Messenger of Allah ﷺ said: “Most of the punishment of the grave is because of urine, so protect yourselves from urine.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (243)، والطبراني في الكبير (11069)."},{"num":3852,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَكْثَرُ عَذَابِ الْقَبْرِ مِنَ الْبَوْلِ."],"takhrij":"صحيح: رواه ابن ماجه (348) عن أبي بكر بن أبي شيبة – وهو في مصنفه (1/122) قال: حدثنا عفان، حدثنا أبو عوانة، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن أكثر عذاب القبر من البول والنميمة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Mājah (348), and Abū Bakr ibn Abī Shaybah in his Muṣannaf (1/122).","chapter_en":"What is reported that most of the punishment of the grave is from urine and tale-bearing","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “Most of the punishment of the grave is from urine.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1424],"tks":"صحيح: رواه ابن ماجه (348)، وأبو بكر بن أبي شيبة في مصنفه (42)."},{"num":3853,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كُنَّا نَمْشِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَرَرْنَا عَلَى قَبْرَيْنِ، فَقَامَ، فَقُمْنَا مَعَهُ، فَجَعَلَ لَوْنُهُ يَتَغَيَّرُ حَتَّى رَعَدَ كُمُّ قَمِيصِهِ، فَقُلْنَا: مَا لَكَ يَا نَبِيَّ اللَّهِ؟ قَالَ: مَا تَسْمَعُونَ مَا أَسْمَعُ؟ قُلْنَا: وَمَا ذَاكَ يَا نَبِيَّ اللَّهِ؟ قَالَ: هَذَانِ رَجُلَانِ يُعَذَّبَانِ فِي قُبُورِهِمَا عَذَابًا شَدِيدًا فِي ذَنْبٍ هَيِّنٍ، قُلْنَا: فِيمَ ذَلِكَ يَا نَبِيَّ اللَّهِ؟ قَالَ: كَانَ أَحَدُهُمَا لَا يَسْتَنْزِهُ مِنَ الْبَوْلِ، وَكَانَ الآخَرُ يُؤْذِي النَّاسَ بِلِسَانِهِ، وَيَمْشِي بَيْنَهُمْ بِالنَّمِيمَةِ، فَدَعَا بِجَرِيدَتَيْنِ مِنْ جَرَائِدِ النَّخْلِ، فَجَعَلَ فِي كُلِّ قَبْرٍ وَاحِدَةً، قُلْنَا: وَهَلْ يَنْفَعُهُمَا ذَلِكَ يَا رَسُولَ اللَّهِ؟ قَالَ: نَعَمْ، يُخَفِّفُ عَنْهُمَا مَا دَامَتَا رَطْبَتَيْنِ."],"takhrij":"صحيح: رواه ابن حبان (824) قال: أخبرنا أبو عروبة، قال: حدثنا محمد بن وهب بن أبي كريمة، قال: حدثنا محمد بن سلمة، عن أبي عبد الرحيم، قال: حدثني زيد بن أبي أُنيْسة، عن المنهال بن عمرو، عن عبدالله بن الحارث، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء أن أكثر عذاب القبر من البول والنميمة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Ḥibbān (824).","chapter_en":"What is reported that most of the punishment of the grave is from urine and tale-bearing","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah said: We were walking with the Messenger of Allah ﷺ, and we passed by two graves. He stopped, so we stopped with him. His color began to change until even the sleeve of his shirt trembled. So we said: “What is the matter, O Prophet of Allah ﷺ?” He said: “Do you hear what I hear?” We said: “And what is that, O Prophet of Allah ﷺ?” He said: “These are two men being punished in their graves with a severe punishment for a small sin.” We said: “Why is that, O Prophet of Allah ﷺ?” He said: “One of them would not cleanse himself from urine, and the other used to harm people with his tongue and go about among them with tale-bearing.” Then he called for two palm branches and placed one on each grave. We said: “Will that benefit them, O Messenger of Allah ﷺ?” He said: “Yes. It will be lightened for them as long as they remain fresh.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (824)."},{"num":3854,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: مَرَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَبْرٍ، فَقَالَ: ائْتُونِي بِجَرِيدَتَيْنِ، فَجَعَلَ إِحْدَاهُمَا عِنْدَ رَأْسِهِ، وَالْأُخْرَى عِنْدَ رِجْلَيْهِ، فَقِيلَ: يَا نَبِيَّ اللَّهِ، أَيَنْفَعُهُ ذَلِكَ؟ قَالَ: لَنْ يَزَالَ يُخَفَّفَ عَنْهُ بَعْضُ عَذَابِ الْقَبْرِ مَا كَانَ فِيهِمَا نُدُوٌّ."],"takhrij":"حسن: رواه أحمد (9686) عن محمد بن عبيد، عن يزيد –يعني ابن كيسان، عن أبي حازم، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن أكثر عذاب القبر من البول والنميمة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (9686).","chapter_en":"What is reported that most of the punishment of the grave is from urine and tale-bearing","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ passed by a grave and said: “Bring me two palm branches.” Then he placed one at its head and the other at its feet. It was said: “O Prophet of Allah ﷺ, will that benefit him?” He said: “Some of the punishment of the grave will continue to be lightened for him as long as there is moisture in them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (9686)."},{"num":3855,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ حُنَيْنٍ فَلَمْ نَغْنَمْ ذَهَبًا وَلاَ وَرِقًا، إِلاَّ الأَمْوَالَ، الثِّيَابَ وَالْمَتَاعَ، - قَالَ، - فَأَهْدَى رِفَاعَةُ بْنُ زَيْدٍ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غُلاَمًا أَسْوَدَ، يُقَالُ لَهُ: مِدْعَمٌ، فَوَجَّهَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى وَادِي الْقُرَى، حَتَّى إِذَا كُنَّا بِوَادِي الْقُرَى، بَيْنَمَا مِدْعَمٌ يَحُطُّ رَحْلَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذْ جَاءَهُ سَهْمٌ عَائِرٌ، فَأَصَابَهُ فَقَتَلَهُ، فَقَالَ النَّاسُ، هَنِيئًا لَهُ الْجَنَّةُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَلاَّ، وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّ الشَّمْلَةَ الَّتِي أَخَذَ يَوْمَ حُنَيْنٍ مِنَ الْمَغَانِمِ لَمْ تُصِبْهَا الْمَقَاسِمُ، لَتَشْتَعِلُ عَلَيْهِ نَارًا. قَالَ فَلَمَّا سَمِعَ النَّاسُ ذَلِكَ، جَاءَ رَجُلٌ بِشِرَاكٍ أَوْ شِرَاكَيْنِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شِرَاكٌ أَوْ شِرَاكَانِ مِنْ نَارٍ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (25) عن ثور بن زيد الديلي، عن أبي الغيث سالم مولى ابن مطيع، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يُخاف من عذاب القبر في الغلول","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (25), al-Bukhārī (4234), Muslim (183).","chapter_en":"What is feared of the punishment of the grave because of stolen war booty","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah said: We went out with the Messenger of Allah ﷺ in the year of Khaybar, and we did not gain any gold or silver as spoils, only property, clothing, and goods. He said: Rifāʿah ibn Zayd gifted the Messenger of Allah ﷺ a black servant named Midʿam. Then the Messenger of Allah ﷺ headed toward Wādī al-Qurā. When we were there, Midʿam was unloading the saddle of the Messenger of Allah ﷺ when a stray arrow struck him and killed him. The people said: “Glad tidings of Paradise for him.” So the Messenger of Allah ﷺ said: “No. By the One in whose hand is my soul, the cloak that he took on the day of Khaybar from the spoils before the distribution was made is blazing upon him as fire.” He said: When the people heard that, a man came with one strap or two straps to the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said: “One strap or two straps from the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (25)، والبخاري (4234)، ومسلم (183)."},{"num":3856,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لِلْقَبْرِ ضَغْطَةٌ، لَوْ نَجَا مِنْهَا أَحَدٌ، لَنَجَا مِنْهَا سَعْدُ بْنُ مُعَاذٍ."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (3112) عن عمر بن محمد الهمداني، حدثنا بُنْدار، عن عبد الملك بن الصباح، حدثنا شعبة، عن سعد بن إبراهيم، عن نافع، عن صفية، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء إن للقبر ضغطة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Ḥibbān in his Ṣaḥīḥ (3112).","chapter_en":"What is reported that the grave has a pressing squeeze","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":9,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, reported from the Prophet ﷺ that he said: “The grave has a squeeze. If anyone were to be saved from it, Saʿd ibn Muʿādh would have been saved from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان في صحيحه (3112)."},{"num":3857,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: هَذَا الَّذِي تَحَرَّكَ لَهُ الْعَرْشُ، وَفُتِحَتْ لَهُ أَبْوَابُ السَّمَاءِ، وَشَهِدَهُ سَبْعُونَ أَلْفًا مِنَ الْمَلاَئِكَةِ، لَقَدْ ضُمَّ ضَمَّةً ثُمَّ فُرِّجَ عَنْهُ."],"takhrij":"صحيح: رواه النسائي (2055) عن إسحاق بن إبراهيم، قال: حدثنا عمرو بن محمد العَنْقري، قال: حدثنا ابن إدريس، عن عبيدالله، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء إن للقبر ضغطة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (2055).","chapter_en":"What is reported that the grave has a pressing squeeze","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar reported from the Messenger of Allah ﷺ that he said: “This is the one for whom the Throne shook, for whom the gates of heaven were opened, and whom seventy thousand angels attended. He was indeed given a squeeze, then relief was given to him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[484],"tks":"صحيح: رواه النسائي (2055)."},{"num":3858,"demo":false,"sanad":"","matn":["عن أَبِي أَيُّوبَأَنْ صَبِيًّا دُفِنَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ أَفْلَتَ أَحَدٌ مِنْ ضَمَّةِ الْقَبْرِ لَأَفْلَتَ هَذَا الصَّبِيُّ."],"takhrij":"حسن: رواه الطبراني في الكبير (3858) عن الحسين بن إسحاق التستري، ثنا عثمان بن أبي شيبة، ثنا وكيع، عن حماد بن سلمة، عن ثمامة بن عبدالله بن أنس، عن البراء بن عازب، عن أبي أيوب فذكره.","grade":"حسن","chapter_ar":"باب ما جاء إن للقبر ضغطة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Kabīr (4/143).","chapter_en":"What is reported that the grave has a pressing squeeze","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":9,"content":{"translation":{"en":["Abū Ayyūb reported that a young boy was buried, and the Messenger of Allah ﷺ said: “If anyone could have escaped the squeeze of the grave, this child would have escaped it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (3843)."},{"num":3859,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى صَبِيٍّ، أَوْ صَبِيَّةٍ فَقَالَ: لَوْ كَانَ نَجَا أَحَدٌ مِنْ ضَمَّةِ الْقَبْرِ لَنَجَا هَذَا الصَّبِيُّ."],"takhrij":"حسن: رواه الطبراني في الأوسط (3774) عن إبراهيم (وهو ابن هاشم البغوي) قال: حدثنا إبراهيم بن الحجاج السامي، قال: حدثنا حماد بن سلمة، عن ثمامة بن عبدالله بن أنس، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء إن للقبر ضغطة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Awsaṭ (3774).","chapter_en":"What is reported that the grave has a pressing squeeze","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ prayed over a boy, or a girl, and said: “If anyone could have escaped the squeeze of the grave, this child would have escaped it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (3774)."},{"num":3860,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْمَيِّتَ إِذَا وُضِعَ فِي قَبْرِهِ إِنَّهُ لَيَسْمَعُ خَفْقَ نِعَالِهِمْ حِينَ يُوَلُّونَ عَنْهُ، فَإِنْ كَانَ مُؤْمِنًا، كَانَتِ الصَّلَاةُ عِنْدَ رَأْسِهِ، وَكَانَ الصِّيَامُ عَنْ يَمِينِهِ، وَكَانَتِ الزَّكَاةُ عَنْ شِمَالِهِ، وَكَانَ فِعْلُ الْخَيْرَاتِ مِنَ الصَّدَقَةِ وَالصِّلَةِ وَالْمَعْرُوفِ وَالإِحْسَانِ إِلَى النَّاسِ عِنْدَ رِجْلَيْهِ، فَيُؤْتَى مِنْ قِبَلِ رَأْسِهِ، فَتَقُولُ الصَّلَاةُ: مَا قِبَلِي مَدْخَلٌ، ثُمَّ يُؤْتَى عَنْ يَمِينِهِ، فَيَقُولُ الصِّيَامُ: مَا قِبَلِي مَدْخَلٌ، ثُمَّ يُؤْتَى عَنْ يَسَارِهِ، فَتَقُولُ الزَّكَاةُ: مَا قِبَلِي مَدْخَلٌ، ثُمَّ يُؤْتَى مِنْ قِبَلِ رِجْلَيْهِ، فَتَقُولُ فِعْلُ الْخَيْرَاتِ مِنَ الصَّدَقَةِ وَالصِّلَةِ وَالْمَعْرُوفِ وَالإِحْسَانِ إِلَى النَّاسِ: مَا قِبَلِي مَدْخَلٌ، فَيُقَالُ لَهُ: اجْلِسْ، فَيَجْلِسُ، وَقَدْ مُثِّلَتْ لَهُ الشَّمْسُ وَقَدْ أُدْنِيَتْ لِلْغُرُوبِ، فَيُقَالُ لَهُ: أَرَأَيْتَكَ هَذَا الرَّجُلَ الَّذِي كَانَ فِيكُمْ مَا تَقُولُ فِيهِ، وَمَاذَا تَشْهَدُ بِهِ عَلَيْهِ؟ فَيَقُولُ: دَعُونِي حَتَّى أُصَلِّيَ، فَيَقُولُونَ: إِنَّكَ سَتَفْعَلُ، أَخْبِرْنَا عَمَّا نَسْأَلُكُ عَنْهُ، أَرَأَيْتَكَ هَذَا الرَّجُلَ الَّذِي كَانَ فِيكُمْ مَا تَقُولُ فِيهِ، وَمَاذَا تَشْهَدُ عَلَيْهِ؟ قَالَ: فَيَقُولُ: مُحَمَّدٌ أَشْهَدُ أَنَّهُ رَسُولُ اللَّهِ، وَأَنَّهُ جَاءَ بِالْحَقِّ مِنْ عِنْدِ اللَّهِ، فَيُقَالُ لَهُ: عَلَى ذَلِكَ حَيِيتَ وَعَلَى ذَلِكَ مِتَّ، وَعَلَى ذَلِكَ تُبْعَثُ إِنْ شَاءَ اللَّهُ، ثُمَّ يُفْتَحُ لَهُ بَابٌ مِنْ أَبْوَابِ الْجَنَّةِ، فَيُقَالُ لَهُ: هَذَا مَقْعَدُكَ مِنْهَا، وَمَا أَعَدَّ اللَّهُ لَكَ فِيهَا، فَيَزْدَادُ غِبْطَةً وَسُرُورًا، ثُمَّ يُفْتَحُ لَهُ بَابٌ مِنْ أَبْوَابِ النَّارِ، فَيُقَالُ لَهُ: هَذَا مَقْعَدُكَ مِنْهَا وَمَا أَعَدَّ اللَّهُ لَكَ فِيهَا لَوْ عَصَيْتَهُ، فَيَزْدَادُ غِبْطَةً وَسُرُورًا، ثُمَّ يُفْسَحُ لَهُ فِي قَبْرِهِ سَبْعُونَ ذِرَاعًا، وَيُنَوَّرُ لَهُ فِيهِ، وَيُعَادُ الْجَسَدُ لِمَا بَدَأَ مِنْهُ، فَتُجْعَلُ نَسْمَتُهُ فِي النَّسِيمِ الطَّيِّبِ، وَهِيَ طَيْرٌ تَعْلُقُ فِي شَجَرِ الْجَنَّةِ، قَالَ: فَذَلِكَ قَوْلُهُ تَعَالَى: ﴿يُثَبِّتُ اللهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الآخِرَةِ﴾ [إبراهيم:","قال: إن الكافر إذا أُتي من قبل رأسه، لم يوجد شيء، ثم أتي عن يمينه، فلا يوجد شيء، ثم أتي عن شماله، فلا يوجد شيء، ثم أتي من قِبَلِ رجلَيْه، فلا يوجد شيء، فيقال له: اجلس، فيجلسُ خائفاً مرعوباً، فيقال له: أرأيتك هذا الرجل الذي كان فيكم ماذا تقول فيه؟ وماذا تشهد به عليه؟ فيقول: أيُّ رجل؟ فيقال: الذي كان فيكم، فلا يهتدي لاسمِه حتى يقالُ له: محمد، فيقول: ما أدري سمعتُ الناس قالوا قولاً، فقلتُ كما قال الناس، فيقال له: على ذلك حييتَ، وعلى ذلك مُتَّ، وعلى ذلك تُبْعَثُ إن شاء الله، ثم يُفْتَحُ له باب من أبواب النار، فيقال له: هذا مقعدُك من النار، وما أعدَّ الله لك فيها، فيزدادُ حسْرةً وثُبوراً، ثم يُفتح له باب من أبواب الجنة، فيقال له: ذلك مقعدك من الجنة، وما أعدَّ اللهُ لك فيه لو أطعتَه فيزدادُ حَسْرَةً وثبوراً، ثم يُضَيَّقُ عليه قبرُهُ حتى تختلِفَ فيه أضلاعُه، فتلك المعيشةُ الضَّنْكَة التي قال الله: ﴿وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكً﴾ [طه: 124]."],"takhrij":"حسن: رواه ابن حبان (3113) عن الحسن بن سفيان، قال: حدثنا عبد الواحد بن غياث، قال: حدثنا معتمر بن سليمان، قال: سمعت محمد بن عمرو يحدث عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما يكون على من أعرض عن ذكر الله تعالى من العذاب في القبر قبل عذاب يوم القيامة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Ḥibbān (3113).","chapter_en":"What happens in the grave to the one who turns away from the remembrance of Allah before the punishment of the Day of Resurrection","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah reported from the Prophet ﷺ: “When the deceased is placed in his grave, he hears the sound of their sandals as they turn away from him. If he is a believer, prayer stands by his head, fasting is on his right, zakāh is on his left, and acts of goodness such as charity, maintaining family ties, kindness, and doing good to people are by his feet. He is approached from the direction of his head, and prayer says: ‘There is no entrance from my side.’ Then he is approached from his right, and fasting says: ‘There is no entrance from my side.’ Then he is approached from his left, and zakāh says: ‘There is no entrance from my side.’ Then he is approached from the direction of his feet, and acts of goodness such as charity, family ties, kindness, and good treatment of people say: ‘There is no entrance from my side.’ Then it will be said to him: ‘Sit,’ so he sits, and the sun is represented before him as though it has been brought near to setting. Then it is said to him: ‘What do you say about this man who was among you, and what do you testify about him?’ He says: ‘Leave me so I may pray.’ They say: ‘You will do that, but tell us what we are asking you about. What do you say about this man who was among you, and what do you testify about him?’ He says: ‘Muhammad. I testify that he is the Messenger of Allah ﷺ and that he came with the truth from Allah.’ Then it is said to him: ‘Upon that you lived, upon that you died, and upon that you will be resurrected, if Allah wills.’ Then a gate from the gates of Paradise is opened for him, and it is said to him: ‘This is your place in it, and what Allah has prepared for you there,’ so he increases in joy and happiness. Then a gate from the gates of the Fire is opened for him, and it is said to him: ‘This would have been your place there and what Allah had prepared for you in it if you had disobeyed Him,’ so he increases in joy and happiness. Then his grave is widened for him by seventy cubits, and it is illuminated for him. The body is restored just as it was first created from it, and his soul is placed among the blessed souls, which are birds feeding among the trees of Paradise.’ He said: That is the meaning of the verse: ‘Allah makes firm those who believe with the firm word in the life of this world and in the Hereafter.’ [Ibrāhīm 14:27] He said: As for the disbeliever, when he is approached from the direction of his head, nothing is found. Then he is approached from his right, and nothing is found. Then from his left, and nothing is found. Then from the direction of his feet, and nothing is found. It is said to him: ‘Sit,’ so he sits in fear and terror. Then it is said to him: ‘What do you say about this man who was among you, and what do you testify about him?’ He says: ‘Which man?’ It is said: ‘The one who was among you,’ and he is not guided to his name until it is said to him: ‘Muhammad.’ Then he says: ‘I do not know. I heard people saying something, and I said what the people said.’ Then it is said to him: ‘Upon that you lived, upon that you died, and upon that you will be resurrected, if Allah wills.’ Then a gate from the gates of the Fire is opened for him, and it is said: ‘This is your place in the Fire and what Allah has prepared for you there,’ so he increases in grief and destruction. Then a gate from the gates of Paradise is opened for him, and it is said: ‘That would have been your place in Paradise and what Allah had prepared for you there if you had obeyed Him,’ so he increases in grief and destruction. Then his grave is constricted until his ribs interlock. That is the hard life that Allah mentioned: ‘Then indeed for him is a life of hardship, and We will raise him on the Day of Resurrection blind.’ [Ṭā Hā 20:124]”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (3113)."},{"num":3861,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي قَوْلِهِ تَعَالَى: فَإِنَّ لَهُ مَعِيشَةً ضَنْكً قَالَ: عَذَابُ الْقَبْرِ ."],"takhrij":"حسن: رواه ابن حبان (3119) عن أبي خليفة، حدثنا أبو الوليد، حدثنا حماد بن سلمة، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما يكون على من أعرض عن ذكر الله تعالى من العذاب في القبر قبل عذاب يوم القيامة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Ḥibbān (3119).","chapter_en":"What happens in the grave to the one who turns away from the remembrance of Allah before the punishment of the Day of Resurrection","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah reported from the Prophet ﷺ regarding the verse “Then indeed for him is a life of hardship” that he said: “It is the punishment of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (3119)."},{"num":3862,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ الْمُؤْمِنَ فِي قَبْرِهِ لَفِي رَوْضَةٍ خَضْرَاءَ، ويُرْحَبُ لَهُ قَبْرِهِ سَبْعُونَ ذِرَاعًا، وَيُنَوَّرُ لَهُ كَالْقَمَرِ لَيْلَةَ الْبَدْرِ، أَتَدْرُونَ فِيمَا أُنْزِلَتْ هَذِهِ الآيَةُ: ﴿وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكًا وَنَحْشُرُهُ يَوْمَ الْقِيَامَةِ أَعْمَى﴾ [سورة طه: 124] أَتَدْرُونَ مَا الْمَعِيشَةُ الضنكة؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ: عَذَابُ الْكَافِرِ فِي قَبْرِهِ وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّهُ يسلَّط عَلَيْهِ تِسْعَةٌ وَتِسْعُونَ تِنِّيناً، أَتَدْرُونَ مَا التِّنيِّنُ؟ سَبْعُونَ حيةً، لِكُلِّ حيةٍ سَبْعُونَ رُؤُوسٍ يلعونه، وَيَخْدِشُونَهُ إِلَى يَوْمِ الْقِيَامَةِ ."],"takhrij":"حسن: رواه ابن حبان في صحيحه (3122) عن عبدالله بن محمد بن سلْم، قال: حدثنا حرملة بن يحيى، قال: حدثنا ابن وهب، قال: أخبرني عمرو ابن الحارث، أن أبا السمح حدَّثه عن ابن حُجيرة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما يكون على من أعرض عن ذكر الله تعالى من العذاب في القبر قبل عذاب يوم القيامة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Ḥibbān in his Ṣaḥīḥ (3122).","chapter_en":"What happens in the grave to the one who turns away from the remembrance of Allah before the punishment of the Day of Resurrection","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah reported from the Messenger of Allah ﷺ: “Indeed, the believer in his grave is in a green garden. His grave is widened for him by seventy cubits, and it is illuminated for him like the moon on the night of the full moon. Do you know concerning what this verse was revealed: ‘Then indeed for him is a life of hardship, and We will raise him on the Day of Resurrection blind’? Do you know what the hard life is?” They said: “Allah and His Messenger know best.” He said: “It is the punishment of the disbeliever in his grave. By the One in whose hand is my soul, ninety-nine dragons are set upon him. Do you know what a dragon is? Seventy serpents, each serpent having seven heads, and they bite him and claw him until the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان في صحيحه (3122)."},{"num":3863,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ﴿مَعِيشَةً ضَنْكًا﴾ [طه: ١٢٤] قَالَ: عَذَابُ الْقَبْرِ."],"takhrij":"صحيح: رواه الحاكم (3439)، -وعنه البيهقي في إثبات عذاب القبر (71)- عن أبي زكريا العنبري، ثنا محمد بن عبد السلام، ثنا إسحاق، أنبأ النضر ابن شُميل، ثنا حماد بن سلمة، عن أبي حازم المدني، عن النعمان بن أبي عياش، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب ما يكون على من أعرض عن ذكر الله تعالى من العذاب في القبر قبل عذاب يوم القيامة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Ḥākim (3439), and al-Bayhaqī quoted it in Ithbāt ʿAdhāb al-Qabr (71).","chapter_en":"What happens in the grave to the one who turns away from the remembrance of Allah before the punishment of the Day of Resurrection","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":10,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said: The Messenger of Allah ﷺ said regarding “a life of hardship”: “It is the punishment of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12738],"tks":"صحيح: رواه الحاكم (3439)، وعنه البيهقي في إثبات عذاب القبر (71)."},{"num":3864,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْعَبْدَ إِذَا وُضِعَ فِي قَبْرِهِ وتولَّى عَنْهُ أَصْحَابُهُ – إنه يسمع قرعَ نِعَالِهِمْ- أَتَاهُ مَلَكَانِ فَيُقْعِدَانِهِ فَيَقُولاَنِ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ لِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ ؟ فَأَمَّا الْمُؤْمِنُ فَيَقُولُ: أَشْهَدُ أَنَّهُ عبدالله وَرَسُولُهُ، فَيُقَالُ لَهُ: انْظُرْ إِلَى مَقْعَدِكَ مِنَ النَّارِ، قَدْ أَبْدَلَكَ اللَّهُ بِهِ مَقْعَدًا مِنَ الْجَنَّةِ فَيَرَاهُمَا جَمِيعًا، وَأَمَّا الْمُنَافِقُ وَالْكَافِرُ فَيُقَالُ لَهُ: مَا كنتَ تَقُولُ فِي هَذَا الرَّجُلِ؟ فَيَقُولُ: لاَ أَدْرِي، كنتُ أَقُولُ مَا يَقُولُ النَّاسُ، فَيُقَالُ: لاَ دَريتَ وَلاَ تَلَيْتَ، وَيُضْرَبُ بِمَطَارِقَ من حَدِيدٍ ضَرْبَةً، فَيَصِيحُ صَيْحَةً يَسْمَعُهَا من يَلِيهِ غيرَ الثَّقَلَيْنِ ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1338)، ومسلم في صفة الجنة (2870/71) كلاهما من حديث يزيد بن زريع، حدثنا سعيد بن أبي عروبة، عن قتادة، عن أنس فذكره، ولفظهما قريب.","grade":"متفق عليه","chapter_ar":"باب إن المؤمن والكافر جميعًا يُسألان، وإن أهل القبور تُعرض عليهم مقاعدهم في كل يوم مرتين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1338), Muslim (2870/71).","chapter_en":"Both the believer and the disbeliever are questioned, and the people of the graves are shown their places twice each day","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik reported that the Messenger of Allah ﷺ said: “When the servant is placed in his grave and his companions turn away from him — and he hears the sound of their sandals — two angels come to him and make him sit. They say: ‘What did you used to say about this man, Muhammad?’ As for the believer, he says: ‘I testify that he is the servant of Allah and His Messenger.’ Then it is said to him: ‘Look at your place in the Fire. Allah has replaced it for you with a place in Paradise,’ and he sees both of them. As for the hypocrite and the disbeliever, it is said to him: ‘What did you used to say about this man?’ He says: ‘I do not know. I used to say what the people said.’ Then it is said: ‘You neither knew nor followed the guidance.’ Then he is struck with iron hammers a blow, and he screams a scream heard by those near him except humans and jinn.”"]},"buhuth":{"en":["In Muslim, Qatādah said: We were also told that his grave is widened for him by seventy cubits and filled with greenery until the day they are resurrected."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1338)، ومسلم (2870/71)."},{"num":3865,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ قَالَ: إن رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَحَدَكُمْ إِذَا مَاتَ عُرِضَ عَلَيْهِ مقْعَدُه بِالْغَدَاةِ وَالْعَشِيِّ، إِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ، وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ، يقال لَهُ: هَذَا مَقْعَدُكَ حَتَّى يَبْعَثَكَ اللَّهُ إِلَى يَوْمَ الْقِيَامَةِ ."],"takhrij":"متفق عليه: رواه مالك في الجنائز (47) عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب إن المؤمن والكافر جميعًا يُسألان، وإن أهل القبور تُعرض عليهم مقاعدهم في كل يوم مرتين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (47), al-Bukhārī (1379), Muslim (2866).","chapter_en":"Both the believer and the disbeliever are questioned, and the people of the graves are shown their places twice each day","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: The Messenger of Allah ﷺ said: “When one of you dies, his place is shown to him morning and evening. If he is from the people of Paradise, then he is shown a place from the people of Paradise, and if he is from the people of the Fire, then from the people of the Fire. It is said to him: This is your place until Allah resurrects you on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (47)، والبخاري (1379)، ومسلم (2866)."},{"num":3866,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ: خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي جِنَازَةِ رَجُلٍ مِنَ الْأَنْصَارِ، فَانْتَهَيْنَا إِلَى الْقَبْرِ، وَلَمَّا يُلْحَدْ، فَجَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَجَلَسْنَا حَوْلَهُ، كَأَنَّ عَلَى رُءُوسِنَا الطَّيْرَ، وَفِي يَدِهِ عُودٌ يَنْكُتُ فِي الْأَرْضِ، فَرَفَعَ رَأْسَهُ، فَقَالَ: اسْتَعِيذُوا بِاللهِ مِنْ عَذَابِ الْقَبْرِ مَرَّتَيْنِ، أَوْ ثَلَاثًا،، ثُمَّ قَالَ: إِنَّ الْعَبْدَ الْمُؤْمِنَ إِذَا كَانَ فِي انْقِطَاعٍ مِنَ الدُّنْيَا وَإِقْبَالٍ مِنَ الْآخِرَةِ، نَزَلَ إِلَيْهِ مَلَائِكَةٌ مِنَ السَّمَاءِ بِيضُ الْوُجُوهِ، كَأَنَّ وُجُوهَهُمُ الشَّمْسُ، مَعَهُمْ كَفَنٌ مِنْ أَكْفَانِ الْجَنَّةِ، وَحَنُوطٌ مِنْ حَنُوطِ الْجَنَّةِ، حَتَّى يَجْلِسُوا مِنْهُ مَدَّ الْبَصَرِ، ثُمَّ يَجِيءُ مَلَكُ الْمَوْتِ، عَلَيْهِ السلام، حَتَّى يَجْلِسَ عِنْدَ رَأْسِهِ، فَيَقُولُ: أَيَّتُهَا النَّفْسُ الطَّيِّبَةُ، اخْرُجِي إِلَى مَغْفِرَةٍ مِنَ اللَّهِ وَرِضْوَانٍ.","قَالَ: فَتَخْرُجُ تَسِيلُ كَمَا تَسِيلُ الْقَطْرَةُ مِنَ فِي السِّقَاءِ فَيَأْخُذُهَا، فَإِذَا أَخَذَهَا لَمْ يَدَعُوهَا فِي يَدِهِ طَرْفَةَ عَيْنٍ حَتَّى يَأْخُذُوهَا، فَيَجْعَلُوهَا فِي ذَلِكَ الْكَفَنِ، وَفِي ذَلِكَ الْحَنُوطِ، وَيَخْرُجُ مِنْهَا كَأَطْيَبِ نَفْحَةِ مِسْكٍ وُجِدَتْ عَلَى وَجْهِ الْأَرْضِ ..","قَالَ: فَيَصْعَدُونَ بِهَا، فلا يَمُرُّونَ –– يَعْنِي بِهَا – عَلَى مَلإٍ مِنَ الْمَلائِكَةِ إِلاَّ قَالُوا: مَا هَذَا الرُّوحُ الطِّيبُ؟! فَيَقُولُونَ: فُلاَنُ بْنُ فُلاَنٍ، بِأَحْسَنِ أَسْمَائِهِ الَّتِي كَانُوا يُسَمُّونَهُ بِهَا فِي الدُّنْيَا، حَتَّى يَنْتَهُوا بِهَا إِلَى السَّمَاءِ الدُّنْيَا، فَيَسْتَفْتِحُونَ لَهُ، فَيَفْتَحَ لهم فَيُشَيِّعَهُ مِنْ كُلِّ سَمَاءٍ مُقَرِّبُوهَا إِلَى السَّمَاءِ الَّتِي تَلِيهَا، حَتَّى يُنْتَهَى بِهِ إِلَى السَّمَاءِ السَّابِعَةِ، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: اكْتُبُوا كتاب عبدي فِي عِلِّيِّينَ، وَأُعِيدُوهُ إِلَى الأَرْضِ، فَإِنِّي مِنْهَا خَلَقْتُهُمْ، وَفِيهَا أُعِيدُهُمْ، وَمِنْهَا أَخْرَجُهُمْ تَارَةً أُخْرَى ..","قال: فتعاد روحُه في جَسَدِه، فيأتيه مَلَكان، فَيُجْلِسَانِه، فيقولان له: من رَبُّكَ؟ فيقولُ: رَبِّيَ الله، فيقولان له: ما دِينُكَ؟ فيقولُ: ديني الإسلامُ، فيقولان له: ما هذا الرَّجُلُ الذي بُعِثَ فيكُمْ؟ فيقول: هو رسولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فيقولان له: وما عِلْمُك؟ فيقول: قرأتُ كتاب الله، فآمنتُ به وصَدَّقتُ، فيُنادي منادٍ في السماء: أن صدق عبدي، فأفْرِشُوه من الجنَّةِ، وأَلْبِسُوهُ من الجنَّة، وَافْتَحُوا له باباً إلى الجنَّة .","قال: فيأتيه من رَوْحِها وطيبها، ويُفْسَحُ له في قبره مَدَّ بصره .","قال: ويأْتيه رجل حسن الوجه، وحسن الثياب، طيبُ الريحِ، فيقول: أبْشِرْ بالذي يَسُرُّكَ، هذا يومُكَ الذي كُنْتَ توعدُ، فيقول له: من أنتَ؟ فوجهُك الوجه يجيء بالخير، فيقول: أنا عملُكَ الصالحُ، فيقول: ربِّ أقِمْ الساعة حتى أرجعَ إلى أهلي ومالي .","قَالَ: وَإِنَّ الْعَبْدَ الْكَافِرَ إِذَا كَانَ فِي انْقِطَاعٍ مِنَ الدُّنْيَا وَإِقْبَالٍ مِنَ الْآخِرَةِ، نَزَلَ إِلَيْهِ مِنَ السَّمَاءِ مَلَائِكَةٌ سُودُ الْوُجُوهِ، مَعَهُمْ الْمُسُوحُ، فَيَجْلِسُونَ مِنْهُ مَدَّ الْبَصَرِ، ثُمَّ يَجِيءُ مَلَكُ الْمَوْتِ حَتَّى يَجْلِسَ عِنْدَ رَأْسِهِ، فَيَقُولُ: أَيَّتُهَا النَّفْسُ الْخَبِيثَةُ، اخْرُجِي إِلَى سَخَطٍ مِنَ اللَّهِ وَغَضَبٍ.","قال: فتفرَّقُ في جسده، فينتَزِعُها كما يُنْتَزَعُ السُّفُّودُ من الصُّوفِ المبلول، فيأْخُذُها، فإذا أخذها لم يَدَعُوها في يده طرفة عين حتى يجعلوها في تلك الـمُسُوحِ، ويخرج منها كأنتنِ ريحٍ جيفةٍ وُجدتْ على وجه الأرض، فيصعدون بها، فلا يَمُرُّونَ بها على ملأ من الملائكة إلا قالوا: ما هذا الروحُ الخَبيثُ؟! فيقولون: فلانُ بن فلانٍ، بأقبح أسمائه التي كان يُسَمَّى بها في الدنيا، حتى يُنْتَهَى به إلى السماء الدنيا، فيُسْتَفْتَح له، فلا يفتح له ثم قرأ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ﴿لَا تُفَتَّحُ لَهُمْ أَبْوَابُ السَّمَاءِ وَلَا يَدْخُلُونَ الْجَنَّةَ حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ﴾ [الأعراف: 40] فيقول الله عز وجل: اكتبوا كتابَهُ في سجِّين في الأرض السُّفْلي، فتُطْرَحُ رُوحُه طرحاً . ثم قرا: ﴿وَمَنْ يُشْرِكْ بِاللَّهِ فَكَأَنَّمَا خَرَّ مِنَ السَّمَاءِ فَتَخْطَفُهُ الطَّيْرُ أَوْ تَهْوِي بِهِ الرِّيحُ فِي مَكَانٍ سَحِيقٍ﴾ [الحج: 31] فتعاد رُوحُهُ في جسده، ويأتيه ملكان، فيُجلسانه، فيقولان له: من ربك؟ فيقول: هاه هاه لا أدري، فيقولان له: ما دينُك؟ فيقول: هاه هاه لا أدري، فيقولان له: ما هذا الرجل الذي بُعث فيكم؟ فيقولُ: هاه هاه لا أدري، فينادي منادٍ من السماء أن كذب فأَفْرِشوا له من النار، وافْتَحُوا له باباً إلى النار، فيأتيه من حَرِّها وسَمُومها، ويُضَيَّقُ عليه قبْرُهُ حتَّى تَخْتَلِفَ فيه أضلاعه، ويأتيه رجل قبيحُ الوجه، قبيحُ الثياب، مُنْتِنُ الريح، فيقول: أبْشِرْ بالذي يَسُوؤكَ، هذا يَومُكَ الذي كنت تُوعد، فيقول: من أنت؟ فوجهُك الوجهُ الذي يجيءُ بالشرِّ، فيقول: أنا عملُك الخبيثُ، فيقول: ربِّ لا تُقِم الساعة ."],"takhrij":"حسن: رواه أبو داود (4753) عن هنَّاد بن السري، عن أبي معاوية، عن الأعمش، عن المنهال، عن زاذان، عن البراء فذكر الحديث.","grade":"حسن","chapter_ar":"باب إن المؤمن والكافر جميعًا يُسألان، وإن أهل القبور تُعرض عليهم مقاعدهم في كل يوم مرتين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (4753), Aḥmad (18534), and this is the wording of Aḥmad.","chapter_en":"Both the believer and the disbeliever are questioned, and the people of the graves are shown their places twice each day","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":12,"content":{"translation":{"en":["Al-Barā’ ibn ʿĀzib said: We went out with the Prophet ﷺ in the funeral of a man from the Anṣār. We came to the grave before the burial niche had been made, so the Messenger of Allah ﷺ sat, and we sat around him as though birds were on our heads. In his hand was a stick with which he scratched the ground. Then he raised his head and said: “Seek refuge in Allah from the punishment of the grave,” two or three times, then he said: “When the believing servant is departing from this world and approaching the Hereafter, angels descend to him from heaven with white faces as if their faces were the sun. With them is a shroud from the shrouds of Paradise and perfume from the perfume of Paradise, and they sit from him as far as the eye can see. Then the Angel of Death comes and sits by his head and says: O good soul, come out to forgiveness from Allah and His pleasure.” He said: “So it comes out, flowing like a drop flows from the mouth of a waterskin. He takes it, and once he takes it, they do not leave it in his hand for even the blink of an eye before they take it and place it in that shroud and that perfume. There comes out from it the sweetest fragrance of musk ever found on the face of the earth.”","He said: “Then they ascend with it, and they do not pass by any company of angels except that they say: What is this good soul? They say: So-and-so son of so-and-so, calling him by the best names by which he used to be called in this world, until they reach the lowest heaven. They ask for it to be opened for him, and it is opened. The nearest angels of each heaven accompany him to the next heaven until he reaches the seventh heaven. Then Allah, Mighty and Majestic, says: Write the record of My servant in ʿIlliyyīn, and return him to the earth, for from it I created them, to it I return them, and from it I will bring them out once again.”","He said: “Then his soul is returned to his body, and two angels come to him and make him sit. They say to him: Who is your Lord? He says: My Lord is Allah. They say to him: What is your religion? He says: My religion is Islam. They say to him: What about this man who was sent among you? He says: He is the Messenger of Allah ﷺ. They say to him: What is your knowledge? He says: I read the Book of Allah, believed in it, and affirmed it. Then a caller from heaven calls out: My servant has spoken the truth, so spread for him from Paradise, clothe him from Paradise, and open for him a gate to Paradise.”","He said: “Then there comes to him from its breeze and fragrance, and his grave is expanded for him as far as the eye can see.” He said: “Then a man with a beautiful face, beautiful clothes, and a pleasant scent comes to him and says: Rejoice in what pleases you. This is your day that you were promised. He says to him: Who are you? Your face is a face that comes with good. He says: I am your righteous deeds. Then he says: My Lord, establish the Hour so that I may return to my family and my wealth.”","He said: “And when the disbelieving servant is departing from this world and approaching the Hereafter, angels descend to him from heaven with black faces, carrying coarse sackcloth, and they sit from him as far as the eye can see. Then the Angel of Death comes and sits by his head and says: O wicked soul, come out to the anger and wrath of Allah.”","He said: “So it disperses within his body, and he pulls it out like an iron skewer is pulled through wet wool. He takes it, and once he takes it, they do not leave it in his hand even for the blink of an eye before they place it in those coarse cloths. There comes out from it the foulest smell of any corpse found on the face of the earth. Then they ascend with it, and they do not pass by any company of angels except that they say: What is this wicked soul? They say: So-and-so son of so-and-so, calling him by the ugliest names by which he used to be called in this world, until they reach the lowest heaven. Then permission is sought for him, but it is not opened for him.” Then the Messenger of Allah ﷺ recited: “The gates of heaven will not be opened for them, nor will they enter Paradise until the camel passes through the eye of the needle.” [al-Aʿrāf 7:40]","“Then Allah, Mighty and Majestic, says: Write his record in Sijjīn in the lowest earth. Then his soul is cast down.” Then he recited: “And whoever associates partners with Allah, it is as though he had fallen from the sky and the birds snatched him away, or the wind carried him off to a far distant place.” [al-Ḥajj 22:31]","“Then his soul is returned to his body, and two angels come to him and make him sit. They say to him: Who is your Lord? He says: Ah, ah, I do not know. They say to him: What is your religion? He says: Ah, ah, I do not know. They say to him: What about this man who was sent among you? He says: Ah, ah, I do not know. Then a caller from heaven calls out: He has lied, so spread for him from the Fire, and open for him a gate to the Fire. Then there comes to him from its heat and scorching wind, and his grave is constricted until his ribs interlock. Then a man with an ugly face, ugly clothes, and a foul smell comes to him and says: Rejoice in what will distress you. This is your day that you were promised. He says: Who are you? Your face is a face that comes with evil. He says: I am your wicked deeds. Then he says: My Lord, do not establish the Hour.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4753)، والإمام أحمد (18534)، واللفظ للإمام أحمد."},{"num":3867,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ نحو حَدِيثَ الْبَرَاءِ إِلَّا أَنَّهُ قَالَ: ارْقُدْ رَقْدَةَ الْمُتَّقِينَ الْمُؤْمِنِينَ وَيُقَالُ لِلْفَاجِرِ: ارْقُدْ مَنْهُوشًا . قَالَ: فَمَا مِنْ دَابَّةٍ إِلَّا وَلَهَا فِي جَسَدِهِ نَصِيبٌ ."],"takhrij":"حسن: رواه الحاكم (108) وعنه البيهقي في إثبات عذاب القبر (36) عن أبي الحسن محمد بن عبدالله العمري، ثنا محمد بن إسحاق، ثنا علي بن المنذر، ثنا محمد بن فُضيل، حدثني أبي، عن أبي حازم، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب إن المؤمن والكافر جميعًا يُسألان، وإن أهل القبور تُعرض عليهم مقاعدهم في كل يوم مرتين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ḥākim (108), and al-Bayhaqī quoted it in Ithbāt ʿAdhāb al-Qabr (36).","chapter_en":"Both the believer and the disbeliever are questioned, and the people of the graves are shown their places twice each day","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated something similar to the hadith of al-Barā’, except that it includes: “Sleep the sleep of the God-fearing believers,” and it is said to the wicked person: “Sleep while being torn and bitten.” He said: “There is no creature except that it will have some share in his body.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (108)، وعنه البيهقي في إثبات عذاب القبر (36)."},{"num":3868,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا قُبِرَ الْمَيِّتُ - أَوْ قَالَ أَحَدُكُمْ أَتَاهُ مَلَكَانِ أَسْوَدَانِ أَزْرَقَانِ، يُقَالُ لأَحَدِهِمَا: الْمُنْكَرُ وَالآخَرُ النَّكِيرُ، فَيَقُولاَنِ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ؟ فَيَقُولُ مَا كَانَ يَقُولُ: هُوَ عَبْدُ اللَّهِ وَرَسُولُهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. فَيَقُولاَنِ: قَدْ كُنَّا نَعْلَمُ أَنَّكَ تَقُولُ هَذَا. ثُمَّ يُفْسَحُ لَهُ فِي قَبْرِهِ سَبْعُونَ ذِرَاعًا فِي سَبْعِينَ، ثُمَّ يُنَوَّرُ لَهُ فِيهِ، ثُمَّ يُقَالُ لَهُ: نَمْ. فَيَقُولُ أَرْجِعُ إِلَى أَهْلِي فَأُخْبِرُهُمْ؟ فَيَقُولاَنِ: نَمْ كَنَوْمَةِ الْعَرُوسِ الَّذِي لاَ يُوقِظُهُ إِلاَّ أَحَبُّ أَهْلِهِ إِلَيْهِ. حَتَّى يَبْعَثَهُ اللَّهُ مِنْ مَضْجَعِهِ ذَلِكَ. وَإِنْ كَانَ مُنَافِقًا قَالَ سَمِعْتُ النَّاسَ يَقُولُونَ فَقُلْتُ مِثْلَهُ لاَ أَدْرِي. فَيَقُولاَنِ قَدْ كُنَّا نَعْلَمُ أَنَّكَ تَقُولُ ذَلِكَ. فَيُقَالُ لِلأَرْضِ الْتَئِمِي عَلَيْهِ. فَتَلْتَئِمُ عَلَيْهِ. فَتَخْتَلِفُ فِيهَا أَضْلاَعُهُ فَلاَ يَزَالُ فِيهَا مُعَذَّبًا حَتَّى يَبْعَثَهُ اللَّهُ مِنْ مَضْجَعِهِ ذَلِكَ."],"takhrij":"حسن: رواه الترمذي (1071) عن أبي سلمة يحيى بن خلف، حدثنا بشر ابن المفضل، عن عبدالرحمن بن إسحاق، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب إن المؤمن والكافر جميعًا يُسألان، وإن أهل القبور تُعرض عليهم مقاعدهم في كل يوم مرتين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Tirmidhī (1071), who graded it Ḥasan, and Ibn Ḥibbān (3117).","chapter_en":"Both the believer and the disbeliever are questioned, and the people of the graves are shown their places twice each day","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “When the deceased — or he said: one of you — is buried, two angels come to him, black and blue in color. One of them is called al-Munkar and the other al-Nakīr. They say: What did you used to say about this man? So he says what he used to say: He is the servant of Allah and His Messenger. I testify that there is no god but Allah and that Muhammad is His servant and Messenger. Then they say: We knew that you used to say this. Then his grave is widened for him seventy by seventy cubits, then it is illuminated for him, then it is said to him: Sleep. He says: Should I return to my family and inform them? They say: Sleep like the sleep of a bridegroom whom no one wakes except the most beloved of his family to him, until Allah raises him from that resting place of his. But if he is a hypocrite, he says: I heard the people saying something, so I said the same. I do not know. Then they say: We knew that you used to say that. Then it is said to the earth: Close in on him. So it closes in on him until his ribs interlock, and he remains being punished in it until Allah raises him from that resting place of his.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1071) وحسنه، وابن حبان (3117)."},{"num":3869,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: جَاءَتْ يَهُودِيَّةٌ، فَاسْتَطْعَمَتْ عَلَى بَابِي، فَقَالَتْ: أَطْعِمُونِي، أَعَاذَكُمُ اللهُ مِنْ فِتْنَةِ الدَّجَّالِ، وَمِنْ فِتْنَةِ عَذَابِ الْقَبْرِ. قَالَتْ: فَلَمْ أَزَلْ أَحْبِسُهَا، حَتَّى جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، مَا تَقُولُ هَذِهِ الْيَهُودِيَّةُ؟ قَالَ: وَمَا تَقُولُ؟ قُلْتُ: تَقُولُ: أَعَاذَكُمُ اللهُ مِنْ فِتْنَةِ الدَّجَّالِ، وَمِنْ فِتْنَةِ عَذَابِ الْقَبْرِ! قَالَتْ: عَائِشَةُ: فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَفَعَ يَدَيْهِ مَدًّا يَسْتَعِيذُ بِاللهِ مِنْ فِتْنَةِ الدَّجَّالِ، وَمِنْ فِتْنَةِ عَذَابِ الْقَبْرِ، ثُمَّ قَالَ: أَمَّا فِتْنَةُ الدَّجَّالِ: فَإِنَّهُ لَمْ يَكُنْ نَبِيٌّ إِلَّا قَدْ حَذَّرَ أُمَّتَهُ، وَسَأُحَذِّرُكُمُوهُ تَحْذِيرًا لَمْ يُحَذِّرْهُ نَبِيٌّ أُمَّتَهُ، إِنَّهُ أَعْوَرُ، وَاللهُ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ، مَكْتُوبٌ بَيْنَ عَيْنَيْهِ: كَافِرٌ، يَقْرَؤُهُ كُلُّ مُؤْمِنٍ. فَأَمَّا فِتْنَةُ الْقَبْرِ: فَبِي تُفْتَنُونَ، وَعَنِّي تُسْأَلُونَ، فَإِذَا كَانَ الرَّجُلُ الصَّالِحُ، أُجْلِسَ فِي قَبْرِهِ غَيْرَ فَزِعٍ، وَلَا مَشْعُوفٍ، ثُمَّ يُقَالُ لَهُ: فِيمَ كُنْتَ؟ فَيَقُولُ: فِي الْإِسْلَامِ؟ فَيُقَالُ: مَا هَذَا الرَّجُلُ الَّذِي كَانَ فِيكُمْ؟ فَيَقُولُ: مُحَمَّدٌ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، جَاءَنَا بِالْبَيِّنَاتِ مِنْ عِنْدِ اللَّهِ عَزَّ وَجَلَّ، فَصَدَّقْنَاهُ، فَيُفْرَجُ لَهُ فُرْجَةٌ قِبَلَ النَّارِ، فَيَنْظُرُ إِلَيْهَا يَحْطِمُ بَعْضُهَا بَعْضًا، فَيُقَالُ لَهُ: انْظُرْ إِلَى مَا وَقَاكَ اللهُ عَزَّ وَجَلَّ، ثُمَّ يُفْرَجُ لَهُ فُرْجَةٌ إِلَى الْجَنَّةِ، فَيَنْظُرُ إِلَى زَهْرَتِهَا وَمَا فِيهَا، فَيُقَالُ لَهُ: هَذَا مَقْعَدُكَ مِنْهَا، وَيُقَالُ: عَلَى الْيَقِينِ كُنْتَ، وَعَلَيْهِ مِتَّ، وَعَلَيْهِ تُبْعَثُ إِنْ شَاءَ اللَّهُ. وَإِذَا كَانَ الرَّجُلُ السَّوْءُ، أُجْلِسَ فِي قَبْرِهِ فَزِعًا مَشْعُوفًا، فَيُقَالُ لَهُ: فِيمَ كُنْتَ؟ فَيَقُولُ: لَا أَدْرِي، فَيُقَالُ: مَا هَذَا الرَّجُلُ الَّذِي كَانَ فِيكُمْ؟ فَيَقُولُ: سَمِعْتُ النَّاسَ يَقُولُونَ قَوْلًا، فَقُلْتُ كَمَا قَالُوا، فَتُفْرَجُ لَهُ فُرْجَةٌ قِبَلَ الْجَنَّةِ، فَيَنْظُرُ إِلَى زَهْرَتِهَا وَمَا فِيهَا، فَيُقَالُ لَهُ: انْظُرْ إِلَى مَا صَرَفَ اللهُ عَزَّ وَجَلَّ عَنْكَ، ثُمَّ يُفْرَجُ لَهُ فُرْجَةٌ قِبَلَ النَّارِ، فَيَنْظُرُ إِلَيْهَا يَحْطِمُ بَعْضُهَا بَعْضًا، وَيُقَالُ لَهُ: هَذَا مَقْعَدُكَ مِنْهَا، كُنْتَ عَلَى الشَّكِّ، وَعَلَيْهِ مِتَّ، وَعَلَيْهِ تُبْعَثُ إِنْ شَاءَ اللَّهُ، ثُمَّ يُعَذَّبُ."],"takhrij":"صحيح: رواه الإمام أحمد (25089) عن يزيد بن هارون قال: أخبرنا ابن أبي ذئب، عن محمد بن عمرو بن عطاء، عن ذكوان، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب إن الله يثبت الذين آمنوا بالقول الثابت في القبر، ويُضل الله الظالمين في القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Aḥmad (25089).","chapter_en":"Allah makes the believers firm with the firm word in the grave, and Allah causes the wrongdoers to go astray in the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":13,"content":{"translation":{"en":["ʿĀ’ishah said: A Jewish woman came and asked for food at my door, and she said: “Feed me. May Allah protect you from the trial of the Dajjāl and from the trial of the punishment of the grave.” She said: I kept her there until the Messenger of Allah ﷺ came, then I said: “O Messenger of Allah ﷺ, what is this Jewish woman saying?” He said: “And what is she saying?” I said: “She says: May Allah protect you from the trial of the Dajjāl and from the trial of the punishment of the grave.” ʿĀ’ishah said: Then the Messenger of Allah ﷺ stood up and stretched out his hands, seeking refuge in Allah from the trial of the Dajjāl and from the trial of the punishment of the grave. Then he said: “As for the trial of the Dajjāl, there was no prophet except that he warned his nation about him, and I will warn you about him with a warning no prophet gave his nation. He is one-eyed, and Allah, Mighty and Majestic, is not one-eyed. Written between his eyes is: disbeliever, and every believer will read it. As for the trial of the grave, it is concerning me that you will be tested, and about me that you will be questioned. If the righteous man is concerned, he will be made to sit in his grave without fear and without panic. Then it will be said to him: What were you upon? He will say: I was upon Islam. Then it will be said: Who is this man who was among you? He will say: Muhammad is the Messenger of Allah ﷺ. He came to us with clear proofs from Allah, Mighty and Majestic, and we believed him. Then an opening toward the Fire will be made for him, and he will look at it, with one part crushing another, and it will be said to him: Look at what Allah protected you from. Then an opening toward Paradise will be made for him, and he will look at its beauty and what is in it, and it will be said to him: This is your place in it. And it will be said: Upon certainty you lived, upon it you died, and upon it you will be resurrected, if Allah wills. And if it is the evil man, he will be made to sit in his grave terrified and panic-stricken. Then it will be said to him: What were you upon? He will say: I do not know. Then it will be said to him: Who is this man who was among you? He will say: I heard the people saying something, so I said what they said. Then an opening toward Paradise will be made for him, and he will look at its beauty and what is in it, and it will be said to him: Look at what Allah turned away from you. Then an opening toward the Fire will be made for him, and he will look at it, with one part crushing another, and it will be said to him: This is your place in it. You lived upon doubt, died upon it, and upon it you will be resurrected, if Allah wills. Then he will be punished.”"]},"buhuth":{"en":["Her phrase “panic-stricken” comes from intense terror that overwhelms the heart."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (25089)."},{"num":3870,"demo":false,"sanad":"","matn":["عن أبي الزبير أنه سأل جابر بن عبدالله، عن فتَّانَي القَبْر، فقال: سمعتُ النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يقول: إن هذه الأمَّة تُبتلى في قُبورِها، فإذا أُدْخِلَ المُؤْمِنُ قَبْرَه، وتَوَلَّى عنه أصحابُه، جاء مَلَكٌ شديدُ الانْتِهار، فيقولُ له: ما كُنْتَ تقولُ في هذا الرَّجلِ؟ فيقولُ المُؤمِنُ: أقولُ: إنَّه رسولُ الله وعَبْدُه، فيقولُ له المَلَكُ: انظُرْ إلى مَقْعَدِكَ الذي كان لك في النار قد أنجاكَ الله منه، وأبدَلَكَ بمَقْعَدِكَ الذي تَرَى من النار، مَقْعَدَكَ الذي تَرَى من الجنة، فيراهُما كِلاهُما، فيقولُ المُؤْمِنُ: دَعُوني أُبَشِّرْ أهلي، فيُقالُ له: اسْكُنْ، وأمَّا المُنافِقُ، فيُقْعَدُ إذا تَوَلَّى عنه أهله، فيقال له: ما كُنْت تقولُ في هذا الرجل؟ فيقولُ: لا أدري، أقولُ ما يقولُ الناسُ، فيقال له: لا دَرَيْتَ، هذا مقْعَدُكَ الذي كان لَكَ من الجنة، قد أُبْدِلْتَ مكانَه مَقْعدَكَ من النار .","قَالَ جَابِرٌ: فَسَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ: يُبْعَثُ كُلُّ عَبْدٍ فِي الْقَبْرِ عَلَى مَا مَاتَ: الْمُؤْمِنُ عَلَى إِيمَانِهِ، وَالْمُنَافِقُ عَلَى نِفَاقِهِ .."],"takhrij":"صحيح: رواه عبد الرزاق (6744، 6746) عن ابن جريج، قال: أخبرني أبو الزبير أنه سمع جابر بن عبدالله يقول فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب إن الله يثبت الذين آمنوا بالقول الثابت في القبر، ويُضل الله الظالمين في القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: ʿAbd al-Razzāq (6744, 6746).","chapter_en":"Allah makes the believers firm with the firm word in the grave, and Allah causes the wrongdoers to go astray in the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":13,"content":{"translation":{"en":["Abū al-Zubayr said that he asked Jābir ibn ʿAbdullāh about the two examiners of the grave, and he said: I heard the Prophet ﷺ say: “This nation is tested in its graves. When the believer is placed in his grave and his companions turn away from him, an angel comes, stern in rebuke, and says to him: What did you used to say about this man? The believer says: I say that he is the Messenger of Allah ﷺ and His servant. Then the angel says to him: Look at your place that was for you in the Fire. Allah has saved you from it and replaced it with your place that you now see in Paradise, and he sees both of them. Then the believer says: Let me go give glad tidings to my family. It is said to him: Remain where you are. As for the hypocrite, he is made to sit when his family has turned away from him, and it is said to him: What did you used to say about this man? He says: I do not know. I used to say what the people said. Then it is said to him: You did not know. This was your place that had been for you in Paradise, but you have been given in its place your place in the Fire.”","Jābir said: I also heard the Prophet ﷺ say: “Every servant will be raised in the grave upon what he died upon: the believer upon his faith, and the hypocrite upon his hypocrisy.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3888],"tks":"صحيح: رواه عبد الرزاق (6744، 6746)."},{"num":3871,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا أُقْعِدَ الْمُؤْمِنُ فِي قَبْرِهِ، أُتِيَ، ثُمَّ شَهِدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَذَلِكَ قَوْلُهُ: ﴿يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ﴾ [سورة إبراهيم: 27]}."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1369) عن حفص بن عمر، حدثنا شعبة، عن علقمة بن مرثد، عن سعد بن عبيدة، عن البراء بن عازب فذكره.","grade":"متفق عليه","chapter_ar":"باب إن الله يثبت الذين آمنوا بالقول الثابت في القبر، ويُضل الله الظالمين في القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1369), Muslim (2871).","chapter_en":"Allah makes the believers firm with the firm word in the grave, and Allah causes the wrongdoers to go astray in the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":13,"content":{"translation":{"en":["Al-Barā’ ibn ʿĀzib reported from the Prophet ﷺ: “When the believer is made to sit in his grave, the angels come to him and he then testifies that there is no god but Allah and that Muhammad is the Messenger of Allah ﷺ. That is the meaning of His saying: ‘Allah makes firm those who believe with the firm word.’ [Ibrāhīm 14:27]”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1369)، ومسلم (2871)."},{"num":3872,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جِنَازَةً، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّهَا النَّاسُ إِنَّ هَذِهِ الْأُمَّةَ تُبْتَلَى فِي قُبُورِهَا، فَإِذَا الْإِنْسَانُ دُفِنَ، فَتَفَرَّقَ عَنْهُ أَصْحَابُهُ، جَاءَهُ مَلَكٌ فِي يَدِهِ مِطْرَاقٌ، فَأَقْعَدَهُ، قَالَ: مَا تَقُولُ فِي هَذَا الرَّجُلِ؟ فَإِنْ كَانَ مُؤْمِنًا قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، فَيَقُولُ: صَدَقْتَ، ثُمَّ يُفْتَحُ لَهُ بَابٌ إِلَى النَّارِ، فَيَقُولُ: هَذَا كَانَ مَنْزِلُكَ لَوْ كَفَرْتَ بِرَبِّكَ، فَأَمَّا إِذْ آمَنْتَ فَهَذَا مَنْزِلُكَ، فَيُفْتَحُ لَهُ بَابٌ إِلَى الْجَنَّةِ، فَيُرِيدُ أَنْ يَنْهَضَ إِلَيْهِ، فَيَقُولُ لَهُ: اسْكُنْ، وَيُفْسَحُ لَهُ فِي قَبْرِهِ، وَإِنْ كَانَ كَافِرًا أَوْ مُنَافِقًا يَقُولُ لَهُ: مَا تَقُولُ فِي هَذَا الرَّجُلِ؟ فَيَقُولَ: لَا أَدْرِي، سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا، فَيَقُولُ: لَا دَرَيْتَ، وَلَا تَلَيْتَ، وَلَا اهْتَدَيْتَ، ثُمَّ يُفْتَحُ لَهُ بَابٌ إِلَى الْجَنَّةِ، فَيَقُولُ: هَذَا مَنْزِلُكَ لَوْ آمَنْتَ بِرَبِّكَ، فَأَمَّا إِذْ كَفَرْتَ بِهِ، فَإِنَّ اللَّهَ عَزَّ وَجَلَّ أَبْدَلَكَ بِهِ هَذَا، وَيُفْتَحُ لَهُ بَابٌ إِلَى النَّارِ، ثُمَّ يَقْمَعُهُ قَمْعَةً بِالْمِطْرَاقِ يَسْمَعُهَا خَلْقُ اللهِ كُلُّهُمْ غَيْرَ الثَّقَلَيْنِ فَقَالَ بَعْضُ الْقَوْمِ: يَا رَسُولَ اللَّهِ، مَا أَحَدٌ يَقُومُ عَلَيْهِ مَلَكٌ فِي يَدِهِ مِطْرَاقٌ إِلَّا هِيِلَ عِنْدَ ذَلِكَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ﴿يُثَبِّتُ اللهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ﴾ [إبراهيم:٢٧]."],"takhrij":"حسن: رواه الإمام أحمد (11000) والبزار كشف الأستار (872) كلاهما من حديث أبي عامر عبد الملك بن عمرو، ثنا عباد بن راشد، عن داود ابن أبي هند، عن أبي نضرة، عن أبي سعيد فذكره.","grade":"حسن","chapter_ar":"باب إن الله يثبت الذين آمنوا بالقول الثابت في القبر، ويُضل الله الظالمين في القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (11000), al-Bazzār in Kashf al-Astār (872).","chapter_en":"Allah makes the believers firm with the firm word in the grave, and Allah causes the wrongdoers to go astray in the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":13,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said: I attended a funeral with the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ said: “O people, this nation is tested in its graves. When a person is buried and his companions have dispersed from him, an angel comes to him with a hammer in his hand and makes him sit. He says: What do you say about this man? If he is a believer, he says: I testify that there is no god but Allah and that Muhammad is His servant and Messenger. Then he says: You have spoken the truth. Then a gate to the Fire is opened for him, and it is said: This would have been your dwelling had you disbelieved in your Lord. But now that you have believed, this is your dwelling. Then a gate to Paradise is opened for him. He wants to rise toward it, but it is said to him: Remain where you are. And his grave is widened for him. But if he is a disbeliever or a hypocrite, he says to him: What do you say about this man? He says: I do not know. I heard the people saying something. Then he says: You neither knew, nor recited, nor were guided. Then a gate to Paradise is opened for him, and it is said: This would have been your dwelling had you believed in your Lord. But since you disbelieved in Him, Allah, Mighty and Majestic, has replaced it for you with this. Then a gate to the Fire is opened for him, and he strikes him with the hammer a blow that all Allah’s creation hears except humans and jinn.” Some of the people said: “O Messenger of Allah ﷺ, there is no one who would have an angel stand over him with a hammer in his hand except that he would be terrified by that.” So the Messenger of Allah ﷺ said: “Allah makes firm those who believe with the firm word.” [Ibrāhīm 14:27]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (11000)، والبزار في كشف الأستار (872)."},{"num":3873,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: تلا رسول الله صلى الله عليه وسلم: ﴿يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ﴾. [سورة إبراهيم: 27]. فقال: ذلك إذا قيل له في القبر: من ربك؟ وما دينك؟ ومن نبيك؟ فيقول: الله ربي، والإسلام ديني، ومحمد نبيي جاءنا بالبينات من عند الله فآمنتُ به، وصدقتُه فيقال:صدقت على هذا حييت، وعليه تبعث إن شاء الله ."],"takhrij":"حسن: رواه البيهقي في إثبات عذاب القبر (8) عن محمد بن عبدالله بن محمد، عن عبدالرحمن بن الحسن القاضي بهمدان، ثنا إبراهيم بن الحسين، ثنا آدم ابن أبي إياس، ثنا حماد بن سلمة، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب إن الله يثبت الذين آمنوا بالقول الثابت في القبر، ويُضل الله الظالمين في القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bayhaqī (8).","chapter_en":"Allah makes the believers firm with the firm word in the grave, and Allah causes the wrongdoers to go astray in the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ recited: “Allah makes firm those who believe with the firm word in the life of this world and in the Hereafter” and then said: “That is when it is said to him in the grave: Who is your Lord? What is your religion? Who is your prophet? So he says: Allah is my Lord, Islam is my religion, and Muhammad is my prophet. He came to us with clear proofs from Allah, so I believed in him and affirmed him. Then it is said: You have spoken the truth. Upon this you lived, and upon it you will be resurrected, if Allah wills.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (8)."},{"num":3874,"demo":false,"sanad":"","matn":["عن البراء قال: قال رسول الله صلى الله عليه وسلم: وذكر الكافر حين تُقبض روحه قال: فتعاد روحُه في جَسده، قال: فيأتيه ملكان شديدا الانتهار فيجلسانه فينتهرانه، فيقولان له: من ربك؟ فيقول: لا أدري، قال: فيقولان له: ما دينك؟ فيقول: لا أدري، قال: فيقال له: ما هذا النبي الذي بُعث فيك؟ قال: فيقول: سمعت الناس يقولون ذلك، لا أدري قـال: فيقولان: لا دريتَ قـال: وذلك قوله الله: ﴿وَيُضِلُّ اللَّهُ الظَّالِمِينَ وَيَفْعَلُ اللَّهُ مَا يَشَاءُ﴾ [سورة إبراهيم: 27] ."],"takhrij":"حسن: رواه الطبري في تفسيره (4373) من طريق أبي عوانة، عن الأعمش، عن المنهال بن عمرو، عن زاذان، عن البراء فذكره، وهو حديث طويل سبق ذكره في الباب الذي قبله.","grade":"حسن","chapter_ar":"باب إن الله يثبت الذين آمنوا بالقول الثابت في القبر، ويُضل الله الظالمين في القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarī in his Tafsīr (13/218).","chapter_en":"Allah makes the believers firm with the firm word in the grave, and Allah causes the wrongdoers to go astray in the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":13,"content":{"translation":{"en":["Al-Barā’ said: The Messenger of Allah ﷺ said — mentioning the disbeliever when his soul is taken — “Then his soul is returned to his body, and two angels come to him, severe in rebuke, and they make him sit and scold him. They say to him: Who is your Lord? He says: I do not know. They say to him: What is your religion? He says: I do not know. Then it is said to him: Who is this prophet who was sent among you? He says: I heard people saying that, but I do not know. Then they say: You did not know.” He said: “That is the meaning of Allah’s saying: ‘And Allah causes the wrongdoers to go astray, and Allah does what He wills.’”"]},"buhuth":{"en":["The meaning of Allah’s saying “And Allah causes the wrongdoers to go astray, and Allah does what He wills” [Ibrāhīm 14:27] is that He makes the believers firm in this world through faith in Allah and His Messenger ﷺ, and in the Hereafter with the same firmness by which He made them firm in worldly life. That occurs in their graves when they are questioned about their belief in divine oneness and their faith in His Messenger ﷺ.","And His saying “And Allah causes the wrongdoers to go astray” means that Allah does not grant the hypocrite and the disbeliever success, in worldly life or in the Hereafter during questioning in the grave, to the guidance that the believer was given of faith in Allah and His Messenger ﷺ. See al-Ṭabarī’s Tafsīr (13/218)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبري في تفسيره (4373)."},{"num":3875,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَجُلاً قَالَ: يَا رَسُولَ اللَّهِ! مَا بَالُ الْمُؤْمِنِينَ يُفْتَنُونَ فِي قُبُورِهِمْ إِلاَّ الشَّهِيدَ؟ قَالَ: كَفَى بِبَارِقَةِ السُّيُوفِ عَلَى رَأْسِهِ فِتْنَةً."],"takhrij":"صحيح: رواه النسائي (2053) عن إبراهيم بن الحسن قال: حدثنا حجاج، عن ليث بن سعد، عن معاوية بن صالح، أن صفوان بن عمْرو حدَّثه عن راشد بن سعد، عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن الشهيد لا يُفتن في قبره","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (2053).","chapter_en":"What is reported that the martyr is not tested in his grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":14,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ reported that a man said: “O Messenger of Allah ﷺ, why are the believers tested in their graves except the martyr?” He said: “The flashing of swords over his head is enough of a test for him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8088],"tks":"صحيح: رواه النسائي (2053)."},{"num":3876,"demo":false,"sanad":"","matn":["عن المقدام بن معد يكرب، عن رسول الله صلى الله عليه وسلم قال: للشهيد عند الله ست خصال وذكر منها: ويُجار من عذاب القبر ."],"takhrij":"حسن: رواه ابن ماجه (2799) عن هشام بن عمار، قال: حدثنا إسماعيل ابن عياش، قال: حدثني بَحير بن سعد، عن خالد بن معدان، عن المقدام بن معد يكرب فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الشهيد لا يُفتن في قبره","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (2799), Aḥmad (17182), al-Tirmidhī (1663).","chapter_en":"What is reported that the martyr is not tested in his grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":14,"content":{"translation":{"en":["Al-Miqdām ibn Maʿdīkarib reported from the Messenger of Allah ﷺ: “The martyr has six qualities with Allah…” and among them he mentioned: “He is protected from the punishment of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2799)، والإمام أحمد (17182)، والترمذي (1663)."},{"num":3877,"demo":false,"sanad":"","matn":["عَنْ قَيْسٍ الْجُذَامِيِّ، رَجُلٍ كَانَتْ لَهُ صُحْبَةٌ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُعْطَى الشَّهِيدُ سِتَّ خِصَالٍ عِنْدَ أَوَّلِ قَطْرَةٍ مِنْ دَمِهِ: يُكَفَّرُ عَنْهُ كُلُّ خَطِيئَةٍ، وَيُرَى مَقْعَدَهُ مِنَ الْجَنَّةِ، وَيُزَوَّجُ مِنَ الْحُورِ الْعِينِ، وَيُؤَمَّنُ مِنَ الْفَزَعِ الْأَكْبَرِ، وَمِنْ عَذَابِ الْقَبْرِ، وَيُحَلَّى حُلَّةَ الْإِيمَانِ."],"takhrij":"حسن: رواه الإمام أحمد (17783) عن زيد بن يحيى الدمشقي، قال: حدثنا ابن ثوبان، عن أبيه، عن مكحول، عن كثير بن مرة، عن قيس الجُذامي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الشهيد لا يُفتن في قبره","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (17783).","chapter_en":"What is reported that the martyr is not tested in his grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":14,"content":{"translation":{"en":["Qays al-Judhāmī — a man who had companionship with the Prophet ﷺ — said: The Prophet ﷺ said: “The martyr is given six qualities with the first drop of his blood: every sin is forgiven for him, he is shown his place in Paradise, he is married to the maidens of Paradise, he is kept safe from the greatest terror and from the punishment of the grave, and he is adorned with the garment of faith.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8087,13277],"tks":"حسن: رواه الإمام أحمد (17783)."},{"num":3878,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن يَسَارٍ قَالَ: كنتُ جَالِسًا، وَسُلَيْمَانُ بْنُ صُرد وَخَالِدُ بْنُ عُرْفُطَةَ فَذَكَرُوا أَنَّ رَجُلاً توفِّيَ، مَاتَ ببطْنِه فإذاهما يَشْتَهِيَانِ أَنْ يَكُونَا شُهَدَاءَ جَنَازَتِهِ، فَقَالَ أَحَدُهُمَا لِلآخَرِ: أَلَمْ يَقُل رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنْ يَقْتُلْهُ بَطْنُه فَلَنْ يُعذَّب فِي قَبْرِهِ فَقَالَ الآخَرُ: بَلَى."],"takhrij":"صحيح: رواه النسائي (2052) عن محمد بن عبد الأعلى، قال: حدثنا خالد، عن شُعبة، قال: أخبرني جامع بن شَدَّاد، قال: سمعت عبدالله بن يسار فذكره، وإسناده صحيح، وقد صحَّحه أيضاً ابن حبان (2933) وأخرجه الإمام أحمد (18310) كلاهما من حديث شعبة، وراه الترمذي (1064) من وجه آخر عن أبي إسحاق السبيعي، قال: قال سليمان بن صُرد لخالد بن عرفَطة (أو خالد لسليمان) فذكره، وقال: حسن غريب من هذا الوجه، وقد رُوي من غير هذا الوجه .","grade":"صحيح","chapter_ar":"باب من قتله بطنه لا يُعذَّب في قبره","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (2052), authenticated by Ibn Ḥibbān (2933), and Aḥmad (18310).","chapter_en":"One who dies from an abdominal illness is not punished in his grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn Yasār said: I was sitting with Sulaymān ibn Ṣurad and Khālid ibn ʿUrfuṭah, and they mentioned that a man had died from an abdominal illness. They both wished that they could attend his funeral. Then one of them said to the other: “Did not the Messenger of Allah ﷺ say: ‘Whoever is killed by an abdominal illness will not be punished in his grave’?” The other said: “Yes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2052)، وصححه ابن حبان (2933)، والإمام أحمد (18310)."},{"num":3879,"demo":false,"sanad":"","matn":["عن عبدالله بن عمْرو يقول: سمعت رسول الله صلى الله عليه وسلم يقول: ما من مسلمٍ يموتُ في ليلة الجمعة إلاَّ بُرِئَ من فتنة القبر ."],"takhrij":"حسن: رواه أحمد (7050) عن إبراهيم بن أبي العباس، حدثنا بقية، حدثني معاوية بن سعيد التجيبي، سمعت أبا قبيل المصري يقول: سمعت عبدالله بن عمْرو بن العاص فذكر الحديث.","grade":"حسن","chapter_ar":"باب من مات يوم الجمعة أو ليلة الجمعة وُقي من عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (7050).","chapter_en":"One who dies on Friday or Friday night is protected from the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr said: I heard the Messenger of Allah ﷺ say: “No Muslim dies on Friday or the night of Friday except that he is protected from the trial of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (7050)."},{"num":3880,"demo":false,"sanad":"","matn":["عَنْ سَلْمَانَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  رِبَاطُ يَوْمٍ وَلَيْلَةٍ خَيْرٌ مِنْ صِيَامِ شَهْرٍ وَقِيَامِهِ، وَإِنْ مَاتَ جَرَى عَلَيْهِ عَمَلُهُ الَّذِي كَانَ يَعْمَلُهُ، وَأُجْرِيَ عَلَيْهِ رِزْقُهُ، وَأَمِنَ الْفَُتَّانَ."],"takhrij":"صحيح: رواه مسلم في كتاب الإمارة (1913) عن عبدالله بن عبدالرحمن بن بهرام الدارمي، حدثنا أبو الوليد الطيالسي، حدثنا الليث (يعني ابن سعد) عن أيوب بن موسى، عن مكحول، عن شرحبيل بن السِمِطْ، عن سلمان فذكره.","grade":"صحيح","chapter_ar":"باب الرباط في سبيل الله وقاية من عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (1913).","chapter_en":"Guarding the frontier in the path of Allah is protection from the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":17,"content":{"translation":{"en":["Salmān said: I heard the Messenger of Allah ﷺ say: “Guarding the frontier for a day and a night is better than fasting and praying at night for a month. And if he dies, the deeds he used to do continue for him, his provision continues for him, and he is kept safe from the examiner.”"]},"buhuth":{"en":["The phrase “the examiner” may be read with a ḍammah on the fā’, making it the plural of one who tests, and it may refer to the different forms of trial after burial, such as the squeeze of the grave, the questioning, and punishment in the grave. Some scholars read it with a fatḥah on the fā’, meaning the one who tests the buried person through questioning and then punishes him."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7764,12119],"tks":"صحيح: رواه مسلم (1913)."},{"num":3881,"demo":false,"sanad":"","matn":["عَنْ فَضَالَةَ بْنِ عُبَيْدٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُلُّ الْمَيِّتِ يُخْتَمُ عَلَى عَمَلِهِ، إِلاَّ الْمُرَابِطَ، فَإِنَّهُ يَنْمُو لَهُ عَمَلُهُ إِلَى يَوْمِ الْقِيَامَةِ، وَيُؤَمَّنُ مِنْ فَتَّانِ الْقَبْرِ."],"takhrij":"صحيح: رواه أبو داود (2500)، والترمذي (1621) كلاهما من طريق أبي هانئ الخولاني، عن عمرو بن مالك، عن فَضالة بن عبيد فذكره، واللفظ لأبي داود، ولفظ الترمذي قريب منه. وقال: حسن صحيح .","grade":"صحيح","chapter_ar":"باب الرباط في سبيل الله وقاية من عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (2500), al-Tirmidhī (1621), and this is the wording of Abū Dāwūd.","chapter_en":"Guarding the frontier in the path of Allah is protection from the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":17,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd reported that the Messenger of Allah ﷺ said: “Every dead person has his deeds sealed off except the one guarding the frontier. His deeds continue to grow for him until the Day of Resurrection, and he is kept safe from the examiner of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2500)، والترمذي (1621)، واللفظ لأبي داود."},{"num":3882,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بن عَامِرٍ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كُلُّ مَيِّتٍ يُخْتَمُ عَلَى عَمَلِهِ، إِلَّا الْمُرَابِطَ فِي سَبِيلِ اللَّهِ، فَإِنَّهُ يُجْرَى لَهُ أَجْرُ عَمَلِهِ حَتَّى يُبْعث . وَيُؤَمَّنُ مِنْ فُتَّان الْقَبْرِ ."],"takhrij":"حسن: رواه أحمد (17359) عن عبدالله بن يزيد، حدثنا ابن لهيعة، حدثنا مِشْرح قال: سمعت عقبة بن عامر فذكره.","grade":"حسن","chapter_ar":"باب الرباط في سبيل الله وقاية من عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (17359).","chapter_en":"Guarding the frontier in the path of Allah is protection from the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":17,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir said: I heard the Messenger of Allah ﷺ say: “Every dead person has his deeds sealed except the one guarding the frontier in the path of Allah. The reward of his deeds continues for him until he is resurrected, and he is kept safe from the examiner of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7767],"tks":"حسن: رواه أحمد (17359)."},{"num":3883,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ مَاتَ مُرَابِطًا فِي سَبِيلِ اللَّهِ أَجْرَى عَلَيْهِ أَجْرَ عَمَلِهِ الصَّالِحِ الَّذِي كَانَ يَعْمَلُ، وَأَجْرَى عَلَيْهِ رِزْقَهُ، وَأَمِنَ مِنَ الْفَتَّانِ، وَبَعَثَهُ اللَّهُ يَوْمَ الْقِيَامَةِ آمِنًا مِنَ الْفَزَعِ."],"takhrij":"حسن: رواه ابن ماجه (2767) عن يونس بن عبد الأعلى، حدثنا عبدالله بن وهب، أخبرني الليث، عن زُهرة بن معبد، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الرباط في سبيل الله وقاية من عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (2767).","chapter_en":"Guarding the frontier in the path of Allah is protection from the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah reported from the Prophet ﷺ: “Whoever dies while guarding the frontier in the path of Allah, the reward of his righteous deeds that he used to do continues for him, his provision continues for him, he is safe from the examiner, and Allah will raise him on the Day of Resurrection safe from terror.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2767)."},{"num":3884,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْمَيِّتَ إِذَا وُضع فِي قَبْرِهِ إِنَّهُ لَيَسْمَعُ خَفْقَ نِعَالِهِمْ حِينَ يُوَلُّونَ عَنْهُ فَإِنْ كَانَ مُؤْمِنًا كَانَتِ الصَّلَاةُ عَنْهُ رَأْسِهِ، وَكَانَ الصِّيَامُ عَنْ يَمِينِهِ، وَكَانَتِ الزَّكَاةُ عَنْ يَسَارِهِ، وَكَانَ فِعْلُ الْخَيْرَاتِ مِنَ الصَّدَقَةِ وَالصِّلَةِ وَالْمَعْرُوفِ وَالإِحْسَانِ إِلَى النَّاسِ عِنْدَ رِجْلَيْهِ، فَيُؤْتَى مِنْ قِبَلِ رَأْسِهِ فَتَقُولُ الصَّلَاةُ: مَا قِبَلِي مَدْخَلٌ ثُمَّ يُؤْتَى عَنْ يَمِينِهِ فَيَقُولُ الصِّيَامُ: مَا قِبَلِي مَدْخَلٌ ثُمَّ يُؤْتَى عَنْ يَسَارِهِ فَتَقُولُ الزَّكَاةُ: مَا قِبَلِي مَدْخَلٌ ، ثُمَّ يُؤْتَى مِنْ قِبَلِ رِجْلَيْهِ فَيَقُولُ فِعْلُ الْخَيْرَاتِ مِنَ الصَّدَقَةِ وَالصِّلَةِ وَالْمَعْرُوفِ إِلَى النَّاسِ: مَا قِبَلِي مَدْخَلٌ وذكر الحديث بِطُولِهِ."],"takhrij":"حسن: رواه ابن حبان (3113)، والحاكم (1403)، والبيهقي في إثبات عذاب القبر (154) كلهم من طرق عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكر الحديث بطوله، وسبق قبل أبواب.","grade":"حسن","chapter_ar":"باب إن الطاعات وقاية من عذاب القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Ḥibbān (3113), al-Ḥākim (1403), and al-Bayhaqī in Ithbāt ʿAdhāb al-Qabr (154).","chapter_en":"Acts of obedience are protection from the punishment of the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah reported from the Prophet ﷺ: “When the deceased is placed in his grave, he hears the sound of their sandals as they turn away from him. If he is a believer, prayer is at his head, fasting is on his right, zakāh is on his left, and acts of goodness such as charity, family ties, kindness, and good treatment of people are by his feet. He is approached from the direction of his head, and prayer says: There is no entrance from my side. Then he is approached from his right, and fasting says: There is no entrance from my side. Then he is approached from his left, and zakāh says: There is no entrance from my side. Then he is approached from the direction of his feet, and acts of goodness such as charity, family ties, kindness, and good treatment of people say: There is no entrance from my side.” Then he mentioned the rest of the long hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (3113)، والحاكم (1403)، والبيهقي في (( إثبات عذاب القبر )) (154)."},{"num":3885,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَحْسِبُهُ رَفَعَهُ، قَالَ: إِنَّ الْمُؤْمِنَ يَنْزِلُ بِهِ الْمَوْتُ، وَيُعَايِنُ مَا يُعَايِنُ، فَوَدَّ لَوْ خَرَجَتْ يَعْنِي: نَفْسَهُ وَاللَّهُ يُحِبُّ لِقَاءَهُ، وَإِنَّ الْمُؤْمِنَ يُصْعَدُ بِرُوحِهِ إِلَى السَّمَاءِ، فَتَأْتِيهِ أَرْوَاحُ الْمُؤْمِنِينَ، فَيَسْتَخْبِرُونَهُ عَنْ مَعَارِفِهِمْ مِنْ أَهْلِ الأَرْضِ، فَإِذَا قَالَ: تَرَكْتُ فُلانًا فِي الدُّنْيَا، أَعْجَبَهُمْ ذَلِكَ، وَإِذَا قَالَ: إِنَّ فُلانًا قَدْ مَاتَ، قَالُوا: مَا جِيءَ بِهِ إِلَيْنَا، وَإِنَّ الْمُؤْمِنَ يُجْلَسُ فِي قَبْرِهِ، فَيُسْأَلُ: مَنْ رَبُّهُ، فَيَقُولُ: رَبِّي اللَّهُ، فَيَقُولُ: مَنْ نَبِيُّكَ؟ فَيَقُولُ: نَبِيِّي مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَمَا دِينُكَ؟ قَالَ: دِينِي الإِسْلامُ، فَيُفْتَحُ لَهُ بَابٌ فِي قَبْرِهِ، فَيَقُولُ أَوْ يُقَالُ: انْظُرْ إِلَى مَجْلِسِكَ، ثُمَّ يُرَى الْقَبْرَ، فَكَأَنَّمَا كَانَتْ رَقْدَةً، فَإِذَا كَانَ عَدُوُّ اللَّهِ نَزَلَ بِهِ الْمَوْتُ، وَعَايَنَ مَا عَايَنَ، فَإِنَّهُ لا يُحِبُّ أَنْ تُخْرَجَ رُوحُهُ أَبَدًا، وَاللَّهُ يُبْغِضُ لِقَاءَهُ، فَإِذَا جَلَسَ فِي قَبْرِهِ أَوْ أُجْلِسَ يُقَالُ لَهُ: مَنْ رَبُّكَ؟ فَيَقُولُ: لا أَدْرِي، فَيُقَالُ: لاَ دَرَيْتَ، فَيُفْتَحُ لَهُ بَابٌ مِنْ جَهَنَّمَ، ثُمَّ يُضْرَبُ ضَرْبَةً يَسْمَعُ كُلُّ دَابَّةٍ إِلا الثَّقَلَيْنِ، ثُمَّ يُقَالُ لَهُ: نَمْ كَمَا يَنَامُ الْمَنْهُوشُ، فَقُلْتُ لأَبِي هُرَيْرَةَ: مَا الْمَنْهُوشُ؟ قَالَ: الَّذِي يَنْهِشُهُ الدَّوَابُّ وَالْحَيَّاتُ، ثُمَّ يُضَيَّقُ عَلَيْهِ قَبْرُهُ."],"takhrij":"حسن: رواه البزار (9760) وعبد الله بن أحمد في السنة (1447) كلاهما من حديث الوليد بن القاسم، نا يزيد بن كيسان، عن أبي حازم، عن أبي هريرة، فذكره، واللفظ للبزار.","grade":"حسن","chapter_ar":"باب إن أرواح المؤمنين يستخبرون عن معارفهم من أهل الأرض","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bazzār (9760), and ʿAbdullāh ibn Aḥmad in al-Sunnah (1447), with this wording from al-Bazzār.","chapter_en":"The souls of the believers ask about those they knew from the people of the earth","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah, and I think he traced it back to the Prophet ﷺ, said: “When death comes to the believer and he sees what he sees, he wishes that his soul would depart — meaning his soul — and Allah loves to meet him. The believer’s soul then rises to heaven, and the souls of the believers come to him and ask him about the people they knew from the earth. If he says: ‘I left so-and-so in the world,’ they are pleased by that. And if he says: ‘So-and-so has died,’ they say: ‘He was not brought to us.’ The believer is then made to sit in his grave and is asked: Who is your Lord? He says: My Lord is Allah. Then: Who is your prophet? He says: My prophet is Muhammad ﷺ. Then it is said: What is your religion? He says: My religion is Islam. Then a gate is opened for him in his grave, and it is said — or he says —: Look at your place. Then he sees the grave, and it is as though it had been only a sleep. But when the enemy of Allah is overtaken by death and sees what he sees, he never wants his soul to leave, and Allah hates to meet him. Then when he is made to sit in his grave — or is seated — it is said to him: Who is your Lord? He says: I do not know. It is said: You did not know. Then a gate from Hell is opened for him. Then he is struck a blow that every creature hears except humans and jinn. Then it is said to him: Sleep as the one who has been violently bitten sleeps.” I asked Abū Hurayrah: What is “the one who has been violently bitten”? He said: The one whom beasts and snakes have torn at, then his grave is tightened upon him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (9760)، وعبد الله بن أحمد في السنة (1447)، واللفظ للبزار."},{"num":3886,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا دَخَلَ الْمَيِّتُ الْقَبْرَ، مُثِّلَتْ لَهُ الشَّمْسُ عِنْدَ غُرُوبِهَا، فَيَقُولُ: دَعُونِي أُصَلِّي."],"takhrij":"حسن: رواه ابن ماجه (4272) عن إسماعيل بن حفصٍ الأُبلّي، قال: حدثنا أبو بكر بن عياش، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب المسلم في قبره تُمثَّل له الشمس عند غروبها فيقول: دعوني أُصلِّي","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (4272), authenticated by Ibn Ḥibbān (3116).","chapter_en":"The Muslim in his grave is shown the sun at its setting and says: Let me pray","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":20,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Messenger of Allah ﷺ said: “When the deceased enters the grave, the sun is represented to him as it is setting, and he says: ‘Leave me so I can pray.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (4272)، وصححه ابن حبان (3116)."},{"num":3887,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ بن عبدالله قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: إِذَا دَخَلَ الْمُؤْمِنُ قَبْرَهُ فَأَتَاهُ مَلَكَانِ فَانْتَهَرَاهُ فَيَقُومُ يَهُبُّ كَمَا يَهُبُّ النَّائِمُ فَيَسْأَلَانِهِ: مَنْ رَبُّكَ؟ وَمَا دِينُكَ؟ وَمَنْ نَبِيُّكَ؟ فَيَقُولُ: اللَّهُ رَبِّي، وَالْإِسْلَامُ دِينِي، وَمُحَمَّدٌ نَبِيِّي، فَيَقُولَانِ لَهُ: صَدَقْتَ كَذَلِكَ كُنْتَ، فَيُقَالُ: أَفْرِشُوهُ مِنَ الْجَنَّةِ، وَأَلْبِسُوهُ مِنَ الْجَنَّةِ، فَيَقُولُ: دَعُونِي حَتَّى آتِيَ أَهْلِي، فَيَقُولَانِ: اسْكُنْ .."],"takhrij":"حسن: رواه ابن أبي عاصم في السنة (866) عن يوسف بن يعقوب الصغار، ثنا أبو بكر بن عياش، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب تمنّي من غُفر له أن يُعلِم أهله بما أكرمه الله تعالى به","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Abī ʿĀṣim (866).","chapter_en":"The wish of the one who was forgiven to inform his family of the honor Allah gave him","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":21,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Messenger of Allah ﷺ said: “When the believer enters his grave, two angels come to him and rebuke him, so he rises in alarm just as a sleeping person rises. Then they ask him: Who is your Lord? What is your religion? Who is your prophet? He says: Allah is my Lord, Islam is my religion, and Muhammad is my prophet. Then they say to him: You have spoken the truth, that is how you were. Then it is said: Spread for him from Paradise and clothe him from Paradise. Then he says: Leave me so I may go to my family. They say: Stay where you are.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم (866)."},{"num":3888,"demo":false,"sanad":"","matn":["عن أبي الزبير أنه سأل جابر بن عبدالله، عن فتَّانَي القَبْر، فقال: سمعتُ النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يقول: إن هذه الأُمَّة تُبتلى في قُبورِها، فإذا أُدْخِلَ المُؤْمِنُ قَبْرَه، وتَوَلَّى عنه أصحابُه، جاء مَلَكٌ شديدُ الانتهار، فيقولُ له: ما كُنْتَ تقولُ في هذا الرَّجلِ؟ فيقولُ المُؤمِنُ: أقـولُ: إنَّه رسولُ الله وعَبْدُه، فيقولُ له المَلَكُ: انظُرْ إلى مَقْعَدِكَ الذي كان لك في النار، قد أنجاكَ الله منه، وأبدَلَكَ بمَقْعَدِكَ الذي تَرَى من النار مَقْعَدَكَ الذي تَرَى من الجنة، فيراهُما كِلاهُما، فيقولُ المُؤْمِنُ: دَعُوني أُبَشِّرْ أهلي، فيُقالُ له: اسْكُنْ، وأمَّا المُنافِقُ، فيُقْعَدُ إذا تَوَلَّى عنه أهله، فيقال له: ما كُنْت تقولُ في هذا الرجل؟ فيقولُ: لا أدري، أقولُ ما يقولُ الناسُ، فيقال له: لا دَرَيْتَ، هذا مقْعَدُكَ الذي كان لَكَ من الجنة، قد أُبْدِلْتَ مكانَه مَقْعدَكَ من النار .","قَالَ جَابِرٌ: فَسَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ: يُبْعَثُ كُلُّ عَبْدٍ فِي الْقَبْرِ عَلَى مَا مَاتَ: الْمُؤْمِنُ عَلَى إِيمَانِهِ، وَالْمُنَافِقُ عَلَى نِفَاقِهِ .."],"takhrij":"صحيح: رواه عبد الرزاق (6744، 6746) عن ابن جريج، قال: أخبرني أبو الزبير أنه سمع جابر بن عبدالله يقول فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تمنّي من غُفر له أن يُعلِم أهله بما أكرمه الله تعالى به","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: ʿAbd al-Razzāq (6744, 6746), Aḥmad (14722), and al-Ṭabarānī in al-Awsaṭ (9072).","chapter_en":"The wish of the one who was forgiven to inform his family of the honor Allah gave him","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":21,"content":{"translation":{"en":["Abū al-Zubayr reported that he asked Jābir ibn ʿAbdullāh about the two examiners of the grave. Jābir said: I heard the Prophet ﷺ say: “This Ummah will be tested in its graves. When the believer is placed in his grave and his companions turn away from him, an angel who is severe in rebuke will come to him and say: ‘What did you used to say about this man?’ The believer will say: ‘I say that he is the Messenger of Allah ﷺ and His servant.’ The angel will say to him: ‘Look at the place that had been prepared for you in the Fire. Allah has saved you from it and has replaced that place in the Fire with the place you now see in Paradise.’ He will see both of them, and the believer will say: ‘Leave me so that I may give glad tidings to my family.’ It will be said to him: ‘Remain where you are.’ As for the hypocrite, he will be made to sit up after his family has turned away from him, and it will be said to him: ‘What did you used to say about this man?’ He will say: ‘I do not know. I used to say what the people said.’ It will be said to him: ‘You did not know. This is the place that had been prepared for you in Paradise; it has now been replaced with your place in the Fire.’”","Jābir said: I also heard the Prophet ﷺ say: “Every servant will be raised in the grave upon the state in which he died: the believer upon his faith and the hypocrite upon his hypocrisy.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3870],"tks":"صحيح: رواه عبد الرزاق (6744، 6746)، وأحمد (14722)، والطبراني في الأوسط (9072)."},{"num":3889,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَ النَّفْخَتَيْنِ أَرْبَعُونَ. قَالُوا: يَا أَبَا هُرَيْرَةَ! أَرْبَعُونَ يَوْمًا؟ قَالَ: أَبَيْتُ. قَالَ: أَرْبَعُونَ سَنَةً؟ قَالَ: أَبَيْتُ. قَالَ: أَرْبَعُونَ شَهْرًا. قَالَ: أَبَيْتُ، وَيَبْلَى كُلُّ شَىْءٍ مِنَ الإِنْسَانِ إِلاَّ عَجْبَ ذَنَبِهِ، فِيهِ يُرَكَّبُ الْخَلْقُ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4814)، ومسلم في الفتن (2955) كلاهما من حديث الأعمش، قال: سمعت أبا صالح، قال: سمعت أبا هريرة فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في عَجْب الذَّنَب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (4814), Muslim (2955), and this is the wording of al-Bukhārī.","chapter_en":"What is reported concerning the tailbone (ʿajb al-dhanab)","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah reported from the Prophet ﷺ: “Between the two trumpet blasts is forty.” They said: “O Abū Hurayrah, forty days?” He said: “I refuse to say.” They said: “Forty years?” He said: “I refuse to say.” They said: “Forty months?” He said: “I refuse to say.” “And everything of the human being decays except the tailbone; from it the creation will be reassembled.”"]},"buhuth":{"en":["Muslim adds at the beginning of the hadith: “Then Allah will send down water from the sky, and they will grow just as vegetation grows. There is nothing of the human being except that it decays except one bone, and that is the tailbone.”","And in another narration with him: “In the human being there is a bone that the earth never consumes; from it he will be reconstructed on the Day of Resurrection.”","They said: “Which bone is it, O Messenger of Allah ﷺ?”","He said: “The tailbone.”","Al-Bayhaqī said: “It is as though Abū Hurayrah did not preserve from the Prophet ﷺ what was intended by the forty, while the people of tafsīr say it is forty years.” Ithbāt ʿAdhāb al-Qabr (242)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12824],"tks":"متفق عليه: رواه البخاري (4814)، ومسلم (2955)، واللفظ للبخاري."},{"num":3890,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  كُلُّ ابْنِ آدَمَ يَأْكُلُهُ التُّرَابُ، إِلَّا عَجْبَ الذَّنَبِ، مِنْهُ خُلِقَ، وَفِيهِ يُرَكَّبُ."],"takhrij":"صحيح: رواه مالك في الجنائز (48) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكر الحديث. ورواه مسلم في الفتن (2955/ 142) من وجه آخر عن المغيرة الحزامي، عن أبي الزناد بإسناده مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في عَجْب الذَّنَب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Mālik (48), Muslim (2955).","chapter_en":"What is reported concerning the tailbone (ʿajb al-dhanab)","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “The earth consumes every part of the son of Adam except the tailbone. From it he was created, and from it he will be reassembled.”"]}},"tuhfa":{},"full":1,"rep":[8253],"tks":"صحيح: رواه مالك (48)، ومسلم (2955)."},{"num":3891,"demo":false,"sanad":"","matn":["عن أَبِي سَعِيدٍ الْخُدْرِيِّ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ: يَأْكُلُ التُّرَابُ كُلَّ شَيْءٍ مِنَ الْإِنْسَانِ إِلَّا عَجْبَ ذَنَبِهِ، قِيلَ: وَمِثْلُ مَا هُوَ يَا رَسُولَ اللَّهِ؟ قَالَ: مِثْلُ حَبَّةِ الْخَرْدَلِ مِنْهُ يَنْبُتُونَ."],"takhrij":"حسن: رواه أحمد (11230)، وأبو يعلى (1382) كلاهما من طريق الحسن بن موسى، عن ابن لهيعة، عن دَرَّاج أبي السمح، عن أبي الهيثم، عن أبي سعيد به.","grade":"حسن","chapter_ar":"باب ما جاء في عَجْب الذَّنَب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (11230), and Abū Yaʿlā (1382).","chapter_en":"What is reported concerning the tailbone (ʿajb al-dhanab)","part_en":"The Book of Funerals","group_ar":"جموع أبواب أحوال الميت في القبر","group_en":"Compilation of chapters on the condition of the deceased in the grave","part_no":13,"group_no":12,"chapter_no":22,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said: The Messenger of Allah ﷺ said: “The earth consumes every part of the human being except his tailbone.” It was said: “What is it like, O Messenger of Allah ﷺ?” He said: “Like a mustard seed. From it you will grow.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (11230)، وأبو يعلى (1382)."},{"num":3892,"demo":false,"sanad":"","matn":["ابْنِ بُرَيْدَةَ، عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ فَزُورُوهَا وَنَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ فَوْقَ ثَلَاثٍ، فَأَمْسِكُوا مَا بَدَا لَكُمْ، وَنَهَيْتُكُمْ عَنِ النَّبِيذِ إِلَّا فِي سِقَاءٍ فَاشْرَبُوا فِي الْأَسْقِيَةِ كُلِّهَا، وَلَا تَشْرَبُوا مُسْكِرًا."],"takhrij":"صحيح: رواه مسلم في الجنائز (977) من طرق عن محمد بن فُضيل، عن أبي سنان (وهو ضرار بن مرة) عن محارب بن دثار، عن ابن بريدة، عن أبيه فذكر الحديث. ورواه النسائي (2032) من وجه آخر، وفيه: ولا تقولوا هُجرا هُجر - بضم الهاء، أي لا تقولوا ما لا ينبغي من الكلام، فإنه ينافي المطلوب الذي هو التذكير.","grade":"صحيح","chapter_ar":"باب استحباب زيارة القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (977).","chapter_en":"The recommendation of visiting graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb said: The Messenger of Allah ﷺ said: “I had forbidden you from visiting graves, so now visit them. I had forbidden you from keeping sacrificial meat for more than three days, so now keep as much as you wish. And I had forbidden you from fermented drinks except in skin containers, so now drink in all containers, but do not drink anything intoxicating.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7225],"tks":"صحيح: رواه مسلم (977)."},{"num":3893,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  اسْتَأْذَنْتُ رَبِّي أَنْ أَسْتَغْفِرَ لِأُمِّي فَلَمْ يَأْذَنْ لِي، وَاسْتَأْذَنْتُهُ أَنْ أَزُورَ قَبْرَهَا، فَأَذِنَ لِي.","وفي رواية قَالَ أبو هريرة: زَارَ النَّبِيُّ صلى الله عليه وسلم قَبْرَ أُمِّهِ، فَبَكَى وَأَبْكَى مَنْ حَوْلَهُ، فَقَالَ: اسْتَأْذَنْتُ رَبِّي فِي أَنْ أَسْتَغْفِرَ لَهَا فَلَمْ يُؤْذَنْ لِي، وَاسْتَأْذَنْتُهُ فِي أَنْ أَزُورَ قَبْرَهَا فَأُذِنَ لِي، فَزُورُوا الْقُبُورَ، فَإِنَّهَا تُذَكِّرُ الْمَوْتَ .."],"takhrij":"صحيح: رواه مسلم في الجنائز (976) من طرق عن مروان بن معاوية، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة فذكر الحديث مثله.","grade":"صحيح","chapter_ar":"باب استحباب زيارة القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (976).","chapter_en":"The recommendation of visiting graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “I asked my Lord for permission to seek forgiveness for my mother, but He did not permit me. And I asked Him for permission to visit her grave, and He permitted me.” In another narration, Abū Hurayrah said: The Prophet ﷺ visited his mother’s grave, then he wept and caused those around him to weep, and he said: “I asked my Lord for permission to seek forgiveness for her, but I was not permitted. And I asked Him for permission to visit her grave, and I was permitted. So visit graves, for they remind one of death.”"]},"buhuth":{"en":["Al-Baghawī, may Allah have mercy on him, said: “It is said that his mother’s grave was at al-Abwā’, and that he passed by it in the year of al-Ḥudaybiyah. It is also narrated that he visited his mother’s grave with one thousand armed riders.” Sharḥ al-Sunnah (5/463).","His statement “I asked my Lord for permission to seek forgiveness for my mother” may have been before the revelation of the verse: “It is not for the Prophet and those who believe to seek forgiveness for the polytheists, even if they are close relatives.” [al-Tawbah 9:113]. It may also have been after that, and he hoped for a special exception regarding his mother.","This hadith shows the permissibility of visiting the graves of polytheists for admonition and reflection by seeing their graves. This is supported by the end of the hadith: “Visit graves, for they remind one of death.” In this regard, the grave of a Muslim and the grave of a polytheist are the same."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (976)."},{"num":3894,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ، فَزُورُوهَا، فَإِنَّ فِيهَا عِبْرَةً، وَنَهَيْتُكُمْ عَنِ النَّبِيذِ فَاشْرَبُوا، وَلَا أُحِلُّ مُسْكِرًا، وَنَهَيْتُكُمْ عَنِ الْأَضَاحِيِّ فَكُلُوا."],"takhrij":"حسن: رواه أحمد (11329) عن يحيى بن آدم، حدثنا ابن المبارك، عن أُسامة، عن محمد بن يحيى بن حَبَّان، عن عمه، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب استحباب زيارة القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (11329).","chapter_en":"The recommendation of visiting graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said: The Messenger of Allah ﷺ said: “I had forbidden you from visiting graves, so now visit them, for in them is a lesson. And I had forbidden you from fermented drinks, so now drink, but I do not allow anything intoxicating. And I had forbidden you regarding sacrificial meat, so now eat.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7549],"tks":"حسن: رواه أحمد (11329)."},{"num":3895,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُنْتُ نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ، أَلَا فَزُورُوهَا، فَإِنَّهُ يُرِقُّ الْقَلْبَ، وَتُدْمِعُ الْعَيْنَ، وَتُذَكِّرُ الْآخِرَةَ، وَلَا تَقُولُوا هُجْرًا."],"takhrij":"حسن: رواه الحاكم (1393) بإسناده عن عامر بن يساف، ثنا إبراهيم ابن طهمان، عن يحيى بن عباد، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب استحباب زيارة القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ḥākim (1393).","chapter_en":"The recommendation of visiting graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik said: The Messenger of Allah ﷺ said: “I had forbidden you from visiting graves. Now visit them, for they soften the heart, bring tears to the eyes, and remind one of the Hereafter. But do not speak improper words.”"]},"buhuth":{"en":["The phrase “do not speak improper words” means: do not say ugly statements such as “Woe to me,” and similar expressions."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (1393)."},{"num":3896,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  رَخَّصَ فِي زِيَارَةِ الْقُبُورِ.","وفي رواية: عَنْ عبدالله بْنِ أَبِي مُلَيْكَةَ، أَنَّ عَائِشَةَ أَقْبَلَتْ ذَاتَ يَوْمٍ مِنَ الْمَقَابِرِ، فَقُلْتُ لَهَا يَا أُمَّ الْمُؤْمِنِينَ! مِنْ أَيْنَ أَقْبَلْتِ؟ قَالَتْ: مِنْ قَبْرِ أَخِي عبدالرحمن بْنِ أَبِي بَكْرٍ، فَقُلْتُ لَهَا: أَلَيْسَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم نَهَى عَنْ زِيَارَةِ الْقُبُورِ؟ قَالَتْ: نَعَمْ كَانَ نَهَى، ثُمَّ أُمِرَ بِزِيَارَتِهَا."],"takhrij":"صحيح: رواه ابن ماجه (1570) عن إبراهيم بن سعيد الجوهري، قال: حدثنا رَوح، قال: حدثنا بسطام بن مسلم، قال: سمعت أبا التيَّاح، قال: سمعت ابن أبي مليكة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب استحباب زيارة القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Mājah (1570), and the second narration was reported by al-Ḥākim (1392), and from him by al-Bayhaqī (4/78).","chapter_en":"The recommendation of visiting graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["ʿĀ’ishah reported that the Messenger of Allah ﷺ permitted visiting graves. In another narration, ʿAbdullāh ibn Abī Mulaykah said that ʿĀ’ishah came one day from the graveyard, so I said to her: “O Mother of the Believers, where are you coming from?” She said: “From the grave of my brother, ʿAbd al-Raḥmān ibn Abī Bakr.” I said: “Did not the Messenger of Allah ﷺ forbid visiting graves?” She said: “Yes, he had forbidden it, then later he commanded that they be visited.”"]},"buhuth":{"en":["The fuller account of this story was narrated by al-Tirmidhī (1055): ʿAbd al-Raḥmān ibn Abī Bakr died at Ḥubshī, then he was carried to Makkah and buried there. When ʿĀ’ishah arrived, she went to the grave of ʿAbd al-Raḥmān ibn Abī Bakr and said:","We were like the two close companions of Judhaymah for a long stretch of time,","until it was said they would never be separated.","But when we parted, it was as though Mālik and I,","despite our long companionship, had not spent even one night together.","Then she said: “By Allah, if I had been present with you, you would not have been buried except where you died. And if I had witnessed your burial, I would not have visited you.”","The phrase “at Ḥubshī” refers to a mountain below Makkah, about six miles from it.","Her statement “If I had witnessed your burial, I would not have visited you” indicates that visiting graves is disliked for women.","Shaykh al-Islām said: “This indicates that visiting graves is not recommended for women as it is for men. If it were, then it would have been recommended for her to visit him just as it is recommended for men, whether she had been present or not.” Majmūʿ al-Fatāwā (24/345)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1570)، والرواية الثانية رواها الحاكم (1392)، وعنه البيهقي (7207)."},{"num":3897,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ قَيْسِ بْنِ مَخْرَمَةَ بْنِ الْمُطَّلِبِ أَنَّهُ قَالَ يَوْمًا: أَلَا أُحَدِّثُكُمْ عَنِّي، وَعَنْ أُمِّي، قَالَ: فَظَنَنَّا أَنَّهُ يُرِيدُ أُمَّهُ الَّتِي وَلَدَتْهُ، قَالَ: قَالَتْ عَائِشَةُ: أَلَا أُحَدِّثُكُمْ عَنِّي وَعَنْ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قُلْنَا: بَلَى، قَالَ: قَالَتْ: لَمَّا كَانَتْ لَيْلَتِي الَّتِي كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا عِنْدِي، انْقَلَبَ فَوَضَعَ رِدَاءَهُ، -فَذَكَرْتُ الْحَدِيثَ بِطُولِهِ الَّذِي فِي بَابِ مَا جَاءَ مِنْ الْأَدْعِيَةِ لِأَصْحَابِ الْقُبُورِ وَفِيهِ-: قَالَتْ: قُلْتُ: كَيْفَ أَقُولُ لَهُمْ يَا رَسُولَ اللهِ؟ قَالَ: قُولِي: السَّلَامُ عَلَى أَهْلِ الدِّيَارِ مِنَ الْمُؤْمِنِينَ، وَالْمُسْلِمِينَ، وَيَرْحَمُ اللهُ الْمُسْتَقْدِمِينَ مِنَّا، وَالْمُسْتَأْخِرِينَ، وَإِنَّا إِنْ شَاءَ اللهُ بِكُمْ لَلَاحِقُونَ »."],"takhrij":"صحيح: رواه مسلم في الجنائز (974/103) من طرق عن ابن جريج قال: أخبرني عبدالله بن كثير بن المطلب، عن محمد بن قيس بن مخرمة بن المطلب فذكره بطوله.","grade":"صحيح","chapter_ar":"باب استحباب زيارة القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (974).","chapter_en":"The recommendation of visiting graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Muḥammad ibn Qays ibn Makhramah ibn al-Muṭṭalib reported that ʿĀ’ishah said: On the night when the Prophet ﷺ was with her, he turned over and put down his cloak — then she mentioned the long hadith already cited in the chapter on supplications for the people of the graves — and in it she said: “How should I speak to them, O Messenger of Allah ﷺ?” He said: “Say: Peace be upon the inhabitants of these dwellings among the believers and the Muslims. May Allah have mercy on those of us who have gone ahead and those who come later, and we will, if Allah wills, join you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (974).","voc":["muslim",2200]},{"num":3898,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: لَعَنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَوَّارَاتِ الْقُبُورِ."],"takhrij":"حسن: رواه الترمذي (1056)، وابن ماجه (1576) كلاهما من طريق أبي عوانة، عن عمر بن أبي سلمة، عن أبيه، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء من النهي عن زيارة القبور للنساء","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Tirmidhī (1056), Ibn Mājah (1576). Al-Tirmidhī said: “Hasan Sahih.”","chapter_en":"What is reported regarding the prohibition of women visiting graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ cursed women who frequently visit graves."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1056)، وابن ماجه (1576). قال الترمذي: (( حسن صحيح ))."},{"num":3899,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ (كُلَّمَا كَانَ لَيْلَتُهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْرُجُ مِنْ آخِرِ اللَّيْلِ إِلَى الْبَقِيعِ فَيَقُولُ: السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَأَتَاكُمْ مَا تُوعَدُونَ، غَدًا مُؤَجَّلُونَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ، اللَّهُمَّ اغْفِرْ لِأَهْلِ بَقِيعِ الْغَرْقَدِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (974) من طرق عن إسماعيل بن جعفر، عن شريك (وهو ابن أبي نمر) عن عطاء بن يسار، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية لأصحاب القبور والاستغفار لأهل البقيع","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (974).","chapter_en":"What is reported of supplications for the people of the graves and seeking forgiveness for the people of al-Baqīʿ","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["ʿĀ’ishah said: Whenever it was her night with the Messenger of Allah ﷺ, he would go out at the end of the night to al-Baqīʿ and say: “Peace be upon you, abode of a believing people. What you were promised has come to you; you are waiting until tomorrow. And we will, if Allah wills, join you. O Allah, forgive the people of Baqīʿ al-Gharqad.”"]}},"tuhfa":{},"full":1,"rep":[11111],"tks":"صحيح: رواه مسلم (974)."},{"num":3900,"demo":false,"sanad":"","matn":["عَنْ محمد بن قيس قَالَ: سَمِعْتُ عَائِشَةُ تُحَدِّثُ فَقَالَتْ: أَلَا أُحَدِّثُكُمْ عَنِّي وَعَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ ؟ قُلْنَا: بَلَى، قَالَتْ: لمَّا كَانَتْ لَيْلَتِي الَّتِي كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهَا عِنْدِي انْقَلَبَ فَوَضَعَ رِدَاءَهُ، وَخَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عِنْدَ رِجْلَيْهِ، وَبَسَطَ طَرَفَ إِزَارِهِ عَلَى فِرَاشِهِ فَاضْطَجَعَ فَلَمْ يَلْبَثْ إِلَّا رَيْثَمَا ظَنَّ أَنْ قَدْ رَقَدْتُ، فَأَخَذَ رداءَهُ رُوَيْداً، وَانْتَعَلَ رُوَيداً، وَفَتَحَ الْبَابَ رُوَيْداً فَخَرَجَ، ثُمَّ أجافَهُ رُوَيْداً، فَجَعَلْتُ دِرْعي فِي رَأْسِي، واخْتَمَرْتُ، وتقنَّعْتُ إِزَارِي، ثُمَّ انْطَلقْتُ عَلَى إثْرِهِ، حتَّى جاءَ البَقِيعَ فَقَامَ فَأَطَالَ الْقِيَامَ، ثُمَّ رَفَعَ يَدَيْهِ ثَلَاثَ مرَّات، ثُمَّ انْحَرَفَ فَانْحَرَفْتُ، فَأَسْرَعَ وأسرعتُ، فهرْوَلَ فَهَرْوَلتُ، فَأَحْضَرَ فَأَحْضَرْتُ، فسَبَقتُه فَدَخَلْتُ، فَلَيْسَ إِلَّا أنِ اضْطَجَعْتُ، فَدَخَلَ فَقَالَ: مَا لكِ؟ يَا عَائِشُ حشْياً رَابيةً قَالَتْ: قلتُ: لَا شَيْءَ، قَالَ: لَتُخْبِرِينِي؟ أَوْ ليُخْبِرَنِّي اللَّطيفُ الْخَبِيرُ قَالَتْ: قلتُ: يَا رَسُولَ اللَّهِ! بِأَبِي أنتَ وأُمِّي، فأَخْبرتُه، قَالَ: فَأَنْتِ السَّوَادُ الَّذِي رَأَيْتَهُ أَمَامي؟ قلتُ: نَعَمْ، فلَهَدَني فِي صَدْرِي لَهْدَةً أوجَعَتْنِي، ثُمَّ قَالَ: أَظنَنْتِ أنْ يَحيفَ اللهُ عَلَيْكِ وَرَسُولُهُ؟ قَالَتْ: مَهْمَا يَكْتُمِ النَّاسُ يَعْلَمْهُ اللهُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : فإنَّ جِبْرِيلَ عَلَيْهِ السَّلَامُ –أَتَانِي حينَ رَأَيْتِ فَنَادَانِي، فأَخْفَاهُ منكِ، فَأَجَبْتُهُ، فأَخْفَيْتُهُ منكِ، وَلَمْ يَكُنْ يَدْخُلُ علَيكِ وقَدْ وَضَعْتِ ثِيَابَكِ، وظَنَنْتُ أنْ قَدْ رَقَدْتِ، فَكَرِهْتُ أَنْ أُوقِظَكِ، وَخَشيتُ أَنْ تَسْتَوحِشي، فَقَالَ: إنَّ رَبَّكَ يَأمُرُكَ أنْ تَأْتِيَ أهلَ الْبَقِيعِ فتَسْتَغْفِرَ لَهُم ، قَالَتْ: قلتُ: كَيْفَ أَقُولُ لَهُمْ؟ يَا رَسُولَ اللَّهِ قَالَ: قُولِي: السَّلَامُ عَلَى أَهْلِ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَيَرْحَمُ اللَّهُ الْمُسْتَقْدِمِينَ مِنَّا وَالْمُسْتَأْخِرِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَلَاحِقُونَ ."],"takhrij":"صحيح: رواه مسلم في الجنائز (974: 103) عن هارون بن سعيد الأيلي، حدثنا عبدالله بن وهب، أخبرنا ابن جريج، عن عبدالله بن كثير بن المطلب، أنه سمع محمد بن قيس، ولم يذكر لفظ الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية لأصحاب القبور والاستغفار لأهل البقيع","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (974/103).","chapter_en":"What is reported of supplications for the people of the graves and seeking forgiveness for the people of al-Baqīʿ","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Muḥammad ibn Qays said: I heard ʿĀ’ishah narrating, and she said: Shall I tell you about myself and the Messenger of Allah ﷺ? We said: Yes. She said: On the night when the Prophet ﷺ was with me, he turned over, placed down his cloak, removed his sandals and set them by his feet, spread the edge of his garment on his bedding, and lay down. He remained only until he thought I had fallen asleep. Then he took his cloak quietly, put on his sandals quietly, opened the door quietly and went out, then closed it quietly. So I put my outer garment over my head, covered myself, wrapped my waistcloth around me, and followed him until he came to al-Baqīʿ. He stood there for a long time, then raised his hands three times, then turned away, and I turned away. He quickened his pace, so I quickened mine. He jogged, so I jogged. He hurried, so I hurried. I got back before him and lay down. Then he entered and said: “What is the matter with you, O ʿĀ’ish? Are you breathing heavily and out of breath?” She said: I said: Nothing. He said: “You will tell me, or the All-Subtle, the All-Aware will tell me.” She said: I said: O Messenger of Allah ﷺ, may my father and mother be sacrificed for you — then I told him. He said: “So you were the dark figure I saw in front of me?” I said: Yes. Then he struck me on the chest in a way that hurt me, then said: “Did you think that Allah and His Messenger would be unfair to you?” She said: Whatever people hide, Allah knows it. Yes. The Messenger of Allah ﷺ said: “Jibrīl came to me when you saw me, and he called me, but he concealed himself from you, so I answered him and concealed it from you. He would not enter upon you while you had laid aside your clothes. I thought you had fallen asleep, so I disliked waking you and feared you might feel lonely. He said: Your Lord commands you to go to the people of al-Baqīʿ and seek forgiveness for them.” She said: I asked: How should I speak to them, O Messenger of Allah ﷺ? He said: “Say: Peace be upon the inhabitants of these dwellings among the believers and the Muslims. May Allah have mercy on those of us who went ahead and those who come later, and we will, if Allah wills, join you.”"]},"buhuth":{"en":["Her phrase “then he closed it” means he shut the door.","His saying “O ʿĀ’ish” uses a shortened vocative form.","The phrase “breathing heavily” means shortness of breath and agitation from moving quickly.","The phrase “raised in the belly” means her abdomen had risen from heavy breathing.","Her phrase “he struck me” means he pushed or hit me on the chest; related expressions include striking or poking."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (974: 103)."},{"num":3901,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا قَالَتْ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَأَرْسَلْتُ بَرِيرَةَ فِي أَثَرِهِ، لِتَنْظُرَ أَيْنَ ذَهَبَ، قَالَتْ: فَسَلَكَ نَحْوَ بَقِيعِ الْغَرْقَدِ، فَوَقَفَ فِي أَدْنَى الْبَقِيعِ، ثُمَّ رَفَعَ يَدَيْهِ، ثُمَّ انْصَرَفَ، فَرَجَعَتْ إِلَيَّ بَرِيرَةُ، فَأَخْبَرَتْنِي، فَلَمَّا أَصْبَحْتُ، سَأَلْتُهُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَيْنَ خَرَجْتَ اللَّيْلَةَ؟ قَالَ: بُعِثْتُ إِلَى أَهْلِ الْبَقِيعِ لِأُصَلِّيَ عَلَيْهِمْ."],"takhrij":"حسن: رواه أحمد (24612) عن قتيبة بن سعيد، قال: حدثنا عبدالعزيز بن محمد، عن علقمة بن أبي علقمة، عن أمه، عن عائشة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية لأصحاب القبور والاستغفار لأهل البقيع","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (24612).","chapter_en":"What is reported of supplications for the people of the graves and seeking forgiveness for the people of al-Baqīʿ","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["ʿĀ’ishah said: The Messenger of Allah ﷺ went out one night, so I sent Barīrah after him to see where he had gone. She said: He went toward Baqīʿ al-Gharqad, stood at the nearest part of al-Baqīʿ, then raised his hands and went back. Barīrah returned to me and informed me. When morning came, I asked him and said: O Messenger of Allah ﷺ, where did you go last night? He said: “I was sent to the people of al-Baqīʿ to pray for them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (24612)."},{"num":3902,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحُصَيب قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُهُمْ إِذَا خَرَجُوا إِلَى الْمَقَابِرِ، فَكَانَ قَائِلُهُمْ يَقُولُ (فِي رِوَايَةِ أَبِي بَكْرٍ): السَّلَامُ عَلَى أَهْلِ الدِّيَارِ، (وَفِي رِوَايَةِ زُهَيْرٍ): السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ لَلَاحِقُونَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ ."],"takhrij":"صحيح: رواه مسلم في الجنائز (975) عن أبي بكر بن أبي شيبة وزهير ابن حرب، قالا: حدثنا محمد بن عبدالله الأسدي، عن سفيان، عن علقمة بن مَرْثَدٍ، عن سليمان بن بريدة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية لأصحاب القبور والاستغفار لأهل البقيع","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (975).","chapter_en":"What is reported of supplications for the people of the graves and seeking forgiveness for the people of al-Baqīʿ","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb said: The Messenger of Allah ﷺ used to teach them, when they went out to the graveyards, that the one speaking should say — in Abū Bakr’s narration —: “Peace be upon the inhabitants of these dwellings.” And in Zuhayr’s narration: “Peace be upon you, inhabitants of these dwellings among the believers and Muslims. We will, if Allah wills, join you. I ask Allah for well-being for us and for you.”"]},"buhuth":{"en":["And al-Nasā’ī (2040) added after “we will join you”: “You have gone ahead for us, and we are following after you. I ask Allah for well-being for us and for you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11113],"tks":"صحيح: رواه مسلم (975)."},{"num":3903,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى الْمَقْبُرَةِ، فَقَالَ: السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ."],"takhrij":"صحيح: رواه مالك في الطهارة (28) عن العلاء بن عبدالرحمن، ومن طريقه مسلم (249) في حديث طويل مضى في الطّهارة، باب فضل الوضوء والغرّ المحجلين من آثار الوضوء.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية لأصحاب القبور والاستغفار لأهل البقيع","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Mālik (28), Muslim (249).","chapter_en":"What is reported of supplications for the people of the graves and seeking forgiveness for the people of al-Baqīʿ","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ went out to the graveyard and said: “Peace be upon you, abode of a believing people. We will, if Allah wills, join you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11114],"tks":"صحيح: رواه مالك (28)، ومسلم (249)."},{"num":3904,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةُ قَالَتْ:... جَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَقِيعَ، فَقَامَ، فَأَطَالَ الْقِيَامَ، ثُمَّ رَفَعَ يَدَيْهِ ثَلَاثَ مَرَّاتٍ."],"takhrij":"صحيح: رواه مسلم في الجنائز (974: 103) عن هارون بن سعيد الأيلي، حدثنا عبدالله بن وهب، أخبرنا ابن جريج، عن عبدالله بن كثير بن المطلب، أنه سمع محمد بن قيس أنه قال: سمعت عائشة تقول: فذكر الحديث بطوله وهو مذكور في باب الأدعية لأصحاب القبور.","grade":"صحيح","chapter_ar":"باب رفع اليدين عند الدعاء لأصحاب القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (974/103).","chapter_en":"Raising the hands when supplicating for the people of the graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["ʿĀ’ishah said: The Prophet ﷺ came to al-Baqīʿ, stood there for a long time, then raised his hands three times."]},"buhuth":{"en":["It is not a condition, when greeting the people of the graves and supplicating for them, to face the qiblah. Rather, one greets them and prays for them while facing them wherever one is. That is because the Prophet ﷺ did not command this, and it is established that he frequently visited al-Baqīʿ, yet it was not reported that he used to face the qiblah when greeting its occupants and supplicating for them. Likewise, when greeting the Prophet ﷺ and his two companions and praying for them, facing the qiblah is not required by the agreement of the scholars. This is the view preferred by Shaykh Ibn Bāz, may Allah have mercy on him, in his fatwas."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (974: 103).","voc":["muslim",2200]},{"num":3905,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بن سَعْدٍ، عن أَبِيهِ أَنَّ أَعْرَابِيًّا، أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! أَيْنَ أَبِي؟ فَقَالَ: فِي النَّارِ قَالَ: فَأَيْنَ أَبُوكَ؟ قَالَ: حَيْثُ مَا مَرَرْتَ بِقَبْرِ كَافِرٍ فَبَشِّرْهُ بِالنَّارِ .","وفي رواية: فَأَسْلَمَ الأَعْرَابِىُّ وَقَالَ: لَقَدْ كَلَّفَنِى رَسُولُ اللَّهِ صلى الله عليه وسلم تَعَبًا مَا مَرَرْتُ بِقَبْرِ كَافِرٍ إِلَاّ بَشَّرْتُهُ بِالنَّارِ."],"takhrij":"صحيح: رواه البزار كشف الأستار (93)، والطبرانيّ في الكبير (326)، وابن السني في عمل اليوم والليلة (595) كلهم من طرق عن إبراهيم بن سعد، عن الزهري، عن عامر بن سعد فذكره.","grade":"صحيح","chapter_ar":"باب من زار قبر الكافر فلا يدعو له، بل يبشره بالنار","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bazzār in Kashf al-Astār (93), and Ibn al-Sunnī in ʿAmal al-Yawm wa al-Laylah (595).","chapter_en":"Whoever visits the grave of a disbeliever does not pray for him, but informs him of the Fire","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["ʿĀmir ibn Saʿd narrated from his father that a Bedouin came to the Prophet ﷺ and said: O Messenger of Allah ﷺ, where is my father? He said: “In the Fire.” He said: Then where is your father? He said: “Whenever you pass by the grave of a disbeliever, tell him of the Fire.” And in another narration: The Bedouin accepted Islam and said: The Messenger of Allah ﷺ gave me a burdensome task; I never passed by the grave of a disbeliever except that I told him of the Fire."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار في كشف الأستار (93)، وابن السني في عمل اليوم والليلة (595)."},{"num":3906,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النّبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إنّ أَبِي كَانَ يصلُ الرَّحم، وَكَانَ وَكَانَ، فَأَيْنَ هُوَ؟ قَالَ: فِي النَّارِ . قَالَ: فَكَأَنَّهُ وَجَدَ مِنْ ذَلِكَ، فَقَالَ: يَا رَسُولَ اللَّهِ، فَأَيْنَ أَبُوكَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : حَيْثُمَا مَرَرْتَ بِقَبْرِ مشرك فبشِّرْه بِالنَّارِ . قَالَ: فَأَسْلَمَ الأَعْرَابِيُّ بَعْدُ، وَقَالَ: لَقَدْ كَلَّفَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَعَبًا، مَا مَرَرْتُ بِقَبْرِ كَافِرٍ إلاّ بشّرتُه بِالنَّارِ ."],"takhrij":"صحيح: رواه ابن ماجه (1573) عن محمد بن إسماعيل بن البختريّ الواسطيّ، قال: حدّثنا يزيد بن هارون، عن إبراهيم بن سعد، عن الزّهريّ، عن سالم، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب من زار قبر الكافر فلا يدعو له، بل يبشره بالنار","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Mājah (1573).","chapter_en":"Whoever visits the grave of a disbeliever does not pray for him, but informs him of the Fire","part_en":"The Book of Funerals","group_ar":"جموع أبواب زيارة القبور","group_en":"Compilation of chapters on visiting graves","part_no":13,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: A Bedouin came to the Prophet ﷺ and said: O Messenger of Allah ﷺ, my father used to maintain family ties, and he used to do such-and-such, so where is he? He said: “In the Fire.” It was as though the man was troubled by that, so he said: O Messenger of Allah ﷺ, then where is your father? So the Messenger of Allah ﷺ said: “Whenever you pass by the grave of a polytheist, tell him of the Fire.” He said: Then the Bedouin later accepted Islam and said: The Messenger of Allah ﷺ gave me a burdensome task; I never passed by the grave of a disbeliever except that I told him of the Fire."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1573)."},{"num":3907,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنْ مُعَاذِ بْنِ جَبَلٍ، قــال: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إنّك تَأْتِي قَوْمًا مِنْ أَهْلِ الْكِتَابِ، فَادْعُهُمْ إِلَى شَهَادَةِ أَنْ لَا إِلَهَ إلاّ اللَّهُ وَأَنِّي رَسُولُ اللَّهِ. فإنْ هُمْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ أنّ اللَّهَ افْتَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي كلّ يَوْمٍ وَلَيْلَةٍ. فإنْ هُمْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ أنّ اللَّهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فتردُّ فِي فُقَرَائِهِمْ. فإنْ هُمْ أَطَاعُوا لِذَلِكَ، فإيّاكَ وَكَرَائِمَ أَمْوَالِهِمْ. واتّقِ دَعْوَةَ الْمَظْلُومِ فَإِنَّهُ لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ ."],"takhrij":"متفق عليه: رواه البخاريُّ في الزّكاة (1458)، ، ومسلم في الإيمان (19) كلاهما من طريق يحيى بن عبدالله بن صيفي، عن أبي معبد، عن ابن عباس، فذكره. واللّفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1458), Muslim (19), and this is the wording of Muslim.","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated from Muʿādh ibn Jabal that he said: The Messenger of Allah ﷺ sent me and said: “You are going to a people from the People of the Book, so call them to testify that there is no god but Allah and that I am the Messenger of Allah ﷺ. If they obey you in that, then inform them that Allah has made five prayers obligatory upon them in every day and night. If they obey you in that, then inform them that Allah has made charity obligatory upon them, to be taken from their rich and returned to their poor. If they obey you in that, then beware of taking the best parts of their wealth. And fear the supplication of the oppressed, for there is no barrier between it and Allah.”"]},"buhuth":{"en":["The phrase “the best parts of their wealth” means the finest and most valuable possessions — the animals or property with the highest quality, such as abundant milk, beautiful form, or extra meat or wool."]},"intro_kitab":{"ar":["فُرضت الزكاة في السنة الثانية على الصحيح."],"en":["Zakat was prescribed in the second year after the migration, according to the stronger view."]},"intro":{"ar":["قال اللّٰه تعالى: (وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ) [سورة البقرة: ٤٣].","والآيات في هذا المعنى كثيرة.","والزكاة تجب في أربعة أصناف:","١- السائمة من بهيمة الأنعام.","٢- المعادن من الذهب والفضة، وما يوجد من الركاز.","٣- عروض التجارة.","٤- الخارج من الأرض من الحبوب والثمار.","وسيأتي تفصيل كل هذه الأصناف."],"en":["Allah the Exalted said: “Establish the prayer and give zakat.” [al-Baqarah 2:43]","There are many verses with this meaning.","Zakat is due in four categories:","Grazing livestock from cattle, camels, and sheep.","Gold and silver, minerals, and buried treasure found in the ground.","Trade goods.","Produce that comes out of the earth, such as grains and fruits.","The details of all these categories will come later."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1458)، ومسلم (19)، واللفظ لمسلم."},{"num":3908,"demo":false,"sanad":"","matn":["عن أَبِي أَيُّوبَ أنّ أَعْرَابِيًّا عرض لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وهو فِي سَفَرٍ، فَأَخَذَ بخطام ناقته أَوْ بزمامها، ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ، أَوْ يَا مُحَمَّدُ، أَخْبِرْنِي بِمَا يُقَرِّبُنِي مِنَ الْجَنَّةِ وَمَا يُبَاعِدُنِي مِنَ النَّارِ، قَالَ: فَكَفَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ نَظَرَ فِي أَصْحَابِهِ، ثُمَّ قَالَ: لَقَدْ وُفِّقَ، أَوْ لَقَدْ هُدِيَ، قَالَ: كَيْفَ قُلْتَ؟ قَالَ: فَأَعَادَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصِلُ الرَّحِمَ، دَعِ النَّاقَةَ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1396)، ومسلم في الإيمان (13) كلاهما من طريق عمرو بن عثمان، حدّثنا موسى بن طلحة، قال: حدّثني أبو أيوب، فذكره.","grade":"متفق عليه","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1396), Muslim (13), and this is the wording of Muslim.","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Ayyūb reported that a Bedouin came across the Messenger of Allah ﷺ while he was on a journey and took hold of the rein of his camel — or its halter — then said: “O Messenger of Allah ﷺ,” or, “O Muhammad, tell me what will bring me near to Paradise and keep me far from the Fire.” The Prophet ﷺ paused, then looked at his companions and said: “He has been guided,” or, “He has been granted success.” Then he said: “What did you say?” So the man repeated it. Then the Prophet ﷺ said: “Worship Allah and do not associate anything with Him, establish the prayer, give zakat, and maintain ties of kinship. Let go of the camel.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1396)، ومسلم (13)، واللفظ لمسلم."},{"num":3909,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ،  أَنَّ أَعْرَابِيًّا جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ دَخَلْتُ الْجَنَّةَ، قَالَ: تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ الْمَكْتُوبَةَ، وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ، وَتَصُومُ رَمَضَانَ، قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ لَا أَزِيدُ عَلَى هَذَا شَيْئًا أَبَدًا، وَلَا أَنْقُصُ مِنْهُ، فَلَمَّا وَلَّى قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى رَجُلٍ مِنْ أَهْلِ الْجَنَّةِ، فَلْيَنْظُرْ إِلَى هَذَا."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1397)، ومسلم في الإيمان (14) كلاهما من طريق عفّان بن مسلم، حدّثنا وُهيب، عن يحيى بن سعيد بن حيان، عن أبي زرعة، عن أبي هريرة، فذكر الحديث. واللّفظ لمسلم، ولفظ البخاريّ نحوه.","grade":"متفق عليه","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1397), Muslim (14), and this is the wording of Muslim.","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah reported that a Bedouin came to the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ, guide me to an action that, if I do it, I will enter Paradise.” He said: “Worship Allah and do not associate anything with Him, establish the prescribed prayer, give the obligatory zakat, and fast Ramadan.” The man said: “By the One in whose hand is my soul, I will never add anything to this, nor will I take anything away from it.” When he turned away, the Prophet ﷺ said: “Whoever would like to look at a man from the people of Paradise, let him look at this man.”"]}},"tuhfa":{},"full":1,"rep":[4294],"tks":"متفق عليه: رواه البخاري (1397)، ومسلم (14)، واللفظ لمسلم."},{"num":3910,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: لَمَّا تُوُفِّيَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاسْتُخْلِفَ أَبُو بَكْرٍ بَعْدَهُ وَكَفَرَ مَنْ كَفَرَ مِنْ الْعَرَبِ، قَالَ عُمَرُ لأَبِي بَكْرٍ: كَيْفَ تُقَاتِلُ النَّاسَ وَقَدْ قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لا إِلَهَ إِلا الله. فَمَنْ قَالَ لا إِلَهَ إِلا الله عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ إِلا بِحَقِّهِ وَحِسَابُهُ عَلَى الله . فَقَالَ: وَاللَّهِ لأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلاةِ وَالزَّكَاةِ، فَإِنَّ الزَّكَاةَ حَقُّ المالِ، وَالله لَوْ مَنَعُونِي عِقَالا كَانُوا يُؤَدُّونَهُ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَاتَلْتُهُمْ عَلَى مَنْعِهِ. فَقَالَ عُمَرُ: فَوَالله مَا هُوَ إِلا أَنْ رَأَيْتُ الله قَدْ شَرَحَ صَدْرَ أَبِي بَكْرٍ لِلْقِتَالِ فَعَرَفْتُ أَنَّهُ الحقُّ."],"takhrij":"متفق عليه: رواه البخاريّ في الاعتصام بالكتاب والسنة (7284)، ومسلم في الإيمان (20: 32) كلاهما عن قتيبة بن سعيد، حدّثنا ليث، عن عقيل، عن الزّهريّ، أخبرني عبيدالله بن عبدالله بن عتبة بن مسعود، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (7284), Muslim (32).","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah said: When the Messenger of Allah ﷺ died and Abū Bakr was appointed after him, and some of the Arabs fell into disbelief, ʿUmar said to Abū Bakr: “How can you fight the people when the Messenger of Allah ﷺ said: ‘I have been commanded to fight the people until they say: There is no god but Allah. Whoever says: There is no god but Allah has protected his wealth and his life from me, except by its due right, and his reckoning is with Allah.’?” Abū Bakr said: “By Allah, I will definitely fight whoever separates prayer from zakat, because zakat is the due right of wealth. By Allah, if they withhold from me even a rope that they used to give to the Messenger of Allah ﷺ, I will fight them for withholding it.” ʿUmar said: “By Allah, it was nothing but that I saw Allah had opened the chest of Abū Bakr to fighting, and I knew that it was the truth.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7859,9858],"tks":"متفق عليه: رواه البخاري (7284)، ومسلم (20: 32)."},{"num":3911,"demo":false,"sanad":"","matn":["عَنْ أَبِي جَمْرَةَ قَالَ: كُنْتُ أُتَرْجِمُ بَيْنَ يَدَيْ ابْنِ عَبَّاسٍ وَبَيْنَ النَّاسِ فَأَتَتْهُ امْرَأَةٌ تَسْأَلُهُ عَنْ نَبِيذِ الْجَرِّ فَقَالَ: إِنَّ وَفْدَ عَبْدِ الْقَيْسِ أَتَوْا رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ الْوَفْدُ أَوْ مَنْ الْقَوْمُ؟ . قَالُوا رَبِيعَةُ قَالَ: مَرْحَبًا بِالْقَوْمِ أَوْ بِالْوَفْدِ غَيْرَ خَزَايَا وَلا النَّدَامَى . قَالَ: فَقَالُوا: يَا رَسُولَ الله إِنَّا نَأْتِيكَ مِنْ شُقَّةٍ بَعِيدَةٍ، وَإِنَّ بَيْنَنَا وَبَيْنَكَ هَذَا الحيَّ مِنْ كُفَّارِ مُضَرَ وَإِنَّا لا نَسْتَطِيعُ أَنْ نَأْتِيَكَ إِلا فِي شَهْرِ الحرَامِ فَمُرْنَا بِأَمْرٍ فَصْلٍ نُخْبِرْ بِهِ مَنْ وَرَاءَنَا نَدْخُلُ بِهِ الجنَّةَ. قَالَ: فَأَمَرَهُمْ بِأَرْبَعٍ وَنَهَاهُمْ عَنْ أَرْبَعٍ. قَالَ: أَمَرَهُمْ بِالإِيمَانِ بالله وَحْدَهُ، وَقَالَ: هَلْ تَدْرُونَ مَا الْإِيمَانُ بالله؟ . قَالُوا: الله وَرَسُولُهُ أَعْلَمُ. قَالَ: شَهَادَةُ أَنْ لا إِلَهَ إِلا الله، وَأَنَّ مُحَمَّدًا رَسُولُ الله، وَإِقَامُ الصَّلاةِ، وَإِيتَاءُ الزَّكَاةِ، وَصَوْمُ رَمَضَانَ، وَأَنْ تُؤَدُّوا خُمُسًا مِنْ الْمَغْنَمِ، وَنَهَاهُمْ عَنْ الدُّبَّاءِ، وَالحَنْتَمِ وَالمُزَفَّتِ .","قَالَ شُعْبَةُ: وَرُبَّمَا قَالَ النَّقِيرِ. قَالَ شُعْبَةُ: وَرُبَّمَا قَالَ المقَيَّرِ. وَقَال: احْفَظُوهُ وَأَخْبِرُوا بِهِ مِنْ وَرَائِكُمْ .","وقَالَ أَبُو بَكْرٍ فِي رِوَايَتِهِ: مَنْ وَرَاءَكُمْ . وَلَيْسَ فِي رِوَايَتِهِ المقَيَّرِ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1398)، وفي المغازي bukhari(4368)، ومسلم في الإيمان (17: 24) كلاهما من طريق أبي جمرة، به، فذكره.","grade":"متفق عليه","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4368, 1398) and Muslim (17); this is Muslim’s wording.","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Jamrah said: I used to interpret between Ibn ʿAbbās and the people. A woman came to him asking about nabīdh prepared in earthen jars. He said: The delegation of ʿAbd al-Qays came to the Messenger of Allah ﷺ. The Messenger of Allah ﷺ asked: “Who are the delegation—or who are the people?” They replied: “Rabīʿah.” He said: “Welcome to the people—or the delegation—without disgrace and without regret.” They said: “O Messenger of Allah ﷺ, we come to you from a distant land, and between us and you live these disbelievers of Muḍar. We are unable to come to you except during the sacred month. So command us with a decisive instruction that we may convey to those behind us and by which we may enter Paradise.” He commanded them with four things and prohibited them from four things. He commanded them to believe in Allah alone and asked: “Do you know what belief in Allah is?” They replied: “Allah and His Messenger know best.” He said: “To testify that there is no deity worthy of worship except Allah and that Muḥammad is the Messenger of Allah ﷺ; to establish the prayer; to give zakat; to fast Ramadan; and to give one-fifth of the spoils of war.” He forbade them from al-dubbāʾ, al-ḥantam, and al-muzaffat. Shuʿbah said:","“Sometimes he said al-naqīr.” Shuʿbah also said: “Sometimes he said al-muqayyar.” And he said: “Memorize this and inform those behind you of it.” Abū Bakr’s narration says, “those behind you,” and his version does not contain the word al-muqayyar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4368، 1398)، ومسلم (17)، واللفظ لمسلم."},{"num":3912,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: كنا نتمنّى أن يأتي الأعرابيُّ العاقل فيسأل النّبيَّ صلى الله عليه وسلم ونحن عنده، فبينا نحن كذلك إذ أتاه أعرابيٌّ فجثا بين يدي النّبيّ صلى الله عليه وسلم فقال (فذكر الحديث) وجاء فيه: ... وزعم رسولك أنّ علينا زكاة في أموالنا؟ فقال (النبيّ صلى الله عليه وسلم: ( صدق . فقال الأعرابيّ: والذي بعثك بالحقّ لا أزيد عليهن ولا أنقص منهن، فقال النبيّ صلى الله عليه وسلم: لئنْ صدق ليدخلن الجنّة ."],"takhrij":"متفق عليه: رواه البخاريّ في العلم (63)، ومسلم في الإيمان (12) واللفظ له، كلاهما من طريق سليمان بن المغيرة، عن ثابت، عن أنس، فذكره بطوله كما مضى في كتاب الإيمان.","grade":"متفق عليه","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (63), Muslim (12), and this is the wording of Muslim.","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik said: We were forbidden from asking the Messenger of Allah ﷺ about anything, so we liked it when an intelligent man from the desert would come and ask him while we listened. A man from the desert came and said: “O Muḥammad, your messenger came to us and claimed that you say Allah sent you.” He said: “He spoke the truth.” He asked: “Who created the sky?” He said: “Allah.” He asked: “Who created the earth?” He said: “Allah.” He asked: “Who erected these mountains and placed in them what He placed?” He said: “Allah.” He said: “By the One who created the sky, created the earth, and erected these mountains, did Allah send you?” He said: “Yes.” He said: “Your messenger claims that five prayers are obligatory upon us during our day and night.” He said: “He spoke the truth.” He asked: “By the One who sent you, did Allah command you with this?” He said: “Yes.” He said: “Your messenger claims that zakat is obligatory upon our wealth.” He said: “He spoke the truth.” He asked: “By the One who sent you, did Allah command you with this?” He said: “Yes.” He said: “Your messenger claims that we must fast the month of Ramadan each year.” He said: “He spoke the truth.” He asked: “By the One who sent you, did Allah command you with this?” He said: “Yes.” He said: “Your messenger claims that pilgrimage to the House is obligatory upon whoever is able to make the journey.” He said: “He spoke the truth.” Then the man turned away and said: “By the One who sent you with the truth, I will neither add anything to these nor subtract anything from them.” The Prophet ﷺ said: “If he has spoken truthfully, he will surely enter Paradise.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (63)، ومسلم (12)، واللفظ لمسلم."},{"num":3913,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، رَضِيَ اللَّهُ عَنْهُ أَنَّ أَعْرَابِيًّا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْهِجْرَةِ، فَقَالَ: وَيْحَكَ، إِنَّ شَأْنَهَا شَدِيدٌ، فَهَلْ لَكَ مِنْ إِبِلٍ تُؤَدِّي صَدَقَتَهَا. قَالَ: نَعَمْ. قَالَ: فَاعْمَلْ مِنْ وَرَاءِ الْبِحَارِ، فَإِنَّ اللَّهَ لَنْ يَتِرَكَ مِنْ عَمَلِكَ شَيْئًا."],"takhrij":"متفق عليه: رواه البخاريّ في الزّكاة (1452)، ومسلم في الإمارة (1865) كلاهما من طريق الوليد بن مسلم، حدّثنا الأوزاعي، حدّثني ابن شهاب، عن عطاء بن يزيد، عن أبي سعيد الخدريّ، فذكره.","grade":"متفق عليه","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1452), Muslim (1865).","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that a Bedouin asked the Messenger of Allah ﷺ about migration, so he said: “Woe to you, its matter is severe. Do you have camels from which you pay their zakat?” He said: Yes. He said: “Then do your deeds from beyond the seas, for Allah will not diminish anything from your deeds.”"]},"buhuth":{"en":["The phrase “will not leave out anything from your deeds” means: He will not decrease any of the reward of your deeds."]}},"tuhfa":{},"full":1,"dr":1,"rep":[4055],"tks":"متفق عليه: رواه البخاري (1452)، ومسلم (1865)."},{"num":3914,"demo":false,"sanad":"","matn":["عن بَهْزَ بْنَ حَكِيمٍ يُحَدِّثُ عَنْ أَبِيهِ عَنْ جَدِّهِ قَالَ: قُلْتُ يَا نَبِيَّ الله مَا أَتَيْتُكَ حَتَّى حَلَفْتُ أَكْثَرَ مِنْ عَدَدِهِنَّ لأَصَابِعِ يَدَيْهِ أَنْ لا آتِيَكَ وَلا آتِيَ دِينَكَ، وَإِنِّي كُنْتُ امْرَأً لا أَعْقِلُ شَيْئًا إِلا مَا عَلَّمَنِي الله عَزَّ وَجَلَّ وَرَسُولُهُ، وَإِنِّي أَسْأَلُكَ بِوَحْيِ الله بِمَا بَعَثَكَ رَبُّكَ إِلَيْنَا؟ قَالَ: بِالإِسْلَامِ . قُلْتُ: وَمَا آيَاتُ الإِسْلَام؟ِ قَالَ: أَنْ تَقُولَ أَسْلَمْتُ وَجْهِي إِلَى الله، وَتَخَلَّيْتُ وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ ."],"takhrij":"حسن: رواه النسائي (2436) عن محمد بن عبد الأعلى، حدّثنا معتمر، قال: سمعت بهز بن حكيم، به، فذكره.","grade":"حسن","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: al-Nasā’ī (2436).","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Bahz ibn Ḥakīm narrates from his father from his grandfather that he said: I said: “O Prophet of Allah ﷺ, I did not come to you until I had sworn more times than the number of the fingers of his hands that I would not come to you and would not come to your religion. And I was a man who understood nothing except what Allah, Mighty and Majestic, and His Messenger taught me. I ask you by Allah’s revelation: with what did your Lord send you to us?” He said: “With Islam.” I said: “And what are the signs of Islam?” He said: “That you say: I have submitted my face to Allah, and I have withdrawn from falsehood, and that you establish the prayer and give zakat.”"]},"buhuth":{"en":["The phrase “I have withdrawn” means: I have abandoned disbelief and falsehood.","And his words “that I would not come to you” mean: that I would not come to your religion while disliking it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2436)."},{"num":3915,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فِي حجّة الْوَدَاعِ - وهو عَلَى الجدعاء، واضع رجله فِي غرز الرّحْل يتطاول- فَقَالَ: اتَّقُوا اللَّهَ ربَّكم، وصلُّوا خَمْسَكُمْ، وَصُومُوا شَهْرَكُمْ، وأدُّوا زَكَاةَ أَمْوَالِكُمْ، وَأَطِيعُوا ذَا أَمْرِكُمْ، تَدْخُلُوا جنّة ربِّكم ."],"takhrij":"صحيح: رواه الترمذيّ (616) عن موسى بن عبدالرحمن الكنديّ الكوفيّ، حدّثنا زيد بن الحباب، أخبرنا معاوية بن صالح، حدّثني سُليم بن عامر، قال: سمعت أبا أمامة، فذكره.","grade":"صحيح","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Tirmidhī (616), also authenticated by Ibn Ḥibbān (4563) and al-Ḥākim (19).","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Umāmah said: I heard the Messenger of Allah ﷺ deliver a sermon during the Farewell Pilgrimage — while on al-Jadʿā’, with his foot in the stirrup, stretching himself upward — and he said: “Fear Allah your Lord, pray your five prayers, fast your month, give the zakat of your wealth, and obey those in authority over you, and you will enter the Paradise of your Lord.”"]},"buhuth":{"en":["The phrase “those in authority over you” appears in another narration as: “obey your rulers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (616)، وصححه أيضا ابن حبان (4563)، والحاكم (19)."},{"num":3916,"demo":false,"sanad":"","matn":["عن عَلْقَمَةَ بْنِ نَاجِيَةَ الخزاعي أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لَهُمْ عَامَ المريسع حِينَ أَسْلَمُوا: إِنَّ مِنْ تَمَامِ إِسْلَامِكُمْ أَنْ تُؤَدُّوا زَكَاةَ أَمْوَالِكُمْ ."],"takhrij":"حسن: رواه الطبراني في الكبير (18/8) والبزار – كشف الأستار (876) وابن أبي عاصم في الآحاد والمثاني (2334) من حديث يعقوب بن حميد، ثنا عيسى بن الحضرمي بن كلثوم بن علقمة بن ناجية بن الحارث الخزاعي، عن جده كلثوم، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب فرض الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Kabīr (18/8), and al-Bazzār in Kashf al-Astār (876).","chapter_en":"The obligation of zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAlqamah ibn Nājiyah al-Khuzāʿī reported that the Prophet ﷺ said to them in the year of al-Muraysīʿ when they accepted Islam: “Part of the completeness of your Islam is that you give the zakat of your wealth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (18/8)، والبزار في كشف الأستار (876)."},{"num":3917,"demo":false,"sanad":"","matn":["عن جرير بْنِ عبدالله بَايَعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى إِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1401)، ومسلم في الإيمان (56) من طرق عن إسماعيل بن أبي خالد، عن قيس، عن جرير، فذكره.","grade":"متفق عليه","chapter_ar":"باب البيعة على إيتاء الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1401), Muslim (56).","chapter_en":"The pledge to give zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Jarīr ibn ʿAbdullāh said: “I gave my pledge to the Messenger of Allah ﷺ upon establishing the prayer, giving zakat, and sincere counsel to every Muslim.”"]}},"tuhfa":{},"full":1,"rep":[14103],"tks":"متفق عليه: رواه البخاري (1401)، ومسلم (56)."},{"num":3918,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: بَعَثَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عُمَرَ عَلَى الصَّدَقَةِ فَقِيـلَ: مَنَعَ ابْنُ جَمِيـلٍ، وَخَالِدُ بْنُ الْوَلِيـدِ، وَالْعَبَّـاسُ عَمُّ رَسُولِ اللهصَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللهصَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا يَنْقِمُ ابْنُ جَمِيلٍ إِلا أَنَّهُ كَانَ فَقِيرًا فَأَغْنَاهُ الله، وَأَمَّا خَالِدٌ فَإِنَّكُمْ تَظْلِمُونَ خَالِدًا قَدْ احْتَبَسَ أَدْرَاعَهُ وَأَعْتَادَهُ فِي سَبِيلِ الله، وَأَمَّا الْعَبَّاسُ فَهِيَ عَلَيَّ وَمِثْلُهَا مَعَهَا . ثُمَّ قَالَ: يَا عُمَرُ أَمَا شَعَرْتَ أَنَّ عَمَّ الرَّجُلِ صِنْوُ أَبِيهِ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1468)، ومسلم في الزكاة (983) كلاهما من طريق أبي الزّناد، عن الأعرج، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تعجيل الزكاة قبل تمام الحول","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1468), Muslim (983), and this is the wording of Muslim.","chapter_en":"What is reported about paying zakat in advance before the completion of the year","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ sent ʿUmar to collect the charity. Then it was said: Ibn Jamīl, Khālid ibn al-Walīd, and al-ʿAbbās, the uncle of the Messenger of Allah ﷺ, withheld it. So the Messenger of Allah ﷺ said: “Ibn Jamīl has no complaint except that he used to be poor and Allah enriched him. As for Khālid, you are wronging Khālid, for he has set aside his armor and his equipment in the path of Allah. And as for al-ʿAbbās, it is upon me, along with its like with it.” Then he said: “O ʿUmar, do you not know that a man’s uncle is like his father?”"]},"buhuth":{"en":["The phrase “he has set aside” means: he has kept and dedicated them.","The word “his equipment” means what is prepared from riding animals and weapons. Some said it refers especially to horses.","The phrase “As for al-ʿAbbās, it is upon me” means: I took his zakat in advance for two years. Other narrations support this meaning, even if many of them are not individually strong; together they point to it.","Ibn Jamīl was from the Anṣār, and his personal name is not known."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1468)، ومسلم (983)، واللفظ لمسلم."},{"num":3919,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، أَنَّ الْعَبَّاسَ، سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي تَعْجِيلِ صَدَقَتِهِ قَبْلَ أَنْ تَحِلَّ، فَرَخَّصَ لَهُ فِي ذَلِكَ.","قَالَ مَرَّةً: فَأَذِنَ لَهُ فِي ذَلِكَ."],"takhrij":"حسن: رواه أبو داود (1624)، والتّرمذيّ (678)، وابن ماجه (1795) كلّهم من طريق سعيد بن منصور، حدّثنا إسماعيل بن زكريا، عن حجّاج بن دينار، عن الحكم، عن حُجية بن عدي، عن علي، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تعجيل الزكاة قبل تمام الحول","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (1624), al-Tirmidhī (678), who graded it Hasan, and Ibn Mājah (1795).","chapter_en":"What is reported about paying zakat in advance before the completion of the year","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib reported that al-ʿAbbās asked the Prophet ﷺ about paying his charity early before it became due, so he gave him permission for that. In one wording: “So he permitted him to do that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1624)، والترمذي (678) وحسنه، وابن ماجه (1795)."},{"num":3920,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن الْحَارِثِ، رَضِيَ اللَّهُ عَنْهُ حَدَّثَهُ قَالَ: صَلَّى بِنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعَصْرَ، فَأَسْرَعَ، ثُمَّ دَخَلَ الْبَيْتَ، فَلَمْ يَلْبَثْ أَنْ خَرَجَ، فَقُلْتُ أَوْ قِيلَ لَهُ. فَقَالَ: كُنْتُ خَلَّفْتُ فِي الْبَيْتِ تِبْرًا مِنَ الصَّدَقَةِ، فَكَرِهْتُ أَنْ أُبَيِّتَهُ، فَقَسَمْتُهُ."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1430) حدّثنا أبو عاصم، عن عمر ابن سعيد، عن ابن أبي مُليكة، أنّ عقبة بن الحارث حدّثه، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية حبس الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1430).","chapter_en":"What is reported about the dislike of delaying charity","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿUqbah ibn al-Ḥārith said: The Prophet ﷺ led us in the ʿAṣr prayer, then hurried away and entered the house. He did not remain long before coming out. I said — or it was said to him — about that, and he said: “I had left some gold from charity in the house, and I disliked keeping it overnight, so I distributed it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1430)."},{"num":3921,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَا يَسُرُّنِي أَنَّ لِي أُحُدًا ذَهَبًا تَأْتِي عَلَيَّ ثَالِثَةٌ، وَعِنْدِي مِنْهُ دِينَارٌ إِلَّا دِينَارٌ أَُرْصُِدُهُ لِدَيْنٍ عَلَيَّ."],"takhrij":"متفق عليه: رواه مسلم في الزكاة (991) من طرق عن محمد بن زياد، قال: سمعت أبا هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية حبس الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (2389), Muslim (991).","chapter_en":"What is reported about the dislike of delaying charity","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “It would not please me to have Mount Uḥud in gold and then for three nights to pass while I still had a dinar of it left with me, except a dinar I would keep aside for a debt I owe.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2389)، ومسلم (991)."},{"num":3922,"demo":false,"sanad":"","matn":["عن أبي ذرٍّ قَالَ: انْتَهَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ جَالِسٌ فِي ظِلِّ الْكَعْبَةِ. فَلَمَّا رَآنِي قَالَ: هُمْ الأَخْسَرُونَ وَرَبِّ الْكَعْبَةِ! . قَالَ: فَجِئْتُ حَتَّى جَلَسْتُ فَلَمْ أَتَقَارَّ أَنْ قُمْتُ. فَقُلْتُ: يَا رَسُولَ الله فِدَاكَ أَبِي وَأُمِّي مَنْ هُمْ؟ قَالَ: هُمْ الأَكْثَرُونَ أَمْوَالا إِلا مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا مِنْ بَيْنَ يَدَيْهِ وَمِنْ خَلْفِهِ وَعَنْ يَمِينِهِ وَعَنْ شِمَالِهِ، وَقَلِيلٌ مَا هُمْ! مَا مِنْ صَاحِبِ إِبِلٍ وَلا بَقَرٍ وَلا غَنَمٍ لا يُؤَدِّي زَكَاتَهَا إِلا جَاءَتْ يَوْمَ الْقِيَامَةِ أَعْظَمَ مَا كَانَتْ وَأَسْمَنَهُ تَنْطَحُهُ بِقُرُونِهَا وَتَطَؤُهُ بِأَظْلافِهَا كُلَّمَا نَفِدَتْ أُخْرَاهَا عَادَتْ عَلَيْهِ أُولاهَا حَتَّى يُقْضَى بَيْنَ النَّاسِ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1460)، ومسلم في الزكاة (990) كلاهما من طريق الأعمش، عن المعرور بن سويد، عن أبي ذرّ الغفاريّ، فذكر الحديث. واللّفظ لمسلم، ولفظ البخاريّ مختصر.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1460), Muslim (990), and this is the wording of Muslim.","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Dharr said: I came to the Prophet ﷺ while he was sitting in the shade of the Kaʿbah. When he saw me, he said: “They are the greatest losers, by the Lord of the Kaʿbah.” He said: So I came and sat down, but I could not remain seated, so I stood up and said: “O Messenger of Allah ﷺ, may my father and mother be sacrificed for you, who are they?” He said: “They are the people with the most wealth, except for the one who gives like this and like this and like this — in front of him, behind him, to his right, and to his left — and they are few. There is no owner of camels, cattle, or sheep who does not pay their zakat except that they will come on the Day of Resurrection larger and fatter than they ever were, striking him with their horns and trampling him with their hooves. Whenever the last of them passes, the first of them returns to him, until judgment is made between the people.”"]},"buhuth":{"en":["The phrase “I could not remain seated” means: I was unable to stay settled in my place.","And Muslim also narrated in the Book of Zakat (987) through another chain with this wording:","“There is no owner of gold or silver who does not pay what is due from it except that on the Day of Resurrection sheets of fire will be made for him. They will be heated in the Fire of Hell, and his side, forehead, and back will be branded with them. Whenever they cool down, they will be heated again for him, on a day whose length is fifty thousand years, until judgment is made between the servants. Then he will see his path, either to Paradise or to the Fire.","It was said: O Messenger of Allah ﷺ, what about camels? He said: There is no owner of camels who does not pay what is due from them — and part of what is due from them is that their milk is given on the day they come to water — except that on the Day of Resurrection he will be thrown down on a broad, flat plain, and they will come in the fullest and fattest form they ever had, with not even one young camel missing. They will trample him with their feet and bite him with their mouths. Whenever the first of them passes over him, the last of them will be returned to him, on a day whose length is fifty thousand years, until judgment is made between the servants. Then he will see his path, either to Paradise or to the Fire.","It was said: O Messenger of Allah ﷺ, what about cattle and sheep? He said: There is no owner of cattle or sheep who does not pay what is due from them except that on the Day of Resurrection he will be thrown down on a broad, flat plain, with none of them missing. None among them will be horn-twisted, hornless, or broken-horned. They will gore him with their horns and trample him with their hooves. Whenever the first of them passes over him, the last of them will be returned to him, on a day whose length is fifty thousand years, until judgment is made between the servants. Then he will see his path, either to Paradise or to the Fire.","It was said: O Messenger of Allah ﷺ, what about horses? He said: Horses are of three kinds. For one man they are a sin, for another they are a covering, and for another they are a reward. As for the one for whom they are a sin, it is a man who keeps them for showing off, pride, and hostility against the people of Islam, so they are a sin for him. As for the one for whom they are a covering, it is a man who keeps them for the cause of Allah and does not forget Allah’s right regarding their backs and necks, so they are a protection for him. And as for the one for whom they are a reward, it is a man who keeps them for the cause of Allah for the people of Islam in a meadow or garden. Whatever they eat from that meadow or garden, Allah records for him a number of good deeds equal to what they ate. And He records for him a number of good deeds equal to their droppings and urine. If they break their tether and run across one or two hills, Allah records for him a number of good deeds equal to their tracks and droppings. And if their owner takes them by a river and they drink from it, even though he did not intend to water them, Allah records for him a number of good deeds equal to what they drank.”","It was said: O Messenger of Allah ﷺ, what about donkeys?","He said: “Nothing has been revealed to me about them except this all-encompassing and unique verse: ‘So whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it.’”"]},"intro":{"ar":["قال اللّٰه تعالى: (وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنْفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ ۝ يَوْمَ يُحْمَى عَلَيْهَا فِي نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ ۖ هَذَا مَا كَنَزْتُمْ لِأَنْفُسِكُمْ فَذُوقُوا مَا كُنْتُمْ تَكْنِزُونَ) [سورة التوبة: ٣٤-٣٥]."],"en":["Allah the Exalted said: “And those who hoard gold and silver and do not spend it in the path of Allah — give them tidings of a painful punishment. On the Day when it will be heated in the Fire of Hell and their foreheads, sides, and backs will be branded with it: ‘This is what you hoarded for yourselves, so taste what you used to hoard.’” [al-Tawbah 9:34–35]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12464],"tks":"متفق عليه: رواه البخاري (1460)، ومسلم (990)، واللفظ لمسلم."},{"num":3923,"demo":false,"sanad":"","matn":["عن الأحْنَفَ بْن قيسٍ حَدَّثَهُمْ قَالَ: جَلَسْتُ إِلَى مَلإٍ مِنْ قُرَيْشٍ فَجَاءَ رَجُلٌ خَشِنُ الشَّعَرِ وَالثِّيَابِ وَالهَيْئَةِ حَتَّى قَامَ عَلَيْهِمْ، فَسَلَّمَ، ثُمَّ قَال: بَشِّر الْكَانِزِينَ بِرَضْفٍ يُحْمَى عَلَيْهِ فِي نَارِ جَهَنَّمَ ثُمَّ يُوضَعُ عَلَى حَلَمَةِ ثَدْيِ أَحَدِهِمْ حَتَّى يَخْرُجَ مِنْ نُغْضِ كَتِفِهِ وَيُوضَعُ عَلَى نُغْضِ كَتِفِهِ حَتَّى يَخْرُجَ مِنْ حَلَمَةِ ثَدْيِهِ يَتَزَلْزَلُ. ثُمَّ وَلَّى فَجَلَسَ إِلَى سَارِيَةٍ وَتَبِعْتُهُ وَجَلَسْتُ إِلَيْهِ وَأَنَا لا أَدْرِي مَنْ هُوَ. فَقُلْتُ: لَهُ لا أُرَى الْقَوْمَ إِلا قَدْ كَرِهُوا الَّذِي قُلْتَ؟ قَالَ: إِنَّهُمْ لا يَعْقِلُونَ شَيْئًا، قَالَ لِي خَلِيلِي. قَالَ قُلْتُ: مَنْ خَلِيلُكَ؟.","قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَبَا ذَرٍّ، أَتُبْصِرُ أُحُدًا؟ . قَالَ: فَنَظَرْتُ إِلَى الشَّمْسِ مَا بَقِيَ مِنْ النَّهَارِ وَأَنَا أُرَى أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرْسِلُنِي فِي حَاجَةٍ لَهُ. قُلْتُ: نَعَمْ. قَالَ: مَا أُحِبُّ أَنَّ لِي مِثْلَ أُحُدٍ ذَهَبًا أُنْفِقُهُ كُلَّهُ إِلا ثَلاثَةَ دَنَانِيرَ .","وَإِنَّ هَؤُلاءِ لا يَعْقِلُونَ إِنَّمَا يَجْمَعُونَ الدُّنْيَا، لا وَالله لا أَسْأَلُهُمْ دُنْيَا وَلا أَسْتَفْتِيهِمْ عَنْ دِينٍ حَتَّى أَلْقَى الله.","وفي رواية: بَشِّر الْكَانِزِينَ بِكَيٍّ فِي ظُهُورِهِمْ يَخْرُجُ مِنْ جُنُوبِهِمْ، وَبِكَيٍّ مِنْ قِبَلِ أَقْفَائِهِمْ يَخْرُجُ مِنْ جِبَاهِهِمْ. قَالَ ثُمَّ تَنَحَّى فَقَعَدَ قَالَ: قُلْتُ: مَنْ هَذَا قَالُوا هَذَا أَبُو ذَرٍّ. قَالَ: فَقُمْتُ إِلَيْهِ فَقُلْتُ مَا شَيْءٌ سَمِعْتُكَ تَقُولُ قُبَيْلُ؟ قَالَ: مَا قُلْتُ إِلا شَيْئًا قَدْ سَمِعْتُهُ مِنْ نَبِيِّهِمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قُلْتُ مَا تَقُولُ فِي هَذَا الْعَطَاءِ؟ قَالَ: خُذْهُ فَإِنَّ فِيهِ الْيَوْمَ مَعُونَةً فَإِذَا كَانَ ثَمَنًا لِدِينِكَ فَدَعْهُ ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1407-1408)، ومسلم في الزكاة (992) كلاهما من طريق الجريريّ، عن أبي العلاء، عن الأحنف فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1407, 1408), Muslim (992). The second narration is also in Muslim.","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Al-Aḥnaf ibn Qays reported to them: I was sitting with a group of Quraysh when a man with rough hair, rough clothes, and a rough appearance came and stood over them. He greeted them and then said: “Give glad tidings to the hoarders of wealth of heated stones heated in the Fire of Hell, then placed on the nipple of one of them until it comes out from the bone of his shoulder, and placed on the bone of his shoulder until it comes out from the nipple of his chest, shaking him violently.” Then he turned away and sat by a pillar. I followed him and sat with him, not knowing who he was. I said to him: “It seems the people disliked what you said.” He said: “They understand nothing. My close friend told me.” I said: “Who is your close friend?”","He said: “The Prophet ﷺ.” He said: “O Abū Dharr, do you see Uḥud?” He said: So I looked at the sun to see how much of the day remained, thinking that the Messenger of Allah ﷺ might send me on an errand. I said: “Yes.” He said: “I would not like to have gold equal to Uḥud and then spend it all, except for three dinars.” And these people do not understand; they only gather worldly wealth. By Allah, I will not ask them for worldly gain, nor seek their legal opinion in religion, until I meet Allah.","And in another narration: “Give glad tidings to the hoarders of branding on their backs that comes out from their sides, and branding from the backs of them that comes out from their foreheads.”","He said: Then he moved away and sat down. I said: “Who is this?” They said: “This is Abū Dharr.” So I went to him and said: “What was that statement I heard you say just before?” He said: “I said nothing except something I heard from their Prophet ﷺ.” I said: “What do you say about this public stipend?” He said: “Take it, for today it is help. But if it becomes the price of your religion, then leave it.”"]},"buhuth":{"en":["The phrase “the bone of his shoulder” refers to the fine bone at the edge of the shoulder.","“Shaking him violently” means moving and trembling.","“Heated stones” means stones made red-hot in fire.","Note: Abū al-ʿAbbās al-Qurṭubī said: the stipend Abū Dharr was asked about is what a person is given from the public treasury in a lawful way that he deserves. This is like the Prophet’s saying: “Whatever comes to you from this wealth while you are neither seeking it eagerly nor asking for it, take it. Otherwise, do not let yourself chase after it.”","And the phrase “if it becomes the price of your religion” means: if you can only get it through an impermissible way, then turn away from it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1407، 1408)، ومسلم (992)، والرواية الثانية رواها مسلم (992/35)."},{"num":3924,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَال: الخيْلُ لِرَجُلٍ أَجْرٌ، وَلِرَجُلٍ سِتْرٌ، وَعَلَى رَجُلٍ وِزْرٌ. فَأَمَّا الَّذِي هِيَ لَهُ أَجْرٌ فَرَجُلٌ رَبَطَهَا فِي سَبِيلِ الله فَأَطَالَ لَهَا فِي مَرْجٍ أَوْ رَوْضَةٍ فَمَا أَصَابَتْ فِي طِيَلِهَا ذَلِكَ مِنْ الْمَرْجِ أَوْ الرَّوْضَةِ كَانَ لَهُ حَسَنَاتٌ وَلَوْ أَنَّهَا قُطِعَتْ طِيَلَهَا ذَلِكَ فَاسْتَنَّتْ شَرَفًا أَوْ شَرَفَيْنِ كَانَتْ آثَارُهَا وَأَرْوَاثُهَا حَسَنَاتٍ لَهُ وَلَوْ أَنَّهَا مَرَّتْ بِنَهَرٍ فَشَرِبَتْ مِنْهُ وَلَمْ يُرِدْ أَنْ يَسْقِيَ بِهِ كَانَ ذَلِكَ لَهُ حَسَنَاتٍ فَهِيَ لَهُ أَجْرٌ، وَرَجُلٌ رَبَطَهَا تَغَنِّيًا وَتَعَفُّفًا وَلَمْ يَنْسَ حَقَّ الله فِي رِقَابِهَا وَلا فِي ظُهُورِهَا فَهِيَ لِذَلِكَ سِتْرٌ، وَرَجُلٌ رَبَطَهَا فَخْرًا وَرِيَاءً وَنِوَاءً لأَهْلِ الإِسْلامِ فَهِيَ عَلَى ذَلِكَ وِزْرٌ .","وَسُئِلَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ الحُمُرِ؟ فَقَالَ: لَمْ يُنْزَلْ عَلَيَّ فِيهَا شَيْءٌ إِلا هَذِهِ الآيَةُ الجَامِعَةُ الْفَاذَّةُ ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ (7) وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ (8)﴾ [سورة الزلزلة] ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (3) عن زيد بن أسلم، عن أبي صالح السّمان، عن أبي هريرة، فذكره. ورواه البخاريّ في المساقاة (2371) من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: Mālik (3), al-Bukhārī (2371), Muslim (987).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “Horses are for one man a reward, for another a covering, and for another a burden of sin. As for the one for whom they are a reward: it is a man who keeps them for the cause of Allah and lets them graze in a meadow or garden. Whatever they eat within the length of their rope from that meadow or garden counts for him as good deeds. Even if they break their rope and run over one hill or two hills, their tracks and their droppings are counted as good deeds for him. And if they pass by a river and drink from it, even though he did not intend to water them from it, that also counts as good deeds for him. So they are for him a reward. And a man who keeps them for self-sufficiency and dignity, and does not forget Allah’s right regarding their necks and backs, then they are for him a protection. And a man who keeps them out of pride, showing off, and hostility toward the people of Islam, then they are for him a burden of sin.”","And the Messenger of Allah ﷺ was asked about donkeys, so he said: “Nothing has been revealed to me about them except this comprehensive and unique verse: ‘So whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it.’” [al-Zalzalah 99:7–8]"]},"buhuth":{"en":["And Muslim also narrated in the Book of Zakat (987) through another chain with this wording:","“There is no owner of gold or silver who does not pay what is due from it except that on the Day of Resurrection sheets of fire will be made for him. They will be heated in the Fire of Hell, and his side, forehead, and back will be branded with them. Whenever they cool down, they will be heated again for him, on a day whose length is fifty thousand years, until judgment is made between the servants. Then he will see his path, either to Paradise or to the Fire.","It was said: O Messenger of Allah ﷺ, what about camels? He said: There is no owner of camels who does not pay what is due from them — and part of what is due from them is that their milk is given on the day they come to water — except that on the Day of Resurrection he will be thrown down on a broad, flat plain, and they will come in the fullest and fattest form they ever had, with not even one young camel missing. They will trample him with their feet and bite him with their mouths. Whenever the first of them passes over him, the last of them will be returned to him, on a day whose length is fifty thousand years, until judgment is made between the servants. Then he will see his path, either to Paradise or to the Fire.","It was said: O Messenger of Allah ﷺ, what about cattle and sheep? He said: There is no owner of cattle or sheep who does not pay what is due from them except that on the Day of Resurrection he will be thrown down on a broad, flat plain, with none of them missing. None among them will be horn-twisted, hornless, or broken-horned. They will gore him with their horns and trample him with their hooves. Whenever the first of them passes over him, the last of them will be returned to him, on a day whose length is fifty thousand years, until judgment is made between the servants. Then he will see his path, either to Paradise or to the Fire.","It was said: O Messenger of Allah ﷺ, what about horses? He said: Horses are of three kinds. For one man they are a sin, for another they are a covering, and for another they are a reward. As for the one for whom they are a sin, it is a man who keeps them for showing off, pride, and hostility against the people of Islam, so they are a sin for him. As for the one for whom they are a covering, it is a man who keeps them for the cause of Allah and does not forget Allah’s right regarding their backs and necks, so they are a protection for him. And as for the one for whom they are a reward, it is a man who keeps them for the cause of Allah for the people of Islam in a meadow or garden. Whatever they eat from that meadow or garden, Allah records for him a number of good deeds equal to what they ate. And He records for him a number of good deeds equal to their droppings and urine. If they break their tether and run across one or two hills, Allah records for him a number of good deeds equal to their tracks and droppings. And if their owner takes them by a river and they drink from it, even though he did not intend to water them, Allah records for him a number of good deeds equal to what they drank.”","It was said: O Messenger of Allah ﷺ, what about donkeys?","He said: “Nothing has been revealed to me about them except this all-encompassing and unique verse: ‘So whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (3)، والبخاري (2371)، ومسلم (987)."},{"num":3925,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:مَا مِنْ صَاحِبِ كَنْزٍ لاَ يُؤَدِّى زَكَاتَهُ إِلاَّ أُحْمِىَ عَلَيْهِ فِى نَارِ جَهَنَّمَ، فَيُجْعَلُ صَفَائِحَ فَيُكْوَى بِهَا جَنْبَاهُ وَجَبِينُهُ حَتَّى يَحْكُمَ الله بَيْنَ عِبَادِهِ فِى يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ، ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الجَنَّةِ وَإِمَّا إِلَى النَّارِ، وَمَا مِنْ صَاحِبِ إِبِلٍ لاَ يُؤَدِّى زَكَاتَهَا إِلاَّ بُطِحَ لَهَا بِقَاعٍ قَرْقَرٍ كَأَوْفَرِ مَا كَانَتْ تَسْتَنُّ عَلَيْهِ، كُلَّمَا مَضَى عَلَيْهِ أُخْرَاهَا رُدَّتْ عَلَيْهِ أُولاَهَا حَتَّى يَحْكُمَ الله بَيْنَ عِبَادِهِ فِى يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ، ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الجَنَّةِ وَإِمَّا إِلَى النَّارِ، وَمَا مِنْ صَاحِبِ غَنَمٍ لاَ يُؤَدِّى زَكَاتَهَا إِلاَّ بُطِحَ لَهَا بِقَاعٍ قَرْقَرٍ كَأَوْفَرِ مَا كَانَتْ، فَتَطَؤُهُ بِأَظْلاَفِهَا وَتَنْطِحُهُ بِقُرُونِهَا لَيْسَ فِيهَا عَقْصَاءُ وَلاَ جَلْحَاءُ، كُلَّمَا مَضَى عَلَيْهِ أُخْرَاهَا رُدَّتْ عَلَيْهِ أُولاَهَا حَتَّى يَحْكُمَ الله بَيْنَ عِبَادِهِ فِى يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ ممَّا تَعُدُّونَ، ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الجَنَّةِ وَإِمَّا إِلَى النَّارِ.","قَالَ سُهَيْلٌ فَلاَ أَدْرِى أَذَكَرَ الْبَقَرَ أَمْ لاَ. قَالُوا فَالْخَيْلُ يَا رَسُولَ الله قَالَ: الخَيْلُ فِى نَوَاصِيهَا - أَوْ قَالَ - الخَيْلُ مَعْقُودٌ فِى نَوَاصِيهَا - قَالَ سُهَيْلٌ أَنَا أَشُكُّ - الخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ، الخَيْلُ ثَلاَثَةٌ: فَهيَ لِرَجُلٍ أَجْرٌ، وَلِرَجُلٍ سِتْرٌ، وَلِرَجُلٍ وِزْرٌ، فَأَمَّا الَّتِى هِىَ لَهُ أَجْرٌ، فَالرَّجُلُ يَتَّخِذُهَا فِى سَبِيلِ الله وَيُعِدُّهَا لَهُ، فَلاَ تُغَيِّبُ شَيْئًا فِى بُطُونِهَا إِلاَّ كَتَبَ الله لَهُ أَجْرًا، وَلَوْ رَعَاهَا فِى مَرْجٍ مَا أَكَلَتْ مِنْ شَىْءٍ إِلاَّ كَتَبَ الله لَهُ بِهَا أَجْرًا، وَلَوْ سَقَاهَا مِنْ نَهْرٍ كَانَ لَهُ بِكُلِّ قَطْرَةٍ تُغَيِّبُهَا فِى بُطُونِهَا أَجْرٌ، - حَتَّى ذَكَرَ الأَجْرَ فِى أَبْوَالِهَا وَأَرْوَاثِهَا - وَلَوِ اسْتَنَّتْ شَرَفًا أَوْ شَرَفَيْنِ كُتِبَ لَهُ بِكُلِّ خَطْوَةٍ تَخْطُوهَا أَجْرٌ، وَأَمَّا الَّذِى هِىَ لَهُ سِتْرٌ فَالرَّجُلُ يَتَّخِذُهَا تَكَرُّمًا وَتَجَمُّلاً، وَلاَ يَنْسَى حَقَّ ظُهُورِهَا وَبُطُونِهَا فِى عُسْرِهَا وَيُسْرِهَا، وَأَمَّا الَّذِى عَلَيْهِ وِزْرٌ فَالَّذِى يَتَّخِذُهَا أَشَرًا وَبَطَرًا وَبَذَخًا وَرِيَاءَ النَّاسِ، فَذَاكَ الَّذِى هِىَ عَلَيْهِ وِزْرٌ .","قَالُوا: فَالحُمُرُ يَا رَسُولَ الله قَالَ:  مَا أَنْزَلَ الله عَلَىَّ فِيهَا شَيْئًا إِلاَّ هَذِهِ الآيَةَ الجَامِعَةَ الْفَاذَّةَ: ﴿فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ (7) وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ [سورة الزلزلة: 7، 8] (8 )."],"takhrij":"صحيح: رواه مسلم في الزكاة (987: 26) عن محمد بن عبدالملك الأموي، حدثنا عبدالعزيز بن المختار، حدثنا سهيل بن أبي صالح، عن أبيه، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Muslim, Book of Zakat (987/26).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There is no owner of hoarded wealth who does not pay its zakat except that it will be heated for him in the Fire of Hell and made into plates, and his sides and forehead will be branded with it until Allah judges between His servants, on a day whose length is fifty thousand years. Then he will see his path, either to Paradise or to the Fire. There is no owner of camels who does not pay their zakat except that he will be thrown down for them on a broad, flat plain while they are in the fullest condition they ever had, passing over him. Whenever the last of them has gone over him, the first of them will be brought back to him, until Allah judges between His servants on a day whose length is fifty thousand years. Then he will see his path, either to Paradise or to the Fire. And there is no owner of sheep who does not pay their zakat except that he will be thrown down for them on a broad, flat plain while they are in the fullest condition they ever had. They will trample him with their hooves and gore him with their horns. None among them will be horn-twisted or hornless. Whenever the last of them has gone over him, the first of them will be brought back to him, until Allah judges between His servants on a day whose length is fifty thousand years by your reckoning. Then he will see his path, either to Paradise or to the Fire.”","Suhayl said: I do not know whether he mentioned cattle or not. They said: O Messenger of Allah ﷺ, what about horses? He said: “Good is in the forelocks of horses — or he said: good is tied in the forelocks of horses; Suhayl said: I am uncertain — until the Day of Resurrection. Horses are of three kinds: for one man they are a reward, for one man they are a covering, and for one man they are a sin. As for the one for whom they are a reward, it is the man who keeps them for the cause of Allah and prepares them for it. Nothing enters their stomachs except that Allah records for him a reward for it. If he lets them graze in a meadow, whatever they eat from it, Allah records for him a reward. If he waters them from a river, Allah records for him a reward for every drop that enters their stomachs” — and he even mentioned reward in their urine and droppings. “If they run over one hill or two hills, a reward is recorded for him for every step they take. As for the one for whom they are a covering, it is the man who keeps them for dignity and good appearance, and he does not neglect what is due regarding their backs and bellies in hardship or ease. As for the one for whom they are a sin, it is the man who keeps them out of arrogance, vanity, extravagance, and showing off before people. That is the one for whom they are a sin.”","They said: O Messenger of Allah ﷺ, what about donkeys? He said: “Allah has not revealed to me anything about them except this all-encompassing and unique verse: ‘So whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (987: 26)."},{"num":3926,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: انْتَهَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ -أَوْ وَالَّذِي لَا إِلَهَ غَيْرُهُ، أَوْ كَمَا حَلَفَ- مَا مِنْ رَجُلٍ تَكُونُ لَهُ إِبِلٌ أَوْ بَقَرٌ أَوْ غَنَمٌ، لَا يُؤَدِّي حَقَّهَا إِلَّا أُتِيَ بِهَا يَوْمَ الْقِيَامَةِ أَعْظَمَ مَا تَكُونُ، وَأَسْمَنَهُ تَطَؤُهُ بِأَخْفَافِهَا، وَتَنْطَحُهُ بِقُرُونِهَا، كُلَّمَا جَازَتْ أُخْرَاهَا رُدَّتْ عَلَيْهِ أُولَاهَا حَتَّى يُقْضَى بَيْنَ النَّاسِ ."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1460)، ومسلم في الزكاة (990) كلاهما من حديث الأعمش، عن المعرور بن سويد، عن أبي ذرٍّ قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī, Book of Zakat (1460), and Muslim, Book of Zakat (990).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Dharr said: I came to the Prophet ﷺ and he said: “By the One in whose hand is my soul — or by the One besides whom there is no god, or as he swore — there is no man who has camels, cattle, or sheep and does not give their due right, except that they will be brought to him on the Day of Resurrection in their greatest and fattest form, trampling him with their hooves and goring him with their horns. Whenever the last of them passes over him, the first of them will be returned to him, until judgment is made between the people.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1460)، ومسلم (990)."},{"num":3927,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنْ آتَاهُ اللَّهُ مَالاً فَلَمْ يؤدِّ زَكَاتَهُ مُثِّلَ لَهُ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ لَهُ زَبِيبَتَانِ يُطوّقه يَوْمَ الْقِيَامَةِ، ثُمَّ يَأْخُذُ بِهِزْمتيه - يَعْنِي شدْقيه - ثُمَّ يَقُولُ: أَنَا مَالُكَ، أَنَا كَنْزُكَ، ثُمَّ تَلاَ: ﴿وَلَا يَحْسَبَنَّ الَّذِينَ يَبْخَلُونَ بِمَا آتَاهُمُ اللَّهُ مِنْ فَضْلِهِ هُوَ خَيْرًا لَهُمْ﴾ [سورة آلِ عِمْرَانَ: 180] ."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1403) عن علي بن عبدالله، حدّثنا هاشم بن القاسم، حدّثنا عبدالرحمن بن عبدالله بن دينار، عن أبيه، عن أبي صالح السّمان، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1403).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “Whoever Allah gives wealth to, but he does not pay its zakat, it will be made for him on the Day of Resurrection into a bald-headed snake with two dark marks above its eyes. It will be wrapped around his neck on the Day of Resurrection, then it will seize his two jaws — meaning the sides of his mouth — and say: I am your wealth, I am your treasure.” Then he recited: “And let not those who withhold what Allah has given them from His bounty think that it is good for them.” [Āl ʿImrān 3:180]"]},"buhuth":{"en":["The phrase “it has two dark marks” has been explained in several ways. The clearest is that they are two fleshy marks on its head like two horns. See Fatḥ al-Bārī (3/270).","The phrase “it will be wrapped around his neck” means that the snake will become like a collar around him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1403)."},{"num":3928,"demo":false,"sanad":"","matn":["عن أبي هُرَيْرَةَ يَقُولُ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَأْتِي الإبِلُ عَلَى صَاحِبِهَا عَلَى خَيْرِ مَا كَانَتْ إِذَا هُوَ لَمْ يُعْطِ فِيهَا حَقَّهَا تَطَؤُهُ بِأَخْفَافِهَا، وَتَأْتِي الْغَنَمُ عَلَى صَاحِبِهَا عَلَى خَيْرِ مَا كَانَتْ إِذَا لَمْ يُعْطِ فِيهَا حَقَّهَا تَطَؤُهُ بِأَظْلافِهَا وَتَنْطَحُهُ بِقُرُونِهَا .","وَقَالَ: وَمِنْ حَقِّهَا أَنْ تُحْلَبَ عَلَى الْمَاءِ .","قَالَ: وَلا يَأْتِي أَحَدُكُمْ يَوْمَ الْقِيَامَةِ بِشَاةٍ يَحْمِلُهَا عَلَى رَقَبَتِهِ لَهَا يُعَارٌ فَيَقُولُ يَا مُحَمَّدُ! فَأَقُولُ: لا أَمْلِكُ لَكَ شَيْئًا قَدْ بَلَّغْتُ، وَلا يَأْتِي بِبَعِيرٍ يَحْمِلُهُ عَلَى رَقَبَتِهِ لَهُ رُغَاءٌ فَيَقُولُ: يَا مُحَمَّدُ! فَأَقُولُ لا أَمْلِكُ لَكَ مِن الله شَيْئًا قَدْ بَلَّغْتُ ."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1402) حدّثنا الحكم بن نافع، أخبرنا شعيب، حدّثنا أبو الزّناد، أنّ عبدالرحمن بن هرمز الأعرج، حدّثه أنه سمع أبا هريرة يقول (فذكره).","grade":"صحيح","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1402).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “Camels will come to their owner in the best condition they ever had if he did not give their due right, trampling him with their hooves. And sheep will come to their owner in the best condition they ever had if he did not give their due right, trampling him with their hooves and goring him with their horns.” And he said: “Part of their right is that they be milked at the watering place.”","He said: “And let none of you come on the Day of Resurrection carrying a sheep on his neck, bleating, saying: O Muhammad! Then I will say: I can do nothing for you against Allah. I conveyed the message. And let none of you come carrying a camel on his neck, making its cry, saying: O Muhammad! Then I will say: I can do nothing for you against Allah. I conveyed the message.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1402)."},{"num":3929,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَأْتِي الإِبِلُ الَّتِي لَمْ تُعْط الحَقَّ مِنْهَا تَطَأُ صَاحِبَهَا بِأَخْفَافِهَا، وَتَأْتِي الْبَقَرُ وَالْغَنَمُ تَطَأُ صَاحِبَهَا بِأَظْلافِهَا وَتَنْطَحُهُ بِقُرُونِهَا، وَيَأْتِي الْكَنْزُ شُجَاعًا أَقْرَعَ فَيَلْقَى صَاحِبَهُ يَوْمَ الْقِيَامَةِ فَيَفِرُّ مِنْهُ صَاحِبُهُ مَرَّتَيْنِ ثُمَّ يَسْتَقْبِلُهُ فَيَفِرُّ فَيَقُولُ: مَا لِي وَلَكَ؟ فَيَقُولُ: أَنَا كَنْزُكَ، أَنَا كَنْزُكَ، فَيَتَّقِيهِ بِيَدِهِ فَيَلْقَمُهَا ."],"takhrij":"حسن: رواه ابن ماجه (1786) عن أبي مروان محمد بن عثمان العثمانيّ، حدّثنا عبد العزيز بن أبي حازم، عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (1786), authenticated by Ibn Ḥibbān (3254).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “The camels from which their due right was not given will come trampling their owner with their hooves. And the cattle and sheep will come trampling their owner with their hooves and goring him with their horns. And the hoarded treasure will come as a bald-headed snake and meet its owner on the Day of Resurrection. Its owner will flee from it twice, then face it, then flee again. It will say: What is the matter between you and me? It will say: I am your treasure, I am your treasure. So he will try to protect himself from it with his hand, and it will swallow it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1786)، وصححه ابن حبان (3254)."},{"num":3930,"demo":false,"sanad":"","matn":["أبي هريرة، عَنْ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: يَكُونُ كَنْزُ أَحَدِهِمْ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ ذَا زَبِيبَتَيْنِ يَتْبَعُ صَاحِبَهُ وَهُوَ يَتَعَوَّذُ مِنْهُ وَلا يَزَالُ يَتْبَعُهُ حَتَّى يُلْقِمَهُ أُصْبُعَهُ ."],"takhrij":"حسن: رواه الإمام أحمد (8933) عن قتيبة، حدّثنا ليث بن سعد، عن ابن عجلان، عن القعقاع بن حكيم، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Aḥmad (8933), authenticated by Ibn Khuzaymah (2254), Ibn Ḥibbān (3258), and al-Ḥākim (1435).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah reported from the Messenger of Allah ﷺ that he said: “A person’s hoarded treasure will be, on the Day of Resurrection, a bald-headed snake with two dark marks that follows its owner while he seeks refuge from it. It will keep following him until it forces his finger into its mouth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8933)، وصححه ابن خزيمة (2254)، وابن حبان (3258)، والحاكم (1435)."},{"num":3931,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُمَرَ الْغُدَانِيِّ قَالَ: كُنْتُ عِنْدَ أَبِي هُرَيْرَةَ جَالِسًا قَالَ فَمَرَّ رَجُلٌ مِنْ بَنِي عَامِرِ بْنِ صَعْصَعَةَ فَقِيلَ لَهُ هَذَا أَكْثَرُ عَامِرِيٍّ نَادَى مَالا. فَقَالَ أَبُو هُرَيْرَةَ: رُدُّوهُ إِلَيَّ، فَرَدُّوهُ عَلَيْهِ فَقَالَ: نُبِّئْتُ أَنَّكَ ذُو مَالٍ كَثِير؟ٍ فَقَالَ الْعَامِرِيُّ: إِي وَالله إِنَّ لِي مِائَةً حُمْرًا وَمِائَةً أُدْمًا حَتَّى عَدَّ مِنْ أَلْوَانِ الإبِلِ، وَأَفْنَانِ الرَّقِيقِ، وَرِبَاطِ الخَيْلِ. فَقَالَ أَبُو هُرَيْرَةَ: إِيَّاكَ وَأَخْفَافَ الإِبِلِ وَأَظْلافَ الْغَنَمِ! - يُرَدِّدُ ذَلِكَ عَلَيْهِ - حَتَّى جَعَلَ لَوْنُ الْعَامِرِيِّ يَتَغَيَّرُ أَوْ يَتَلَوَّنُ فَقَالَ: مَا ذَاكَ يَا أَبَا هُرَيْرَةَ؟ فَقَالَ سَمِعْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ كَانَتْ لَهُ إِبِلٌ لا يُعْطِي حَقَّهَا فِي نَجْدَتِهَا وَرِسْلِهَا . قُلْنَا: يَا رَسُولَ الله، وَمَا رِسْلُهَا وَنَجْدَتُهَا؟ قَالَ: فِي عُسْرِهَا وَيُسْرِهَا، فَإِنَّهَا تَأْتِي يَوْمَ الْقِيَامَةِ كَأَغَذِّ مَا كَانَتْ وَأَكْبَرِهِ وَأَسْمَنِهِ وَأَسَرِّهِ ثُمَّ يُبْطَحُ لَهَا بِقَاعٍ قَرْقَرٍ فَتَطَؤُهُ فِيهِ بِأَخْفَافِهَا إِذَا جَاوَزَتْهُ أُخْرَاهَا أُعِيدَتْ عَلَيْهِ أُولاهَا فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ حَتَّى يُقْضَى بَيْنَ النَّاسِ فَيَرَى سَبِيلَهُ، وَإِذَا كَانَتْ لَهُ بَقَرٌ لا يُعْطِي حَقَّهَا فِي نَجْدَتِهَا وَرِسْلِهَا فَإِنَّهَا تَأْتِي يَوْمَ الْقِيَامَةِ كَأَغَذِّ مَا كَانَتْ وَأَكْبَرِهِ وَأَسْمَنِهِ وَأَسَرِّهِ ثُمَّ يُبْطَحُ لَهَا بِقَاعٍ قَرْقَرٍ فَتَطَؤُهُ فِيهِ كُلُّ ذَاتِ ظِلْفٍ بِظِلْفِهَا وَتَنْطَحُهُ كُلُّ ذَاتِ قَرْنٍ بِقَرْنِهَا إِذَا جَاوَزَتْهُ أُخْرَاهَا أُعِيدَتْ عَلَيْهِ أُولاهَا فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ حَتَّى يُقْضَى بَيْنَ النَّاسِ حَتَّى يَرَى سَبِيلَهُ، وَإِذَا كَانَتْ لَهُ غَنَمٌ لا يُعْطِي حَقَّهَا فِي نَجْدَتِهَا وَرِسْلِهَا فَإِنَّهَا تَأْتِي يَوْمَ الْقِيَامَةِ كَأَغَذِّ مَا كَانَتْ وَأَكْبَرِهِ وَأَسْمَنِهِ وَأَسَرِّهِ، ثُمَّ يُبْطَحُ لَهَا بِقَاعٍ قَرْقَرٍ فَتَطَؤُهُ كُلُّ ذَاتِ ظِلْفٍ بِظِلْفِهَا وَتَنْطَحُهُ كُلُّ ذَاتِ قَرْنٍ بِقَرْنِهَا يَعْنِي لَيْسَ فِيهَا عَقْصَاءُ وَلا عَضْبَاءُ إِذَا جَاوَزَتْهُ أُخْرَاهَا أُعِيدَتْ أُولاهَا فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ حَتَّى يُقْضَى بَيْنَ النَّاسِ فَيَرَى سَبِيلَهُ .","فَقَالَ الْعَامِرِيّ:ُ وَمَا حَقُّ الإِبِلِ يَا أَبَا هُرَيْرَةَ؟ قَالَ: أَنْ تُعْطِيَ الْكَرِيمَةَ، وَتَمْنَحَ الْغَزِيرَةَ، وَتُفْقِرَ الظَّهْرَ، وَتَسْقِيَ اللَّبَنَ، وَتُطْرِقَ الْفَحْلَ."],"takhrij":"حسن: رواه الإمام أحمد (10350) عن محمد بن جعفر، حدّثنا سعيد بن أبي عروبة، عن قتادة، عن أبي عمر الغدانيّ، قال (فذكره).","grade":"حسن","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (10350) and Ibn Khuzaymah in his Ṣaḥīḥ (2322).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū ʿUmar al-Ghudānī said: I was sitting with Abū Hurayrah when a man from Banū ʿĀmir ibn Ṣaʿṣaʿah passed by. It was said to him: “This is the richest man among Banū ʿĀmir.” So Abū Hurayrah said: “Bring him back to me.” They brought him back, and he said: “I have been told that you are a man of great wealth.” The man said: “Yes, by Allah. I have one hundred red camels and one hundred brown camels,” and he kept listing different kinds of camels, various kinds of slaves, and tied horses. Abū Hurayrah then said: “Watch out for the hooves of camels and the hoofs of sheep,” repeating it to him until the man’s face changed color. He said: “What do you mean by that, Abū Hurayrah?” He said: I heard the Messenger of Allah ﷺ say: “Whoever has camels and does not give their due right in hardship and ease…” We said: “O Messenger of Allah ﷺ, what does that mean in hardship and ease?” He said: “They will come on the Day of Resurrection in their healthiest, largest, fattest, and most vigorous form. Then he will be thrown down for them on a broad flat plain, and they will trample him with their feet. Whenever the last of them passes, the first of them will be brought back over him, on a day whose length is fifty thousand years, until judgment is made between the people, and then he will see his final path. And if he has cattle and does not give their due right in hardship and ease, they will come on the Day of Resurrection in their healthiest, largest, fattest, and most vigorous form. Then he will be thrown down for them on a broad flat plain, and every hoofed animal among them will trample him with its hoof, and every horned one will gore him with its horn. Whenever the last of them passes, the first of them will be brought back over him, on a day whose length is fifty thousand years, until judgment is made between the people, and then he will see his final path. And if he has sheep and does not give their due right in hardship and ease, they will come on the Day of Resurrection in their healthiest, largest, fattest, and most vigorous form. Then he will be thrown down for them on a broad flat plain, and every hoofed one will trample him with its hoof, and every horned one will gore him with its horn — meaning there will be none among them with twisted or broken horns — and whenever the last of them passes, the first of them will be brought back over him, on a day whose length is fifty thousand years, until judgment is made between the people, and then he will see his final path.” The ʿĀmirī man then said: “What is the due right of camels, Abū Hurayrah?”","He said: “To give the best one when due, to lend out the one with abundant milk, to let others borrow it for riding, to provide milk, and to let the breeding male be used.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (10350)، وابن خزيمة في صحيحه (2322)."},{"num":3932,"demo":false,"sanad":"","matn":["عن جَابِرَ بْن عبدالله قال: سَمِعْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ صَاحِبِ إِبِلٍ لا يَفْعَلُ فِيهَا حَقَّهَا إِلاّ جَاءَتْ يَوْمَ الْقِيَامَةِ أَكْثَرَ مَا كَانَتْ قَطُّ وَقَعَدَ لَهَا بِقَاعٍ قَرْقَرٍ تَسْتَنُّ عَلَيْهِ بِقَوَائِمِهَا وَأَخْفَافِهَا وَلا صَاحِبِ بَقَرٍ لا يَفْعَلُ فِيهَا حَقَّهَا إِلا جَاءَتْ يَوْمَ الْقِيَامَةِ أَكْثَرَ مَا كَانَتْ وَقَعَدَ لَهَا بِقَاعٍ قَرْقَرٍ تَنْطَحُهُ بِقُرُونِهَا وَتَطَؤُهُ بِقَوَائِمِهَا وَلا صَاحِبِ غَنَمٍ لا يَفْعَلُ فِيهَا حَقَّهَا إِلا جَاءَتْ يَوْمَ الْقِيَامَةِ أَكْثَرَ مَا كَانَتْ وَقَعَدَ لَهَا بِقَاعٍ قَرْقَرٍ تَنْطَحُهُ بِقُرُونِهَا وَتَطَؤُهُ بِأَظْلَافِهَا لَيْسَ فِيهَا جَمَّاءُ وَلا مُنْكَسِرٌ قَرْنُهَا وَلا صَاحِبِ كَنْزٍ لا يَفْعَلُ فِيهِ حَقَّهُ إِلا جَاءَ كَنْزُهُ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ يَتْبَعُهُ فَاتِحًا فَاهُ فَإِذَا أَتَاهُ فَرَّ مِنْهُ فَيُنَادِيهِ خُذْ كَنْزَكَ الَّذِي خَبَأْتَهُ فَأَنَا عَنْهُ غَنِيٌّ فَإِذَا رَأَى أَنْ لا بُدَّ مِنْهُ سَلَكَ يَدَهُ فِي فِيهِ فَيَقْضَمُهَا قَضْمَ الْفَحْلِ ."],"takhrij":"صحيح: رواه مسلم في الزّكاة (988) من طريق عبد الرزّاق، أخبرنا ابنُ جريج، أخبرني أبو الزّبير، أنه سمع جابر بن عبدالله الأنصاريّ، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Muslim (988).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh al-Anṣārī said: I heard the Messenger of Allah ﷺ say: “There is no owner of camels who does not fulfill what is due regarding them except that they will come on the Day of Resurrection more numerous than they ever were, and he will be laid down for them on a broad flat plain, and they will trample over him with their feet. There is no owner of cattle who does not fulfill what is due regarding them except that they will come on the Day of Resurrection more numerous than they ever were, and he will be laid down for them on a broad flat plain, and they will gore him with their horns and trample him with their legs. There is no owner of sheep who does not fulfill what is due regarding them except that they will come on the Day of Resurrection more numerous than they ever were, and he will be laid down for them on a broad flat plain, and they will gore him with their horns and trample him with their hoofs. None among them will be hornless or broken-horned. And there is no owner of hoarded wealth who does not fulfill what is due regarding it except that his treasure will come on the Day of Resurrection as a bald-headed snake following him. When he flees from it, it will call out: Take your treasure that you stored away, for I have no need of it. When he realizes he cannot escape it, he will put his hand into its mouth, and it will crush it like a male camel bites.”"]},"buhuth":{"en":["The phrase “a broad flat plain” means a wide, level area. The original sense is a low place where water settles.","“Hornless” means a sheep that has no horns.","“A bald-headed snake” means a male snake whose scalp has become bare because of the intensity of its venom.","“It will crush it” means it will bite and chew it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (988)."},{"num":3933,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: قَالَ رَجُلٌ مِنَ الْقَوْمِ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِذَا أَدَّى رَجُلٌ زَكَاةَ مَالِهِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَدَّى زَكَاةَ مَالِهِ، فَقَدْ ذَهَبَ عَنْهُ شَرُّهُ."],"takhrij":"حسن: رواه الطبرانيّ في الأوسط (مجمع البحرين 1345) عن أحمد بن حمدون، حدّثنا محمد بن عمار الموصليّ، ثنا عمر بن أيوب، عن المغيرة بن زياد، عن أبي الزبير، عن جابر، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (1345), and by al-Ḥākim (1/390).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Jābir said: A man from the people said: “O Messenger of Allah ﷺ, what if a man pays the zakat of his wealth?” So the Messenger of Allah ﷺ said: “Whoever pays the zakat of his wealth has removed its evil from himself.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (( مجمع البحرين 1345 ))، والحاكم (1/390)."},{"num":3934,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مسعود قَالَ: قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ رَجُلٍ لَهُ مَالٌ لا يُؤَدِّي حَقَّ مَالِهِ إِلا جُعِلَ لَهُ طَوْقًا فِي عُنُقِهِ شُجَاعٌ أَقْرَعُ وَهُوَ يَفِرُّ مِنْهُ وَهُوَ يَتْبَعُهُ ثُمَّ قَرَأَ مِصْدَاقَهُ مِنْ كِتَابِ الله عَزَّ وَجَلَّ: ﴿وَلَا يَحْسَبَنَّ الَّذِينَ يَبْخَلُونَ بِمَا آتَاهُمُ اللَّهُ مِنْ فَضْلِهِ هُوَ خَيْرًا لَهُمْ بَلْ هُوَ شَرٌّ لَهُمْ سَيُطَوَّقُونَ مَا بَخِلُوا بِهِ يَوْمَ الْقِيَامَةِ﴾ [آل عمران: 180] ."],"takhrij":"صحيح: رواه الترمذيّ (3012)، والنسائيّ (2441)، وابن ماجه (1784) كلّهم من حديث سفيان بن عيينة، عن جامع (وهو ابن أبي راشد)، عن أبي وائل، عن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Tirmidhī (3012), al-Nasā’ī (2441), Ibn Mājah (1784). Al-Tirmidhī said: Hasan Sahih.","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: The Messenger of Allah ﷺ said: “There is no man who has wealth and does not give its due right except that a bald-headed snake will be made for him as a collar around his neck, while he flees from it and it follows him.” Then he recited its confirmation from the Book of Allah, Mighty and Majestic: “And let not those who withhold what Allah has given them from His bounty think it is good for them. Rather, it is bad for them. What they withheld will be fastened around their necks on the Day of Resurrection.” [Āl ʿImrān 3:180]"]},"buhuth":{"en":["The phrase “a bald-headed snake” means a snake."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3012)، والنسائي (2441)، وابن ماجه (1784). قال الترمذي: حسن صحيح."},{"num":3935,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ، قَالَ: آكِلُ الرِّبَا ومؤكله وَشَاهِدَاهُ إِذَا عَلِمَاهُ، وَالْوَاشِمَةُ والمستوشمة، وَلَاوِي الصَّدَقَةِ، وَالْمُرْتَدُّ أَعْرَابِيًّا بَعْدَ الْهِجْرَةِ مَلْعُونُونَ عَلَى لِسَانِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْقِيَامَةِ ."],"takhrij":"حسن: رواه ابن خزيمة (2250)، والحاكم (1430) كلاهما من طريق ابن عيسى، عن الأعمش، عن عبدالله بن مرة، عن مسروق، قال: قال عبدالله، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Ibn Khuzaymah (2250), al-Ḥākim (1430).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: “The one who consumes usury, the one who pays it, its two witnesses when they know it, the woman who tattoos and the one who asks to be tattooed, the one who delays or withholds charity, and the one who reverts to desert life after migration, are cursed upon the tongue of Muhammad ﷺ on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (2250)، والحاكم (1430)."},{"num":3936,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الَّذِي لا يُؤَدِّي زَكَاةَ مَالِهِ يُخَيَّلُ إِلَيْهِ مَالُهُ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ لَهُ زَبِيبَتَانِ. قَالَ: فَيَلْتَزِمُهُ أَوْ يُطَوِّقُهُ قَالَ: يَقُولُ: أَنَا كَنْزُكَ أَنَا كَنْزُكَ ."],"takhrij":"صحيح: رواه النسائيّ (2481) عن الفضل بن سهل، قال: حدّثنا أبو النّضر هاشم بن القاسم، قال: حدّثنا عبد العزيز بن عبدالله بن أبي سلمة، عن عبدالله بن دينار، عن ابن عمر، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (2481), authenticated by Ibn Khuzaymah (2257).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “The one who does not pay the zakat of his wealth will have his wealth made to appear to him on the Day of Resurrection as a bald-headed snake with two dark marks.” He said: “It will cling to him or coil around him and say: I am your treasure, I am your treasure.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2481)، وصححه ابن خزيمة (2257)."},{"num":3937,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تَرَكَ بَعْدَهُ كَنْزًا مُثِّلَ لَهُ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ، لَهُ زَبِيبَتَانِ يُتْبِعُهُ، فَيَقُولُ: وَيْلَكَ مَا أَنْتَ، فَيَقُولُ: أَنَا كَنْزُكُ الَّذِي تَرَكْتَهُ بَعْدَكَ، فَلَا يَزَالُ يَتْبَعُهُ حَتَّى يُلْقِمَهُ يَدَهُ، فَيُقَصْقِصُهَا، ثمَّ يَتْبَعَهُ سَائِرُ جَسَدِهِ."],"takhrij":"صحيح: رواه الطبرانيّ في \"الكبير\" (1408)، والبزّار - كشف الأستار (882) -، وصحّحه ابن خزيمة (2255)، والحاكم (1434) كلّهم من طرق عن يزيد بن زريع، ثنا سعيد بن أبي عروبة، عن قتادة، عن سالم بن أبي الجعد الغطفانيّ، عن معدان بن أبي طلحة اليعمريّ، عن ثوبان، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Ṭabarānī in al-Kabīr (1408), al-Bazzār in Kashf al-Astār (882), authenticated by Ibn Khuzaymah (2255).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Thawbān said: The Messenger of Allah ﷺ said: “Whoever leaves behind hoarded treasure, it will be made for him on the Day of Resurrection as a bald-headed snake with two dark marks, following him with its mouth open. He will say: Woe to you, what do you want with me? It will say: I am your treasure that you left behind. It will continue following him until it forces his hand into its mouth and crushes it, then it will follow the rest of his body.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (1408)، والبزار في كشف الأستار (882)، وصححه ابن خزيمة (2255)."},{"num":3938,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ دِينَارٍ، عَنِ ابْنِ الزُّبَيْرِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنْ صَاحِبِ إِبِلٍ لا يُؤَدِّي حَقَّهَا فِي رِسْلِهَا وَنَجْدَتِهَا إِلا جِيءَ يَوْمَ الْقِيَامَةِ حَتَّى يُبْطَحَ لَهَا بِقَاعٍ قَرْقَرٍ تَطَؤُهُ بِأَخْفَافِهَا، كُلَّمَا نَفِدَتْ أُخْرَاهَا، أُعِيدَتْ عَلَيْهِ أُولاهَا حَتَّى يُقْضَى بَيْنَ النَّاسِ، وَيُرَى سَبِيلَهُ."],"takhrij":"حسن: رواه البزار (2199) - كشف الأستار (879) - عن مرزوق ابن بكير وعمر بن الخطاب، قالا: ثنا موسى بن مسعود، ثنا محمد بن مسلم، عن عمرو بن دينار، عن ابن الزبير، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: al-Bazzār (2199), Kashf al-Astār (879).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn al-Zubayr reported that the Messenger of Allah ﷺ said: “There is no owner of camels who does not give their due right in hardship and ease except that they will be brought on the Day of Resurrection and he will be thrown down for them on a broad flat plain. They will trample him with their feet, and whenever the last of them finishes, the first of them will be brought back over him, until judgment is made between the people and he sees his final path.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (2199) في كشف الأستار (879)."},{"num":3939,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَا مَنَعَ قَوْمٌ الزَّكَاةَ إلاّ ابْتَلَاهُمُ اللَّهُ بِالسِّنِينَ ."],"takhrij":"حسن: رواه الطبراني في \"الأوسط\" - مجمع البحرين (1343) - عن عبدان بن أحمد، ثنا العباس بن الوليد الخلاّل الدّمشقيّ، ثنا مروان بن محمد الطّاطريّ، ثنا سليمان بن موسى أبو داود الكوفيّ، عن فضيل بن مرزوق، عن عبدالله بن بريدة، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الوعيد الشديد لمانع الزكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Awsaṭ, cited in Majmaʿ al-Baḥrayn (1343).","chapter_en":"What is reported of the severe warning for one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb said: The Messenger of Allah ﷺ said: “No people withhold zakat except that Allah afflicts them with years of hardship.”"]},"buhuth":{"en":["And al-Ḥākim (2/126) narrated it with the wording: “Whenever a people break a covenant, fighting appears among them. Whenever immorality becomes widespread among a people, Allah sends death upon them. And whenever a people withhold zakat, Allah withholds rain from them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط، في مجمع البحرين (1343)."},{"num":3940,"demo":false,"sanad":"","matn":["عن بهز بن حكيم، قال: حدّثني أبي، عن جدّي، قال: سمعت النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يقول: فِي كُلِّ إِبِلٍ سَائِمَةٍ فِي كُلِّ أَرْبَعِينَ ابْنَةُ لَبُونٍ، لا يُفَرَّقُ إِبِلٌ عَنْ حِسَابِهَا مَنْ أَعْطَاهَا مُؤْتَجِرًا فَلَهُ أَجْرُهَا وَمَنْ أَبَى فَإِنَّا آخِذُوهَا وَشَطْرَ إِبِلِهِ عَزْمَةٌ مِنْ عَزَمَاتِ رَبِّنَا، لا يَحِلُّ لآلِ مُحَمَّدٍ صَلَّى الله عَلَيْهِ وَسَلَّمَ مِنْهَا شَيْءٌ ."],"takhrij":"حسن: رواه أبو داود (1575)، والنسائي (2446) كلاهما من وجهين، عن بهز بن حكيم، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب عقوبة مانع الزكاة في الدنيا","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (1575), al-Nasā’ī (2446), authenticated by Ibn Khuzaymah (2266) and al-Ḥākim (1448).","chapter_en":"The worldly punishment of the one who withholds zakat","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Bahz ibn Ḥakīm said: My father narrated to me from my grandfather, who said: I heard the Prophet ﷺ say: “For every forty grazing camels, one bint labūn is due. Camels are not to be separated to alter their calculation. Whoever gives it seeking reward will have its reward, and whoever refuses, we will take it and half of his camels as well, as a firm command from the commands of our Lord. Nothing from it is lawful for the family of Muhammad ﷺ.”"]},"buhuth":{"en":["The phrase “for every forty, one bint labūn” means: in the range above one hundred and twenty.","The phrase “seeking reward” means: giving it while hoping for its reward from Allah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1575)، والنسائي (2446)، وصححه ابن خزيمة (2266)، والحاكم (1448)."},{"num":3941,"demo":false,"sanad":"","matn":["عن الأحْنَفَ بْن قيسٍ حَدَّثَهُمْ قَالَ: جَلَسْتُ إِلَى مَلإٍ مِنْ قُرَيْشٍ، فَجَاءَ رَجُلٌ خَشِنُ الشَّعَرِ وَالثِّيَابِ وَالهَيْئَةِ حَتَّى قَامَ عَلَيْهِمْ، فَسَلَّمَ، ثُمَّ قَال: بَشِّرِ الْكَانِزِينَ بِرَضْفٍ، يُحْمَى عَلَيْهِ فِي نَارِ جَهَنَّمَ، ثُمَّ يُوضَعُ عَلَى حَلَمَةِ ثَدْيِ أَحَدِهِمْ حَتَّى يَخْرُجَ مِنْ نُغْضِ كَتِفِهِ، وَيُوضَعُ عَلَى نُغْضِ كَتِفِهِ، حَتَّى يَخْرُجَ مِنْ حَلَمَةِ ثَدْيِهِ يَتَزَلْزَلُ. ثُمَّ وَلَّى، فَجَلَسَ إِلَى سَارِيَةٍ، وَتَبِعْتُهُ، وَجَلَسْتُ إِلَيْهِ وَأَنَا لا أَدْرِي مَنْ هُوَ؟. فَقُلْتُ: لَهُ لا أُرَى الْقَوْمَ إِلا قَدْ كَرِهُوا الَّذِي قُلْتَ؟ قَالَ: إِنَّهُمْ لا يَعْقِلُونَ شَيْئًا، قَالَ لِي خَلِيلِي. قَالَ: قُلْتُ: مَنْ خَلِيلُكَ؟ قَالَ: النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَبَا ذَرٍّ، أَتُبْصِرُ أُحُدًا؟ . قَالَ: فَنَظَرْتُ إِلَى الشَّمْسِ مَا بَقِيَ مِنْ النَّهَارِ، وَأَنَا أُرَى أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرْسِلُنِي فِي حَاجَةٍ لَهُ. قُلْتُ: نَعَمْ. قَالَ: مَا أُحِبُّ أَنَّ لِي مِثْلَ أُحُدٍ ذَهَبًا أُنْفِقُهُ كُلَّهُ إِلا ثَلاثَةَ دَنَانِيرَ .","وَإِنَّ هَؤُلَاءِ لا يَعْقِلُونَ، إِنَّمَا يَجْمَعُونَ الدُّنْيَا، لا وَالله، لا أَسْأَلُهُمْ دُنْيَا، وَلا أَسْتَفْتِيهِمْ عَنْ دِينٍ، حَتَّى أَلْقَى الله ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1407)، ومسلم في الزكاة (992) كلاهما من طريق الجريريّ، عن أبي العلاء، عن الأحنف، فذكره. واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب من يرى كراهية جمع الأموال عن حاجته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1407), Muslim (992), and this is the wording of al-Bukhārī.","chapter_en":"The view of those who disliked gathering wealth beyond one’s need","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Al-Aḥnaf ibn Qays reported to them: I was sitting with a group of Quraysh when a man with rough hair, rough clothing, and a rough appearance came and stood over them. He greeted them and then said: “Give glad tidings to those who hoard wealth of heated stones heated in the Fire of Hell. It will be placed on the nipple of one of them until it comes out from the bone of his shoulder, then placed on the bone of his shoulder until it comes out from the nipple of his chest, making him shake violently.” Then he turned away and sat by a pillar. I followed him and sat with him, not knowing who he was. I said to him: “It seems the people disliked what you said.” He said: “They understand nothing. My close friend said this to me.” I said: “Who is your close friend?” He said: “The Prophet ﷺ.” He said: “O Abū Dharr, do you see Uḥud?” He said: I looked at the sun to see how much of the day remained, thinking the Messenger of Allah ﷺ might send me for some need of his. I said: “Yes.” He said: “I would not like to have gold equal to Uḥud and spend all of it, except three dinars.” And these people do not understand. They are only gathering worldly wealth. No, by Allah, I will not ask them for worldly gain, nor will I seek religious judgment from them, until I meet Allah."]},"buhuth":{"en":["Muslim added after the phrase “They are only gathering worldly wealth”: I said, “What is between you and your brothers from Quraysh? You do not seek benefit from them or receive from them.” He then mentioned what comes after this.","The phrase “a man with rough hair” refers to Abū Dharr.","The words “Give glad tidings to the hoarders” are understood according to the view of Abū Dharr, because he held that whatever exceeded a person’s need counted as hoarded wealth.","The correct view, held by the majority, is that hoarded wealth is wealth whose zakat has not been paid. If its zakat has been paid, then it is not considered hoarded wealth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1407)، ومسلم (992)، واللفظ للبخاري."},{"num":3942,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ وَهْبٍ قَالَ: مَرَرْتُ بِالرَّبَذَةِ فَإِذَا أَنَا بِأَبِي ذَرٍّ رَضِيَ الله عَنْهُ، فَقُلْتُ لَهُ: مَا أَنْزَلَكَ مَنْزِلكَ هَذَا؟ قَالَ: كُنْتُ بِالشَّأْمِ، فَاخْتَلَفْتُ أَنَا وَمُعَاوِيَةُ فِي ﴿وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنْفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ﴾ [سورة التوبة: 34]. قَالَ مُعَاوِيَةُ نَزَلَتْ فِي أَهْلِ الْكِتَابِ. فَقُلْتُ: نَزَلَتْ فِينَا وَفِيهِمْ فَكَانَ بَيْنِي وَبَيْنَهُ فِي ذَاكَ، وَكَتَبَ إِلَى عُثْمَانَ رَضِيَ الله عَنْهُ يَشْكُونِي فَكَتَبَ إِلَيَّ عُثْمَانُ أَنْ اقْدَم المَدِينَةَ فَقَدِمْتُهَا، فَكَثُرَ عَلَيَّ النَّاسُ حَتَّى كَأَنَّهُمْ لَمْ يَرَوْنِي قَبْلَ ذَلِكَ فَذَكَرْتُ ذَاكَ لِعُثْمَانَ فَقَالَ لِي: إِنْ شِئْتَ تَنَحَّيْتَ فَكُنْتَ قَرِيبًا فَذَاكَ الَّذِي أَنْزَلَنِي هَذَا المَنْزِلَ وَلَوْ أَمَّرُوا عَلَيَّ حَبَشِيًّا لَسَمِعْتُ وَأَطَعْتُ ."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1406) عن علي بن أبي هاشم، سمع هُشيماً، أخبرنا حصين، عن زيد بن وهب، فذكره.","grade":"صحيح","chapter_ar":"باب من يرى كراهية جمع الأموال عن حاجته","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Bukhari (1406).","chapter_en":"The view of those who disliked gathering wealth beyond one’s need","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Zayd ibn Wahb said: I passed by al-Rabadhah and found Abū Dharr there. I said to him: “What brought you to live in this place?” He said: “I was in Syria, and Muʿāwiyah and I differed regarding the verse: ‘And those who hoard gold and silver and do not spend it in the path of Allah, give them tidings of a painful punishment.’ [al-Tawbah 9:34] Muʿāwiyah said: ‘It was revealed about the People of the Book.’ I said: ‘It was revealed about us and about them.’ So there was disagreement between me and him over that, and he wrote to ʿUthmān, may Allah be pleased with him, complaining about me. Then ʿUthmān wrote to me telling me to come to Madinah. So I came there, and people gathered around me in such numbers as though they had never seen me before. I mentioned that to ʿUthmān, and he said to me: ‘If you wish, you may move away while remaining nearby.’ That is what caused me to settle in this place. And even if they appointed an Abyssinian over me, I would hear and obey.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1406)."},{"num":3943,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ صَاحِبِ كَنْزٍ لاَ يُؤَدِّى زَكَاتَهُ إِلاَّ أُحْمِىَ عَلَيْهِ فِى نَارِ جَهَنَّمَ."],"takhrij":"صحيح: رواه مسلم في الزكاة (987: 26) عن محمد بن عبدالملك الأموي، حدثنا عبدالعزيز بن المختار، حدثنا سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب ما أُدِّي زكاته فليس بكنز","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Muslim, Book of Zakat (987).","chapter_en":"Whatever zakat has been paid on is not considered hoarded wealth","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There is no owner of hoarded wealth who does not pay its zakat except that it will be heated for him in the Fire of Hell.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (987: 26)."},{"num":3944,"demo":false,"sanad":"","matn":["عن أمّ سلمة زوج النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُنْتُ أَلْبَسُ أَوْضَاحًا مِنْ ذَهَبٍ فَقُلْتُ: يَا رَسُولَ الله أَكَنْزٌ هُوَ؟ فَقَالَ: مَا بَلَغَ أَنْ تُؤَدَّى زَكَاتُهُ، فَزُكِّيَ، فَلَيْسَ بِكَنْزٍ ."],"takhrij":"حسن: رواه أبو داود (1564) عن محمد بن عيسى، حدّثنا عتّاب - يعني ابن بشير -، عن ثابت بن عجلان، عن عطاء، عن أمّ سلمة، فذكرته.","grade":"حسن","chapter_ar":"باب ما أُدِّي زكاته فليس بكنز","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Abu Dawud (1564).","chapter_en":"Whatever zakat has been paid on is not considered hoarded wealth","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah said: I used to wear gold ornaments, so I said: “O Messenger of Allah ﷺ, is this considered hoarded wealth?” He said: “Whatever reaches the amount on which zakat is due, and its zakat is paid, is not hoarded wealth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1564)."},{"num":3945,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا أَدَّيْتَ زَكَاةَ مَالِكَ، فَقَدْ قَضَيْتَ مَا عَلَيْكَ."],"takhrij":"حسن: رواه الترمذي (618)، وابن ماجه (1788) كلاهما من حديث دراج أبي السمح، عن ابن حيرة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما أُدِّي زكاته فليس بكنز","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: al-Tirmidhi (618), Ibn Majah (1788).","chapter_en":"Whatever zakat has been paid on is not considered hoarded wealth","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “When you pay the zakat of your wealth, you have fulfilled what is due upon you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (618)، وابن ماجه (1788)."},{"num":3946,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، عن النّبيّ صلى الله عليه وسلم قال: ليس في مال زكاة حتّى يحول عليه الحول في حديث طويل."],"takhrij":"حسن: رواه أبو داود (1573) عن سليمان بن داود المهريّ، أخبرنا ابن وهب، أخبرني جرير بن حازم - وسمَّى آخر -، عن أبي إسحاق، عن عاصم ابن ضمرة والحارث الأعور، عن علي بن أبي طالب، فذكر الحديث.","grade":"حسن","chapter_ar":"باب لا زكاة في الذهب والفضة حتى يحول عليه الحول","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Abu Dawud (1573).","chapter_en":"There is no zakat on gold and silver until a full year passes over them","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿAli ibn Abi Talib reported from the Prophet ﷺ that he said: “There is no zakat on wealth until a full year has passed over it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1573)."},{"num":3947,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ الْعَاصِ يَقُولُ: بَعَثَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: خُذْ عَلَيْكَ ثِيَابَكَ وَسِلَاحَكَ، ثُمَّ ائْتِنِي فَأَتَيْتُهُ وَهُوَ يَتَوَضَّأُ، فَصَعَّدَ فِيَّ النَّظَرَ ثُمَّ طَأْطَأَهُ، فَقَالَ: إِنِّي أُرِيدُ أَنْ أَبْعَثَكَ عَلَى جَيْشٍ فَيُسَلِّمَكَ اللهُ وَيُغْنِمَكَ، وَأَزْعبُ لَكَ مِنَ الْمَالِ رَغْبَةً صَالِحَةً.","قال: فقلت: يا رسول الله، ما أسلمتُ من أجل المال، ولكني أسلمتُ رغبة في الإسلام، وأن أكون مع رسول الله صلى الله عليه وسلم، فقـــال رسول الله صلى الله عليه وسلم: يا عمرو نِعمّا بالمال الصّالح للرجل الصالح ."],"takhrij":"صحيح: رواه الإمام أحمد (17763)، والطبراني في الأوسط (3213)، وصحّحه ابن حبان (3210)، والحاكم (2926) كلّهم من طريق موسى ابن عُليّ، عن أبيه، قال: سمعت عمرو بن العاص يقول (فذكره).","grade":"صحيح","chapter_ar":"باب إباحة المال من طرق الحلال","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Aḥmad (17763), al-Ṭabarānī in al-Awsaṭ (3213), and authenticated by Ibn Ḥibbān (3210).","chapter_en":"The Permissibility of Wealth Earned Through Lawful Means","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["ʿAmr ibn al-ʿĀṣ said: The Messenger of Allah ﷺ sent for me and said, “Put on your clothes and your weapons, then come to me.” So I came to him while he was performing ablution. He looked up at me, then lowered his gaze and said, “I want to send you on an expedition through which Allah will keep you safe and grant you spoils, and I will give you a good share of wealth.” He said: I replied, “O Messenger of Allah ﷺ, I did not accept Islam for the sake of wealth. Rather, I accepted Islam out of desire for Islam and so that I might be with the Messenger of Allah ﷺ.” So the Messenger of Allah ﷺ said, “O ʿAmr, how excellent is righteous wealth for a righteous man.”"]},"buhuth":{"en":["His statement, “I will give you a share,” with the letters zāy and ʿayn, means giving or handing over. It is said: “He gave him a portion of his wealth,” meaning he handed over to him a payment from it. A portion means a piece of wealth. In some hadith sources, the wording appears as, “I will grant you a desire,” and that meaning is also sound. It is as though some narrators reported the meaning rather than the exact original wording and brought wording that matched its meaning."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (17763)، والطبراني في الأوسط (3213)، وصححه ابن حبان (3210)."},{"num":3948,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ مُعَاذًا إِلَى الْيَمَنِ، فَقَالَ.... فَأَعْلِمْهُمْ أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً فِي أَمْوَالِهِمْ تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ، وَتُرَدُّ عَلَى فُقَرَائِهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1458)، ومسلم في الإيمان (19) كلاهما من طريق يحيى بن عبدالله بن صيفي، عن أبي معبد، عن ابن عباس، فذكره في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب الصدقة تؤخذ من الأغنياء وترد على الفقراء","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1458) and Muslim (19).","chapter_en":"Charity Is Taken from the Wealthy and Returned to the Poor","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿAbbās reported that Muʿādh said: The Messenger of Allah ﷺ sent me and said: “Inform them that Allah has made charity obligatory upon them, to be taken from their wealthy and returned to their poor.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1458)، ومسلم (19).","voc":["bukhari",1496]},{"num":3949,"demo":false,"sanad":"","matn":["عن إِبْرَاهِيمَ بن عَطَاءٍ مولى عمران بْنِ حُصَيْنٍ، عَنْ أَبِيهِ، أَنَّ زِيَادًا، أَوْ بَعْضَ الأُمَرَاءِ بَعَثَ عِمْرَانَ بْنَ حُصَيْنٍ عَلَى الصَّدَقَةِ. فَلَمَّا رَجَعَ قَالَ لِعِمْرَانَ: أَيْنَ الْمَالُ؟ قَالَ: وَلِلْمَالِ أَرْسَلْتَنِي؟ أَخَذْنَاهَا مِنْ حَيْثُ كُنَّا نَأْخُذُهَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَوَضَعْنَاهَا حَيْثُ كُنَّا نَضَعُهَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه أبو داود (1625)، وابن ماجه (1811) كلاهما من طريق إبراهيم بن عطاء بإسناده، مثله.","grade":"حسن","chapter_ar":"باب الصدقة تؤخذ من الأغنياء وترد على الفقراء","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1625) and Ibn Mājah (1811).","chapter_en":"Charity Is Taken from the Wealthy and Returned to the Poor","part_en":"Zakat","group_ar":"جموع الأبواب في وجوب الزكاة والترغيب في أدائها والترهيب من منعها","group_en":"Compilation of chapters on the obligation of zakat, encouragement to give it, and warning against withholding it","part_no":14,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Ibrāhīm ibn ʿAṭā, the freedman of ʿImrān ibn Ḥuṣayn, narrated from his father that Ziyād, or one of the governors, appointed ʿImrān ibn Ḥuṣayn over the charity collection. When he returned, he said to ʿImrān, “Where is the money?” He replied, “Was it for the money that you sent me? We took it from where we used to take it during the time of the Messenger of Allah ﷺ, and we placed it where we used to place it during the time of the Messenger of Allah ﷺ.”"]},"buhuth":{"en":["These hadiths are used as evidence that the zakat of each land should be distributed to its own poor people. However, if it is not possible to identify the poor of that land, then it is permissible to transfer it to the poor of another land, just as the zakat of the desert Arabs used to be brought to Madinah and given to the poor among the Emigrants and the Helpers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1625)، وابن ماجه (1811)."},{"num":3950,"demo":false,"sanad":"","matn":["عن أَنَس بن مالك، أنّ أَبَا بَكْرٍ رَضِيَ الله عَنْهُ كَتَبَ لَهُ هَذَا الْكِتَابَ لَمَّا وَجَّهَهُ إِلَى الْبَحْرَيْنِ: بِسْمِ الله الرَّحْمَنِ الرَّحِيمِ هَذِهِ فَرِيضَةُ الصَّدَقَةِ الَّتِي فَرَضَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى المُسْلِمِينَ وَالَّتِي أَمَرَ الله بِهَا رَسُولَهُ فَمَنْ سُئِلَهَا مِنْ المُسْلِمِينَ عَلَى وَجْهِهَا فَلْيُعْطِهَا وَمَنْ سُئِلَ فَوْقَهَا فَلا يُعْطِ. فِي أَرْبَعٍ وَعِشْرِينَ مِنْ الإِبِلِ فَمَا دُونَهَا مِنْ الْغَنَمِ مِنْ كُلِّ خَمْسٍ شَاةٌ إِذَا بَلَغَتْ خَمْسًا وَعِشْرِينَ إِلَى خَمْسٍ وَثَلاثِينَ فَفِيهَا بِنْتُ مَخَاضٍ أُنْثَى، فَإِذَا بَلَغَتْ سِتًّا وَثَلاثِينَ إِلَى خَمْسٍ وَأَرْبَعِينَ فَفِيهَا بِنْتُ لَبُونٍ أُنْثَى، فَإِذَا بَلَغَتْ سِتًّا وَأَرْبَعِينَ إِلَى سِتِّينَ فَفِيهَا حِقَّةٌ طَرُوقَةُ الجَمَلِ، فَإِذَا بَلَغَتْ وَاحِدَةً وَسِتِّينَ إِلَى خَمْسٍ وَسَبْعِينَ فَفِيهَا جَذَعَةٌ، فَإِذَا بَلَغَتْ يَعْنِي سِتًّا وَسَبْعِينَ إِلَى تِسْعِينَ فَفِيهَا بِنْتَا لَبُونٍ، فَإِذَا بَلَغَتْ إِحْدَى وَتِسْعِينَ إِلَى عِشْرِينَ وَمِائَةٍ فَفِيهَا حِقَّتَانِ طَرُوقَتَا الجَمَلِ، فَإِذَا زَادَتْ عَلَى عِشْرِينَ وَمِائَةٍ فَفِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ وَفِي كُلِّ خَمْسِينَ حِقَّةٌ وَمَنْ لَمْ يَكُنْ مَعَهُ إِلا أَرْبَعٌ مِنْ الْإِبِلِ فَلَيْسَ فِيهَا صَدَقَةٌ إِلا أَنْ يَشَاءَ رَبُّهَا، فَإِذَا بَلَغَتْ خَمْسًا مِنْ الإِبِلِ فَفِيهَا شَاةٌ، وَفِي صَدَقَةِ الْغَنَمِ فِي سَائِمَتِهَا إِذَا كَانَتْ أَرْبَعِينَ إِلَى عِشْرِينَ وَمِائَةٍ شَاةٌ فَإِذَا زَادَتْ عَلَى عِشْرِينَ وَمِائَةٍ إِلَى مِائَتَيْنِ شَاتَانِ، فَإِذَا زَادَتْ عَلَى مِائَتَيْنِ إِلَى ثَلاثِ مِائَةٍ فَفِيهَا ثَلاثُ شِيَاهٍ، فَإِذَا زَادَتْ عَلَى ثَلاثِ مِائَةٍ فَفِي كُلِّ مِائَةٍ شَاةٌ، فَإِذَا كَانَتْ سَائِمَةُ الرَّجُلِ نَاقِصَةً مِنْ أَرْبَعِينَ شَاةً وَاحِدَةً فَلَيْسَ فِيهَا صَدَقَةٌ إِلا أَنْ يَشَاءَ رَبُّهَا، وَفِي الرِّقَّةِ رُبْعُ الْعُشْرِ فَإِنْ لَمْ تَكُنْ إِلا تِسْعِينَ وَمِائَةً فَلَيْسَ فِيهَا شَيْءٌ إِلا أَنْ يَشَاءَ رَبُّهَا ."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1454) عن محمد بن عبدالله بن المثنى الأنصاريّ، قال: حدثني أبي، قال: حدثني ثمامة بن عبدالله بن أنس، أنّ أنساً حدّثه، أنّ أبا بكر كتب له هذا الكتاب، فذكره.","grade":"صحيح","chapter_ar":"باب زكاة الإبل","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1454).","chapter_en":"The Zakat of Camels","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik reported that Abū Bakr, may Allah be pleased with him, wrote this document for him when he sent him to Bahrain: “In the Name of Allah, the Most Merciful, the Especially Merciful. This is the prescribed charity which the Messenger of Allah ﷺ made obligatory upon the Muslims and which Allah commanded His Messenger to impose. Whoever among the Muslims is asked to give it according to its proper amount should give it, and whoever is asked for more than what is due should not give it. For twenty-four camels or fewer, the zakat is sheep: one sheep for every five camels. When the number reaches twenty-five up to thirty-five, one female bint makhāḍ is due. From thirty-six to forty-five, one female bint labūn is due. From forty-six to sixty, one ḥiqqah fit to be covered by a male camel is due. From sixty-one to seventy-five, one jadhaʿah is due. From seventy-six to ninety, two bint labūn camels are due. From ninety-one to one hundred and twenty, two ḥiqqah camels fit for breeding are due. When there are more than one hundred and twenty camels, then for every forty there is one bint labūn, and for every fifty there is one ḥiqqah. Whoever owns only four camels owes no zakat on them unless their owner wishes to give voluntarily. When they reach five camels, one sheep is due. Regarding grazing sheep: if they number from forty up to one hundred and twenty, one sheep is due. If they exceed one hundred and twenty up to two hundred, two sheep are due. If they exceed two hundred up to three hundred, three sheep are due. If they exceed three hundred, then one sheep is due for every one hundred. If a man’s grazing flock is one sheep short of forty, then no zakat is due unless its owner wishes to give voluntarily. On silver, one-quarter of one-tenth is due. If there are only one hundred and ninety dirhams, nothing is due unless the owner wishes to give voluntarily.”"]},"intro_majmu":{"ar":["١- باب زكاة الإبل"],"en":["Collection of Chapters on the Zakat of Livestock","1. Chapter: The Zakat of Camels"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1454)."},{"num":3951,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ فِيمَا دُونَ خَمْسٍ مِنَ الإِبِلِ صَدَقَةٌ. وَلَيْسَ فِي الأَرْبَعِ شَىْءٌ، فَإِذَا بَلَغَتْ خَمْسًا فَفِيهَا شَاةٌ إِلَى أَنْ تَبْلُغَ تِسْعًا. فَإِذَا بَلَغَتْ عَشْرًا فَفِيهَا شَاتَانِ إِلَى أَنْ تَبْلُغَ أَرْبَعَ عَشْرَةَ. فَإِذَا بَلَغَتْ خَمْسَ عَشْرَةَ فَفِيهَا ثَلاَثُ شِيَاهٍ إِلَى أَنْ تَبْلُغَ تِسْعَ عَشْرَةَ. فَإِذَا بَلَغَتْ عِشْرِينَ فَفِيهَا أَرْبَعُ شِيَاهٍ إِلَى أَنْ تَبْلُغَ أَرْبَعًا وَعِشْرِينَ. فَإِذَا بَلَغَتْ خَمْسًا وَعِشْرِينَ فَفِيهَا بِنْتُ مَخَاضٍ إِلَى خَمْسٍ وَثَلاَثِينَ. فَإِذَا لَمْ تَكُنْ بِنْتُ مَخَاضٍ فَابْنُ لَبُونٍ ذَكَرٌ. فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا بِنْتُ لَبُونٍ إِلَى أَنْ تَبْلُغَ خَمْسًا وَأَرْبَعِينَ. فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا حِقَّةٌ إِلَى أَنْ تَبْلُغَ سِتِّينَ. فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا جَذَعَةٌ إِلَى أَنْ تَبْلُغَ خَمْسًا وَسَبْعِينَ. فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا بِنْتَا لَبُونٍ إِلَى أَنْ تَبْلُغَ تِسْعِينَ. فَإِنْ زَادَتْ بَعِيرًا فَفِيهَا حِقَّتَانِ إِلَى أَنْ تَبْلُغَ عِشْرِينَ وَمِائَةً. ثُمَّ فِي كُلِّ خَمْسِينَ حِقَّةٌ وَفِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ."],"takhrij":"حسن: رواه ابن ماجه (1799) عن محمد بن عقيل بن خويلد النيسابوري، حدثنا حفص بن عبد الله السلمي، حدثنا إبراهيم بن طهمان، عن عمرو بن يحيى بن عُمارة، عن أبيه، عن أبي سعيد الخدري، فذكره.","grade":"حسن","chapter_ar":"باب زكاة الإبل","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1799).","chapter_en":"The Zakat of Camels","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ said, “There is no obligatory charity on fewer than five camels. There is nothing due on four. Once they reach five, then one sheep is due until they reach nine. Once they reach ten, then two sheep are due until they reach fourteen. Once they reach fifteen, then three sheep are due until they reach nineteen. Once they reach twenty, then four sheep are due until they reach twenty-four. Once they reach twenty-five, then one she-camel in her second year is due until they reach thirty-five. If such a camel is not available, then a male camel in its third year is due. If there is one more camel, then one she-camel in her third year is due until they reach forty-five. If there is one more camel, then one she-camel in her fourth year is due until they reach sixty. If there is one more camel, then one she-camel in her fifth year is due until they reach seventy-five. If there is one more camel, then two she-camels in their third year are due until they reach ninety. If there is one more camel, then two she-camels in their fourth year are due until they reach one hundred and twenty. After that, for every fifty there is one she-camel in her fourth year due, and for every forty there is one she-camel in her third year due.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1799)."},{"num":3952,"demo":false,"sanad":"","matn":["عن نَافِعٍ، أَنَّهُ قَرَأَ كِتَابَ عُمَرَ بْنِ الْخَطَّابِ: أَنَّهُ لَيْسَ فِيمَا دُونَ خَمْسٍ مِنَ الْإِبِلِ شَيْءٌ. فَإِذَا بَلَغَتْ خَمْسًا فَفِيهَا شَاةٌ إِلَى تِسْعٍ. فَإِذَا كَانَتْ عَشْرًا فَشَاتَانِ إِلَى أَرْبَعَ عَشْرَةَ. فَإِذَا بَلَغَتْ خَمْسَ عَشْرَةَ فَفِيهَا ثَلَاثٌ إِلَى تِسْعَ عَشْرَةَ. فَإِذَا بَلَغَتِ الْعِشْرِينَ فَأَرْبَعٌ إِلَى أَرْبَعٍ وَعِشْرِينَ. فَإِذَا بَلَغَتْ خَمْسًا وَعِشْرِينَ فَفِيهَا بِنْتُ مَخَاضٍ إِلَى خَمْسٍ وَثَلَاثِينَ. فَإِذَا زَادَتْ فَفِيهَا ابْنَةُ لَبُونٍ إِلَى خَمْسٍ وَأَرْبَعِينَ. فَإِذَا زَادَتْ فَفِيهَا حِقَّةٌ إِلَى السِّتِّينَ. فَإِذَا زَادَتْ فَفِيهَا ابْنَتَا لَبُونٍ إِلَى التِّسْعِينَ. فَإِذَا زَادَتْ فَفِيهَا حِقَّتَانِ إِلَى الْعِشْرِينَ وَمِائَةٍ. فَإِذَا زَادَتْ فَفِي كُلِّ خَمْسِينَ حِقَّةٌ.، وَفِي كُلِّ أَرْبَعِينَ ابْنَةُ لَبُونٍ. وَلَيْسَ فِي الْغَنَمِ شَيْءٌ فِيمَا دُونَ الْأَرْبَعِينَ. فَإِذَا بَلَغَتِ الْأَرْبَعِينَ فَفِيهَا شَاةٌ إِلَى الْعِشْرِينَ وَمِائَةٍ. فَإِذَا زَادَتْ فَشَاتَانِ إِلَى الْمِائَتَيْنِ. فَإِذَا زَادَتْ عَلَى الْمِائَتَيْنِ فَثَلَاثُ شِيَاهٍ إِلَى الثَّلَاثِ مِائَةٍ. فَإِذَا زَادَتْ عَلَى الثَّلَاثِ مِائَةٍ، فَفِي كُلِّ مِائَةٍ شَاةٌ."],"takhrij":"صحيح: رواه أبو يعلى في \"مسند\" (125) عن أبي الرّبيع (هو الزّهرانيّ)، ثنا حماد (هو ابن زيد)، قال: سمعت أيوب وعبدالرحمن وعبيدالله بن عمر يحدّثون عن نافع، أنّه قرأ كتاب عمر ابن الخطّاب، فذكره.","grade":"صحيح","chapter_ar":"باب زكاة الإبل","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Ya‘la in his Musnad (125).","chapter_en":"The Zakat of Camels","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Nafi‘ said that he read in the letter of ‘Umar ibn al-Khattab: “There is nothing due on fewer than five camels. When they reach five, then one sheep is due until nine. If they are ten, then two sheep are due until fourteen. When they reach fifteen, then three sheep are due until nineteen. When they reach twenty, then four sheep are due until twenty-four. When they reach twenty-five, then one she-camel in her second year is due until thirty-five. If they increase, then one she-camel in her third year is due until forty-five. If they increase, then one she-camel in her fourth year is due until sixty. If they increase, then two she-camels in their third year are due until ninety. If they increase, then two she-camels in their fourth year are due until one hundred and twenty. If they increase beyond that, then for every fifty there is one she-camel in her fourth year due, and for every forty there is one she-camel in her third year due. And there is nothing due on sheep if they are fewer than forty. Once they reach forty, then one sheep is due until one hundred and twenty. If they increase, then two sheep are due until two hundred. If they increase beyond two hundred, then three sheep are due until three hundred. If they increase beyond three hundred, then for every hundred one sheep is due.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى في “مسند” ( 125)."},{"num":3953,"demo":false,"sanad":"","matn":["عن قَزَعَة بن يحيى البصريّ، قَالَ: أَتَيْتُ أَبَا سَعِيدٍ وَهُوَ مَكْثُورٌ عَلَيْهِ فَلَمَّا تَفَرَّقَ النَّاسُ عَنْهُ قُلْتُ: إِنِّي لا أَسْأَلُكَ عَمَّا يَسْأَلُكَ هَؤُلاءِ عَنْهُ، قُلْتُ أَسْأَلُكَ عَنْ صَلاةِ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا لَكَ فِي ذَلِكَ مِنْ خَيْرٍ، فَأَعَادَهَا عَلَيْهِ فَقَالَ: كَانَتْ صَلاةُ الظُّهْرِ تُقَامُ فَيَنْطَلِقُ أَحَدُنَا إِلَى الْبَقِيعِ فَيَقْضِي حَاجَتَهُ، ثُمَّ يَأْتِي أَهْلَهُ فَيَتَوَضَّأُ، ثُمَّ يَرْجِعُ إِلَى المَسْجِدِ وَرَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الرَّكْعَةِ الأُولَى. قَالَ: وَسَأَلْتُهُ عَنْ الزَّكَاةِ فَقَالَ: لا أَدْرِي أَرَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْ لا؟ فِي مِائَتَيْ دِرْهَمٍ خَمْسَةُ دَرَاهِمَ، وَفِي أَرْبَعِينَ شَاةً شَاةٌ إِلَى عِشْرِينَ وَمِائَةٍ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا شَاتَانِ إِلَى مِائَتَيْنِ، فَإِذَا زَادَتْ فَفِيهَا ثَلاثُ شِيَاهٍ إِلَى ثَلاثِ مِائَةٍ، فَإِذَا زَادَتْ فَفِي كُلِّ مِائَةٍ شَاةٌ، وَفِي الإِبِلِ فِي خَمْسٍ شَاةٌ، وَفِي عَشْرٍ شَاتَانِ وَفِي خَمْسَ عَشْرَةَ ثَلاثُ شِيَاهٍ، وَفِي عِشْرِينَ أَرْبَعُ شِيَاهٍ وَفِي خَمْسٍ وَعِشْرِينَ ابْنَةُ مَخَاضٍ إِلَى خَمْسٍ وَثَلاثِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا ابْنَةُ لَبُونٍ إِلَى خَمْسٍ وَأَرْبَعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا حِقَّةٌ إِلَى سِتِّينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا جَذَعَةٌ إِلَى خَمْسٍ وَسَبْعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا ابْنَتَا لَبُونٍ إِلَى تِسْعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا حِقَّتَانِ إِلَى عِشْرِينَ وَمِائَةٍ، فَإِذَا زَادَتْ فَفِي كُلِّ خَمْسِينَ حِقَّةٌ وَفِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ . وَسَأَلْتُهُ عَنْ الصَّوْمِ فِي السَّفَرِ قَالَ: سَافَرْنَا مَعَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى مَكَّةَ وَنَحْنُ صِيَام،ٌ قَال: فَنَزَلْنَا مَنْزِلا، فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّكُمْ قَدْ دَنَوْتُمْ مِنْ عَدُوِّكُمْ وَالْفِطْرُ أَقْوَى لَكُمْ . فَكَانَتْ رُخْصَةً فَمِنَّا مَنْ صَامَ وَمِنَّا مَنْ أَفْطَرَ ثُمَّ نَزَلْنَا مَنْزِلا آخَرَ فَقَالَ: إِنَّكُمْ مُصَبِّحُو عَدُوِّكُمْ وَالْفِطْرُ أَقْوَى لَكُمْ فَأَفْطِرُوا .","فَكَانَتْ عَزِيمَةً فَأَفْطَرْنَا ثُمَّ قَالَ: لَقَدْ رَأَيْتُنَا نَصُومُ مَعَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ فِي السَّفَرِ."],"takhrij":"صحيح: رواه الإمام أحمد (11307) عن عبدالرحمن بن مهدي، حدّثني معاوية - يعني ابن صالح -، عن ربيعة بن يزيد، حدّثني قزعة، فذكره بطوله. ورواه مسلم في الصيام (1120) من هذا الوجه مختصراً، وهو الجزء الخاص بالصّوم.","grade":"صحيح","chapter_ar":"باب زكاة الإبل","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Narrated in full by Aḥmad (11307); Muslim (1120) narrates the fasting portion in abbreviated form.","chapter_en":"The Zakat of Camels","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Qazaʿah ibn Yaḥyā al-Baṣrī said: I came to Abū Saʿīd while many people were gathered around him. When the people dispersed, I said: “I am not going to ask you about what these people were asking you. I want to ask you about the prayer of the Messenger of Allah ﷺ.” He said: “There is no good for you in asking about that.” I repeated the question, so he said: “The Ẓuhr prayer would be established, and one of us would go to al-Baqīʿ to relieve himself, then return to his family and perform wuḍūʾ, then return to the mosque while the Messenger of Allah ﷺ was still in the first rakʿah.” He said: I asked him about zakat, and he replied: “I do not know whether he attributed this to the Prophet ﷺ or not: On two hundred dirhams, five dirhams are due. On forty sheep, one sheep is due up to one hundred and twenty. If they increase by one, two sheep are due up to two hundred. If they increase beyond that, three sheep are due up to three hundred. If they increase beyond three hundred, one sheep is due for every hundred. Regarding camels: for five camels, one sheep is due; for ten, two sheep; for fifteen, three sheep; for twenty, four sheep; and for twenty-five, one bint makhāḍ is due up to thirty-five. If they increase by one, one bint labūn is due up to forty-five. If they increase by one, one ḥiqqah is due up to sixty. If they increase by one, one jadhaʿah is due up to seventy-five. If they increase by one, two bint labūn camels are due up to ninety. If they increase by one, two ḥiqqah camels are due up to one hundred and twenty. If they exceed that, then for every fifty one ḥiqqah is due, and for every forty one bint labūn is due.” I also asked him about fasting while traveling. He said: “We traveled with the Messenger of Allah ﷺ toward Makkah while we were fasting. We stopped at a place, and the Messenger of Allah ﷺ said: ‘You have drawn near to your enemy, and breaking the fast will make you stronger.’ So it was a concession. Some of us fasted and some broke their fast. Then we stopped at another place, and he said: ‘You will meet your enemy in the morning, and breaking the fast will make you stronger, so break your fast.’","This time it was a firm command, so we broke our fast. Afterward, I saw us fasting with the Messenger of Allah ﷺ while traveling.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (11307) بطوله، ومسلم (1120) مختصرا في الصوم."},{"num":3954,"demo":false,"sanad":"","matn":["عن عبدالله بن عمر، قال: كَتَبَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كِتَابَ الصَّدَقَةِ فَلَمْ يُخْرِجْهُ إِلَى عُمَّالِهِ حَتَّى قُبِضَ، فَقَرَنَهُ بِسَيْفِهِ فَعَمِلَ بِهِ أَبُو بَكْرٍ حَتَّى قُبِضَ، ثُمَّ عَمِلَ بِهِ عُمَرُ حَتَّى قُبِضَ، فَكَانَ فِيهِ: فِي خَمْسٍ مِنْ الإِبِلِ شَاةٌ، وَفِي عَشْرٍ شَاتَانِ، وَفِي خَمْسَ عَشْرَةَ ثَلاثُ شِيَاهٍ وَفِي عِشْرِينَ أَرْبَعُ شِيَاهٍ، وَفِي خَمْسٍ وَعِشْرِينَ ابْنَةُ مَخَاضٍ إِلَى خَمْسٍ وَثَلاثِينَ، فَإِنْ زَادَتْ وَاحِدَةً فَفِيهَا ابْنَةُ لَبُونٍ إِلَى خَمْسٍ وَأَرْبَعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا حِقَّةٌ إِلَى سِتِّينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا جَذَعَةٌ إِلَى خَمْسٍ وَسَبْعِين،َ فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا ابْنَتَا لَبُونٍ إِلَى تِسْعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا حِقَّتَانِ إِلَى عِشْرِينَ وَمِائَةٍ، فَإِنْ كَانَتْ الإِبِلُ أَكْثَرَ مِنْ ذَلِكَ فَفِي كُلِّ خَمْسِينَ حِقَّةٌ وَفِي كُلِّ أَرْبَعِينَ ابْنَةُ لَبُونٍ. وَفِي الْغَنَمِ فِي كُلِّ أَرْبَعِينَ شَاةً شَاةٌ إِلَى عِشْرِينَ وَمِائَةٍ، فَإِنْ زَادَتْ وَاحِدَةً فَشَاتَانِ إِلَى مِائَتَيْنِ، فَإِنْ زَادَتْ وَاحِدَةً عَلَى الْمِائَتَيْنِ فَفِيهَا ثَلاثُ شِيَاهٍ إِلَى ثَلاثِ مِائَةٍ، فَإِنْ كَانَتْ الْغَنَمُ أَكْثَرَ مِنْ ذَلِكَ فَفِي كُلِّ مِائَةِ شَاةٍ شَاةٌ وَلَيْسَ فِيهَا شَيْءٌ حَتَّى تَبْلُغَ المِائَةَ، وَلا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ وَلا يُجْمَعُ بَيْنَ مُتَفَرِّقٍ مَخَافَةَ الصَّدَقَةِ، وَمَا كَانَ مِنْ خَلِيطَيْنِ فَإِنَّهُمَا يَتَرَاجَعَانِ بَيْنَهُمَا بِالسَّوِيَّةِ وَلا يُؤْخَذُ فِي الصَّدَقَةِ هَرِمَةٌ وَلا ذَاتُ عَيْبٍ .","قَالَ: وقَالَ الزُّهْرِيُّ: إِذَا جَاءَ المُصَدِّقُ قُسِّمَتْ الشَّاءُ أَثْلاثًا: ثُلُثًا شِرَارًا، وَثُلُثًا خِيَارًا، وَثُلُثًا وَسَطًا، فَأَخَذَ المُصَدِّقُ مِنْ الْوَسَطِ وَلَمْ يَذْكُر الزُّهْرِيُّ الْبَقَرَ."],"takhrij":"حسن: رواه أبو داود (1568) واللّفظ له، والترمذي (621) كلاهما من حديث عبّاد بن العوّام، حدّثنا سفيان بن حسين، عن الزّهريّ، عن سالم، عن ابن عمر، فذكره.","grade":"حسن","chapter_ar":"باب زكاة الإبل","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (1568) and al-Tirmidhī (621).","chapter_en":"The Zakat of Camels","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar reported: The Messenger of Allah ﷺ wrote a document concerning zakat, but he died before sending it to his officials. He kept it attached to his sword. Abū Bakr acted according to it until he died, then ʿUmar acted according to it until he died. It contained: “For five camels, one sheep is due; for ten, two sheep; for fifteen, three sheep; and for twenty, four sheep. For twenty-five up to thirty-five camels, one female bint makhāḍ is due. If they increase by one, then one bint labūn is due up to forty-five. If they increase by one, then one ḥiqqah is due up to sixty. If they increase by one, then one jadhaʿah is due up to seventy-five. If they increase by one, then two bint labūn camels are due up to ninety. If they increase by one, then two ḥiqqah camels are due up to one hundred and twenty. If the camels exceed that, then for every fifty one ḥiqqah is due, and for every forty one bint labūn is due. Regarding sheep: for every forty sheep, one sheep is due up to one hundred and twenty. If they increase by one, two sheep are due up to two hundred. If they increase by one beyond two hundred, three sheep are due up to three hundred. If they exceed three hundred, one sheep is due for every hundred. And nothing is due on them until they reach one hundred. Animals belonging to one combined flock must not be separated, and separate flocks must not be combined, out of fear of zakat. If two owners have mixed property, they must settle between themselves equitably. Neither an old animal nor a defective animal is to be taken as zakat.”","Al-Zuhrī said: “When the zakat collector comes, the sheep are divided into three groups: the inferior, the superior, and the middle-quality animals. The collector takes from the middle.” Al-Zuhrī did not mention cattle."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1568)، والترمذي (621)."},{"num":3955,"demo":false,"sanad":"","matn":["عَنْ عَلِيّ بن أبي طالب - قَالَ زُهَيْرٌ: أَحْسَبُهُ عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَنَّه قَالَ: هَاتُوا رُبْعَ الْعُشُورِ مِنْ كُلِّ أَرْبَعِينَ دِرْهَمًا دِرْهَمٌ وَلَيْسَ عَلَيْكُمْ شَيْءٌ حَتَّى تَتِمَّ مِائَتَيْ دِرْهَمٍ فَإِذَا كَانَتْ مِائَتَيْ دِرْهَمٍ فَفِيهَا خَمْسَةُ دَرَاهِمَ، فَمَا زَادَ فَعَلَى حِسَابِ ذَلِكَ، وَفِي الْغَنَمِ فِي أَرْبَعِينَ شَاةً شَاةٌ، فَإِنْ لَمْ يَكُنْ إِلا تِسْعٌ وَثَلاثُونَ فَلَيْسَ عَلَيْكَ فِيهَا شَيْءٌ . وَسَاقَ صَدَقَةَ الْغَنَمِ مِثْلَ الزُّهْرِيِّ قَالَ: وَفِي الْبَقَرِ فِي كُلِّ ثَلاثِينَ تَبِيعٌ، وَفِي الأَرْبَعِينَ مُسِنَّةٌ وَلَيْسَ عَلَى الْعَوَامِلِ شَيْءٌ وَفِي الإِبِلِ . فَذَكَرَ صَدَقَتَهَا كَمَا ذَكَرَ الزُّهْرِيُّ قَالَ: وَفِي خَمْسٍ وَعِشْرِينَ خَمْسَةٌ مِنْ الْغَنَمِ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا ابْنَةُ مَخَاضٍ فَإِنْ لَمْ تَكُنْ بِنْتُ مَخَاضٍ فَابْنُ لَبُونٍ ذَكَرٌ إِلَى خَمْسٍ وَثَلاثِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا بِنْتُ لَبُونٍ إِلَى خَمْسٍ وَأَرْبَعِينَ، فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا حِقَّةٌ طَرُوقَةُ الجَمَلِ إِلَى سِتِّينَ . ثُمَّ سَاقَ مِثْلَ حَدِيثِ الزُّهْرِيِّ قَالَ: فَإِذَا زَادَتْ وَاحِدَةً يَعْنِي وَاحِدَةً وَتِسْعِينَ فَفِيهَا حِقَّتَانِ طَرُوقَتَا الْجَمَلِ إِلَى عِشْرِينَ وَمِائَةٍ، فَإِنْ كَانَتْ الإِبِلُ أَكْثَرُ مِنْ ذَلِكَ فَفِي كُلِّ خَمْسِينَ حِقَّةٌ، وَلا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ وَلَا يُجْمَعُ بَيْنَ مُفْتَرِقٍ خَشْيَةَ الصَّدَقَةِ، وَلا تُؤْخَذُ فِي الصَّدَقَةِ هَرِمَةٌ، وَلا ذَاتُ عَوَارٍ، وَلا تَيْسٌ إِلا أَنْ يَشَاءَ المُصَدِّقُ. وَفِي النَّبَاتِ مَا سَقَتْهُ الْأَنْهَارُ أَوْ سَقَتْ السَّمَاءُ الْعُشْرُ، وَمَا سَقَى الْغَرْبُ فَفِيهِ نِصْفُ الْعُشْرِ .","وَفِي حَدِيثِ عَاصِمٍ وَالحَارِثِ: الصَّدَقَةُ فِي كُلِّ عَامٍ . قَالَ زُهَيْرٌ: أَحْسَبُهُ قَالَ: مَرَّةً .","وَفِي حَدِيثِ عَاصِمٍ: إِذَا لَمْ يَكُنْ فِي الإِبِلِ ابْنَةُ مَخَاضٍ وَلا ابْنُ لَبُونٍ فَعَشَرَةُ دَرَاهِمَ أَوْ شَاتَانِ ."],"takhrij":"حسن: رواه أبو داود (1572) عن عبدالله بن محمد النّفيليّ، حدّثنا زهير، حدّثنا أبو إسحاق، عن عاصم بن حمزة، وعن الحارث الأعور، عن علي رضي الله عنه قال زهير: أحسبه عن النبيّ صلى الله عليه وسلم أنه قال (فذكره).","grade":"حسن","chapter_ar":"باب زكاة الإبل","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Good: Narrated by Abū Dāwūd (1572).","chapter_en":"The Zakat of Camels","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿAlī reported—and Zuhayr said, “I think he attributed it to the Prophet ﷺ”—that he said: “Give one-quarter of one-tenth. For every forty dirhams, one dirham is due. Nothing is due until the amount reaches two hundred dirhams. When it reaches two hundred dirhams, five dirhams are due, and whatever exceeds that is calculated according to the same proportion. Regarding sheep, one sheep is due for every forty. If there are only thirty-nine, nothing is due.” He then narrated the zakat regulations concerning sheep in the same manner as al-Zuhrī. He said: “Regarding cattle, for every thirty one yearling calf is due, and for every forty one musinnah is due. Nothing is due on working cattle.” He also mentioned the zakat regulations concerning camels in the same manner as al-Zuhrī. He said: “For twenty-five camels, five sheep are due. If they increase by one, then one bint makhāḍ is due; and if no bint makhāḍ is available, then a male ibn labūn is due up to thirty-five. If they increase by one, then one bint labūn is due up to forty-five. If they increase by one, then one ḥiqqah fit for breeding is due up to sixty.” Then he continued with wording like al-Zuhrī’s report. He said: “If they increase by one — meaning to ninety-one — then two ḥiqqah camels fit for breeding are due up to one hundred and twenty. If the camels exceed that, then for every fifty one ḥiqqah is due.” He said: “A combined herd is not to be separated, nor separate herds combined, out of fear of zakat. An old animal, an animal with an obvious defect, or a breeding male goat is not to be taken as zakat unless the collector wishes. Regarding crops, whatever is irrigated by rivers or rain is subject to one-tenth, while whatever is irrigated by drawing water is subject to one-half of one-tenth.”","In the narration of ʿĀṣim and al-Ḥārith: “Zakat is due every year.” Zuhayr said: “I think he said: once.” And in ʿĀṣim’s narration:","“If neither a bint makhāḍ nor a male ibn labūn is available among the camels, then ten dirhams or two sheep are due.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1572)."},{"num":3956,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ، عَنْ أَبِيهِ ، عَنْ جدّه: أنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَتَبَ إِلَى أَهْلِ الْيَمَنِ بِكِتَابٍ فِيهِ الْفَرَائِضُ وَالسُّنَنُ وَالدِّيَاتُ، وَبَعَثَ بِهِ مَعَ عَمْرِو بْنِ حَزْمٍ، فَقُرِئَتْ عَلَى أَهْلِ الْيَمَنِ، وَهَذِهِ نُسْخَتُهَا : مِنْ مُحَمَّدٍ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى شُرَحْبِيلَ بْنِ عَبْدِ كُلَالٍ، وَالْحَارِثِ بْنِ عَبْدِ كُلَالٍ، وَنُعَيْمِ بْنِ عَبْدِ كُلَالٍ، قَيْلِ ذِي رُعَينٍ وَمَعَافِرَ وَهَمْدَانَ: أمّا بَعْدُ، فَقَدْ رَجَعَ رَسُولُكُمْ، وَأُعْطِيتُمْ مِنَ الغنائم خُمس اللهِ، وَمَا كَتَبَ اللهُ عَلَى الْمُؤْمِنِينَ مِنَ الْعُشْرِ فِي الْعَقَارِ، وَمَا سَقَتِ السَّمَاءُ أَوْ كَانَ سَيْحاً أَوْ بَعْلا، فَفِيهِ العُشْر إِذَا بَلَغَ خَمْسَةَ أَوْسُقٍ، وَمَا سُقِيَ بِالرَّشَاءِ، وَالدَّالِيَةِ، فَفِيهِ نِصْفُ الْعُشْرِ إِذَا بَلَغَ خَمْسَةَ أَوْسُقٍ. وَفِي كلّ خَمْسٍ مِنَ الإِبِلِ سَائِمَةً شَاةٌ إِلَى أَنْ تَبْلُغَ أَرْبَعًا وَعِشْرِينَ، فَإِذَا زَادَتْ وَاحِدَةً عَلَى أَرْبَعٍ وَعِشْرِينَ فَفِيهَا ابْنَةُ مَخَاضٍ، فَإِنْ لَمْ تُوجَدْ بِنْتُ مَخَاضٍ، فَابْنُ لَبُونٍ ذَكَرٍ إِلَى أَنْ تَبْلُغَ خَمْسًا وَثَلَاثِينَ، فَإِذَا زَادَتْ عَلَى خَمْسٍ وَثَلَاثِينَ، فَفِيهَا ابْنَةُ لَبُونٍ إِلَى أَنْ تَبْلُغَ خَمْسًا وَأَرْبَعِينَ، فَإِذَا زَادَتْ عَلَى خَمْسٍ وَأَرْبَعِينَ، فَفِيهَا حِقَّةٌ طَرُوقَةٌ إِلَى أَنْ تَبْلُغَ سِتِّينَ، فَإِنْ زَادَتْ عَلَى سِتِّينَ وَاحِدَةً، فَفِيهَا جَذَعَةٌ إِلَى أَنْ تَبْلُغَ خمسة وَسَبْعِينَ، فَإِنْ زَادَتْ عَلَى خَمْسٍ وَسَبْعِينَ وَاحِدَةً، فَفِيهَا ابْنَتَا لَبُونٍ إِلَى أَنْ تَبْلُغَ تِسْعِينَ، فَإِنْ زَادَتْ عَلَى تِسْعِينَ وَاحِدَةً، فَفِيهَا حِقَّتَانِ طَرُوقَتَا الْجَمَلِ، إِلَى أَنْ تَبْلُغَ عِشْرِينَ ومائة، فَمَا زَادَ فَفِي كلّ أَرْبَعِينَ ابْنَةُ لَبُونٍ، وَفِي كلّ خَمْسِينَ حِقَّةً طَرُوقَةُ الْجَمَلِ، وَفِي كلّ ثَلَاثِينَ بَاقُورَةً بَقَرَةٌ. وَفِي كلّ أَرْبَعِينَ شَاةً سَائِمَةً شَاةٌ إِلَى أَنْ تَبْلُغَ عِشْرِينَ ومائة، فَإِنْ زَادَتْ عَلَى عِشْرِينَ وَاحِدَةً، فَفِيهَا شَاتَانِ إِلَى أَنْ تَبْلُغَ مِئَتَيْنِ، فَإِنْ زَادَتْ وَاحِدَةً، فَثَلَاثَةُ شِيَاهٍ إِلَى أَنْ تَبْلُغَ ثَلَاثَ مِائَةً، فَمَا زَادَ فَفِي كُلِّ مِائَةً شَاةٍ شَاةٌ . وَلَا تُؤْخَذُ فِي الصَّدَقَةِ هَرِمَةٌ، وَلَا عَجْفَاءُ، وَلَا ذَاتُ عَوَارٍ، وَلَا تَيْسُ الْغَنَمِ ، وَلَا يُجْمَعُ بَيْنَ مُتَفَرِّقٍ، وَلَا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ خِيفَةَ الصَّدَقَةَ، وَمَا أُخِذَ مِنَ الْخَلِيطَيْنِ، فَإِنَّهُمَا يَتَرَاجَعَانِ بَيْنَهُمَا بِالسَّوِيَّةِ. وَفِي كُلِّ خَمْسِ أَوَاقٍ مِنَ الْوَرِقِ خَمْسَةُ دَرَاهِمَ، فَمَا زَادَ فَفِي كلّ أَرْبَعِينَ دِرْهَمًا دِرْهَمٌ، وَلَيْسَ فِيهَا دُونَ خَمْسِ أَوَاقٍ شَيْءٌ، وَفِي كلِّ أَرْبَعِينَ دِينَارًا دِينَارٌ. وإنَّ الصَّدَقَةَ لَا تَحِلُّ لِمُحَمَّدٍ وَلَا لأَهْلِ بَيْتِهِ، وَإِنَّمَا هِيَ الزَّكَاةُ تُزَكَّى بِهَا أَنْفُسُهُمْ فِي فُقَرَاءِ الْمُؤْمِنِينَ، أَوْ فِي سَبِيلِ اللَّهِ. وَلَيْسَ فِي رَقِيقٍ وَلَا مَزْرَعَةٍ وَلَا عُمَّالِهَا شَيْءٌ، إِذَا كَانَتْ تُؤَدَّى صَدَقَتُهَا مِنَ الْعُشْرِ. وَلَيْسَ فِي عَبْدِ الْمُسْلِمِ وَلَا فَرَسِهِ شَيْءٌ. وإنّ أَكْبَرَ الْكَبَائِرِ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ الإِشْرَاكُ بِاللهِ، وَقَتْلُ النَّفْسِ الْمُؤْمِنَةِ بِغَيْرِ الْحَقِّ، وَالْفِرَارُ فِي سَبِيلِ اللَّهِ يَوْمَ الزَّحْفِ، وَعُقُوقُ الْوَالِدَيْنِ، وَرَمْيُ الْمُحْصَنَةِ، وَتَعَلُّمُ السِّحْرِ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ. وإنّ الْعُمْرَةَ الْحَجُّ الأَصْغَرُ.","وَلا يَمَسُّ الْقُرْآنَ إِلا طَاهِرٌ.","وَلَا طَلَاقَ قَبْلَ إِمْلَاكٍ، وَلَا عِتْقَ حَتَّى يُبْتَاعَ.","وَلَا يُصَلِّيَنَّ أَحَدُكُمْ فِي ثَوْبٍ وَاحِدٍ لَيْسَ عَلَى مَنْكِبِهِ مِنْهُ شَيْءٌ، وَلَا يَحْتَبِيَنَّ فِي ثَوْبٍ وَاحِدٍ لَيْسَ بَيْنَهُ وَبَيْنَ السَّمَاءِ شَيْءٌ، وَلَا يُصَلِّيَنَّ أَحَدُكُمْ فِي ثَوْبٍ وَاحِدٍ وَشِقُّهُ بَادٍ. وَلَا يُصَلِّيَنَّ أَحَدُكُمْ عَاقِصًا شَعْرَهُ.","وَإِنَّ مَنِ اعْتَبَطَ مُؤْمِنًا قَتْلًا عَنْ بَيِّنَةٍ، فَهُوَ قَوَدٌ إِلَاّ أَنْ يَرْضَى أَوْلِيَاءُ الْمَقْتُولِ.","وَأَنَّ فِي النَّفْسِ الدِّيَةُ مِائَةً مِنَ الإِبِلِ، وَفِي الأَنْفِ إِذَا أُوعِبَ جَدْعُهُ الدِّيَةُ ، وَفِي اللِّسَانِ الدِّيَةُ، وَفِي الشَّفَتَيْنِ الدِّيَةُ، وَفِي الْبَيْضَتَيْنِ الدِّيَةُ، وَفِي الذَّكَرِ الدِّيَةُ، وَفِي الصُّلْبِ الدِّيَةُ، وَفِي الْعَيْنَيْنِ الدِّيَةُ، وَفِي الرِّجْلِ الْوَاحِدَةِ نِصْفُ الدِّيَةِ، وَفِي الْمَأْمُومَةِ ثُلُثُ الدِّيَةِ، وَفِي الْجَائِفَةِ ثُلُثُ الدِّيَةِ، وَفِي الْمُنَقِّلَةِ خَمْسَ عَشَرَةَ مِنَ الإِبِلِ، وَفِي كُلِّ أُصْبُعٍ مِنْ الأصابع من الْيَدِ وَالرِّجْلِ عَشْرٌ مِنَ الإِبِلِ، وَفِي السِّنِّ خَمْسٌ مِنَ الإِبِلِ، وَفِي الْمُوضِحَةِ خَمْسٌ مِنَ الإِبِلِ، وَأَنَّ الرَّجُلَ يُقْتَلُ بِالْمَرْأَةِ، وَعَلَى أَهْلِ الذَّهَبِ أَلْفُ دِينَارٍ .."],"takhrij":"صحيح وجادة: رواه ابن حبان (6559) - واللّفظ له -، والحاكم (1447)، والبيهقيّ (7255) مطوّلاً.","grade":"صحيح وجادة","chapter_ar":"باب زكاة الإبل","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic by transmitted manuscript form: Narrated by Ibn Hibban (6559) — and this is his wording — as well as al-Hakim (1447) and al-Bayhaqi (4/89).","chapter_en":"The Zakat of Camels","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Bakr ibn Muhammad ibn ‘Amr ibn Hazm narrated from his father, from his grandfather, that the Messenger of Allah ﷺ wrote to the people of Yemen a document containing the prescribed obligations, the established practices, and the blood-money rulings, and he sent it with ‘Amr ibn Hazm. It was read to the people of Yemen, and this is its text: “From Muhammad the Prophet ﷺ to Shurahbil ibn ‘Abd Kulal, al-Harith ibn ‘Abd Kulal, Nu‘aym ibn ‘Abd Kulal, and the chiefs of Dhu Ru‘ayn, Ma‘afir, and Hamdan. To proceed: Your messenger has returned, and you have been given from the war booty the fifth belonging to Allah. Also included is what Allah has prescribed upon the believers: one tenth on agricultural produce. Whatever is watered by rain, or flows naturally, or grows by natural moisture, then one tenth is due on it when it reaches five wasqs. And whatever is watered by lifting water or by irrigation equipment, then half of one tenth is due when it reaches five wasqs. For every five grazing camels, one sheep is due until they reach twenty-four. If they increase by one over twenty-four, then one she-camel in her second year is due. If such a camel is not found, then a male camel in its third year is due until they reach thirty-five. If they increase beyond thirty-five, then one she-camel in her third year is due until forty-five. If they increase beyond forty-five, then one she-camel in her fourth year, fit for breeding, is due until sixty. If they increase by one over sixty, then one she-camel in her fifth year is due until seventy-five. If they increase by one over seventy-five, then two she-camels in their third year are due until ninety. If they increase by one over ninety, then two she-camels in their fourth year, fit for breeding, are due until one hundred and twenty. Whatever is more than that, then for every forty there is one she-camel in her third year due, and for every fifty there is one she-camel in her fourth year, fit for breeding, due. And for every thirty cattle, one yearling calf, male or female, is due; and for every forty cattle, one cow is due. For every forty grazing sheep, one sheep is due until they reach one hundred and twenty. If they increase by one over one hundred and twenty, then two sheep are due until they reach two hundred. If they increase by one, then three sheep are due until they reach three hundred. Whatever is more than that, then for every hundred there is one sheep due. An aged animal, an emaciated animal, one with a defect, or a breeding ram is not to be taken in charity. Separate herds are not to be combined, and combined herds are not to be separated, out of fear of charity. Whatever is taken from two mixed partners, then they are to settle it equally between themselves. For every five awqiyahs of silver, five dirhams are due. Whatever is more than that, then for every forty dirhams, one dirham is due. There is nothing due on less than five awqiyahs of silver. And for every forty dinars, one dinar is due. The charity is not lawful for Muhammad ﷺ nor for the people of his household. Rather, it is the zakat by which they purify themselves, and it is to be given to the poor among the believers or in the path of Allah. There is nothing due on slaves, nor on cultivated land, nor on its workers, if its due charity from the one tenth has already been paid. There is nothing due on a Muslim’s slave or his horse. The greatest major sins before Allah on the Day of Resurrection are associating partners with Allah, killing a believing soul without right, fleeing from battle in the path of Allah on the day of combat, being undutiful to parents, falsely accusing a chaste woman, learning sorcery, consuming usury, and consuming the wealth of an orphan. ʿUmrah is the lesser pilgrimage. No one should touch the Qur’an except one who is in a state of purity. There is no divorce before marriage, and no freeing of a slave until one owns him.","None of you should pray in a single garment with nothing of it over his shoulder. And none should sit wrapped up in a single garment with nothing between him and the sky. And none of you should pray in a single garment while a side of his body is exposed. And none of you should pray with his hair tied up.","Whoever deliberately kills a believer with clear proof established against him is subject to legal retaliation, unless the family of the slain person accepts otherwise.","For a life, the blood money is one hundred camels. For the nose, if it is completely severed, the full blood money is due. For the tongue, the full blood money is due. For the two lips, the full blood money is due. For the two testicles, the full blood money is due. For the male organ, the full blood money is due. For the backbone, the full blood money is due. For the two eyes, the full blood money is due. For one leg, half of the blood money is due. For a head wound reaching the brain, one third of the blood money is due. For a wound penetrating into the body cavity, one third of the blood money is due. For a fracture that displaces the bone, fifteen camels are due. For each finger of the hands and feet, ten camels are due. For each tooth, five camels are due. For an exposing wound, five camels are due. And a man is to be killed in retaliation for a woman. And upon the people of gold is one thousand dinars.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح وجادة: رواه ابن حبان (6559) — واللفظ له —، والحاكم (1447)، والبيهقي (7255)."},{"num":3957,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ جَبَلٍ، قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ، وَأَمَرَنِي أَنْ آخُذَ مِنَ الْبَقَرِ مِنْ كُلِّ أَرْبَعِينَ مُسِنَّةً، وَمِنْ كُلِّ ثَلاَثِينَ تَبِيعًا أَوْ تَبِيعَةً."],"takhrij":"صحيح: رواه أبو داود (1576)، والترمذي (623)، والنسائي (2455)، وابن ماجه (1803) كلّهم من طرق عن الأعمش، عن شقيق، عن مسروق، عن معاذ بن جبل، فذكره.","grade":"صحيح","chapter_ar":"باب زكاة البقر","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1576), al-Tirmidhi (623), al-Nasa’i (2455), and Ibn Majah (1803).","chapter_en":"The Zakat of Cattle","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Mu‘adh ibn Jabal said: The Messenger of Allah ﷺ sent me to Yemen and commanded me to take, from cattle, one two-year-old cow for every forty, and one one-year-old calf, male or female, for every thirty."]},"buhuth":{"en":["And the phrase “one-year-old calf” means an animal that has entered its second year. It is called that because it has been weaned from its mother and follows her.","And the phrase “two-year-old cow” means one that has entered its third year, and it was also said: its fourth year."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1576)، والترمذي (623)، والنسائي (2455)، وابن ماجه (1803)."},{"num":3958,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أَنَّ أَبَا بَكْرٍ رَضِيَ الله عَنْهُ كَتَبَ لَهُ هَذَا الْكِتَابَ لَمَّا وَجَّهَهُ إِلَى الْبَحْرَيْنِ: بِسْمِ الله الرَّحْمَنِ الرَّحِيمِ هَذِهِ فَرِيضَةُ الصَّدَقَةِ الَّتِي فَرَضَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى المُسْلِمِينَ وَالَّتِي أَمَرَ الله بِهَا رَسُولَهُ فَمَنْ سُئِلَهَا مِنْ المُسْلِمِينَ عَلَى وَجْهِهَا فَلْيُعْطِهَا وَمَنْ سُئِلَ فَوْقَهَا فَلا يُعْطِ... .","وجاء فيه: وَفِي صَدَقَةِ الْغَنَمِ فِي سَائِمَتِهَا إِذَا كَانَتْ أَرْبَعِينَ إِلَى عِشْرِينَ وَمِائَةٍ شَاةٌ، فَإِذَا زَادَتْ عَلَى عِشْرِينَ وَمِائَةٍ إِلَى مِائَتَيْنِ شَاتَانِ، فَإِذَا زَادَتْ عَلَى مِائَتَيْنِ إِلَى ثَلاثِ مِائَةٍ فَفِيهَا ثَلاثُ شِيَاهٍ، فَإِذَا زَادَتْ عَلَى ثَلاثِ مِائَةٍ فَفِي كُلِّ مِائَةٍ شَاةٌ، فَإِذَا كَانَتْ سَائِمَةُ الرَّجُلِ نَاقِصَةً مِنْ أَرْبَعِينَ شَاةً وَاحِدَةً فَلَيْسَ فِيهَا صَدَقَةٌ إِلا أَنْ يَشَاءَ رَبُّهَا وَفِي الرِّقَّةِ رُبْعُ الْعُشْرِ، فَإِنْ لَمْ تَكُنْ إِلا تِسْعِينَ وَمِائَةً فَلَيْسَ فِيهَا شَيْءٌ إِلا أَنْ يَشَاءَ رَبُّهَا ."],"takhrij":"صحيح: رواه البخاريّ في الزّكاة (1454) عن محمد بن عبدالله بن المثنى الأنصاريّ، قال: حدثني أبي، قال: حدثني ثمامة بن عبدالله بن أنس، أنّ أنساً حدّثه، أنّ أبا بكر كتب له الكتاب، فذكره.","grade":"صحيح","chapter_ar":"باب زكاة الغنم","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1454).","chapter_en":"The Zakat of Sheep","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Anas narrated that Abu Bakr, may Allah be pleased with him, wrote this document for him when he sent him to Bahrain: “In the name of Allah, the Most Merciful, the Especially Merciful. This is the obligatory charity which the Messenger of Allah ﷺ made binding upon the Muslims, and which Allah commanded His Messenger with. Whoever among the Muslims is asked for it according to what is due must give it, and whoever is asked for more than that should not give it…” And in it came: “Regarding the charity due on grazing sheep: if they are from forty to one hundred and twenty, then one sheep is due. If they increase beyond one hundred and twenty up to two hundred, then two sheep are due. If they increase beyond two hundred up to three hundred, then three sheep are due. If they increase beyond three hundred, then for every hundred, one sheep is due. If a man’s grazing sheep are one short of forty, then no charity is due on them unless their owner wishes to give voluntarily. And regarding silver, one quarter of one tenth is due. If it is only one hundred and ninety, then nothing is due on it unless its owner wishes to give voluntarily.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1454)."},{"num":3959,"demo":false,"sanad":"","matn":["عَنْ أَنَسُ بْنُ مَالِكٍ قال: أَنَّ أَبَا بَكْرٍ لَمَّا استخلفه كَتَبَ لَهُ: بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، هَذِهِ فَرِيضَةُ الصَّدَقَةِ الَّتِي فَرَضَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى الْمُسْلِمِينَ الَّتِي أَمَرَ اللَّهُ بِهَا رَسُولَهُ فَذَكَرَ الْحَدِيثَ.","وقال فيه: لَا يَجْمَعُ بَيْنَ مُتَفَرِّقٍ، وَلَا يُفَرِّقُ بَيْنَ مُجْتَمِعٍ خَشْيَةَ الصَّدَقَةِ، وَمَا مِنْ خَلِيطَيْنِ فَهُمَا يَتَرَاجَعَانِ بَيْنَهُمَا بِالسَّوِيَّةِ ."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1451) عن محمد بن عبدالله، قال: حدّثني أبي، قال: حدّثني ثمامة، أنّ أنساً حدّثه، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الزَّجر عن الجمع بين المتفق والتفريق بين المجتمع في السوائم خيفة الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1451).","chapter_en":"The Prohibition of Combining Separate Herds or Separating Combined Herds Out of Fear of Zakat","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["From Anas: Abu Bakr, when he appointed him, wrote for him: “This is the obligatory charity which the Messenger of Allah ﷺ made binding upon the Muslims, which Allah commanded His Messenger with,” then he mentioned the hadith. And in it is: “Separate herds are not to be combined, and combined herds are not to be separated, out of fear of charity. And whatever belongs to two mixed partners, they are to settle it equally between themselves.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1451)."},{"num":3960,"demo":false,"sanad":"","matn":["عن سويد بن غفلة، قال: سرتُ أو قال: أخبرني من سار مع مصدّق النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فإذا في عهد رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنْ لا تَأْخُذَ مِنْ رَاضِعِ لَبَنٍ وَلا تَجْمَعَ بَيْنَ مُفْتَرِقٍ وَلَا تُفَرِّقَ بَيْنَ مُجْتَمِعٍ .","وكَانَ إِنَّمَا يَأْتِي الْمِيَاهَ حِينَ تَرِدُ الْغَنَمُ فَيَقُولُ أَدُّوا صَدَقَاتِ أَمْوَالِكُمْ قَالَ: فَعَمَدَ رَجُلٌ مِنْهُمْ إِلَى نَاقَةٍ كَوْمَاءَ. قَالَ: قُلْتُ يَا أَبَا صَالِحٍ مَا الْكَوْمَاءُ؟ قَالَ: عَظِيمَةُ السَّنَامِ. قَال: فَأَبَى أَنْ يَقْبَلَهَا، قَالَ: إِنِّي أُحِبُّ أَنْ تَأْخُذَ خَيْرَ إِبِلِي. قَالَ: فَأَبَى أَنْ يَقْبَلَهَا، قَالَ: فَخَطَمَ لَهُ أُخْرَى دُونَهَا، فَأَبَى أَنْ يَقْبَلَهَا، ثُمَّ خَطَمَ لَهُ أُخْرَى دُونَهَا. فَقَبِلَهَا وَقَالَ: إِنِّي آخِذُهَا وَأَخَــــــــافُ أَنْ يَجِدَ عَلَيَّ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لِي عَمَدْتَ إِلَى رَجُلٍ فَتَخَيَّرْتَ عَلَيْهِ إِبِلَهُ ."],"takhrij":"حسن: رواه أبو داود (1579)، والنسائيّ (2459) كلاهما من حديث هلال بن خبّاب، عن ميسرة أبي صالح، عن سويد بن غفلة، فذكره.","grade":"حسن","chapter_ar":"باب الزَّجر عن الجمع بين المتفق والتفريق بين المجتمع في السوائم خيفة الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1579) and al-Nasāʾī (2459).","chapter_en":"The Prohibition of Combining Separate Herds or Separating Combined Herds Out of Fear of Zakat","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Suwayd ibn Ghafalah said: I traveled—or he said: someone who traveled with the zakat collector of the Prophet ﷺ informed me—that in the written instructions of the Messenger of Allah ﷺ it stated: “Do not take a milk-suckling animal, do not combine separate herds, and do not separate a combined herd.” The collector would come to the watering places when the livestock arrived and say:","“Give the zakat due on your property.” A man among them then brought a large-humped she-camel. I asked: “O Abū Ṣāliḥ, what does kawmāʾ mean?” He replied: “A camel with a large hump.” The collector refused to accept it. The man said: “I would like you to take the best of my camels.” But he refused to accept it. Then he haltered another camel of lower quality, but the collector refused that one as well. Then he haltered another one below that in quality, and the collector accepted it, saying: “I will take this one, though I fear that the Messenger of Allah ﷺ may be displeased with me and say: ‘You went to a man and deliberately selected the choicest of his camels.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1579)، والنسائي (2459)."},{"num":3961,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيْسَ عَلَى الْمُسْلِمِ فِي عَبْدِهِ وَلاَ فِي فَرَسِهِ صَدَقَةٌ."],"takhrij":"متفق عليه: رواه مالك في الزكاة (37) عن عبدالله بن دينار، عن سليمان بن يسار، عن عراك بن مالك، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب لا زكاة في الخيل والرقيق","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (37), Muslim in the Book of Zakat (982), and al-Bukhari in the Book of Zakat (1463).","chapter_en":"There is no zakat on horses or slaves","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “A Muslim owes no charity on his slave or on his horse.”"]},"buhuth":{"en":["And in the version of Muslim: “There is no charity due on a slave except the charity of the breaking of the fast.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (37)، ومسلم (982)، والبخاري (1463)."},{"num":3962,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، عَلَيْهِ السَّلاَمُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَدْ عَفَوْتُ عَنِ الْخَيْلِ وَالرَّقِيقِ، فَهَاتُوا صَدَقَةَ الرِّقَةِ مِنْ كُلِّ أَرْبَعِينَ دِرْهَمًا دِرْهَمٌ وَلَيْسَ فِي تِسْعِينَ وَمِائَةٍ شَىْءٌ فَإِذَا بَلَغَتْ مِائَتَيْنِ فَفِيهَا خَمْسَةُ دَرَاهِمَ."],"takhrij":"حسن: رواه أبو داود (1574)، والترمذيّ (620) من حديث أبي عوانة، والنسائيّ (2478) من حديث الأعمش - كلاهما عن أبي إسحاق، عن عاصم بن ضمرة، عن علي، (هو ابن أبي طالب) فذكره.","grade":"حسن","chapter_ar":"باب لا زكاة في الخيل والرقيق","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1574), al-Tirmidhi (620), and al-Nasa’i (2478).","chapter_en":"There is no zakat on horses or slaves","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ said: “I have exempted horses and slaves. So give the charity due on silver: from every forty dirhams, one dirham. There is nothing due on one hundred and ninety. Once it reaches two hundred, then five dirhams are due.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3973],"tks":"حسن: رواه أبو داود (1574)، والترمذي (620)، والنسائي (2478)."},{"num":3963,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ صَاحِبِ ذَهَبٍ وَلا فِضَّةٍ لا يُؤَدِّي مِنْهَا حَقَّهَا إِلا إِذَا كَانَ يَوْمُ الْقِيَامَةِ صُفِّحَتْ لَهُ صَفَائِحُ مِنْ نَارٍ فَأُحْمِيَ عَلَيْهَا فِي نَارِ جَهَنَّمَ فَيُكْوَى بِهَا جَنْبُهُ وَجَبِينُهُ وَظَهْرُهُ كُلَّمَا بَرَدَتْ أُعِيدَتْ لَهُ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ حَتَّى يُقْضَى بَيْنَ الْعِبَادِ فَيَرَى سَبِيلَهُ إِمَّا إِلَى الجَنَّةِ وَإِمَّا إِلَى النَّارِ . قِيلَ يَا رَسُولَ الله، فَالإِبِلُ؟ قَالَ: وَلا صَاحِبُ إِبِلٍ لا يُؤَدِّي مِنْهَا حَقَّهَا - وَمِنْ حَقِّهَا حَلَبُهَا يَوْمَ وِرْدِهَا - إِلا إِذَا كَانَ يَوْمُ الْقِيَامَةِ بُطِحَ لَهَا بِقَاعٍ قَرْقَرٍ أَوْفَرَ مَا كَانَتْ لا يَفْقِدُ مِنْهَا فَصِيلا وَاحِدًا تَطَؤُهُ بِأَخْفَافِهَا وَتَعَضُّهُ بِأَفْوَاهِهَا كُلَّمَا مَرَّ عَلَيْهِ أُولاهَا رُدَّ عَلَيْهِ أُخْرَاهَا فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ حَتَّى يُقْضَى بَيْنَ الْعِبَادِ فَيَرَى سَبِيلَهُ إِمَّا إِلَى الجَنَّةِ وَإِمَّا إِلَى النَّارِ . قِيلَ: يَا رَسُولَ الله، فَالْبَقَرُ وَالْغَنَمُ؟ قَالَ: وَلا صَاحِبُ بَقَرٍ وَلا غَنَمٍ لا يُؤَدِّي مِنْهَا حَقَّهَا إِلا إِذَا كَانَ يَوْمُ الْقِيَامَةِ بُطِحَ لَهَا بِقَاعٍ قَرْقَرٍ لا يَفْقِدُ مِنْهَا شَيْئًا لَيْسَ فِيهَا عَقْصَاءُ وَلا جَلْحَاءُ وَلا عَضْبَاءُ تَنْطَحُهُ بِقُرُونِهَا وَتَطَؤُهُ بِأَظْلافِهَا كُلَّمَا مَرَّ عَلَيْهِ أُولاهَا رُدَّ عَلَيْهِ أُخْرَاهَا فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ حَتَّى يُقْضَى بَيْنَ الْعِبَادِ فَيَرَى سَبِيلَهُ إِمَّا إِلَى الجَنَّةِ وَإِمَّا إِلَى النَّارِ. قِيلَ: يَا رَسُولَ الله، فَالخَيْلُ؟ قَالَ: الخَيْلُ ثَلاثَةٌ هِيَ لِرَجُلٍ وِزْرٌ، وَهِيَ لِرَجُلٍ سِتْرٌ، وَهِيَ لِرَجُلٍ أَجْرٌ، فَأَمَّا الَّتِي هِيَ لَهُ وِزْرٌ فَرَجُلٌ رَبَطَهَا رِيَاءً وَفَخْرًا وَنِوَاءً عَلَى أَهْلِ الإِسْلامِ فَهِيَ لَهُ وِزْر،ٌ وَأَمَّا الَّتِي هِيَ لَهُ سِتْرٌ فَرَجُلٌ رَبَطَهَا فِي سَبِيلِ اللَّهِ ثُمَّ لَمْ يَنْسَ حَقَّ الله فِي ظُهُورِهَا وَلا رِقَابِهَا فَهِيَ لَهُ سِتْرٌ ."],"takhrij":"متفق عليه: رواه مسلم في الزكاة (987) عن سويد بن سعيد، حدّثنا حفص بن ميسرة الصّنعانيّ، عن زيد بن أسلم، أنّ أبا صالح ذكوان أخبره، أنه سمع أبا هريرة يقول: (فذكره).","grade":"متفق عليه","chapter_ar":"باب من قال: إن في الخيل صدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (987) and al-Bukhari (2371), and this wording is from Muslim.","chapter_en":"Those Who Said There Is Charity Due on Horses","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said, “There is no owner of gold or silver who does not pay what is due on it except that, on the Day of Resurrection, sheets of fire will be made for him, heated in the Fire of Hell, and his side, forehead, and back will be branded with them. Every time they cool down, they will be reheated for him during a day the length of which is fifty thousand years, until judgment is passed among the people and he sees his path, either to Paradise or to the Fire.” It was said, “O Messenger of Allah ﷺ, what about camels?” He said, “And no owner of camels who does not give their due — and part of their due is that they are milked on the day they come to water — except that on the Day of Resurrection he will be thrown down for them on a broad, level plain, with the herd as full as it ever was, not missing even a single young one. They will trample him with their hooves and bite him with their mouths. Every time the first of them passes over him, the last of them will be brought back over him again, during a day the length of which is fifty thousand years, until judgment is passed among the people and he sees his path, either to Paradise or to the Fire.” It was said, “O Messenger of Allah ﷺ, what about cattle and sheep?” He said, “And no owner of cattle or sheep who does not give their due except that on the Day of Resurrection he will be thrown down for them on a broad, level plain, not missing any of them. None of them will be twisted-horned, hornless, or broken-horned. They will gore him with their horns and trample him with their hooves. Every time the first of them passes over him, the last of them will be brought back over him again, during a day the length of which is fifty thousand years, until judgment is passed among the people and he sees his path, either to Paradise or to the Fire.” It was said, “O Messenger of Allah ﷺ, what about horses?” He said, “Horses are of three kinds: for one man they are a burden of sin, for another they are a shield, and for another they are a reward. As for the one for whom they are a burden of sin, he is a man who keeps them out of showing off, pride, and hostility against the people of Islam, so they are a burden of sin for him. As for the one for whom they are a shield, he is a man who keeps them in the path of Allah, then does not forget the right of Allah concerning their backs and their necks, so they are a protection for him. As for the one for whom they are a reward, he is a man who keeps them in the path of Allah for the people of Islam in a meadow or garden. Whatever they eat from that meadow or garden, good deeds are written for him equal to the number of what they eat. And good deeds are written for him equal to the number of their droppings and urine. If they break their tether and run over one hill or two hills, good deeds are written for him equal to the number of their tracks and droppings. And whenever their owner passes by a river and they drink from it, even though he did not intend to water them, good deeds are written for him equal to the number of what they drank.” It was said, “O Messenger of Allah ﷺ, what about donkeys?” He said, “Nothing has been revealed to me regarding donkeys except this all-encompassing verse: ‘So whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it.’” [al-Zalzalah 99:7–8]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (987)، والبخاري (2371)، واللفظ لمسلم."},{"num":3964,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ جَلَبَ وَلاَ جَنَبَ، وَلاَ تُؤْخَذُ صَدَقَاتُهُمْ إِلاَّ فِي دُورِهِمْ."],"takhrij":"حسن: رواه أبو داود (1591) عن قتيبة بن سعيد، حدّثنا ابن أبي عدي، عن ابن إسحاق، عن عمرو بن شعيب، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب النّهي عن الجلب عند أخذ الصّدقة من المواشي","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1591), authenticated by Ibn Khuzaymah (2280), and also by Ahmad (7024).","chapter_en":"The Prohibition of Driving Livestock to the Collector When Taking Charity","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather, from the Prophet, who said: “There is to be no driving of livestock in and no sending them from afar, and their charities are only to be taken in their own places.”"]},"buhuth":{"en":["Its meaning is: the livestock are to be assessed for charity in their own locations, and they are not to be driven to the collector.","And it also means: their owners are not to be made to bring them from far-off places. A man should not be at the far edge of the collection area and have the animals driven to him. Rather, they are taken where they are."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1591) وصححه ابن خزيمة (2280). وأحمد (7024)."},{"num":3965,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تُؤْخَذُ صَدَقَةُ أَهْلِ الْبَادِيَةِ عَلَى مِيَاهِهِمْ، وَبِأَفْنِيَتِهِمْ."],"takhrij":"حسن: رواه الطبرانيّ في \"الأوسط\" (مجمع البحرين 1360) عن محمد بن العباس المؤدّب، ثنا عبدالله بن صالح العجليّ، ثنا عبد الملك بن محمد بن أبي بكر، عن عبدالله بن أبي بكر، عن عمرو، عن عائشة، فذكرته.","grade":"حسن","chapter_ar":"باب النّهي عن الجلب عند أخذ الصّدقة من المواشي","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (Majma‘ al-Bahrayn, 1360).","chapter_en":"The Prohibition of Driving Livestock to the Collector When Taking Charity","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["The Mother of the Believers, ‘A’ishah, said: The Messenger of Allah ﷺ said, “The charities of the desert people are to be taken at their watering places and in their courtyards.”"]},"buhuth":{"en":["What is understood from the hadiths of this chapter is that the collector is the one who goes to the people who owe charity and takes it from them at their own watering places, because that is easier for the owners of livestock."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في “الأوسط” (مجمع البحرين 1360)."},{"num":3966,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ، قَالَ: غَدَوْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بعبدالله ابن أَبِي طَلْحَةَ يحنِّكه، فَوَافَيْتُهُ فِي يَدِهِ الْمِيسَمُ يَسِمُ إِبِلَ الصَّدَقَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1502)، ومسلم في اللباس (2119: 112) كلاهما من طريق الوليد بن مسلم، حدّثنا أبو عمرو الأوزاعيّ، حدثني إسحاق بن عبدالله بن أبي طلحة، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب وسم الأنعام من الصدقة والجزية","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1502), Muslim (2119).","chapter_en":"Branding livestock from charity and jizyah","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Malik said: I went early to the Messenger of Allah ﷺ with ʿAbdullah ibn Abi Talhah so that he could perform taḥnīk for him, and I found him holding the branding iron, branding the camels of charity."]},"buhuth":{"en":["Branding comes from the verb meaning to mark something by cauterizing it. The mīsam is the iron instrument used for branding."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1502)، ومسلم (2119: 112)."},{"num":3967,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَخٍ لِي يُحَنِّكُهُ، وَهْوَ فِي مِرْبَدٍ لَهُ، فَرَأَيْتُهُ يَسِمُ شَاةً. ـ حَسِبْتُهُ قَالَ: ـ فِي آذَانِهَا."],"takhrij":"متفق عليه: رواه البخاريّ في الذّبائح (5542)، ومسلم في اللباس (2119/111) كلاهما من حديث شعبة، عن هشام بن زيد، عن أنس، قال (فذكره). واللّفظ للبخاريّ، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب وسم الأنعام من الصدقة والجزية","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (5542), Muslim (2119), and this is the wording of al-Bukhari.","chapter_en":"Branding livestock from charity and jizyah","part_en":"Zakat","group_ar":"جموع أبواب زكاة الأنعام","group_en":"Compilation of chapters on the zakat of livestock","part_no":14,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Malik said: I entered upon the Prophet ﷺ with a brother of mine so that he could perform taḥnīk for him, while he was in an enclosure of his, and I saw him branding a sheep. I think he said: on its ears."]}},"tuhfa":{},"full":1,"dr":1,"rep":[14838],"tks":"متفق عليه: رواه البخاري (5542)، ومسلم (2119/111)، واللفظ للبخاري."},{"num":3968,"demo":false,"sanad":"","matn":["عن أنس، أنّ أبا بكر رضي الله عنه: كتب له هذا الكتاب لما وجهه إلى البحرين: هذه فريضة الصّدقة، فرض رسول الله صلى الله عليه وسلم على المسلمين. فذكر الكتاب بطوله وجاء فيه:","وَفِي الرِّقَةِ رُبْعُ الْعُشْرِ، فَإِنْ لَمْ تَكُنْ إِلاَّ تِسْعِينَ وَمِائَةً فَلَيْسَ فِيهَا شَىْءٌ إِلاَّ أَنْ يَشَاءَ رَبُّهَا .."],"takhrij":"صحيح: رواه البخاريّ في الزكاة (1454) عن محمد بن عبدالله بن المثنى الأنصاريّ، قال: حدثني أبي، قال: حدّثني ثمامة بن عبدالله بن أنس، أن أنساً حدّثه، فذكر الكتاب بطوله.","grade":"صحيح","chapter_ar":"باب ما جاء في نصاب الزكاة في الفضة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Bukhari (1454).","chapter_en":"What is reported regarding the zakat threshold for silver","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Anas reported that Abu Bakr, may Allah be pleased with him, wrote this letter for him when he sent him to Bahrain: “This is the obligation of charity that the Messenger of Allah ﷺ made obligatory upon the Muslims.” Then he mentioned the full document, and in it was:","“Regarding silver, one-quarter of one-tenth is due. If it is only one hundred and ninety, then nothing is due on it unless its owner wishes.”"]},"buhuth":{"en":["Riqqah means pure silver, whether minted into coins or not.","The phrase “if it is only one hundred and ninety” might make it sound as though zakat becomes due on anything above one hundred and ninety before reaching two hundred, but that is not the meaning. Ninety was mentioned because it is the last full ten before two hundred, to show that there is no zakat on anything less than two hundred. This is also proven by the hadith: “There is no charity due on less than five uqiyyahs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1454)."},{"num":3969,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لَيْسَ فِيمَا دُونَ خَمْسِ ذَوْدٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسَةِ أَوَاقٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ صَدَقَةٌ ."],"takhrij":"متفق عليه: رواه مالك في الزكاة (1) عن عمرو بن يحيى المازني، عن أبيه، أنه سمع أبا سعيد الخدريّ يقول (فذكر الحديث).","grade":"متفق عليه","chapter_ar":"باب ما جاء في نصاب الزكاة في الفضة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: Malik (1), al-Bukhari (1447), Muslim (979).","chapter_en":"What is reported regarding the zakat threshold for silver","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “There is no charity due on fewer than five camels, no charity due on fewer than five uqiyyahs, and no charity due on fewer than five awsuq.”"]},"buhuth":{"en":["The phrase “five camels” uses the word dhawd, which in Arabic refers to a small number of camels, usually from three to ten.","The phrase “five uqiyyahs” is also narrated as awāqī, and both are correct.","The legal uqiyyah is agreed upon by hadith scholars, jurists, and language scholars to equal forty dirhams, which means that the nisab of silver is two hundred dirhams. In present-day measure, that is about six hundred grams. If it is less than that, then no zakat is due on it.","The phrase “five awsuq” means five wasqs. One wasq equals sixty sāʿs, so five awsuq equal three hundred sāʿs.","The Prophetic sāʿ is approximately 2.5 kilograms, so five awsuq weigh about 750 kilograms."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1)، والبخاري (1447)، ومسلم (979)."},{"num":3970,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  لَيْسَ فِيمَا دُونَ خَمْسِ أَوَاقٍ مِنَ الْوَرِقِ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسِ ذَوْدٍ مِنَ الْإِبِلِ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ مِنَ التَّمْرِ صَدَقَةٌ."],"takhrij":"صحيح: رواه مسلم في الزكاة (980) من طرق عن ابن وهب، أخبرني عياض بن عبدالله، عن أبي الزبير، عن جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نصاب الزكاة في الفضة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Muslim (980).","chapter_en":"What is reported regarding the zakat threshold for silver","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn ʿAbdullah reported that the Messenger of Allah ﷺ said: “There is no charity due on less than five uqiyyahs of silver, no charity due on less than five camels, and no charity due on less than five awsuq of dates.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (980)."},{"num":3971,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ صَدَقَةٌ، وَلَا فِيمَا دُونَ خَمْسِ أَوَاقٍ صَدَقَةٌ، وَلَا فِيمَا دُونَ خَمْسِ ذَوْدٍ صَدَقَةٌ."],"takhrij":"صحيح: رواه الإمام أحمد (9221، 9232) من وجهين عن عبدالله بن المبارك، قال: أخبرنا معمر، قال: حدّثني سُهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في نصاب الزكاة في الفضة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Aḥmad (9221, 9232).","chapter_en":"What is reported regarding the zakat threshold for silver","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “There is no charity due on less than five awsuq, no charity due on less than five uqiyyahs, and no charity due on less than five camels.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه الإمام أحمد (9221، 9232)."},{"num":3972,"demo":false,"sanad":"","matn":["عن أَبِي رَافِعٍأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ رَجُلًا مَنْ بُنِيَ مَخْزُومٍ عَلَى الصَّدَقَةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسَاقٍ صَدَقَةٌ، وَلَا فِيمَا دُونَ خَمْسِ ذَوْدٍ صَدَقَةٌ، وَلَا فِيمَا دُونَ خَمْسِ أَوَاقٍ صَدَقَةٌ."],"takhrij":"صحيح: رواه الطبرانيّ في \"الكبير\" (929) عن الحسين بن إسحاق التّستريّ، ويحيى بن زكريا السّاجيّ، قالا: ثنا موسى بن عبدالرحمن المسروقي، ثنا أبو أسامة، ثنا شعبة، عن الحكم، عن ابن أبي رافع، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نصاب الزكاة في الفضة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: al-Ṭabarani in al-Kabir (1/295).","chapter_en":"What is reported regarding the zakat threshold for silver","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Rafiʿ reported that the Messenger of Allah ﷺ sent a man from Banu Makhzum to collect charity, and the Messenger of Allah ﷺ said: “There is no charity due on less than five awsuq, no charity due on less than five camels, and no charity due on less than five uqiyyahs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في “الكبير” (929)."},{"num":3973,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، عَلَيْهِ السَّلاَمُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَدْ عَفَوْتُ عَنِ الْخَيْلِ وَالرَّقِيقِ، فَهَاتُوا صَدَقَةَ الرِّقَةِ مِنْ كُلِّ أَرْبَعِينَ دِرْهَمًا دِرْهَمٌ وَلَيْسَ فِي تِسْعِينَ وَمِائَةٍ شَىْءٌ فَإِذَا بَلَغَتْ مِائَتَيْنِ فَفِيهَا خَمْسَةُ دَرَاهِمَ."],"takhrij":"حسن: رواه أبو داود (1574)، والترمذيّ (620) من حديث أبي عوانة، والنسائيّ (2478)، وابن ماجه (1790)، والإمام أحمد (711، 984) كلّهم من طرق عن أبي إسحاق، عن عاصم بن ضمرة - والحارث في بعض طرقه -، كلاهما عن علي فذكره. وصحّحه ابن خزيمة (2284).","grade":"حسن","chapter_ar":"باب ما جاء في نصاب الزكاة في الفضة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1574), al-Tirmidhi (620), al-Nasa’i (2478), Ibn Majah (1790), and Ahmad (711, 984).","chapter_en":"What is reported regarding the zakat threshold for silver","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Messenger of Allah ﷺ said: “I have excused horses and slaves, so bring the charity due on silver: from every forty dirhams, one dirham. There is nothing due on one hundred and ninety, but when it reaches two hundred, then five dirhams are due on it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3962],"tks":"حسن: رواه أبو داود (1574)، والترمذي (620)، والنسائي (2478)، وابن ماجه (1790)، وأحمد (711، 984)."},{"num":3974,"demo":false,"sanad":"","matn":["عَنْ بَهْزِ بْنِ حَكِيمٍ، عَنْ أَبِيهِ، عَنْ جدّه، أنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فِي كلّ خَمْسِ ذَوْدٍ سَائِمَةٍ صَدَقَةٌ ."],"takhrij":"حسن: رواه الطبراني في \"المعجم الأوسط\" (مجمع البحرين 1353) عن محمد بن جعفر بن سام، ثنا الزبير بن بكار، ثنا عبد المجيد بن عبد العزيز، عن معمر، عن الزهري، قال: حدثني رجل من بني قشير - يقال له بهز بن حكيم - عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في نصاب الزكاة في الفضة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarani in al-Muʿjam al-Awsaṭ (Majmaʿ al-Baḥrayn 1353).","chapter_en":"What is reported regarding the zakat threshold for silver","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Bahz ibn Hakim narrated from his father, from his grandfather, that the Prophet ﷺ said: “For every five grazing camels, charity is due.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في “المعجم الأوسط” (مجمع البحرين 1353)."},{"num":3975,"demo":false,"sanad":"","matn":["عن محمد بن عبدالرحمن الأنصاريّ قال: إنّ في كتـاب رسول الله وفي كتاب عمر في الصدقة: أنّ الذهب لا يؤخذ منه شيء حتى يبلغ عشرين ديناراً، فإذا بلغ عشرين ديناراً ففيه نصف دينار. والوَرِق لا يؤخذ منه شيء حتى يبلغ مائتي درهم، فإذا بلغ مائتي درهم ففيها خمسة دراهم ."],"takhrij":"صحيح: رواه أبو عبيد في كتاب \"الأموال\" (ص559) عن يزيد بن هارون، عن حبيب بن أبي حبيب، عن عمرو بن هرم، عن محمد بن عبدالرحمن الأنصاريّ قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نصاب الذهب","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu ʿUbayd in al-Amwal (p. 559).","chapter_en":"What is reported regarding the nisab of gold","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Muhammad ibn ʿAbd al-Rahman al-Ansari said: In the document of the Messenger of Allah ﷺ and in the document of ʿUmar regarding charity, it says: “Nothing is taken from gold until it reaches twenty dinars. When it reaches twenty dinars, then half a dinar is due on it. And nothing is taken from silver until it reaches two hundred dirhams. When it reaches two hundred dirhams, then five dirhams are due on it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو عبيد في كتاب “الأموال” (ص 559)."},{"num":3976,"demo":false,"sanad":"","matn":["عن عليٍّ، عن النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قال: فَإِذَا كَانَتْ لَكَ مِائَتَا دِرْهَمٍ وَحَالَ عَلَيْهَا الحَوْلُ فَفِيهَا خَمْسَةُ دَرَاهِمَ وَلَيْسَ عَلَيْكَ شَيْءٌ يَعْنِي فِي الذَّهَبِ حَتَّى يَكُونَ لَكَ عِشْرُونَ دِينَارًا فَإِذَا كَانَ لَكَ عِشْرُونَ دِينَارًا وَحَالَ عَلَيْهَا الحَوْلُ فَفِيهَا نِصْفُ دِينَارٍ فَمَا زَادَ فَبِحِسَابِ ذَلِكَ ."],"takhrij":"حسن: رواه أبو داود (1573) عن سليمان بن داود المهري، أخبرنا ابن وهب، أخبرني جرير بن حازم - وسمّى آخر -، عن أبي إسحاق، عن عاصم اين ضمرة، والحارث الأعور، عن علي بن أبي طالب، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في نصاب الذهب","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Abu Dawud (1573).","chapter_en":"What is reported regarding the nisab of gold","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["ʿAli ibn Abi Talib reported from the Prophet ﷺ that he said: “If you have two hundred dirhams and a year passes over them, then five dirhams are due on them. And nothing is due on you in gold until you have twenty dinars. If you have twenty dinars and a year passes over them, then half a dinar is due on them. Whatever is more than that is according to this calculation.”"]},"buhuth":{"en":["The nisab of gold is twenty dinars, which is about 85 grams today, and it is also said to be about 92 grams.","The nisab of silver is two hundred dirhams, which is about 595 grams today.","Whoever has paper currency should assess it according to silver, because that is more beneficial for the poor. If its value reaches the nisab of silver and a full year passes over it, then zakat becomes obligatory on it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1573)."},{"num":3977,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فِي الرِّكَازِ الْخُمُسُ."],"takhrij":"متفق عليه: رواه الإمام مالك في الزكاة (9) عن ابن شهاب، عن سعيد ابن المسيب - وعن أبي سلمة بن عبدالرحمن، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب زكاة الركاز","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: Malik (9), al-Bukhari (1499), and Muslim (1710).","chapter_en":"Zakat on buried treasure","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “On buried treasure, one-fifth is due.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (9)، والبخاري (1499)، ومسلم (1710)."},{"num":3978,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ اللُّقَطَةِ فَقَالَ: مَا كَانَ فِي طَرِيقٍ مَأْتِيٍّ، أَوْ فِي قَرْيَةٍ عَامِرَةٍ فَعَرِّفْهَا سَنَةً، فَإِنْ جَاءَ صَاحِبُهَا وَإِلاَّ فَلَكَ، وَمَا لَمْ يَكُنْ فِي طَرِيقٍ مَأْتِيٍّ وَلاَ فِي قَرْيَةٍ عَامِرَةٍ فَفِيهِ وَفِي الرِّكَازِ الْخُمْسُ."],"takhrij":"حسن: رواه النسائيّ (2494) عن قتيبة، وأبو داود (1712) عن مسدّد، كلاهما عن أبي عوانة، عن عبيدالله بن الأخنس، عن عمرو بن شعيب، بإسناده، فذكره واللّفظ للنسائيّ.","grade":"حسن","chapter_ar":"باب زكاة الركاز","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (2494) and Abu Dawud (1712), and this is the wording of al-Nasa’i.","chapter_en":"Zakat on buried treasure","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ was asked about found property, and he said: “Whatever is found on a traveled road or in an inhabited village, announce it for one year. If its owner comes, then give it to him; otherwise it is yours. But whatever is not found on a traveled road nor in an inhabited village, then one-fifth is due on it and on buried treasure.”"]},"buhuth":{"en":["The phrase “a traveled road” means a road that people use.","Rikaz means pre-Islamic treasure buried in the ground. One-fifth is due on it because of its great benefit and the ease of obtaining it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2494)، وأبو داود (1712)، واللفظ للنسائي."},{"num":3979,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: السَّائِبَةُ، وقَالَ خَلَفُ بْنُ الْوَلِيدِ: السَّائِمَةُ - جُبَارٌ، وَالْجُبُّ جُبَارٌ، وَالْمَعْدِنُ جُبَارٌ، وَفِي الرِّكَازِ الْخُمُسُ.","قَالَ الشَّعْبِيُّ: الرِّكَازُ: الْكَنْزُ الْعَادِيُّ."],"takhrij":"حسن: رواه الإمام أحمد (14810، 14592) من طريقين عن عباد بن عباد، عن مجالد، عن الشعبي، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب زكاة الركاز","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (14592, 14810) and al-Bazzar in Kashf al-Astar (894).","chapter_en":"Zakat on buried treasure","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “An unattended animal — and Khalaf ibn al-Walīd said: a grazing animal — is without liability; a well is without liability; a mine is without liability; and on buried treasure one-fifth is due.”","Al-Shaʿbi said: Rikaz means ancient buried treasure."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (14592، 14810)، والبزار “كشف الأستار” (894)."},{"num":3980,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  تَصَدَّقْنَ يَا مَعْشَرَ النِّسَاءِ، وَلَوْ مِنْ حُلِيِّكُنَّ."],"takhrij":"متفق عليه: رواه البخاريّ في الزّكاة (1466)، ومسلم في الزّكاة (1000) كلاهما من حديث الأعمش، عن أبي وائل، عن عمرو بن الحارث، عن زينب امرأة عبدالله، فذكرته في حديث طويل، وهو مذكور في موضعه.","grade":"متفق عليه","chapter_ar":"باب ليس في الحلي زكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1466) and Muslim (1000).","chapter_en":"No zakat on jewelry","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Zaynab, the wife of ʿAbdullah, reported that the Messenger of Allah ﷺ said: “Give charity, O women, even if it is from your jewelry.”"]},"buhuth":{"en":["Ibn al-ʿArabi said: The apparent meaning of this hadith indicates that there is no zakat on jewelry, because the Prophet ﷺ encouraged voluntary charity from it. If zakat were obligatory on it, he would not have used it as an example of voluntary charity.","Al-Tirmidhi said: Scholars differed on this issue:","Some Companions and Followers held that zakat is due on gold and silver jewelry, including Sufyan al-Thawri and ʿAbdullah ibn al-Mubarak.","Others among the Companions said there is no zakat on jewelry, including Ibn ʿUmar, ʿA’ishah, Jabir, and Anas; and this is the view of Malik, al-Shafiʿi, Ahmad, and Ishaq."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1466)، ومسلم (1000)."},{"num":3981,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جدّه: أَنَّ امْرَأَةً أَتَتْ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهَا ابْنَةٌ لَهَا، وَفِي يَدِ ابْنَتِهَا مَسَكَتَانِ غَلِيظَتَانِ مِنْ ذَهَبٍ، فَقَالَ لَهَا: أَتُعْطِينَ زَكَاةَ هَذَا؟ . قَالَتْ: لا. قَالَ: أَيَسُرُّكِ أَنْ يُسَوِّرَكِ الله بِهِمَا يَوْمَ الْقِيَامَةِ سِوَارَيْنِ مِنْ نَارٍ؟! . قَــالَ: فَخَلَعَتْهُمَا فَأَلْقَتْهُمَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَتْ:هُمَا لله عَزَّ وَجَلَّ وَلِرَسُولِهِ."],"takhrij":"حسن: رواه أبو داود (1563)، والنسائي (2481) كلاهما من طريق خالد بن الحارث، عن حسين، عن عمرو بن شعيب، عن أبيه، عن جدّه، قال: فذكره.","grade":"حسن","chapter_ar":"باب من قال: في الحلي زكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Abu Dawud (1563) and al-Nasa’i (2481).","chapter_en":"Those who say zakat is due on jewelry","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that a woman came to the Messenger of Allah ﷺ with her daughter, who was wearing two thick gold bracelets. He said: “Do you pay zakat on this?” She said: No. He said: “Would you like Allah to place on you two bracelets of fire on the Day of Judgment?” So she removed them and gave them to the Prophet ﷺ, saying: They are for Allah, Mighty and Majestic, and His Messenger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1563)، والنسائي (2481)."},{"num":3982,"demo":false,"sanad":"","matn":["عن عبدالله بن شدّاد بن الهاد أنه قال: دَخَلْنَا عَلَى عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: دَخَلَ عَلَيَّ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَأَى فِي يَدَيَّ فَتَخَاتٍ مِنْ وَرِقٍ فَقَالَ: مَا هَذَا يَا عَائِشَةُ؟ . فَقُلْتُ: صَنَعْتُهُنَّ أَتَزَيَّنُ لَكَ يَا رَسُولَ الله. قَالَ: أَتُؤَدِّينَ زَكَاتَهُنَّ . قُلْتُ: لا أَوْ مَا شَاءَ الله. قَالَ: هُوَ حَسْبُكِ مِنْ النَّارِ ."],"takhrij":"حسن: رواه أبو داود (1565) عن محمد بن إدريس الرّازيّ، حدّثنا عمرو بن الرّبيع بن طارق، حدّثنا يحيى بن أيوب، عن عبيدالله بن أبي جعفر، أن محمّد بن عمرو بن عطاء أخبره، عن عبدالله بن شدّاد بن الهاد، فذكره.","grade":"حسن","chapter_ar":"باب من قال: في الحلي زكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Abu Dawud (1565).","chapter_en":"Those who say zakat is due on jewelry","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn Shaddad reported: We entered upon ʿAisha, the wife of the Prophet ﷺ, and she said: The Messenger of Allah ﷺ came to me and saw silver rings in my hand. He said: “What is this, O Aisha?” I said: I made them to adorn myself for you. He said: “Do you give their zakat?” I said: No, or as Allah wills. He said: “That is enough to lead you to the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1565)."},{"num":3983,"demo":false,"sanad":"","matn":["عن أمّ سلمة:كُنْتُ أَلْبَسُ أَوْضَاحًا مِنْ ذَهَبٍ فَقُلْتُ: يَا رَسُولَ الله أَكَنْزٌ هُوَ؟ فَقَالَ: مَا بَلَغَ أَنْ تُؤَدَّى زَكَاتُهُ فَزُكِّيَ فَلَيْسَ بِكَنْزٍ ."],"takhrij":"حسن: رواه أبو داود (1564) عن محمد بن عيسى، حدّثنا عتّاب - يعني ابن بشير -، عن ثابت بن عجلان، عن عطاء، عن أمّ سلمة، فذكرته.","grade":"حسن","chapter_ar":"باب من قال: في الحلي زكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: Abu Dawud (1564).","chapter_en":"Those who say zakat is due on jewelry","part_en":"Zakat","group_ar":"جموع الأبواب فيما جاء في زكاة المعادن من الذهب والفضة","group_en":"Compilation of chapters on zakat on metals, gold, and silver","part_no":14,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Umm Salamah said: I used to wear gold jewelry and asked: O Messenger of Allah ﷺ, is this considered hoarded wealth? He said: “Whatever reaches the amount on which zakat is due and its zakat is paid is not considered hoarded wealth.”"]},"buhuth":{"en":["Scholars differed regarding zakat on jewelry:","Those who say it is obligatory rely on the warning hadiths.","Those who say it is not obligatory view jewelry as personal use items like household goods.","Conclusion: The safer opinion is to pay zakat on it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1564)."},{"num":3984,"demo":false,"sanad":"","matn":["عن ابن عمر، عن النبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أنه قال: فِيمَا سَقَتْ السَّمَاءُ وَالْعُيُونُ أَوْ كَانَ عَثَرِيًّا الْعُشْرُ وَمَا سُقِيَ بِالنَّضْحِ نِصْفُ الْعُشْرِ ."],"takhrij":"صحيح: رواه البخاريّ في الزّكاة (1483) عن سعيد بن أبي مريم، حدثنا عبدالله بن وهب، قال: أخبرني يونس بن يزيد، عن الزهريّ، عن سالم بن عبدالله، عن أبيه رضي الله عنه، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب زكاة الحرث والزرع","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1483).","chapter_en":"Zakat on cultivated land and crops","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿUmar reported that the Prophet ﷺ said: “Whatever is watered by the sky, springs, or is naturally watered through its roots, then one-tenth is due. And whatever is watered by manual irrigation, then half of one-tenth is due.”"]},"buhuth":{"en":["And in some routes of the hadith:","“Whatever is watered by the sky, rivers, and springs, or is naturally watered, then one-tenth is due. And whatever is watered by water-wheels or manual irrigation, then half of one-tenth is due.”","Narrated by Abu Dawud (1596) and others.","The phrase “or is naturally watered” refers to crops that drink through their roots without direct irrigation. This includes what takes water from rivers without expense, or trees planted where underground water is close enough for roots to reach it, so that irrigation is unnecessary. See: Fath al-Bari (3/349).","The phrase “baʿl” was explained by Abu Dawud from Wakiʿ as that which grows from rainwater. Al-Nadr ibn Shumayl said: it means rainwater. In short, it refers to what drinks through its roots without irrigation effort.","“Al-nadḥ” means irrigation by drawing water with ropes.","What is understood from this is that the Prophet ﷺ made the zakat larger for crops whose cost is light and whose benefit is greater, as an ease for the poor, and made it smaller for crops whose cost is high, as a mercy to the owners of wealth.","“Al-sawani” is the plural of saniyah, meaning a camel used to draw water."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1483)."},{"num":3985,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عبدالله أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: فِيمَا سَقَتِ الْأَنْهَارُ وَالْغَيْمُ الْعُشُورُ، وَفِيمَا سُقي بِالسَّانِيَةِ نِصْفُ الْعُشْرِ ."],"takhrij":"صحيح: رواه مسلم في الزكاة (981) من طرق عن ابن وهب، عن عمرو بن الحارث، أنّ أبا الزّبير حدّثه أنّه سمع جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب زكاة الحرث والزرع","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (981).","chapter_en":"Zakat on cultivated land and crops","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn ʿAbdullah reported that he heard the Prophet ﷺ say: “In whatever is watered by rivers and rainclouds, tenths are due, and in whatever is watered by the water-drawing camel, half of one-tenth is due.”"]},"buhuth":{"en":["The phrase “tenths are due” means one-tenth.","And “clouds” here means rain."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (981)."},{"num":3986,"demo":false,"sanad":"","matn":["عن معاذ بن جبل، قال: بَعَثَنِي رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  إِلَى الْيَمَنِ وَأَمَرَنِي أَنْ آخُذَ مِمَّا سَقَت السَّمَاءُ وَمَا سُقِيَ بَعْلا الْعُشْرَ، وَمَا سُقِيَ بِالدَّوَالِي نِصْفَ الْعُشْرِ."],"takhrij":"حسن: رواه ابن ماجه (1818)، والنسائي (2492) كلاهما من حديث أبي بكر بن عياش، عن عاصم بن أبي النّجود، عن أبي وائل، عن مسروق، عن معاذ بن جبل، فذكره.","grade":"حسن","chapter_ar":"باب زكاة الحرث والزرع","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Majah (1818) and al-Nasa’i (2492).","chapter_en":"Zakat on cultivated land and crops","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Muʿadh ibn Jabal said: The Messenger of Allah ﷺ sent me to Yemen and ordered me to take: “One-tenth from what is watered by rain and what is naturally watered, and half of one-tenth from what is watered by irrigation devices.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1818)، والنسائي (2492)."},{"num":3987,"demo":false,"sanad":"","matn":["عَنْ مُوسَى بْنِ طَلْحَةَ، قَالَ: عِنْدَنَا كِتَابُ مُعَاذٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ إِنَّمَا أَخَذَ الصَّدَقَةَ مِنَ الْحِنْطَةِ وَالشَّعِيرِ وَالزَّبِيبِ وَالتَّمْرِ."],"takhrij":"صحيح: رواه أحمد (21989) عن عبدالرحمن بن مهدي، عن سفيان، عن عمرو بن عثمان -يعني ابن موهب، عن موسى بن طلحة، قال (فذكره).","grade":"صحيح","chapter_ar":"باب ليس في الخضروات والفواكه زكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (21989).","chapter_en":"There is no zakat on vegetables and fruits","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Musa ibn Talhah said: We have the document of Muʿadh from the Prophet ﷺ stating: “He only took zakat from wheat, barley, raisins, and dates.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (21989)."},{"num":3988,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، وَمُعَاذِ بْنِ جَبَلٍ، حِينَ بَعَثَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ يُعَلِّمَانِ النَّاسَ أَمْرَ دِينِهِمْ: لَا تَأْخُذُوا الصَّدَقَةَ إِلَّا مِنْ هَذِهِ الْأَرْبَعَةِ: الشَّعِيرِ، وَالْحِنْطَةِ، وَالزَّبِيبِ، وَالتَّمْرِ."],"takhrij":"حسن: رواه الدّارقطنيّ (1921)، والحاكم (1459)، والبيهقيّ (7451) كلّهم من حديث أبي حذيفة، حدّثنا سفيان، عن طلحة بن يحيى، عن أبي بردة، عن أبي موسى ومعاذ بن جبل، فذكراه.","grade":"حسن","chapter_ar":"باب ليس في الخضروات والفواكه زكاة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Daraqutni (1921), al-Hakim (1459), and al-Bayhaqi (4/125).","chapter_en":"There is no zakat on vegetables and fruits","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abu Musa and Muʿadh ibn Jabal reported that when the Messenger of Allah ﷺ sent them to Yemen to teach the people their religion, he said: “Do not take zakat except from these four: barley, wheat, raisins, and dates.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني (1921)، والحاكم (1459)، والبيهقي (7451)."},{"num":3989,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جدّه قال: جَاءَ هِلالٌ أَحَدُ بَنِي مُتْعَانَ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بِعُشُورِ نَحْلٍ لَهُ وَكَانَ سَأَلَهُ أَنْ يَحْمِيَ لَهُ وَادِيًا يُقَالُ لَهُ سَلَبَةُ فَحَمَى لَهُ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  ذَلِكَ الْوَادِي فَلَمَّا وُلِّيَ عُمَرُ بْنُ الخَطَّابِ رَضِيَ الله عَنْهُ كَتَبَ سُفْيَانُ بْنُ وَهْبٍ إِلَى عُمَرَ بْنِ الخَطَّابِ يَسْأَلُهُ عَنْ ذَلِكَ، فَكَتَبَ عُمَرُ رَضِيَ اللهُ عَنْهُ: إِنْ أَدَّى إِلَيْكَ مَا كَانَ يُؤَدِّي إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  مِنْ عُشُورِ نَحْلِهِ فَاحْمِ لَهُ سَلَبَةَ، وَإِلا فَإِنَّمَا هُوَ ذُبَابُ غَيْثٍ يَأْكُلُهُ مَنْ يَشَاءُ ."],"takhrij":"حسن: رواه أبو داود (1600) واللّفظ له، والنسائيّ (2501) كلاهما من حديث أحمد بن أبي شعيب الحرانيّ، حدّثنا موسى بن أعين، عن عمرو بن الحارث المصريّ، عن عمرو بن شعيب، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب زكاة العسل","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1600), and this is his wording, and by al-Nasa’i (2498).","chapter_en":"Zakat on honey","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: Hilal, one of Banu Mutʿan, came to the Messenger of Allah ﷺ with the tithe of his bees. He had asked him to reserve for him a valley called Salabah, so the Messenger of Allah ﷺ protected that valley for him. When ʿUmar ibn al-Khattab became ruler, Sufyan ibn Wahb wrote to ʿUmar asking him about that, so ʿUmar wrote: “If he gives you what he used to give to the Messenger of Allah ﷺ from the tithes of his bees, then reserve Salabah for him. Otherwise, they are only rain-flies, eaten by whoever wishes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1600) واللفظ له، والنسائي (2501)."},{"num":3990,"demo":false,"sanad":"","matn":["عن أبي حميد السّاعديّ قال: غَزَوْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  غَزْوَةَ تَبُوكَ فَلَمَّا جَاءَ وَادِيَ الْقُرَى إِذَا امْرَأَةٌ فِي حَدِيقَةٍ لَهَا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لأَصْحَابِهِ: اخْرُصُوا . وَخَرَصَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  عَشَرَةَ أَوْسُقٍ فَقَالَ لَهَا: أَحْصِي مَا يَخْرُجُ مِنْهَا . فَلَمَّا أَتَيْنَا تَبُوكَ قَالَ: أَمَا إِنَّهَا سَتَهُبُّ اللَّيْلَةَ رِيحٌ شَدِيدَةٌ فَلا يَقُومَنَّ أَحَدٌ وَمَنْ كَانَ مَعَهُ بَعِيرٌ فَلْيَعْقِلْهُ . فَعَقَلْنَاهَا وَهَبَّتْ رِيحٌ شَدِيدَةٌ، فَقَامَ رَجُلٌ فَأَلْقَتْهُ بِجَبَلِ طَيِّءٍ، وَأَهْدَى مَلِكُ أَيْلَةَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بَغْلَةً بَيْضَاءَ وَكَسَاهُ بُرْدًا وَكَتَبَ لَهُ بِبَحْرِهِمْ فَلَمَّا أَتَى وَادِيَ الْقُرَى قَالَ لِلْمَرْأَةِ: كَمْ جَاءَ حَدِيقَتُكِ؟ . قَالَتْ: عَشَرَةَ أَوْسُقٍ خَرْصَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  : إِنِّي مُتَعَجِّلٌ إِلَى المَدِينَةِ فَمَنْ أَرَادَ مِنْكُمْ أَنْ يَتَعَجَّلَ مَعِي فَلْيَتَعَجَّلْ . فَلَمَّا - قَالَ ابْنُ بَكَّارٍ كَلِمَةً مَعْنَاهَا - أَشْرَفَ عَلَى المَدِينَةِ قَالَ: هَذِهِ طَابَةُ . فَلَمَّا رَأَى أُحُدًا قَالَ: هَذَا جُبَيْلٌ يُحِبُّنَا وَنُحِبُّهُ، أَلا أُخْبِرُكُمْ بِخَيْرِ دُورِ الأَنْصَارِ؟ . قَالُوا: بَلَى. قَالَ: دُورُ بَنِي النَّجَّارِ، ثُمَّ دُورُ بَنِي عَبْدِ الأَشْهَلِ، ثُمَّ دُورُ بَنِي سَاعِدَةَ أَوْ دُورُ بَنِي الحَارِثِ بْنِ الخَزْرَجِ، وَفِي كُلِّ دُورِ الأَنْصَارِ يَعْنِي خَيْرًا ."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1481) عن سهل بن بكّار، حدّثنا وُهيب، عن عمرو بن يحيى، عن عبّاس السّاعديّ، عن أبي حميد السّاعديّ، قال (فذكره) واللّفظ له.","grade":"متفق عليه","chapter_ar":"باب خرص الثمار","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1481), and this is his wording, and Muslim (1392).","chapter_en":"Estimating fruits on the trees","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abu Humayd al-Saʿidi said: We went out with the Prophet ﷺ on the expedition of Tabuk. When he came to Wadi al-Qura, there was a woman in her garden, and the Prophet ﷺ said to his companions: “Estimate it.” The Messenger of Allah ﷺ estimated it as ten awsuq, and said to her: “Keep count of what comes out from it.” When we came to Tabuk, he said: “Tonight a strong wind will blow, so none of you should stand up, and whoever has a camel with him should tie it.” So we tied them, and a strong wind blew. A man stood up, and the wind threw him onto the mountain of Tayy. The ruler of Aylah gifted the Prophet ﷺ a white mule, clothed him with a mantle, and wrote for him concerning their sea territory. When he came to Wadi al-Qura, he said to the woman: “How much did your garden produce?” She said: “Ten awsuq, exactly as the Messenger of Allah ﷺ estimated.” Then the Prophet ﷺ said: “I am hurrying to Madinah, so whoever among you wants to hurry with me should do so.” Then—after Ibn Bakkār said a word with this meaning—when he came near Madinah, he said: “This is Tabah.” When he saw Uhud, he said: “This is a small mountain that loves us and we love it. Shall I tell you about the best homes of the Ansar?” They said: “Yes.” He said: “The homes of Banu al-Najjar, then the homes of Banu ʿAbd al-Ashhal, then the homes of Banu Saʿidah or the homes of Banu al-Harith ibn al-Khazraj — and there is good in every clan of the Ansar.”"]},"buhuth":{"en":["The phrase “Keep count” means: preserve the measured amount.","And in Muslim’s narration: “Keep count of it until we return to you, if Allah wills.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1481) واللفظ له، ومسلم (1392)."},{"num":3991,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: افْتَتَحَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  خَيْبَرَ وَاشْتَرَطَ أَنَّ لَهُ الأَرْضَ وَكُلَّ صَفْرَاءَ وَبَيْضَاءَ. قَالَ أَهْلُ خَيْبَرَ: نَحْنُ أَعْلَمُ بِالأَرْضِ مِنْكُمْ فَأَعْطِنَاهَا عَلَى أَنَّ لَكُمْ نِصْفَ الثَّمَرَةِ وَلَنَا نِصْفٌ، فَزَعَمَ أَنَّهُ أَعْطَاهُمْ عَلَى ذَلِكَ فَلَمَّا كَانَ حِينَ يُصْرَمُ النَّخْلُ بَعَثَ إِلَيْهِمْ عبدالله ابْنَ رَوَاحَةَ فَحَزَرَ عَلَيْهِمْ النَّخْلَ- وَهُوَ الَّذِي يُسَمِّيهِ أَهْلُ المَدِينَةِ الخَرْصَ - فَقَالَ: فِي ذِهْ كَذَا وَكَذَا. قَالُوا: أَكْثَرْتَ عَلَيْنَا يَا ابْنَ رَوَاحَةَ! فَقَالَ: فَأَنَا أَلِي حَزْرَ النَّخْلِ وَأُعْطِيكُمْ نِصْفَ الَّذِي قُلْتُ. قَالُوا: هَذَا الحَقُّ وَبِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ قَدْ رَضِينَا أَنْ نَأْخُذَهُ بِالَّذِي قُلْتَ."],"takhrij":"حسن: رواه أبو داود (3410)، وابن ماجه (1820) كلاهما من حديث عمر بن أيوب، عن جعفر بن برقان، عن ميمون بن مهران، عن مِقْسم، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب خرص الثمار","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (3410) and Ibn Majah (1820).","chapter_en":"Estimating fruits on the trees","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: The Messenger of Allah ﷺ conquered Khaybar and stipulated that the land and all yellow and white wealth belonged to him. The people of Khaybar said: “We know the land better than you, so give it to us on the condition that you will have half the produce and we will have half.” When the time came to harvest the dates, he sent ʿAbdullah ibn Rawahah to estimate the palm trees — and this is what the people of Madinah call khars. He said: “This amount is such-and-such.” They said: “You have estimated too much against us, Ibn Rawahah.” He replied: “Then I will undertake the estimation of the palm trees and give you half of what I said.” They said: “This is the truth, and by it the heaven and the earth stand. We are satisfied to take it according to what you said.”"]},"buhuth":{"en":["Khars means estimating the amount of fresh dates on the trees as dried dates, so that the amount to be taken later at harvest time in zakat or otherwise may be known."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3410)، وابن ماجه (1820)."},{"num":3992,"demo":false,"sanad":"","matn":["عن جابر بن عبدالله قال: خَرَصَهَا ابْنُ رَوَاحَةَ أَرْبَعِينَ أَلْفَ وَسْقٍ وَزَعَمَ أَنَّ الْيَهُودَ لَمَّا خَيَّرَهُمْ ابْنُ رَوَاحَةَ أَخَذُوا الثَّمَرَ وَعَلَيْهِمْ عِشْرُونَ أَلْفَ وَسْقٍ."],"takhrij":"صحيح: رواه أبو داود (3415) عن أحمد - وهو في مسنده (14161) -، عن عبد الرزّاق - وهو في مصنفه (2705) - ومحمد بن بكر قالا: أخبرنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبدالله، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب خرص الثمار","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (3415), Ahmad (14161), and ʿAbd al-Razzaq (7205).","chapter_en":"Estimating fruits on the trees","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: Ibn Rawahah estimated it at forty thousand awsuq, and it is reported that when Ibn Rawahah gave the Jews the choice, they took the fruit, and twenty thousand awsuq were due from them."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود (3415)، وأحمد (14161)، وعبد الرزاق (7205)."},{"num":3993,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَثْمَةَ، أَنَّ النبيّ صلى الله عليه وسلم  بعثه خَارِصًا، فَجَاءَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللهِ، إِنَّ أَبَا حَثْمَةَ قَدْ زَادَ عَلَيَّ. فَدَعَا أَبَا حَثْمَةَ، فَقَالَ: إنّ ابْنُ عَمِّكَ يَزْعُمُ أَنَّكَ قَدْ زِدْتَ عَلَيْهِ؟ . فَقَالَ: يَا رَسُولَ اللهِ، قَدْ تَرَكْتُ عَرِيَّةَ أَهْلِهِ، وَمَا يُطْعِمُ الْمَسَاكِينَ، وَمَا يُصِيبُ الرِّيحَ. فقال: قَدْ زَادَكَ ابْنُ عَمِّكَ وأنصفك ."],"takhrij":"حسن: رواه البخاريّ في التاريخ الكبير (4/97) عن إبراهيم بن المنذر، نا محمد بن صدقة، قال: حدثني محمد بن يحيى بن سهل بن أبي حثمة، عن أبيه، عن جدّه، أنّ النّبيّ صلى الله عليه وسلم  بعث أبا حثمة خارصاً، فذكره.","grade":"حسن","chapter_ar":"باب خرص الثمار","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Bukhari in al-Tarikh al-Kabir (4/97), and by al-Tabarani in al-Awsat (Majmaʿ al-Bahrayn 1357).","chapter_en":"Estimating fruits on the trees","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abu Hathmah reported that the Prophet ﷺ sent him as an estimator. Then a man came and said: “O Messenger of Allah ﷺ, Abu Hathmah has estimated too much against me.” So he called Abu Hathmah and said: “Your cousin claims that you estimated too much against him?” He replied: “O Messenger of Allah ﷺ, I left out the share for his family’s gift-dates, what feeds the poor, and what the wind spoils.” So he said: “Your cousin has allowed you extra and treated you fairly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في التاريخ الكبير (4/97)، والطبراني في الأوسط (مجمع البحرين 1357)."},{"num":3994,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ صَدَقَةٌ."],"takhrij":"متفق عليه: رواه البخاريّ في الزّكاة (1405)، ومسلم في الزكاة (979) كلاهما من حديث عمرو بن يحيى بن عمارة، عن أبيه، عن أبي سعيد الخدريّ، فذكره.","grade":"متفق عليه","chapter_ar":"باب نصاب الزروع والثمار","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1405) and Muslim (979).","chapter_en":"The minimum amount for crops and fruits","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Abu Saʿid al-Khudri reported that the Prophet ﷺ said: “There is no zakat on less than five awsuq.”"]},"buhuth":{"en":["And in another wording in Muslim:","“There is no zakat on grain or dates until it reaches five awsuq.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1405)، ومسلم (979)."},{"num":3995,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَحِلُّ فِي الْبُرِّ وَالتَّمْرِ زَكَاةٌ، حَتَّى يَبْلُغَ خَمْسَةَ أَوْسُقٍ، وَلَا تَحِلُّ فِي الْوَرِقِ زَكَاةٌ حَتَّى تَبْلُغَ خَمْسَ أَوَاقٍ، وَلَا تَحِلُّ فِي الْإِبِلِ زَكَاةٌ حَتَّى تَبْلُغَ خَمْسَةَ ذَوْدٍ."],"takhrij":"صحيح: رواه النسائيّ (2484) عن إسماعيل بن مسعود، حدّثنا يزيد بن زريع، حدّثنا روح بن القاسم، قال: حدّثني عمرو بن يحيى بن عُمارة، عن أبيه، عن أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب نصاب الزروع والثمار","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2484), and graded authentic by Ibn Khuzaymah (2301).","chapter_en":"The minimum amount for crops and fruits","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Abu Saʿid al-Khudri reported that the Messenger of Allah ﷺ said: “There is no zakat on wheat or dates until they reach five awsuq, no zakat on silver until it reaches five uqiyyahs, and no zakat on camels until they reach five head.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (2484)، وصححه ابن خزيمة (2301)."},{"num":3996,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدَالِلَهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: وَلَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ مِنْ التَّمْرِ صَدَقَةٌ .."],"takhrij":"صحيح: رواه مسلم في الزكاة (980) من طرق عن ابن وهب، أخبرني عياض بن عبدالله، عن أبي الزّبير، عن جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب نصاب الزروع والثمار","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (980).","chapter_en":"The minimum amount for crops and fruits","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn ʿAbdullah reported that the Prophet ﷺ said: “There is no zakat on less than five awsuq of dates.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (980)."},{"num":3997,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسَاقٍ صَدَقَةٌ."],"takhrij":"صحيح: رواه الإمام أحمد (9221، 9232) من وجهين عن عبدالله بن المبارك، أخبرنا معمر، قال: حدثني سُهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب نصاب الزروع والثمار","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Authentic: narrated by Imam Ahmad (9232, 9221).","chapter_en":"The minimum amount for crops and fruits","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “There is no zakat on less than five awsuq.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (9232، 9221)."},{"num":3998,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ، عَنْ أَبِيهِ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجُعْرُورِ، وَلَوْنِ الْحُبَيْقِ أَنْ يُؤْخَذَا فِي الصَّدَقَةِ.","قَالَ الزُّهْرِيُّ: لَوْنَيْنِ مِنْ تَمْرِ الْمَدِينَةِ.","قَالَ أَبُو دَاوُدَ: وَأَسْنَدَهُ أَيْضًا أَبُو الْوَلِيدِ، عَنْ سُلَيْمَانَ بْنِ كَثِيرٍ، عَنِ الزُّهْرِيِّ."],"takhrij":"حسن: رواه أبو داود (1607) عن محمد بن يحيى بن فارس، حدّثنا سعيد ابن سليمان، حدّثنا عبّاد، عن سفيان بن حسين، عن الزّهريّ، عن أبي أمامة ابن سهل، عن أبيه، فذكره. وصحّحه ابن خزيمة (2313) ورواه من طريق سعيد بن سليمان.","grade":"حسن","chapter_ar":"باب ما لا يجوز من الثمرة في الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1607), and graded authentic by Ibn Khuzaymah (2313).","chapter_en":"What is not permissible from fruits in charity","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Abu Umamah ibn Sahl narrated from his father, who said: The Messenger of Allah ﷺ forbade that al-jaʿrur and the color-type called al-ḥubayq be taken in zakat. Al-Zuhri said: They are two kinds of Madinah dates.","Abu Dawud said: Abu al-Walid also narrated it with a connected chain from Sulayman ibn Kathir, from al-Zuhri."]},"intro":{"ar":["قال الله تعالى:","( يَا أَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِن طَيِّبَاتِ مَا كَسَبْتُمْ وَمِمَّا أَخْرَجْنَا لَكُمْ مِنَ الْأَرْضِ وَلَا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ وَلَسْتُمْ بِآخِذِيهِ إِلَّا أَنْ تُغْمِضُوا فِيهِ وَاعْلَمُوا أَنَّ اللَّهَ غَنِيٌّ حَمِيدٌ ) [سورة البقرة: ٢٦٧]."],"en":["Allah the Exalted said:","“O you who believe, spend from the good things you have earned and from what We have brought forth for you from the earth, and do not choose the bad from it to give away, while you yourselves would not take it except with closed eyes. And know that Allah is Free of need and Praiseworthy.”","[Surah al-Baqarah, 2:267]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1607)، وصححه ابن خزيمة (2313)."},{"num":3999,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ، قَالَ: دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ وَبِيَدِهِ عَصًا، وَقَدْ عَلَّقَ رَجُلٌ مِنَّا قِنًا حَشَفًا، فَطَعَنَ بِالْعَصَا فِي ذَلِكَ الْقِنْوِ وَقَالَ: لَوْ شَاءَ رَبُّ هَذِهِ الصَّدَقَةِ تَصَدَّقَ بِأَطْيَبَ مِنْهَا. وَقَالَ إِنَّ رَبَّ هَذِهِ الصَّدَقَةِ يَأْكُلُ الْحَشَفَ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أبو داود (1608)، والنّسائيّ (2495)، وابن ماجه (1821) كلّهم من حديث يحيى بن سعيد، عن عبد الحميد بن جعفر، حدّثني صالح بن أبي عريب، عن كثير بن مرة الحضرميّ، عن عوف بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب ما لا يجوز من الثمرة في الصدقة","chapter_ur":"","part_ar":"كتاب الزكاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1608), al-Nasa’i (2495), and Ibn Majah (1821).","chapter_en":"What is not permissible from fruits in charity","part_en":"Zakat","group_ar":"جموع أبواب ما جاء في زكاة الزروع","group_en":"Collection of chapters regarding zakat on crops","part_no":14,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿAwf ibn Malik said: The Messenger of Allah ﷺ entered upon us holding a staff, while a man had hung up a cluster of poor, dried dates. He poked that cluster with the staff and said: “If the owner of this charity wished, he could have given better than this.” And he said: “The owner of this charity will eat poor dried dates on the Day of Resurrection.”"]},"buhuth":{"en":["The phrase “a cluster of poor dried dates” means:","A qinw is a date cluster with its dates on it.","Its plural is qinwan and aqna’.","Hashaf means dried, spoiled, low-quality dates."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1608)، والنسائي (2495)، وابن ماجه (1821)."}]);